SELECT '09bc0868-0ec0-73cd-901a-8e89493a0809', 'f099bdb0-d7db-72bc-81bc-2979eae733c2', 1, 'PUBLISHED', 'Operators & Precedence', '[{"id":"1bf9a352-df0c-7729-bfed-90b90e50b5f6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every operator Python has, how tightly each one binds, and the surprising corners — floor division with negatives, "},{"type":"text","text":"and","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"or","marks":[{"type":"code"}]},{"type":"text","text":" returning operands, chained comparisons and bit tricks."}]}]}},"revision":1},{"id":"e305cc17-72d5-7706-ac07-29614ca65d02","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Precedence table (highest first)"}]},"revision":1},{"id":"a6b59b1f-e731-713e-846b-f3cad2c97e7e","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Level"}],[{"type":"text","text":"Operators"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"1"}],[{"type":"text","text":"(…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"[…]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"{…}","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x[i]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x(…)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x.attr","marks":[{"type":"code"}]}],[{"type":"text","text":"Grouping, subscription, calls, attribute access"}]],[[{"type":"text","text":"2"}],[{"type":"text","text":"await x","marks":[{"type":"code"}]}],[{"type":"text","text":"Inside "},{"type":"text","text":"async def","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3"}],[{"type":"text","text":"**","marks":[{"type":"code"}]}],[{"type":"text","text":"Power — "},{"type":"text","text":"right","marks":[{"type":"b