  ('a6b59b1f-e731-713e-846b-f3cad2c97e7e', 'a2', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Level"}],[{"type":"text","text":"Operators"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"1"}],[{"type":"text","text":"(…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"[…]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"{…}","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x[i]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x(…)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x.attr","marks":[{"type":"code"}]}],[{"type":"text","text":"Grouping, subscription, calls, attribute access"}]],[[{"type":"text","text":"2"}],[{"type":"text","text":"await x","marks":[{"type":"code"}]}],[{"type":"text","text":"Inside "},{"type":"text","text":"async def","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3"}],[{"type":"text","text":"**","marks":[{"type":"code"}]}],[{"type":"text","text":"Power — "},{"type":"text","text":"right","marks":[{"type":"bold"}]},{"type":"text","text":"-associative; binds tighter than a unary minus on its left"}]],[[{"type":"text","text":"4"}],[{"type":"text","text":"+x","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"-x","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"~x","marks":[{"type":"code"}]}],[{"type":"text","text":"Unary plus, minus, bitwise NOT"}]],[[{"type":"text","text":"5"}],[{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"@","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"/","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"//","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"%","marks":[{"type":"code"}]}],[{"type":"text","text":"Multiplicative ("},{"type":"text","text":"@","marks":[{"type":"code"}]},{"type":"text","text":" is matrix multiplication)"}]],[[{"type":"text","text":"6"}],[{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"-","marks":[{"type":"code"}]}],[{"type":"text","text":"Additive"}]],[[{"type":"text","text":"7"}],[{"type":"text","text":"<<","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":">>","marks":[{"type":"code"}]}],[{"type":"text","text":"Shifts"}]],[[{"type":"text","text":"8"}],[{"type":"text","text":"&","marks":[{"type":"code"}]}],[{"type":"text","text":"Bitwise AND"}]],[[{"type":"text","text":"9"}],[{"type":"text","text":"^","marks":[{"type":"code"}]}],[{"type":"text","text":"Bitwise XOR"}]],[[{"type":"text","text":"10"}],[{"type":"text","text":"|","marks":[{"type":"code"}]}],[{"type":"text","text":"Bitwise OR"}]],[[{"type":"text","text":"11"}],[{"type":"text","text":"in","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"not in","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is not","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":">=","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"!=","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"==","marks":[{"type":"code"}]}],[{"type":"text","text":"All comparisons share one level and "},{"type":"text","text":"chain","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"12"}],[{"type":"text","text":"not x","marks":[{"type":"code"}]}],[{"type":"text","text":"Boolean NOT"}]],[[{"type":"text","text":"13"}],[{"type":"text","text":"and","marks":[{"type":"code"}]}],[{"type":"text","text":"Short-circuit AND"}]],[[{"type":"text","text":"14"}],[{"type":"text","text":"or","marks":[{"type":"code"}]}],[{"type":"text","text":"Short-circuit OR"}]],[[{"type":"text","text":"15"}],[{"type":"text","text":"x if c else y","marks":[{"type":"code"}]}],[{"type":"text","text":"Conditional expression"}]],[[{"type":"text","text":"16"}],[{"type":"text","text":"lambda","marks":[{"type":"code"}]}],[{"type":"text","text":"Anonymous function"}]],[[{"type":"text","text":"17"}],[{"type":"text","text":":=","marks":[{"type":"code"}]}],[{"type":"text","text":"Assignment expression (walrus) — lowest"}]]]}'),
  ('797e7286-64e6-7e79-bc4a-167033efee7c', 'a3', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything is left-to-right associative except "},{"type":"text","text":"**","marks":[{"type":"code"}]},{"type":"text","text":" (right-to-left) and comparisons (which chain). When in doubt, add parentheses — they cost nothing and help the reader."}]}]}}'),
  ('a08fed45-a944-7500-a657-ea61fbed5efc', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Arithmetic"}]}'),
  ('920ed2c4-c309-7205-8fe1-e369662ecc8c', 'a5', 'code', '{"language":"python","code":"print(7 / 2, 7 // 2, 7 % 2)           # 3.5 3 1\nprint(-7 // 2, -7 % 2)                # -4 1\nprint(7 // -2, 7 % -2)                # -4 -1\nprint(divmod(-7, 2))                  # (-4, 1)\nprint(7.5 // 2, 7.5 % 2)              # 3.0 1.5\nprint(2 ** 3 ** 2, (2 ** 3) ** 2)     # 512 64\nprint(-2 ** 2, (-2) ** 2)             # -4 4\nprint(2 ** -1, 10 ** 20)              # 0.5 100000000000000000000","filename":"Python"}'),
  ('d60a39eb-2d4a-7b03-a24f-874120e1609b', 'a6', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operator"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Watch out"}]],[[{"type":"text","text":"/","marks":[{"type":"code"}]}],[{"type":"text","text":"True division"}],[{"type":"text","text":"Always returns a "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"4 / 2 == 2.0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"//","marks":[{"type":"code"}]}],[{"type":"text","text":"Floor division"}],[{"type":"text","text":"Rounds toward "},{"type":"text","text":"−∞","marks":[{"type":"bold"}]},{"type":"text","text":", not toward 0: "},{"type":"text","text":"-7 // 2 == -4","marks":[{"type":"code"}]},{"type":"text","text":" (C/Java give "},{"type":"text","text":"-3","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"%","marks":[{"type":"code"}]}],[{"type":"text","text":"Modulo"}],[{"type":"text","text":"Result has the sign of the "},{"type":"text","text":"divisor","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"-7 % 2 == 1","marks":[{"type":"code"}]},{"type":"text","text":"; always "},{"type":"text","text":"(a // b) * b + a % b == a","marks":[{"type":"code"}]}]],[[{"type":"text","text":"**","marks":[{"type":"code"}]}],[{"type":"text","text":"Power"}],[{"type":"text","text":"Right-associative; "},{"type":"text","text":"pow(a, b, m)","marks":[{"type":"code"}]},{"type":"text","text":" does fast modular exponentiation"}]],[[{"type":"text","text":"divmod(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"(a // b, a % b)","marks":[{"type":"code"}]},{"type":"text","text":" at once"}],[{"type":"text","text":"Handy for digit extraction and time conversions"}]]]}'),
  ('599e3171-adeb-7851-9cbd-b25a2a592c42', 'a7', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" makes wrap-around indexing easy: "},{"type":"text","text":"(i - 1) % n","marks":[{"type":"code"}]},{"type":"text","text":" is always a valid index, even when "},{"type":"text","text":"i == 0","marks":[{"type":"code"}]},{"type":"text","text":". For C-style truncation use "},{"type":"text","text":"int(a / b)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"math.fmod","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b066ec5e-13b9-7c3d-b683-36f946bb8b8b', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Comparisons chain"}]}'),
  ('e510b615-291a-730a-a50e-9678ec9527a5', 'a9', 'code', '{"language":"python","code":"x = 5\nprint(1 < x < 10, 10 > x >= 5)        # True True\nprint(1 < 2 == 2)                     # True   ← means (1 < 2) and (2 == 2)\nprint((1 < 2) == 2)                   # False  ← True == 2 is False\nprint(False == False in [False])      # True   ← (False == False) and (False in [False])\nprint(\"apple\" < \"banana\" < \"cherry\")  # True   ← strings compare lexicographically\nprint([1, 2] < [1, 3], (2, 0) > (1, 9))   # True True","filename":"Python"}'),
  ('e40c2c1a-186b-7d7d-b719-db35aa0e5ab5', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"a < b < c","marks":[{"type":"code"}]},{"type":"text","text":" evaluates "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" only once and means "},{"type":"text","text":"a < b and b < c","marks":[{"type":"code"}]},{"type":"text","text":". Sequences compare element by element, which is why tuples make great multi-key sort keys."}]}]}}'),
  ('6d0a2bb8-483b-7941-97bc-4ce2a5a3cd87', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"and","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"or","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"not","marks":[{"type":"code"}]},{"type":"text","text":" — short-circuit and return operands"}]}'),
  ('6bcd76f0-a06b-7e6c-9035-4274f600ed99', 'aC', 'code', '{"language":"python","code":"print(0 or \"default\", \"x\" or \"default\")   # default x\nprint(0 and 1 / 0, 3 and 4)               # 0 4   ← 1 / 0 is never evaluated\nprint([] or None or 0)                    # 0     ← every operand falsy → the last one\nprint(not \"\", not \"hi\")                   # True False\n\nname = \"\"\nprint(name or \"Anonymous\")                # Anonymous","filename":"Python"}'),
  ('d3b67bb6-dff1-79b9-ab43-4d5b4362b87f', 'aD', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Expression"}],[{"type":"text","text":"Returns"}]],[[{"type":"text","text":"a or b","marks":[{"type":"code"}]}],[{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is truthy, otherwise "},{"type":"text","text":"b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"a and b","marks":[{"type":"code"}]}],[{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is falsy, otherwise "},{"type":"text","text":"b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"not a","marks":[{"type":"code"}]}],[{"type":"text","text":"Always a real "},{"type":"text","text":"bool","marks":[{"type":"code"}]}]]]}'),
  ('c19f1488-79e1-7b00-8116-b0f5628ae873', 'aE', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"count = user_count or 10","marks":[{"type":"code"}]},{"type":"text","text":" replaces a legitimate "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"10","marks":[{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"''''","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":" are valid values, test explicitly: "},{"type":"text","text":"10 if user_count is None else user_count","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('c10699c7-5977-7d2a-b586-e4d14a161868', 'aF', 'heading', '{"level":1,"content":[{"type":"text","text":"Bitwise operators & tricks"}]}'),
  ('016ec680-893b-727a-8c7e-4a9b8b08c44c', 'aG', 'code', '{"language":"python","code":"a, b = 0b1100, 0b1010                 # 12, 10\nprint(a & b, a | b, a ^ b)            # 8 14 6\nprint(bin(a & b), ~a)                 # 0b1000 -13   ← ~x == -x - 1\nprint(1 << 4, 100 >> 2)               # 16 25        ← x << k == x * 2**k","filename":"Python"}'),
  ('045a5548-146e-7eeb-a650-d58ee81e56e5', 'aH', 'code', '{"language":"python","code":"def is_power_of_two(x):\n    return x > 0 and x & (x - 1) == 0     # clears the lowest set bit\n\nprint(is_power_of_two(64), is_power_of_two(96))   # True False\nprint(40 & -40)                         # 8      ← lowest set bit of 0b101000\nprint((13 >> 2) & 1)                    # 1      ← bit 2 of 0b1101\nprint((255).bit_count(), (255).bit_length())   # 8 8\n\nREAD, WRITE, EXEC = 1, 2, 4             # flags packed in one int\nperms = READ | WRITE\nperms &= ~WRITE                         # clear a flag\nperms |= EXEC                           # set a flag\nprint(perms, bool(perms & READ), bool(perms & WRITE))   # 5 True False\n\nnums = [4, 1, 2, 1, 2]\nsingle = 0\nfor n in nums:\n    single ^= n                         # x ^ x == 0, so pairs cancel out\nprint(single)                           # 4","filename":"Python"}'),
  ('936b55d6-170e-7c5e-8a9e-3520a1390693', 'aI', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unlike C, bitwise operators bind "},{"type":"text","text":"tighter","marks":[{"type":"bold"}]},{"type":"text","text":" than comparisons in Python: "},{"type":"text","text":"n & 1 == 0","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"(n & 1) == 0","marks":[{"type":"code"}]},{"type":"text","text":". Python ints are unbounded, so "},{"type":"text","text":"~","marks":[{"type":"code"}]},{"type":"text","text":" and negative numbers behave as if they had infinitely many leading 1 bits."}]}]}}'),
