ragraph","content":[{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" clauses are tried top to bottom and match subclasses. "},{"type":"text","text":"KeyError","marks":[{"type":"code"}]},{"type":"text","text":" is a subclass of "},{"type":"text","text":"LookupError","marks":[{"type":"code"}]},{"type":"text","text":", so the first clause wins — put specific exceptions first."}]}]}},"revision":1},{"id":"078a64ea-00eb-7c92-a0f9-0b16b66056c3","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Classes"}]},"revision":1},{"id":"407c2dfb-beaa-70fa-9602-3770d953573f","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MRO in diamond inheritance"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"class A:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def who(self): return \"A\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"class B(A):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def who(self): return \"B\" + super().who()","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"class C(A):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def who(self): return \"C\" + super().who()","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"class D(B, C):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    pass","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(D().who())           # BCA","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" follows the MRO "},{"type":"text","text":"D → B → C → A","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":"''s "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":". → "},{"type":"text","text":"Inheritance, MRO & super()","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"410593a1-1853-7118-a385-f80f10824a8e","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"__eq__ without __hash__"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"class P:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def __init__(self, x): self.x = x","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def __eq__(self, o): return self.x == o.x","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(P.__hash__)          # None","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"try:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    {P(1)}","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"except TypeError as e:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    print(type(e).__name__)   # TypeError","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Defining "},{"type":"text","text":"__eq__","marks":[{"type":"code"}]},{"type":"text","text":" sets "},{"type":"text","text":"__hash__","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". Add a "},{"type":"text","text":"__hash__","marks":[{"type":"code"}]},{"type":"text","text":" based on the same fields (and keep them immutable), or use "},{"type":"text","text":"@dataclass(frozen=True)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
