  ('e39f2d13-866b-7221-ade2-89603741bb0a', 'a4', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiplying a nested list"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"board = [[\" \"] * 2] * 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"board[0][0] = \"X\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(board)               # [[''X'', '' ''], [''X'', '' '']]","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"* 2","marks":[{"type":"code"}]},{"type":"text","text":" copies the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" to the inner list, so both rows are the same object. Use "},{"type":"text","text":"[[\" \"] * 2 for _ in range(2)]","marks":[{"type":"code"}]},{"type":"text","text":". → "},{"type":"text","text":"Lists & Tuples","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('c65e9bad-e0c8-7584-a05c-6fdb736b3342', 'a5', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Augmented assignment on a tuple item"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"t = ([1], 2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"try:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    t[0] += [3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"except TypeError as e:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    print(type(e).__name__)   # TypeError","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(t)                      # ([1, 3], 2)","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"t[0] += [3]","marks":[{"type":"code"}]},{"type":"text","text":" first extends the list in place (succeeds), then tries to store it back into the tuple (fails). The error is raised "},{"type":"text","text":"after","marks":[{"type":"bold"}]},{"type":"text","text":" the mutation. → "},{"type":"text","text":"Identity, Mutability & Copying","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('2d13163d-f68b-719a-90d2-84889b99e6b4', 'a6', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rebinding vs mutating a parameter"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"def f(xs):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    xs.append(1)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    xs = [99]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    xs.append(2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"data = []","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"f(data)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(data)                # [1]","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The first "},{"type":"text","text":"append","marks":[{"type":"code"}]},{"type":"text","text":" mutates the caller''s list. "},{"type":"text","text":"xs = [99]","marks":[{"type":"code"}]},{"type":"text","text":" rebinds only the local name, so later changes don''t reach the caller."}]}]}}'),
