  ('8ba05aa8-5665-705f-b624-f13b9117283f', 'a8', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UnboundLocalError"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"count = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"def bump():","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    try:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"        count += 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    except UnboundLocalError:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"        return \"unbound\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(bump())              # unbound","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Assigning to "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":" anywhere in the function makes it local for the "},{"type":"text","text":"whole","marks":[{"type":"bold"}]},{"type":"text","text":" function, so reading it first fails. Use "},{"type":"text","text":"global count","marks":[{"type":"code"}]},{"type":"text","text":" (or better, return the new value). → "},{"type":"text","text":"Scope & Closures","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('ec3ce319-108b-7045-8583-6859edae4684', 'a9', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Closures in a loop"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"adders = [lambda x: x + i for i in range(3)]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print([f(10) for f in adders])   # [12, 12, 12]","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"All lambdas share the same "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":", read when they are called — after the loop left it at 2. Bind it early: "},{"type":"text","text":"lambda x, i=i: x + i","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('81b16fe5-fe0e-791a-9812-08ee3dbb4053', 'aA', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Class variable vs instance variable"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"class Dog:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    tricks = []","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    def add(self, t):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"        self.tricks.append(t)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"a, b = Dog(), Dog()","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"a.add(\"roll\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(b.tricks)            # [''roll'']","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"tricks","marks":[{"type":"code"}]},{"type":"text","text":" lives on the class and is shared by every instance. Create it in "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":" instead. → "},{"type":"text","text":"Classes & Objects","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('2c140176-db97-7a62-abb7-561f25bd01f6', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Operators & values"}]}'),
  ('31975d29-6214-73a6-ba9f-8f71c692da6e', 'aC', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chained comparisons and precedence"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print(1 < 2 == 2)          # True","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print((1 < 2) == 2)        # False","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(-2 ** 2)             # -4","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(not 1 == 2)          # True","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"1 < 2 == 2","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"1 < 2 and 2 == 2","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"True == 2","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":" because "},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"**","marks":[{"type":"code"}]},{"type":"text","text":" binds tighter than unary minus. "},{"type":"text","text":"not","marks":[{"type":"code"}]},{"type":"text","text":" has lower precedence than "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":". → "},{"type":"text","text":"Operators & Precedence","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('a042dab6-89bc-74e9-bd38-591a2ffa8866', 'aD', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Floats and rounding"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print(0.1 + 0.2 == 0.3)       # False","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(round(0.5), round(1.5), round(2.5))   # 0 2 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(-7 // 2, -7 % 2)        # -4 1","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Binary floats can''t represent 0.1 exactly — compare with "},{"type":"text","text":"math.isclose","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"round","marks":[{"type":"code"}]},{"type":"text","text":" uses banker''s rounding (halves to even). "},{"type":"text","text":"//","marks":[{"type":"code"}]},{"type":"text","text":" floors toward negative infinity and "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" takes the sign of the divisor. → "},{"type":"text","text":"Numbers","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('394b3b20-3038-7a9b-8dd7-90d61ab90d90', 'aE', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"and / or return operands"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print(0 or [] or \"x\")      # x","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(3 and 0 and 5)       # 0","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(None or 0)           # 0","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"or","marks":[{"type":"code"}]},{"type":"text","text":" returns the first truthy operand (or the last one); "},{"type":"text","text":"and","marks":[{"type":"code"}]},{"type":"text","text":" returns the first falsy operand (or the last one). They return objects, not booleans."}]}]}}'),
  ('02d03a6d-f01e-7870-abc4-94f96315621c', 'aF', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"True is an int"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"d = {1: \"int\", True: \"bool\", 1.0: \"float\"}","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(d)                   # {1: ''float''}","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(sum([True, True, False]))   # 2","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"1 == True == 1.0","marks":[{"type":"code"}]},{"type":"text","text":" and they hash equally, so they are the "},{"type":"text","text":"same key","marks":[{"type":"bold"}]},{"type":"text","text":": the first key object is kept and the value is overwritten twice."}]}]}}'),
