  ('b7ed8883-c421-7cfe-83ea-e4f0075f28b9', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exhausted iterators"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"nums = map(lambda n: n * 2, [1, 2, 3])","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(list(nums))          # [2, 4, 6]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(list(nums))          # []","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"z = zip(\"ab\", [1, 2])","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(dict(z), dict(z))    # {''a'': 1, ''b'': 2} {}","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"zip","marks":[{"type":"code"}]},{"type":"text","text":" and generators are one-shot iterators. Convert to a list once if you need several passes. → "},{"type":"text","text":"Iterators & Generators","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('17caa453-8505-7d29-9f43-851edc432ed2', 'aI', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modifying a list while iterating"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"nums = [1, 2, 2, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"for n in nums:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    if n == 2:","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"        nums.remove(n)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(nums)                # [1, 2, 3]","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Removing shifts later items left, so the loop''s index skips the second "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"text","text":". Build a new list instead: "},{"type":"text","text":"[n for n in nums if n != 2]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
