SELECT 'ff81d876-5c1d-7673-bf6a-fdeed03db18a', '9fe1e504-eb55-78d2-8a54-2ee56da29656', 1, 'PUBLISHED', 'Virtual Environments, pip & Packaging', '[{"id":"f2edaa9c-ab07-7def-954b-2e86ecb001a4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Isolate each project''s dependencies in a virtual environment, pin them for reproducible installs, and describe your own project in "},{"type":"text","text":"pyproject.toml","marks":[{"type":"code"}]},{"type":"text","text":" so it can be installed and published."}]}]}},"revision":1},{"id":"45b26010-0ca7-7c25-be41-d23aaa3e5615","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual environment","marks":[{"type":"bold"}]},{"type":"text","text":" — a directory with its own "},{"type":"text","text":"python","marks":[{"type":"code"}]},{"type":"text","text":" executable and "},{"type":"text","text":"site-packages","marks":[{"type":"code"}]},{"type":"text","text":". Packages installed while it''s active go there, not into the system Python — so two projects can use different versions of the same library."}]}]}},"revision":1},{"id":"e82ec653-5e8c-7038-a29d-a2f772a4b28d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The venv lifecycle"}]},"revision":1},{"id":"237c6dc3-cbfa-70e4-80ca-7ae3afff9412","type":"code","position":"a3","content":{"language":"","code":"$ python3 -m venv .venv                   # create (once per project; don''t commit it)\n$ source .venv/bin/activate               # activate — Windows: .venv\\Scripts\\activate\n(.venv) $ which python                    # → /path/to/project/.venv/bin/python\n(.venv) $ python -m pip install --upgrade pip\n(.venv) $ pip install \"requests>=2.31\" pytest\n(.venv) $ deactivate                      # back to the system Python\n$ rm -rf .venv                            # environments are disposable: delete & recreate","filename":"Terminal"},"revision":1},{"id":"dce5ce9a-85b9-7c0e-8d8e-04b801a089b9","type":"code","position":"a4","content":{"language":"python","code":"import sys\nprint(\"inside a venv:\", sys.prefix != sys.base_prefix)   # True inside a venv, False otherwise\nprint(sys.version_info >= (3, 10))                      # True","filename":"Python"},"revision":1},{"id":"85c3aee1-30e6-7110-a995-0d8d0b016f37","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Activation only prepends "},{"type":"text","text":".venv/bin","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"PATH","marks":[{"type":"code"}]},{"type":"text","text":". You can skip it entirely by calling the interpreter directly: "},{"type":"text","text":".venv/bin/python -m pytest","marks":[{"type":"code"}]},{"type":"text","text":". Add "},{"type":"text","text":".venv/","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":".gitignore","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d033c27b-a97f-71f0-b3bf-571578139958","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"pip essentials"}]},"revision":1},{"id":"55910566-f85a-7013-8234-ee9ea53ef805","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Command"}],[{"type":"text","text":"Does"}]],[[{"type":"text","text":"pip install pkg","marks":[{"type":"code"}]}],[{"type":"text","text":"Install the latest compatible version (plus dependencies)"}]],[[{"type":"text","text":"pip install \"pkg==1.4.2\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Install an exact version"}]],[[{"type":"text","text":"pip install -U pkg","marks":[{"type":"code"}]}],[{"type":"text","text":"Upgrade"}]],[[{"type":"text","text":"pip uninstall pkg","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove (dependencies stay installed)"}]],[[{"type":"text","text":"pip list","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"pip list --outdated","marks":[{"type":"code"}]}],[{"type":"text","text":"What''s installed / what can be upgraded"}]],[[{"type":"text","text":"pip show pkg","marks":[{"type":"code"}]}],[{"type":"text","text":"Version, location, dependencies of one package"}]],[[{"type":"text","text":"pip freeze > requirements.txt","marks":[{"type":"code"}]}],[{"type":"text","text":"Exact versions of everything installed"}]],[[{"type":"text","text":"pip install -r requirements.txt","marks":[{"type":"code"}]}],[{"type":"text","text":"Install from a requirements file"}]],[[{"type":"text","text":"pip install -e .","marks":[{"type":"code"}]}],[{"type":"text","text":"Editable install of the current project"}]]]},"revision":1},{"id":"fb480c8f-46bc-7ff6-9321-2fd7c10cee75","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"python -m pip …","marks":[{"type":"code"}]},{"type":"text","text":" over bare "},{"type":"text","text":"pip","marks":[{"type":"code"}]},{"type":"text","text":": it guarantees you''re installing into the interpreter you think you are. And never "},{"type":"text","text":"sudo pip install","marks":[{"type":"code"}]},{"type":"text","text":" into the system Python."}]}]}},"revision":1},{"id":"125268f9-aa68-754d-bda1-d8f83e70135b","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Version specifiers"}]},"revision":1},{"id":"f647d2a6-9fe2-7d9c-91fa-c441d50a4eb9","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Specifier"}],[{"type":"text","text":"Means"}]],[[{"type":"text","text":"==1.4.2","marks":[{"type":"code"}]}],[{"type":"text","text":"Exactly 1.4.2"}]],[[{"type":"text","text":">=1.4,<2","marks":[{"type":"code"}]}],[{"type":"text","text":"At least 1.4, below 2.0"}]],[[{"type":"text","text":"~=1.4.2","marks":[{"type":"code"}]}],[{"type":"text","text":"Compatible release: "},{"type":"text","text":">=1.4.2, ==1.4.*","marks":[{"type":"code"}]}]],[[{"type":"text","text":"~=1.4","marks":[{"type":"code"}]}],[{"type":"text","text":">=1.4, ==1.*","marks":[{"type":"code"}]},{"type":"text","text":" (i.e. below 2.0)"}]],[[{"type":"text","text":"!=1.5.0","marks":[{"type":"code"}]}],[{"type":"text","text":"Anything except 1.5.0"}]],[[{"type":"text","text":"requests[socks]","marks":[{"type":"code"}]}],[{"type":"text","text":"Install with an optional "},{"type":"text","text":"extra","marks":[{"type":"italic"}]}]],[[{"type":"text","text":"tomli; python_version < \"3.11\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Environment marker — only on older Pythons"}]]]},"revision":1},{"id":"581de7e3-4d9e-7136-a23e-ac30ff0b7172","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"requirements.txt vs lock files"}]},"revision":1},{"id":"e0a6ec9a-01db-7c00-afd1-82e129f13b8b","type":"callout","position":"aC","content":{"variant":"note","title":"Library","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Declares "},{"type":"text","text":"loose","marks":[{"type":"bold"}]},{"type":"text","text":" ranges ("},{"type":"text","text":"requests>=2.28","marks":[{"type":"code"}]},{"type":"text","text":") in "},{"type":"text","text":"pyproject.toml","marks":[{"type":"code"}]},{"type":"text","text":" so it can coexist with other packages."}]}]}},"revision":1},{"id":"bd72c051-fb79-78ce-b71d-72ec34039f24","type":"callout","position":"aD","content":{"variant":"note","title":"Application","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pins "},{"type":"text","text":"exact","marks":[{"type":"bold"}]},{"type":"text","text":" versions of every package, including transitive ones, for reproducible deploys."}]}]}},"revision":1},{"id":"d1ee68c7-1057-72d7-8179-412e9a916e31","type":"callout","position":"aE","content":{"variant":"note","title":"requirements.txt","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A plain list, often produced by "},{"type":"text","text":"pip freeze","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"pip-compile","marks":[{"type":"code"}]},{"type":"text","text":". No hashes by default."}]}]}},"revision":1},{"id":"4488ff91-b84e-7d72-9fa1-dbcc4a54df63","type":"callout","position":"aF","content":{"variant":"note","title":"Lock files","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"uv.lock","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"poetry.lock","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pylock.toml","marks":[{"type":"code"}]},{"type":"text","text":" (PEP 751): exact versions + hashes for every platform, generated from your declared ranges."}]}]}},"revision":1},{"id":"a7aab76d-2c20-7a4f-9a33-c0819dae3ffc","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"pyproject.toml"}]},"revision":1},{"id":"7aec4f79-ce3f-7bc9-9651-af6576e0dbdb","type":"code","position":"aH","content":{"language":"python","code":"[project]\nname = \"lvn-notes\"\nversion = \"0.3.0\"\ndescription = \"Study notes toolkit\"\nreadme = \"README.md\"\nrequires-python = \">=3.10\"\ndependencies = [\"requests>=2.31\", \"rich~=13.7\"]\n\n[project.optional-dependencies]\ndev = [\"pytest>=8\", \"mypy\", \"ruff\"]\n\n[project.scripts]\nlvn = \"lvn_notes.cli:main\"          # installs an `lvn` command\n\n[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n\n[tool.ruff]\nline-length = 100","filename":"pyproject.toml"},"revision":1},{"id":"ef7cf01d-187e-7f42-be7c-553578b96dac","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s plain TOML, so the standard library can read it:"}]}]}},"revision":1},{"id":"01c043e0-e400-78b9-8d69-bc4223bf2463","type":"code","position":"aJ","content":{"language":"python","code":"import tomllib\n\ntext = \"\"\"\n[project]\nname = \"lvn-notes\"\nrequires-python = \">=3.10\"\ndependencies = [\"requests>=2.31\", \"rich~=13.7\"]\n[project.scripts]\nlvn = \"lvn_notes.cli:main\"\n\"\"\"\nmeta = tomllib.loads(text)[\"project\"]\nprint(meta[\"name\"], meta[\"dependencies\"])   # lvn-notes [''requests>=2.31'', ''rich~=13.7'']\nprint(tomllib.loads(text)[\"project\"][\"scripts\"][\"lvn\"])   # lvn_notes.cli:main","filename":"Python"},"revision":1},{"id":"549a2c23-593b-7809-899d-c730cd0db70d","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Project layout, editable installs & publishing"}]},"revision":1},{"id":"bb772cbd-e6ae-7b6f-b534-96511a448d52","type":"code","position":"aL","content":{"language":"","code":"lvn-notes/\n├── pyproject.toml\n├── README.md\n├── src/\n│   └── lvn_notes/\n│       ├── __init__.py\n│       └── cli.py\n└── tests/\n    └── test_cli.py","filename":"src layout"},"revision":1},{"id":"7f38923d-69c8-75a8-a984-da7402cc98af","type":"code","position":"aM","content":{"language":"","code":"(.venv) $ pip install -e \".[dev]\"      # editable: code changes apply without reinstalling\n(.venv) $ python -m pip install build twine\n(.venv) $ python -m build              # → dist/lvn_notes-0.3.0.tar.gz and .whl\n(.venv) $ twine upload dist/*          # publish to PyPI (use TestPyPI first)","filename":"Terminal"},"revision":1},{"id":"272955d0-0f19-7826-a882-2ee7cd8aae88","type":"callout","position":"aN","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"src/","marks":[{"type":"code"}]},{"type":"text","text":" layout stops tests from accidentally importing the package from the working directory — they must use the installed version, exactly like your users."}]}]}},"revision":1},{"id":"97d95a91-70af-7677-9f3c-bb7cd4cbf470","type":"table","position":"aO","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Artifact"}],[{"type":"text","text":"What it is"}]],[[{"type":"text","text":"sdist ("},{"type":"text","text":".tar.gz","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Source distribution — built on the user''s machine"}]],[[{"type":"text","text":"wheel ("},{"type":"text","text":".whl","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Pre-built zip that installs by just unpacking — fast; platform-specific if it contains C extensions"}]]]},"revision":1},{"id":"7d826710-ac3b-7bc1-8dd9-f20b8fe52bae","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"The tool landscape"}]},"revision":1},{"id":"caeb2db1-d68e-78c2-8b16-ce92c406c6b6","type":"table","position":"aQ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Tool"}],[{"type":"text","text":"Role"}]],[[{"type":"text","text":"venv","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"pip","marks":[{"type":"code"}]}],[{"type":"text","text":"Built in. Enough for most projects"}]],[[{"type":"text","text":"uv","marks":[{"type":"bold"}]}],[{"type":"text","text":"Very fast Rust replacement for pip / venv / pip-tools; manages Python versions and "},{"type":"text","text":"uv.lock","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"uv add","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"uv run","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Poetry","marks":[{"type":"bold"}]}],[{"type":"text","text":"Dependency management + lock file + build/publish in one tool"}]],[[{"type":"text","text":"pipx","marks":[{"type":"bold"}]}],[{"type":"text","text":"Installs CLI "},{"type":"text","text":"applications","marks":[{"type":"italic"}]},{"type":"text","text":" (black, httpie) each in its own isolated venv"}]],[[{"type":"text","text":"conda","marks":[{"type":"bold"}]}],[{"type":"text","text":"Environments with non-Python binaries too (CUDA, MKL) — popular in data science"}]],[[{"type":"text","text":"pyenv","marks":[{"type":"bold"}]}],[{"type":"text","text":"Install and switch between several Python versions"}]],[[{"type":"text","text":"pip-tools","marks":[{"type":"bold"}]}],[{"type":"text","text":"pip-compile","marks":[{"type":"code"}]},{"type":"text","text":" turns loose "},{"type":"text","text":"requirements.in","marks":[{"type":"code"}]},{"type":"text","text":" into pinned "},{"type":"text","text":"requirements.txt","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"5fa406a9-d4fe-7585-ba88-17adbc58968c","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use a virtual environment?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To isolate each project''s dependencies: different projects can need different versions of the same library, and installing into the system Python can break OS tools. A venv also makes the dependency list explicit and reproducible."}]}]}},"revision":1},{"id":"8d819b64-e483-7888-9724-fabbad281ba3","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between pip freeze output and pyproject.toml dependencies?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pyproject.toml","marks":[{"type":"code"}]},{"type":"text","text":" lists the "},{"type":"text","text":"direct","marks":[{"type":"italic"}]},{"type":"text","text":" dependencies with compatible ranges — what your code needs. "},{"type":"text","text":"pip freeze","marks":[{"type":"code"}]},{"type":"text","text":" lists "},{"type":"text","text":"every","marks":[{"type":"italic"}]},{"type":"text","text":" installed package at its exact version — a snapshot for reproducing one environment."}]}]}},"revision":1},{"id":"b1b5684c-c369-7c14-9105-998baba318f3","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does pip install -e . do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An editable (development) install: the package is registered in the environment but points at your source folder, so edits take effect immediately without reinstalling."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
