SELECT 'dcbff34a-cb36-792a-9b13-743a0da6c04b', '0932c5a9-c785-707f-9d75-db209293e872', 1, 'PUBLISHED', 'Pattern Matching (match)', '[{"id":"3612bc13-aa93-7f16-bc16-0a17ce6bbd13","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" (Python 3.10+) compares a value against a series of "},{"type":"text","text":"patterns","marks":[{"type":"italic"}]},{"type":"text","text":" — shapes, not just values — and binds the pieces it finds to names."}]}]}},"revision":1},{"id":"1b61f91d-8719-78a5-9cf1-b6abf3beebcd","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structural pattern matching","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"match subject:","marks":[{"type":"code"}]},{"type":"text","text":" followed by "},{"type":"text","text":"case pattern:","marks":[{"type":"code"}]},{"type":"text","text":" blocks. Cases are tried top to bottom; the "},{"type":"text","text":"first","marks":[{"type":"bold"}]},{"type":"text","text":" one that matches runs, and there is no fall-through."}]}]}},"revision":1},{"id":"7de5368a-a870-7440-a25a-42897d0373cb","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Literals, OR-patterns, "},{"type":"text","text":"as","marks":[{"type":"code"}]},{"type":"text","text":" and the wildcard"}]},"revision":1},{"id":"23ea9df6-cafd-77fe-a8d2-997dfe204a01","type":"code","position":"a3","content":{"language":"python","code":"def http_status(code):\n    match code:\n        case 200 | 201 | 204:            # OR-pattern\n            return \"success\"\n        case 301 | 302 as r:             # bind the matched value with as\n            return f\"redirect {r}\"\n        case 404:\n            return \"not found\"\n        case _:                          # wildcard: matches anything, binds nothing\n            return \"other\"\n\nprint(http_status(201), http_status(302))   # success redirect 302\nprint(http_status(404), http_status(500))   # not found other","filename":"Python"},"revision":1},{"id":"8dc25206-5c16-7f6a-9776-c8d0df943fcd","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Sequence patterns"}]},"revision":1},{"id":"b8f443c3-f105-7bb8-8584-9dad6edb0cb2","type":"code","position":"a5","content":{"language":"python","code":"def summarize(seq):\n    match seq:\n        case []:\n            return \"empty\"\n        case [x]:\n            return f\"one item: {x}\"\n        case [x, y]:\n            return f\"pair: {x}, {y}\"\n        case [first, *rest]:             # star captures the remainder as a list\n            return f\"{first} and {len(rest)} more\"\n\nprint(summarize([]))              # empty\nprint(summarize([7]))             # one item: 7\nprint(summarize((1, 2)))          # pair: 1, 2   ← tuples match list patterns too\nprint(summarize([1, 2, 3, 4]))    # 1 and 3 more\nprint(summarize(\"ab\"))            # None   ← str is NOT treated as a sequence here","filename":"Python"},"revision":1},{"id":"8de820c3-1903-7cde-8d1f-fda58cb545d9","type":"code","position":"a6","content":{"language":"python","code":"def fizzbuzz(n):\n    match (n % 3, n % 5):                # match a tuple built on the spot\n        case (0, 0): return \"FizzBuzz\"\n        case (0, _): return \"Fizz\"\n        case (_, 0): return \"Buzz\"\n        case _: return str(n)\n\nprint(\" \".join(fizzbuzz(i) for i in range(1, 16)))   # 1 2 Fizz 4 Buzz Fizz 7 8 Fizz Buzz 11 Fizz 13 14 FizzBuzz","filename":"Python"},"revision":1},{"id":"96d73b42-5acb-7a4e-bfb2-413c69f65d51","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Mapping patterns"}]},"revision":1},{"id":"663684be-637a-787e-abb9-bc666477a12f","type":"code","position":"a8","content":{"language":"python","code":"def handle(event):\n    match event:\n        case {\"type\": \"click\", \"x\": x, \"y\": y}:\n            return f\"click at ({x}, {y})\"\n        case {\"type\": \"key\", \"key\": str(k)} if len(k) == 1:\n            return f\"key {k!r}\"\n        case {\"type\": \"resize\", **rest}:\n            return f\"resize {rest}\"\n        case {\"type\": t}:\n            return f\"unhandled {t}\"\n\nprint(handle({\"type\": \"click\", \"x\": 3, \"y\": 4, \"ts\": 99}))   # click at (3, 4)   ← extra keys are ignored\nprint(handle({\"type\": \"key\", \"key\": \"q\"}))                  # key ''q''\nprint(handle({\"type\": \"resize\", \"w\": 800, \"h\": 600}))       # resize {''w'': 800, ''h'': 600}\nprint(handle({\"type\": \"scroll\"}))                           # unhandled scroll","filename":"Python"},"revision":1},{"id":"04db0b99-b8ea-7fcc-864d-be0da1719eec","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mapping patterns match if the listed keys are present — other keys are allowed. Sequence patterns are the opposite: the length must match exactly unless you use "},{"type":"text","text":"*rest","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b18695e2-84a9-7153-8b4e-415497a54af3","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Class patterns"}]},"revision":1},{"id":"9ca7ed26-774b-7a62-af6b-b8f8047d078c","type":"code","position":"aB","content":{"language":"python","code":"from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n    y: int\n\n@dataclass\nclass Circle:\n    center: Point\n    r: float\n\ndef where(shape):\n    match shape:\n        case Point(x=0, y=0):\n            return \"origin\"\n        case Point(0, y):                # positional → uses Point.__match_args__\n            return f\"on the y-axis at {y}\"\n        case Point(x, y) if x == y:      # guard\n            return \"on the diagonal\"\n        case Circle(Point(0, 0), r):     # patterns nest\n            return f\"circle of radius {r} at the origin\"\n        case Point() | Circle():         # just an isinstance check\n            return \"somewhere else\"\n        case _:\n            return \"not a shape\"\n\nprint(where(Point(0, 0)), \"|\", where(Point(0, 5)))        # origin | on the y-axis at 5\nprint(where(Point(3, 3)), \"|\", where(Circle(Point(0, 0), 2)))   # on the diagonal | circle of radius 2 at the origin\nprint(where(Point(1, 2)), \"|\", where(\"hi\"))               # somewhere else | not a shape\nprint(Point.__match_args__)                               # (''x'', ''y'')","filename":"Python"},"revision":1},{"id":"0166bf6f-4599-702e-90ae-bf74e20aac9e","type":"code","position":"aC","content":{"language":"python","code":"def kind(value):\n    match value:\n        case bool():                     # check bool before int — bool is a subclass of int\n            return \"bool\"\n        case int(n) if n < 0:            # built-ins match the whole value positionally\n            return \"negative int\"\n        case int() | float():\n            return \"number\"\n        case str() as s:\n            return f\"string of {len(s)}\"\n        case _:\n            return type(value).__name__\n\nprint(kind(True), kind(-4), kind(2.5), kind(\"abc\"), kind(None))   # bool negative int number string of 3 NoneType","filename":"Python"},"revision":1},{"id":"ce56dee2-970d-721f-ae4f-7b9cca85477b","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class pattern "},{"type":"text","text":"Cls(...)","marks":[{"type":"code"}]},{"type":"text","text":" first checks "},{"type":"text","text":"isinstance(subject, Cls)","marks":[{"type":"code"}]},{"type":"text","text":", then matches attributes: keyword sub-patterns by name, positional ones via the class''s "},{"type":"text","text":"__match_args__","marks":[{"type":"code"}]},{"type":"text","text":" tuple (generated automatically by "},{"type":"text","text":"@dataclass","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"namedtuple","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"bce06e47-6755-77b3-9dd9-e554a05705dd","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Guards"}]},"revision":1},{"id":"414a7a8e-89b0-78fe-a9a5-dbfc4b612066","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"case pattern if condition:","marks":[{"type":"code"}]},{"type":"text","text":" — the pattern must match "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" the condition must be truthy. Names bound by the pattern are available in the guard."}]}]}},"revision":1},{"id":"7edbcfdb-6663-720d-99fc-5eb3d242baeb","type":"code","position":"aG","content":{"language":"python","code":"def classify(pair):\n    match pair:\n        case (a, b) if a == b:\n            return \"equal\"\n        case (a, b) if a > b:\n            return \"descending\"\n        case (_, _):\n            return \"ascending\"\n\nprint(classify((2, 2)), classify((5, 1)), classify((1, 5)))   # equal descending ascending","filename":"Python"},"revision":1},{"id":"597fb0bf-6908-7dd7-b91f-9c7aba35fcb0","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"The capture-pattern trap"}]},"revision":1},{"id":"29d7356e-e202-7680-9dab-90a7169040b1","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"bare name","marks":[{"type":"bold"}]},{"type":"text","text":" in a pattern is a "},{"type":"text","text":"capture","marks":[{"type":"italic"}]},{"type":"text","text":": it matches anything and assigns to that name. To compare against a constant, use a "},{"type":"text","text":"dotted name","marks":[{"type":"bold"}]},{"type":"text","text":" (a value pattern) such as "},{"type":"text","text":"Color.RED","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"http.HTTPStatus.OK","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"197e8220-edef-7b59-a1f7-35386a8d7a8d","type":"code","position":"aJ","content":{"language":"python","code":"RED = \"red\"\n\ndef is_red(color):\n    match color:\n        case RED:                        # captures! binds a local RED = color\n            return True\n    return False\n\nprint(is_red(\"blue\"))                    # True   ← oops\n\nfrom enum import Enum\nclass Color(Enum):\n    RED = \"red\"\n    BLUE = \"blue\"\n\ndef is_red_fixed(color):\n    match color:\n        case Color.RED:                  # dotted name → compared with ==\n            return True\n        case _:\n            return False\n\nprint(is_red_fixed(Color.BLUE), is_red_fixed(Color.RED))   # False True","filename":"Python"},"revision":1},{"id":"fd3feeff-c018-70dd-a764-069153e6f451","type":"code","position":"aK","content":{"language":"python","code":"src = \"match x:\\n    case y:\\n        pass\\n    case 1:\\n        pass\\n\"\ntry:\n    compile(src, \"<demo>\", \"exec\")\nexcept SyntaxError as e:\n    print(e.msg)          # name capture ''y'' makes remaining patterns unreachable","filename":"Python"},"revision":1},{"id":"9d15bc7c-9823-7268-9c7e-d7fb51a6c10d","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Pattern kinds cheat sheet"}]},"revision":1},{"id":"ed8910f7-d077-7e2a-a156-ddf9b345ffca","type":"table","position":"aM","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pattern"}],[{"type":"text","text":"Example"}],[{"type":"text","text":"Matches"}]],[[{"type":"text","text":"Literal"}],[{"type":"text","text":"case 0:","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"case \"quit\":","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"case None:","marks":[{"type":"code"}]}],[{"type":"text","text":"Equal value ("},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":" compared with "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Capture"}],[{"type":"text","text":"case x:","marks":[{"type":"code"}]}],[{"type":"text","text":"Anything; binds "},{"type":"text","text":"x","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Wildcard"}],[{"type":"text","text":"case _:","marks":[{"type":"code"}]}],[{"type":"text","text":"Anything; binds nothing"}]],[[{"type":"text","text":"Value"}],[{"type":"text","text":"case Color.RED:","marks":[{"type":"code"}]}],[{"type":"text","text":"Equal to a dotted constant"}]],[[{"type":"text","text":"OR"}],[{"type":"text","text":"case 1 | 2 | 3:","marks":[{"type":"code"}]}],[{"type":"text","text":"Any alternative"}]],[[{"type":"text","text":"AS"}],[{"type":"text","text":"case [x, y] as pair:","marks":[{"type":"code"}]}],[{"type":"text","text":"The inner pattern; binds the whole subject too"}]],[[{"type":"text","text":"Sequence"}],[{"type":"text","text":"case [x, *rest]:","marks":[{"type":"code"}]}],[{"type":"text","text":"Lists/tuples (not "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":") of the right length"}]],[[{"type":"text","text":"Mapping"}],[{"type":"text","text":"case {\"id\": i}:","marks":[{"type":"code"}]}],[{"type":"text","text":"Dicts containing those keys; "},{"type":"text","text":"**rest","marks":[{"type":"code"}]},{"type":"text","text":" collects the others"}]],[[{"type":"text","text":"Class"}],[{"type":"text","text":"case Point(x, y=0):","marks":[{"type":"code"}]}],[{"type":"text","text":"isinstance","marks":[{"type":"code"}]},{"type":"text","text":" + attribute patterns"}]]]},"revision":1},{"id":"970327ba-c776-7eb5-969d-aa9a76cdbc58","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"When to use "},{"type":"text","text":"match","marks":[{"type":"code"}]}]},"revision":1},{"id":"028ebae4-711d-7b7d-b51d-2aca6fefbb9a","type":"callout","position":"aO","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" to branch on the "},{"type":"text","text":"shape","marks":[{"type":"bold"}]},{"type":"text","text":" of data: parsed commands, JSON events, AST nodes, tuples of states."}]}]}},"revision":1},{"id":"639f420c-81a1-7c90-8c0f-e1af47993453","type":"callout","position":"aP","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using it as a glorified "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" for simple value → value mapping — a "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" lookup is shorter and faster."}]}]}},"revision":1},{"id":"db95608b-b500-792b-a5b8-cabb11dbe388","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How is match different from a C/Java switch?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" compares one value against constants. "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" tests "},{"type":"text","text":"structure","marks":[{"type":"italic"}]},{"type":"text","text":": it can destructure lists, dicts and objects, bind variables, combine alternatives with "},{"type":"text","text":"|","marks":[{"type":"code"}]},{"type":"text","text":", and filter with guards. There is no fall-through and no "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" — the first matching case runs and the statement ends."}]}]}},"revision":1},{"id":"13199760-b44e-76d8-8b65-946aa3eab755","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does case RED: match every value?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bare name is a capture pattern: it always matches and binds the subject to "},{"type":"text","text":"RED","marks":[{"type":"code"}]},{"type":"text","text":". Constants must be referenced with a dotted name ("},{"type":"text","text":"Color.RED","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"module.RED","marks":[{"type":"code"}]},{"type":"text","text":") so Python treats them as value patterns compared with "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"04be7bb1-5a4a-72d1-8f54-c79227c4ecc3","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do positional class patterns like Point(0, y) work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python checks "},{"type":"text","text":"isinstance(subject, Point)","marks":[{"type":"code"}]},{"type":"text","text":", then maps positional sub-patterns to attribute names using "},{"type":"text","text":"Point.__match_args__","marks":[{"type":"code"}]},{"type":"text","text":" — here "},{"type":"text","text":"(''x'', ''y'')","marks":[{"type":"code"}]},{"type":"text","text":" — and matches "},{"type":"text","text":"subject.x","marks":[{"type":"code"}]},{"type":"text","text":" against "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" and binds "},{"type":"text","text":"subject.y","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":". Dataclasses and named tuples define "},{"type":"text","text":"__match_args__","marks":[{"type":"code"}]},{"type":"text","text":" automatically."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
