  ('23ea9df6-cafd-77fe-a8d2-997dfe204a01', 'a3', 'code', '{"language":"python","code":"def http_status(code):\n    match code:\n        case 200 | 201 | 204:            # OR-pattern\n            return \"success\"\n        case 301 | 302 as r:             # bind the matched value with as\n            return f\"redirect {r}\"\n        case 404:\n            return \"not found\"\n        case _:                          # wildcard: matches anything, binds nothing\n            return \"other\"\n\nprint(http_status(201), http_status(302))   # success redirect 302\nprint(http_status(404), http_status(500))   # not found other","filename":"Python"}'),
