INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '8677e733-5ef6-791d-8adc-2efb51425732', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('b1280265-e270-7acc-abd9-fb3048c7bfd3', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"@property","marks":[{"type":"code"}]},{"type":"text","text":" turns method calls into plain attribute access. Underneath it sits the "},{"type":"text","text":"descriptor protocol","marks":[{"type":"italic"}]},{"type":"text","text":" — the same mechanism that powers methods, "},{"type":"text","text":"classmethod","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"staticmethod","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__slots__","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"cached_property","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d2e12c08-09bb-7c2d-b56d-1a746014b81b', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"property recap: getter, setter, deleter"}]}'),
  ('fefe7f41-4d7c-76d1-9536-fadbc984bf68', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start with plain public attributes. When you later need validation or a computed value, swap in a "},{"type":"text","text":"property","marks":[{"type":"code"}]},{"type":"text","text":" — callers keep writing "},{"type":"text","text":"obj.attr","marks":[{"type":"code"}]},{"type":"text","text":" and nothing breaks. That is why Python code has no "},{"type":"text","text":"getX()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"setX()","marks":[{"type":"code"}]},{"type":"text","text":" boilerplate."}]}]}}'),
  ('a1e6dbac-2663-79bd-93a5-24cbf876e9b8', 'a3', 'code', '{"language":"python","code":"class Temperature:\n    def __init__(self, celsius):\n        self.celsius = celsius            # goes through the setter → validated from the start\n\n    @property\n    def celsius(self):                    # getter\n        return self._celsius\n\n    @celsius.setter\n    def celsius(self, value):             # setter: validation lives here\n        if value < -273.15:\n            raise ValueError(\"below absolute zero\")\n        self._celsius = value\n\n    @celsius.deleter\n    def celsius(self):                    # deleter: runs on `del t.celsius`\n        del self._celsius\n\n    @property\n    def fahrenheit(self):                 # computed and read-only (no setter)\n        return self._celsius * 9 / 5 + 32\n\nt = Temperature(100)\nprint(t.celsius, t.fahrenheit)            # 100 212.0\nt.celsius = 0\nprint(t.fahrenheit)                       # 32.0\ntry:\n    t.fahrenheit = 50\nexcept AttributeError as e:\n    print(type(e).__name__)               # AttributeError\ndel t.celsius\nprint(hasattr(t, \"_celsius\"))             # False","filename":"Python"}'),
  ('81ae7861-7bbb-78ab-9b48-99fe777ce2d3', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pattern"}],[{"type":"text","text":"How"}]],[[{"type":"text","text":"Read-only attribute"}],[{"type":"text","text":"@property","marks":[{"type":"code"}]},{"type":"text","text":" with no setter — assignment raises "},{"type":"text","text":"AttributeError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Validated attribute"}],[{"type":"text","text":"Setter checks the value, stores it in "},{"type":"text","text":"self._name","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Computed attribute"}],[{"type":"text","text":"Getter derives it from other fields — never goes stale"}]],[[{"type":"text","text":"Lazy + cached"}],[{"type":"text","text":"@functools.cached_property","marks":[{"type":"code"}]},{"type":"text","text":" — computed once, then stored"}]]]}'),
  ('577a3ccc-3e15-7689-9e5f-0b7c87673a23', 'a5', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside the getter, return "},{"type":"text","text":"self._celsius","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"self.celsius","marks":[{"type":"code"}]},{"type":"text","text":" — the latter calls the getter again and recurses until "},{"type":"text","text":"RecursionError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('0b4d974d-7eaa-78ab-8454-5497085d44e8', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"How "},{"type":"text","text":"obj.attr","marks":[{"type":"code"}]},{"type":"text","text":" is looked up"}]}'),
  ('ed1b6c88-54a9-79d7-a43b-fec15b958aaa', 'a7', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Descriptor","marks":[{"type":"bold"}]},{"type":"text","text":" — any object whose class defines "},{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__set__","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"__delete__","marks":[{"type":"code"}]},{"type":"text","text":", stored as a "},{"type":"text","text":"class","marks":[{"type":"bold"}]},{"type":"text","text":" attribute. Accessing it through an instance calls those methods instead of returning the object itself."}]}]}}'),
  ('b60e4a02-9bb7-764b-a96f-9e0ecf42689e', 'a8', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Defines"}],[{"type":"text","text":"Priority vs the instance "},{"type":"text","text":"__dict__","marks":[{"type":"code"}]}],[{"type":"text","text":"Examples"}]],[[{"type":"text","text":"Data","marks":[{"type":"bold"}]},{"type":"text","text":" descriptor"}],[{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"__set__","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"__delete__","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Wins over "},{"type":"text","text":"obj.__dict__","marks":[{"type":"code"}]}],[{"type":"text","text":"property","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__slots__","marks":[{"type":"code"}]},{"type":"text","text":" members"}]],[[{"type":"text","text":"Non-data","marks":[{"type":"bold"}]},{"type":"text","text":" descriptor"}],[{"type":"text","text":"only "},{"type":"text","text":"__get__","marks":[{"type":"code"}]}],[{"type":"text","text":"Loses to "},{"type":"text","text":"obj.__dict__","marks":[{"type":"code"}]}],[{"type":"text","text":"functions (methods), "},{"type":"text","text":"classmethod","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"staticmethod","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cached_property","marks":[{"type":"code"}]}]]]}'),
  ('62a72a56-2412-7918-a7c0-c43e6f74aac7', 'a9', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data descriptor on the class?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Search "},{"type":"text","text":"type(obj).__mro__","marks":[{"type":"code"}]},{"type":"text","text":". If the attribute found there is a data descriptor, call its "},{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":" and stop."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instance dictionary","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Otherwise, if the name is in "},{"type":"text","text":"obj.__dict__","marks":[{"type":"code"}]},{"type":"text","text":", return that value."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Non-data descriptor or class attribute","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Otherwise use what was found on the class: call "},{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":" if it has one, else return it as is."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"__getattr__","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" fallback","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Still nothing? Call "},{"type":"text","text":"__getattr__(name)","marks":[{"type":"code"}]},{"type":"text","text":" if the class defines it, else raise "},{"type":"text","text":"AttributeError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('8870472f-dcef-7b73-815a-80342b6d4172', 'aA', 'code', '{"language":"python","code":"class Demo:\n    @property\n    def p(self):\n        return \"property\"\n    def m(self):\n        return \"method\"\n\nd = Demo()\nd.__dict__[\"p\"] = \"instance value\"       # sneak values straight into the instance dict\nd.__dict__[\"m\"] = lambda: \"instance value\"\nprint(d.p)       # property        ← data descriptor beats the instance dict\nprint(d.m())     # instance value  ← the instance dict beats a non-data descriptor","filename":"Python"}'),
  ('c2117ac9-6368-7664-a2a4-20154113055b', 'aB', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All of this is implemented in "},{"type":"text","text":"object.__getattribute__","marks":[{"type":"code"}]},{"type":"text","text":", which runs for "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" attribute access."}]}]}}'),
  ('907f4633-f77f-744a-8729-4ad0d7f83f21', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Writing a reusable descriptor"}]}'),
  ('c7da5841-f165-7d39-bd79-093fa551eb36', 'aD', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A property is tied to one attribute of one class. When many attributes need the same rule, write the rule once as a descriptor class and reuse it."}]}]}}'),
  ('ee0440a3-899e-72f5-ac8c-2c2c0490de6c', 'aE', 'code', '{"language":"python","code":"class Positive:\n    \"\"\"A validated numeric field, reusable across classes.\"\"\"\n    def __set_name__(self, owner, name):      # called when the owning class is created\n        self.name = name\n        self.private = \"_\" + name\n\n    def __get__(self, obj, objtype=None):\n        if obj is None:                        # accessed on the class, not an instance\n            return self\n        return getattr(obj, self.private)\n\n    def __set__(self, obj, value):\n        if not isinstance(value, (int, float)) or value <= 0:\n            raise ValueError(f\"{self.name} must be a positive number, got {value!r}\")\n        setattr(obj, self.private, value)\n\nclass Product:\n    price = Positive()\n    qty = Positive()\n\n    def __init__(self, name, price, qty):\n        self.name, self.price, self.qty = name, price, qty\n\np = Product(\"pen\", 20, 3)\nprint(p.price * p.qty)            # 60\ntry:\n    p.qty = -1\nexcept ValueError as e:\n    print(e)                      # qty must be a positive number, got -1\nprint(Product.price.name)         # price\nprint(sorted(vars(p)))            # [''_price'', ''_qty'', ''name'']","filename":"Python"}'),
  ('25db2b4f-662b-77de-ae3f-181f9ed9c89a', 'aF', 'callout', '{"variant":"note","title":"__set_name__(owner, name)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tells the descriptor which attribute name it was assigned to (3.6+) — no need to repeat the name."}]}]}}'),
  ('e5596ffc-d101-70ad-b5aa-7f215d3cab18', 'aG', 'callout', '{"variant":"note","title":"__get__(obj, objtype)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"obj","marks":[{"type":"code"}]},{"type":"text","text":" is the instance, or "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" when accessed on the class — return "},{"type":"text","text":"self","marks":[{"type":"code"}]},{"type":"text","text":" then."}]}]}}'),
  ('5c5fa8d5-32e7-7378-a002-39cda0502c4a', 'aH', 'callout', '{"variant":"note","title":"__set__(obj, value)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Having it makes this a "},{"type":"text","text":"data","marks":[{"type":"italic"}]},{"type":"text","text":" descriptor, so it always intercepts assignment."}]}]}}'),
  ('0d143d2b-c836-72bc-8214-b74c88d39b06', 'aI', 'callout', '{"variant":"note","title":"Where to store the value","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On the instance ("},{"type":"text","text":"obj._name","marks":[{"type":"code"}]},{"type":"text","text":") — storing on the descriptor would share one value across all instances."}]}]}}'),
  ('a323445f-dc04-7f03-9f08-30069277b45e', 'aJ', 'heading', '{"level":1,"content":[{"type":"text","text":"Methods are descriptors too"}]}'),
  ('ad31884b-66c9-7bf8-8a31-414cac1f6572', 'aK', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function in a class body is a non-data descriptor. "},{"type":"text","text":"obj.method","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"function.__get__(obj, type(obj))","marks":[{"type":"code"}]},{"type":"text","text":", which returns a "},{"type":"text","text":"bound method","marks":[{"type":"bold"}]},{"type":"text","text":" with "},{"type":"text","text":"obj","marks":[{"type":"code"}]},{"type":"text","text":" pre-filled as "},{"type":"text","text":"self","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('01a35246-346a-7411-a3c5-496be3389a57', 'aL', 'code', '{"language":"python","code":"class Greeter:\n    def hello(self, name):\n        return f\"hi {name}\"\n\ng = Greeter()\nf = Greeter.__dict__[\"hello\"]           # the plain function stored in the class\nbound = f.__get__(g, Greeter)           # exactly what `g.hello` does\nprint(bound(\"asha\"))                    # hi asha\nprint(bound.__self__ is g)              # True\nprint(type(g.hello).__name__, type(Greeter.hello).__name__)   # method function\nprint(hasattr(property, \"__set__\"), hasattr(f, \"__set__\"))    # True False","filename":"Python"}'),
  ('3d6ab551-178b-75ac-81c7-633bbcd5c2d1', 'aM', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Built-in"}],[{"type":"text","text":"Descriptor kind"}],[{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":" returns"}]],[[{"type":"text","text":"function"}],[{"type":"text","text":"non-data"}],[{"type":"text","text":"a bound method (instance) or the function (class)"}]],[[{"type":"text","text":"classmethod","marks":[{"type":"code"}]}],[{"type":"text","text":"non-data"}],[{"type":"text","text":"a method bound to the "},{"type":"text","text":"class","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"staticmethod","marks":[{"type":"code"}]}],[{"type":"text","text":"non-data"}],[{"type":"text","text":"the underlying function, unbound"}]],[[{"type":"text","text":"property","marks":[{"type":"code"}]}],[{"type":"text","text":"data"}],[{"type":"text","text":"the getter''s result"}]],[[{"type":"text","text":"__slots__","marks":[{"type":"code"}]},{"type":"text","text":" entry"}],[{"type":"text","text":"data ("},{"type":"text","text":"member_descriptor","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"the value in the object''s fixed slot"}]]]}'),
  ('c4356195-4f79-79ac-a27a-77c8e7595a2a', 'aN', 'heading', '{"level":1,"content":[{"type":"text","text":"__getattr__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__getattribute__","marks":[{"type":"code"}]},{"type":"text","text":" & "},{"type":"text","text":"__setattr__","marks":[{"type":"code"}]}]}'),
  ('ce7794e3-1dfd-78e3-9c78-492e8c4eb198', 'aO', 'code', '{"language":"python","code":"class Config:\n    def __init__(self, **values):\n        object.__setattr__(self, \"_values\", values)   # bypass our own __setattr__\n\n    def __getattr__(self, name):          # only called when normal lookup FAILS\n        try:\n            return self._values[name]\n        except KeyError:\n            raise AttributeError(name) from None\n\n    def __setattr__(self, name, value):   # called for EVERY assignment\n        raise AttributeError(f\"Config is read-only ({name})\")\n\nc = Config(debug=True, level=3)\nprint(c.debug, c.level)                   # True 3\nprint(getattr(c, \"missing\", \"n/a\"))       # n/a\ntry:\n    c.level = 5\nexcept AttributeError as e:\n    print(e)                              # Config is read-only (level)","filename":"Python"}'),
