SELECT '2b263ae4-61b8-78a9-b20c-9fb96b4521b5', '18ea7c6e-55e4-7c58-b6c4-c85c0bc5b455', 1, 'PUBLISHED', 'What''s New: Python 3.8 → 3.14', '[{"id":"9373694d-820e-7322-9d9a-7b0dc439423c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The features added in each recent release — what interviewers mean by “modern Python”, and what you''ll see in current codebases."}]}]}},"revision":1},{"id":"9c849d30-da60-7f99-8375-c784a91cd9a8","type":"callout","position":"a1","content":{"variant":"note","title":"Release cadence","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A new Python 3.x ships every October and gets ~5 years of support. At the time of writing 3.14 is current and 3.9 and older are end-of-life. Check yours with "},{"type":"text","text":"python3 --version","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"sys.version_info","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c36976d3-541a-7fd0-b316-a8225ae03fc8","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"At a glance"}]},"revision":1},{"id":"1398659f-3ffa-79a3-90e0-2d49941a7ef1","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Version"}],[{"type":"text","text":"Headline features"}]],[[{"type":"text","text":"3.8","marks":[{"type":"bold"}]},{"type":"text","text":" (2019)"}],[{"type":"text","text":"Walrus "},{"type":"text","text":":=","marks":[{"type":"code"}]},{"type":"text","text":", positional-only params "},{"type":"text","text":"/","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"f\"{x=}\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"functools.cached_property","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"math.prod","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"isqrt","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3.9","marks":[{"type":"bold"}]},{"type":"text","text":" (2020)"}],[{"type":"text","text":"Dict merge "},{"type":"text","text":"|","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"|=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"str.removeprefix","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"removesuffix","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"list[int]","marks":[{"type":"code"}]},{"type":"text","text":" generics without "},{"type":"text","text":"typing","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"zoneinfo","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3.10","marks":[{"type":"bold"}]},{"type":"text","text":" (2021)"}],[{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" statement, "},{"type":"text","text":"X | Y","marks":[{"type":"code"}]},{"type":"text","text":" union types, "},{"type":"text","text":"zip(strict=True)","marks":[{"type":"code"}]},{"type":"text","text":", parenthesised "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":", much better error messages"}]],[[{"type":"text","text":"3.11","marks":[{"type":"bold"}]},{"type":"text","text":" (2022)"}],[{"type":"text","text":"10–60% faster CPython, "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"add_note","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"tomllib","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"asyncio.TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typing.Self","marks":[{"type":"code"}]},{"type":"text","text":", error locations with "},{"type":"text","text":"^^^","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3.12","marks":[{"type":"bold"}]},{"type":"text","text":" (2023)"}],[{"type":"text","text":"Type-parameter syntax "},{"type":"text","text":"def f[T]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":" alias statement, f-strings may reuse quotes and nest freely, "},{"type":"text","text":"itertools.batched","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"@override","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3.13","marks":[{"type":"bold"}]},{"type":"text","text":" (2024)"}],[{"type":"text","text":"New colourful REPL, experimental free-threaded build (no GIL) and JIT, "},{"type":"text","text":"copy.replace","marks":[{"type":"code"}]},{"type":"text","text":", removed old “dead battery” modules"}]],[[{"type":"text","text":"3.14","marks":[{"type":"bold"}]},{"type":"text","text":" (2025)"}],[{"type":"text","text":"Deferred evaluation of annotations, template strings "},{"type":"text","text":"t\"…\"","marks":[{"type":"code"}]},{"type":"text","text":", free-threading officially supported, "},{"type":"text","text":"except A, B","marks":[{"type":"code"}]},{"type":"text","text":" without brackets, "},{"type":"text","text":"concurrent.interpreters","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"compression.zstd","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"9fec3a0a-46f6-799a-bbe0-e53e075ffe4b","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"3.8 – 3.9: walrus, "},{"type":"text","text":"/","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":" debugging, dict union"}]},"revision":1},{"id":"20b8ae62-167a-7348-ac40-bb6b22c9b92a","type":"code","position":"a5","content":{"language":"python","code":"import re\n\n# Walrus: assign inside an expression — avoids calling twice\nif (m := re.search(r\"\\d+\", \"order 66 shipped\")):\n    print(m.group())                         # 66\n\n# Positional-only (/) and keyword-only (*) parameters\ndef clamp(x, /, lo=0, *, hi=10):\n    return max(lo, min(x, hi))\nprint(clamp(15), clamp(-3, lo=-1))           # 10 -1\n\n# Self-documenting f-strings\nwidth = 42\nprint(f\"{width=}, {width * 2 = }\")           # width=42, width * 2 = 84\n\n# 3.9: dict merge and prefix removal\ndefaults, user = {\"theme\": \"light\", \"size\": 12}, {\"size\": 14}\nprint(defaults | user)                       # {''theme'': ''light'', ''size'': 14}\nprint(\"test_login\".removeprefix(\"test_\"))    # login","filename":"Python"},"revision":1},{"id":"2ead3723-6c63-7490-8ff8-eed4040cc370","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"3.10: "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"X | Y","marks":[{"type":"code"}]},{"type":"text","text":", strict "},{"type":"text","text":"zip","marks":[{"type":"code"}]}]},"revision":1},{"id":"402de8c5-1cfb-7283-a332-252d79edfa96","type":"code","position":"a7","content":{"language":"python","code":"def http_status(code: int | None) -> str:        # union without typing.Union\n    match code:\n        case 200 | 201:\n            return \"ok\"\n        case 404:\n            return \"not found\"\n        case int(n) if n >= 500:\n            return \"server error\"\n        case None:\n            return \"no response\"\n        case _:\n            return \"other\"\n\nprint(http_status(201), http_status(503), http_status(None))   # ok server error no response\n\ntry:\n    list(zip([1, 2, 3], [\"a\", \"b\"], strict=True))              # catch length bugs early\nexcept ValueError as e:\n    print(e)                  # zip() argument 2 is shorter than argument 1","filename":"Python"},"revision":1},{"id":"143551cc-1691-7b66-9e4c-5e0e213408d7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"3.11: speed, exception groups, notes"}]},"revision":1},{"id":"79dda4f3-3cb0-7937-baea-a79c6802b1a7","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3.11 was the first release of the "},{"type":"text","text":"Faster CPython","marks":[{"type":"italic"}]},{"type":"text","text":" project — an adaptive, specialising interpreter that made typical code 10–60% faster with no changes. It also made concurrent failures first-class."}]}]}},"revision":1},{"id":"d977b4db-a54a-7d64-8bf9-b40b986aead8","type":"code","position":"aA","content":{"language":"python","code":"def validate(user):\n    errors = []\n    if not user.get(\"name\"):\n        errors.append(ValueError(\"name is required\"))\n    if user.get(\"age\", 0) < 0:\n        errors.append(ValueError(\"age must be >= 0\"))\n    if errors:\n        raise ExceptionGroup(\"invalid user\", errors)\n\ntry:\n    validate({\"age\": -1})\nexcept* ValueError as eg:                           # handles every ValueError in the group\n    print(len(eg.exceptions), eg.exceptions[0])     # 2 name is required\n\ntry:\n    int(\"x\")\nexcept ValueError as e:\n    e.add_note(\"while parsing the ''qty'' column\")    # extra context in the traceback\n    print(e.__notes__)                              # [\"while parsing the ''qty'' column\"]","filename":"Python"},"revision":1},{"id":"9209c075-fbfc-7031-b8dc-820ea42c076b","type":"code","position":"aB","content":{"language":"python","code":"import tomllib                                     # read TOML config (stdlib since 3.11)\ncfg = tomllib.loads(\"\"\"\n[tool.app]\ndebug = true\nworkers = 4\n\"\"\")\nprint(cfg[\"tool\"][\"app\"])                          # {''debug'': True, ''workers'': 4}","filename":"Python"},"revision":1},{"id":"e8d065bd-ac54-7719-bb29-7ff79c610060","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"3.12: generics syntax & f-string freedom"}]},"revision":1},{"id":"f3f1f3a5-ae5d-7cba-935d-3909ba8cca01","type":"code","position":"aD","content":{"language":"python","code":"from itertools import batched\n\ndef first[T](items: list[T]) -> T:          # no TypeVar boilerplate\n    return items[0]\n\nclass Stack[T]:\n    def __init__(self) -> None:\n        self._items: list[T] = []\n    def push(self, item: T) -> None:\n        self._items.append(item)\n    def pop(self) -> T:\n        return self._items.pop()\n\ntype Pair[T] = tuple[T, T]                  # lazily evaluated type alias\n\ns = Stack[int]()\ns.push(first([7, 8]))\nprint(s.pop(), Pair.__value__)              # 7 tuple[T, T]\n\nnames = [\"asha\", \"ravi\"]\nprint(f\"{\", \".join(names)}\")                # asha, ravi   ← same quotes inside, 3.12+\nprint(list(batched(\"abcdefg\", 3)))          # [(''a'', ''b'', ''c''), (''d'', ''e'', ''f''), (''g'',)]","filename":"Python"},"revision":1},{"id":"44f815df-5489-7d31-b355-a84a5f522c11","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"3.13: new REPL, free-threading, JIT"}]},"revision":1},{"id":"98553e50-1167-7dcb-8ac9-5d7520d07f62","type":"callout","position":"aF","content":{"variant":"note","title":"New interactive shell","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Colour, multi-line editing, history browsing, and "},{"type":"text","text":"exit","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"help","marks":[{"type":"code"}]},{"type":"text","text":" work without parentheses."}]}]}},"revision":1},{"id":"596cfd8b-3dde-7357-8b19-a4d15070298b","type":"callout","position":"aG","content":{"variant":"note","title":"Free-threaded build","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An optional "},{"type":"text","text":"python3.13t","marks":[{"type":"code"}]},{"type":"text","text":" build without the GIL, so threads can run Python code on several cores. Experimental in 3.13."}]}]}},"revision":1},{"id":"9fd35bab-6118-73ac-b6fb-c19bdc49f15c","type":"callout","position":"aH","content":{"variant":"note","title":"Experimental JIT","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A copy-and-patch JIT compiler, off by default — groundwork for future speed-ups."}]}]}},"revision":1},{"id":"50b0ff32-d236-7d18-bc2d-4cebada5429b","type":"callout","position":"aI","content":{"variant":"note","title":"copy.replace()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One function to make a modified copy of dataclasses, named tuples, "},{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":"s and more."}]}]}},"revision":1},{"id":"99265ec0-7077-77c1-b4d8-407a0ea3ee79","type":"code","position":"aJ","content":{"language":"python","code":"import copy\nfrom dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass Point:\n    x: int\n    y: int\n\np = Point(1, 2)\nprint(copy.replace(p, y=5))          # Point(x=1, y=5)","filename":"Python"},"revision":1},{"id":"e0e944a1-0074-7a2e-ba38-df711e932fe6","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"3.14: t-strings, lazy annotations, "},{"type":"text","text":"except A, B","marks":[{"type":"code"}]}]},"revision":1},{"id":"11d22c4e-e2ed-71f4-b5d8-6b0bd3c44854","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Template strings","marks":[{"type":"bold"}]},{"type":"text","text":" look like f-strings but produce a "},{"type":"text","text":"Template","marks":[{"type":"code"}]},{"type":"text","text":" object instead of a "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":", so a library can see the static text and the interpolated values separately — the safe way to build SQL, HTML or shell commands."}]}]}},"revision":1},{"id":"6a52bee6-24c4-792c-93da-3cd3bd88d893","type":"code","position":"aM","content":{"language":"python","code":"from string.templatelib import Template, Interpolation\n\ndef safe_html(tpl: Template) -> str:\n    out = []\n    for part in tpl:                              # static strings and Interpolations, in order\n        if isinstance(part, Interpolation):\n            out.append(str(part.value).replace(\"<\", \"&lt;\").replace(\">\", \"&gt;\"))\n        else:\n            out.append(part)\n    return \"\".join(out)\n\nuser = \"<script>\"\ntpl = t\"<p>Hello {user}</p>\"\nprint(type(tpl).__name__, tpl.values)             # Template (''<script>'',)\nprint(safe_html(tpl))                             # <p>Hello &lt;script&gt;</p>","filename":"Python"},"revision":1},{"id":"b2d277af-9a3b-7fc0-a3ba-f7bbb473e2c0","type":"code","position":"aN","content":{"language":"python","code":"# Annotations are evaluated lazily (only when asked for), so forward references just work:\ndef make_node() -> Node:          # Node isn''t defined yet — fine in 3.14\n    return Node()\n\nclass Node:\n    pass\n\nprint(type(make_node()).__name__)                 # Node\n\n# Several exception types without brackets (when there''s no \"as\"):\ntry:\n    int(None)\nexcept ValueError, TypeError:\n    print(\"bad input\")                            # bad input","filename":"Python"},"revision":1},{"id":"c57beb6c-bf64-7245-96d5-e46a8663cca0","type":"table","position":"aO","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Also in 3.14"}],[{"type":"text","text":"What it gives you"}]],[[{"type":"text","text":"Free-threaded build supported"}],[{"type":"text","text":"python3.14t","marks":[{"type":"code"}]},{"type":"text","text":" is no longer experimental (still optional; the default build keeps the GIL)"}]],[[{"type":"text","text":"concurrent.interpreters","marks":[{"type":"code"}]}],[{"type":"text","text":"Several isolated interpreters in one process — parallelism without separate processes"}]],[[{"type":"text","text":"compression.zstd","marks":[{"type":"code"}]}],[{"type":"text","text":"Zstandard compression in the standard library"}]],[[{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" warnings"}],[{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"continue","marks":[{"type":"code"}]},{"type":"text","text":" inside "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" now warns — it silently swallows exceptions"}]],[[{"type":"text","text":"Better errors"}],[{"type":"text","text":"Suggestions for mistyped keywords ("},{"type":"text","text":"whille","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":"?)"}]]]},"revision":1},{"id":"75c2d047-8e6e-7b00-902c-697c45c6f330","type":"callout","position":"aP","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a job description or codebase pins an older version, avoid the newer syntax: "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" needs 3.10, "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" 3.11, "},{"type":"text","text":"def f[T]","marks":[{"type":"code"}]},{"type":"text","text":" 3.12, t-strings 3.14. Check "},{"type":"text","text":"requires-python","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"pyproject.toml","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e8889e1b-5e95-7bd9-99a3-128140f15190","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name three features added to Python in the last few versions."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For example: structural pattern matching ("},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":", 3.10), exception groups with "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" and the big interpreter speed-up (3.11), the "},{"type":"text","text":"def f[T]","marks":[{"type":"code"}]},{"type":"text","text":" generics syntax (3.12), the optional no-GIL free-threaded build (3.13, supported in 3.14), and template strings "},{"type":"text","text":"t\"…\"","marks":[{"type":"code"}]},{"type":"text","text":" (3.14)."}]}]}},"revision":1},{"id":"dc23a0da-ccb0-7f24-acc7-0c3e05c385ac","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between an f-string and a t-string?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An f-string is evaluated immediately into a "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":". A t-string (3.14) evaluates the expressions but returns a "},{"type":"text","text":"Template","marks":[{"type":"code"}]},{"type":"text","text":" holding the literal parts and the values separately, so code can escape or transform the values before producing the final string — useful for preventing injection in SQL, HTML and shell commands."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
