FROM (VALUES
  ('30499ad4-33d9-7485-8482-7f69bffaeb01', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Turning Python objects into bytes or text and back — JSON for APIs, CSV for tables, TOML/INI for config, pickle for Python-only caches, and "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" for binary formats."}]}]}}'),
  ('dd668b31-f0ef-7521-9cd8-b5d7baa47732', 'a1', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Format"}],[{"type":"text","text":"Module"}],[{"type":"text","text":"Human-readable"}],[{"type":"text","text":"Cross-language"}],[{"type":"text","text":"Safe on untrusted input"}]],[[{"type":"text","text":"JSON"}],[{"type":"text","text":"json","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"CSV"}],[{"type":"text","text":"csv","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"TOML"}],[{"type":"text","text":"tomllib","marks":[{"type":"code"}]},{"type":"text","text":" (read-only)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"INI"}],[{"type":"text","text":"configparser","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Mostly"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"pickle"}],[{"type":"text","text":"pickle","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Python only","marks":[{"type":"bold"}]}],[{"type":"text","text":"No — can run code","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"SQLite"}],[{"type":"text","text":"sqlite3","marks":[{"type":"code"}]}],[{"type":"text","text":"No (queryable)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Packed binary"}],[{"type":"text","text":"struct","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes (you define the layout)"}],[{"type":"text","text":"Yes"}]]]}'),
  ('a5ce59cb-32c7-748c-98c5-53b9e7643d8c', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"JSON basics & type mapping"}]}'),
  ('ba30678b-b1af-7c37-be52-7bdeb2e2aeea', 'a3', 'code', '{"language":"python","code":"import json\nuser = {\"name\": \"Asha\", \"skills\": [\"python\", \"sql\"], \"active\": True, \"manager\": None}\ntext = json.dumps(user)                  # object → str\nprint(text)                              # {\"name\": \"Asha\", \"skills\": [\"python\", \"sql\"], \"active\": true, \"manager\": null}\nprint(json.loads(text)[\"skills\"][0])     # python\n\nprint(json.loads(json.dumps({1: (1, 2)})))   # {''1'': [1, 2]}   ← int keys become strings, tuples become lists","filename":"Python"}'),
  ('0a169208-6b63-79e3-9712-d956aff8e4ed', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Python"}],[{"type":"text","text":"JSON"}],[{"type":"text","text":"Back to Python"}]],[[{"type":"text","text":"dict","marks":[{"type":"code"}]}],[{"type":"text","text":"object "},{"type":"text","text":"{}","marks":[{"type":"code"}]}],[{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" (keys always "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"list","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"tuple","marks":[{"type":"code"}]}],[{"type":"text","text":"array "},{"type":"text","text":"[]","marks":[{"type":"code"}]}],[{"type":"text","text":"list","marks":[{"type":"code"}]}]],[[{"type":"text","text":"str","marks":[{"type":"code"}]}],[{"type":"text","text":"string"}],[{"type":"text","text":"str","marks":[{"type":"code"}]}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"float","marks":[{"type":"code"}]}],[{"type":"text","text":"number"}],[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"float","marks":[{"type":"code"}]}]],[[{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"False","marks":[{"type":"code"}]}],[{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"false","marks":[{"type":"code"}]}],[{"type":"text","text":"bool","marks":[{"type":"code"}]}]],[[{"type":"text","text":"None","marks":[{"type":"code"}]}],[{"type":"text","text":"null","marks":[{"type":"code"}]}],[{"type":"text","text":"None","marks":[{"type":"code"}]}]],[[{"type":"text","text":"set","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":", objects"}],[{"type":"text","text":"TypeError","marks":[{"type":"bold"}]}],[{"type":"text","text":"— convert first"}]]]}'),
  ('de43b423-fad7-7fbd-ae47-03a7560e48ca', 'a5', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dumps","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"loads","marks":[{"type":"code"}]},{"type":"text","text":" work with strings; "},{"type":"text","text":"dump(obj, f)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"load(f)","marks":[{"type":"code"}]},{"type":"text","text":" with open files."}]}]}}'),
  ('40392974-927d-77d2-966c-aadecc75bdeb', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Formatting options"}]}'),
  ('9948964d-5d9a-7134-ab82-56ed89d6d6bb', 'a7', 'code', '{"language":"python","code":"import json\ndata = {\"name\": \"Zoë\", \"tags\": [\"a\", \"b\"], \"id\": 7}\n\nprint(json.dumps(data))                                         # {\"name\": \"Zo\\u00eb\", \"tags\": [\"a\", \"b\"], \"id\": 7}\nprint(json.dumps(data, ensure_ascii=False, sort_keys=True))     # {\"id\": 7, \"name\": \"Zoë\", \"tags\": [\"a\", \"b\"]}\nprint(json.dumps(data, ensure_ascii=False, separators=(\",\", \":\")))   # {\"name\":\"Zoë\",\"tags\":[\"a\",\"b\"],\"id\":7}","filename":"Python"}'),
  ('a064a249-804f-70eb-8b6f-9e0e6455256e', 'a8', 'code', '{"language":"python","code":"import json\nprint(json.dumps({\"id\": 7, \"tags\": [\"a\", \"b\"]}, indent=2))","filename":"Python"}'),
  ('e193d6be-c75d-750a-8d82-2b6567bb69c9', 'a9', 'code', '{"language":"text","code":"{\n  \"id\": 7,\n  \"tags\": [\n    \"a\",\n    \"b\"\n  ]\n}","filename":"Output"}'),
  ('5e704ab5-455c-7199-a045-6cc8f49570a9', 'aA', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Option"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"indent=2","marks":[{"type":"code"}]}],[{"type":"text","text":"Pretty-print (config files, debugging)"}]],[[{"type":"text","text":"sort_keys=True","marks":[{"type":"code"}]}],[{"type":"text","text":"Stable key order — diff-friendly output, cache keys"}]],[[{"type":"text","text":"ensure_ascii=False","marks":[{"type":"code"}]}],[{"type":"text","text":"Keep non-ASCII characters instead of "},{"type":"text","text":"\\uXXXX","marks":[{"type":"code"}]},{"type":"text","text":" escapes"}]],[[{"type":"text","text":"separators=('','', '':'')","marks":[{"type":"code"}]}],[{"type":"text","text":"Most compact output (network payloads)"}]],[[{"type":"text","text":"default=fn","marks":[{"type":"code"}]}],[{"type":"text","text":"Called for objects JSON can''t encode"}]],[[{"type":"text","text":"allow_nan=False","marks":[{"type":"code"}]}],[{"type":"text","text":"Reject "},{"type":"text","text":"NaN","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"Infinity","marks":[{"type":"code"}]},{"type":"text","text":", which are not valid JSON"}]]]}'),
  ('578f83be-bbdd-744f-9c77-e06b69a76e6e', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Custom types: "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"object_hook","marks":[{"type":"code"}]}]}'),
  ('7f4646e4-fd00-7ef1-a3b8-623a9c2dcf77', 'aC', 'code', '{"language":"python","code":"import json\nfrom dataclasses import dataclass, asdict, is_dataclass\nfrom datetime import date\n\n@dataclass\nclass Event:\n    title: str\n    day: date\n    tags: set\n\ndef encode(obj):\n    if isinstance(obj, date):\n        return obj.isoformat()\n    if isinstance(obj, set):\n        return sorted(obj)\n    if is_dataclass(obj):\n        return asdict(obj)\n    raise TypeError(f\"{type(obj).__name__} is not JSON serializable\")\n\ntext = json.dumps(Event(\"launch\", date(2026, 9, 29), {\"b\", \"a\"}), default=encode)\nprint(text)                                  # {\"title\": \"launch\", \"day\": \"2026-09-29\", \"tags\": [\"a\", \"b\"]}\n\ndef decode(d):                               # called for every JSON object, innermost first\n    if \"day\" in d:\n        d[\"day\"] = date.fromisoformat(d[\"day\"])\n    return d\n\nback = json.loads(text, object_hook=decode)\nprint(back[\"day\"].year, type(back[\"day\"]).__name__)   # 2026 date","filename":"Python"}'),
  ('096ebbba-0d20-7534-8d45-d8d8a47a111b', 'aD', 'code', '{"language":"python","code":"import json\ntry:\n    json.loads(\"{''single'': ''quotes''}\")        # Python-style dict text is NOT JSON\nexcept json.JSONDecodeError as e:\n    print(e.msg, \"at position\", e.pos)        # Expecting property name enclosed in double quotes at position 1","filename":"Python"}'),
  ('ac91bfb4-e6c6-7e67-a67e-413ddc9de5dd', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"CSV: reading & writing"}]}'),
  ('e939ca3b-c41f-75dd-a30f-3aa192f89a72', 'aF', 'code', '{"language":"python","code":"import csv, io\n\nrows = [{\"name\": \"Asha\", \"city\": \"Pune, MH\"}, {\"name\": \"Ravi\", \"city\": ''Say \"hi\"''}]\nbuf = io.StringIO()\nwriter = csv.DictWriter(buf, fieldnames=[\"name\", \"city\"])\nwriter.writeheader()\nwriter.writerows(rows)\nprint(buf.getvalue().splitlines())   # [''name,city'', ''Asha,\"Pune, MH\"'', ''Ravi,\"Say \"\"hi\"\"\"'']   ← commas and quotes are escaped for you\n\nreader = csv.reader(io.StringIO(buf.getvalue()))\nheader = next(reader)\nprint(header, list(reader))       # [''name'', ''city''] [[''Asha'', ''Pune, MH''], [''Ravi'', ''Say \"hi\"'']]\n\nraw = \"name,score\\nasha,91\\nravi,84\\n\"\nscores = [int(r[\"score\"]) for r in csv.DictReader(io.StringIO(raw))]\nprint(sum(scores) / len(scores))  # 87.5","filename":"Python"}'),
  ('dad1bafd-7029-76e9-b1fa-0f2e05126d07', 'aG', 'code', '{"language":"python","code":"import csv, io\ntsv = \"a\\tb\\n1\\t2\\n\"\nprint(list(csv.reader(io.StringIO(tsv), delimiter=\"\\t\")))    # [[''a'', ''b''], [''1'', ''2'']]\n\nbuf = io.StringIO()\ncsv.writer(buf, quoting=csv.QUOTE_NONNUMERIC, lineterminator=\"\\n\").writerow([\"x\", 1.5, 2])\nprint(buf.getvalue().strip())                                # \"x\",1.5,2","filename":"Python"}'),
  ('4e163469-c262-79e5-ae2d-3d83d361276d', 'aH', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open CSV files with "},{"type":"text","text":"open(path, \"w\", newline=\"\", encoding=\"utf-8\")","marks":[{"type":"code"}]},{"type":"text","text":". Without "},{"type":"text","text":"newline=\"\"","marks":[{"type":"code"}]},{"type":"text","text":" you get blank lines between rows on Windows. And never split lines on "},{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":" by hand — quoted fields contain commas."}]}]}}'),
  ('986581c0-c25b-70f0-a48c-a9c1668ddd65', 'aI', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every CSV value is read as a "},{"type":"text","text":"string","marks":[{"type":"bold"}]},{"type":"text","text":" — convert types yourself. For heavy tabular work use pandas ("},{"type":"text","text":"pd.read_csv","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('60d4805e-18c9-7c95-949d-8c2e10dd2e7b', 'aJ', 'heading', '{"level":1,"content":[{"type":"text","text":"pickle — Python objects as bytes"}]}'),
  ('6376bfa6-1604-75b0-80cf-31aa21856692', 'aK', 'code', '{"language":"python","code":"import pickle\n\ndata = {\"ids\": (1, 2, 3), \"tags\": {\"py\"}, \"nested\": [b\"raw\", None, 3.5]}\nblob = pickle.dumps(data)                    # tuples, sets, bytes: all preserved\nrestored = pickle.loads(blob)\nprint(type(blob).__name__, restored == data, type(restored[\"ids\"]).__name__)   # bytes True tuple","filename":"Python"}'),
  ('9ecf7d75-5a80-7647-9783-d0c523cc4d68', 'aL', 'callout', '{"variant":"warning","title":"Security","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never unpickle data from an untrusted source.","marks":[{"type":"bold"}]},{"type":"text","text":" A pickle can instruct the loader to call any function (via "},{"type":"text","text":"__reduce__","marks":[{"type":"code"}]},{"type":"text","text":"), i.e. run arbitrary code. Use JSON for anything that crosses a trust boundary."}]}]}}'),
  ('d196992d-f05e-70c6-82df-d7129eac0615', 'aM', 'callout', '{"variant":"note","title":"How it stores classes","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By "},{"type":"text","text":"import path","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"module.ClassName","marks":[{"type":"code"}]},{"type":"text","text":"), not code — the class must be importable when loading, and renaming it breaks old pickles."}]}]}}'),
  ('fc264683-d80f-749d-be7b-3322e30133ac', 'aN', 'callout', '{"variant":"note","title":"Good uses","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Caching intermediate results, passing objects between your own processes ("},{"type":"text","text":"multiprocessing","marks":[{"type":"code"}]},{"type":"text","text":" uses pickle)."}]}]}}'),
  ('1fe4efd4-aa43-7a8f-a9d5-6c9238479def', 'aO', 'callout', '{"variant":"note","title":"Bad uses","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Long-term storage, APIs, anything shared across Python versions or teams."}]}]}}'),
  ('6b8508d5-fbfa-7796-bea4-308f09151ad3', 'aP', 'callout', '{"variant":"note","title":"shelve","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A persistent dict backed by pickle: "},{"type":"text","text":"with shelve.open(''cache'') as db: db[''k''] = obj","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d5d59f5c-b5d0-759c-9ae0-ceb25f2e536d', 'aQ', 'heading', '{"level":1,"content":[{"type":"text","text":"sqlite3 — a database in the standard library"}]}'),
  ('35486903-478f-7c3d-9d43-403c37ddf6e8', 'aR', 'code', '{"language":"python","code":"import sqlite3\n\ncon = sqlite3.connect(\":memory:\")            # or a file path\ncon.execute(\"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)\")\nwith con:                                    # commits on success, rolls back on error\n    con.executemany(\"INSERT INTO users (name) VALUES (?)\", [(\"Asha\",), (\"Ravi\",)])\nprint(con.execute(\"SELECT id, name FROM users ORDER BY id\").fetchall())   # [(1, ''Asha''), (2, ''Ravi'')]\nprint(con.execute(\"SELECT name FROM users WHERE id = ?\", (2,)).fetchone())  # (''Ravi'',)\ncon.close()","filename":"Python"}'),
  ('7d49f2ea-565c-7d87-baed-0d19b71f6b45', 'aS', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always pass values as parameters ("},{"type":"text","text":"?","marks":[{"type":"code"}]},{"type":"text","text":"), never with f-strings — string-built SQL is an injection hole."}]}]}}'),
  ('e9440ad3-1fbc-7baf-9635-3273e0c93067', 'aT', 'heading', '{"level":1,"content":[{"type":"text","text":"Config files: TOML & INI"}]}'),
  ('77e63127-fe47-70f3-adf1-5336d26ebfe1', 'aU', 'code', '{"language":"python","code":"import tomllib, configparser\n\ncfg = tomllib.loads(\"\"\"\n[server]\nhost = \"0.0.0.0\"\nport = 8080\ndebug = false\n\n[database]\npool = { min = 1, max = 5 }\n\"\"\")\nprint(cfg[\"server\"][\"port\"], cfg[\"server\"][\"debug\"], cfg[\"database\"][\"pool\"][\"max\"])   # 8080 False 5\n\ncp = configparser.ConfigParser()\ncp.read_string(\"\"\"\n[app]\nname = notes\nworkers = 4\ndebug = yes\n\"\"\")\nprint(cp[\"app\"][\"name\"], cp.getint(\"app\", \"workers\"), cp.getboolean(\"app\", \"debug\"))   # notes 4 True","filename":"Python"}'),
  ('376d251c-7db2-78b0-b168-708c95e2de5f', 'aV', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"TOML has real types (ints, booleans, dates, arrays); INI values are all strings until you call "},{"type":"text","text":"getint","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"getboolean","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"tomllib","marks":[{"type":"code"}]},{"type":"text","text":" (3.11+) only reads — write TOML with the third-party "},{"type":"text","text":"tomli-w","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"tomllib.load","marks":[{"type":"code"}]},{"type":"text","text":" with a file opened in "},{"type":"text","text":"binary","marks":[{"type":"bold"}]},{"type":"text","text":" mode."}]}]}}'),
  ('fc039ada-ca1c-78c6-ab78-6a1d5c795152', 'aW', 'heading', '{"level":1,"content":[{"type":"text","text":"Binary layouts with struct"}]}'),
  ('f18f7c39-d04c-7403-9cf7-c961111ae287', 'aX', 'code', '{"language":"python","code":"import struct\n\n# \"<\" little-endian, H = unsigned 16-bit, I = unsigned 32-bit, f = 32-bit float\npacked = struct.pack(\"<HIf\", 7, 65536, 1.5)\nprint(len(packed), packed.hex())             # 10 0700000001000000c03f\nprint(struct.unpack(\"<HIf\", packed))         # (7, 65536, 1.5)\nprint(struct.calcsize(\"<HIf\"), struct.calcsize(\"HIf\"))   # 10 12   ← native mode adds alignment padding","filename":"Python"}'),
  ('aeb2a4ab-1afb-7e6f-bd0b-b89d5d51fe32', 'aY', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JSON vs pickle — when would you use each?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JSON for data exchanged with other programs or stored long-term: it''s text, language-neutral and safe to parse. Pickle only for short-lived, trusted, Python-to-Python data (caches, IPC) — it handles almost any Python object but is insecure and version-fragile."}]}]}}'),
  ('563b332b-06e7-7c88-9fa6-16749e0ae4dd', 'aZ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you serialize a datetime or a custom object to JSON?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pass "},{"type":"text","text":"default=","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"json.dumps","marks":[{"type":"code"}]},{"type":"text","text":" — a function that converts unsupported objects (e.g. "},{"type":"text","text":"dt.isoformat()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dataclasses.asdict(obj)","marks":[{"type":"code"}]},{"type":"text","text":") — or subclass "},{"type":"text","text":"json.JSONEncoder","marks":[{"type":"code"}]},{"type":"text","text":". Decode with "},{"type":"text","text":"object_hook=","marks":[{"type":"code"}]},{"type":"text","text":" to turn the dicts back into rich types."}]}]}}')
) AS c(id, position, type, content)
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '376da8bd-4423-7e49-bcdf-22b2b1b420ea' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
