FROM (VALUES
  ('0f7a1c19-e25e-7e6b-9f81-10898da41ab9', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s sort is fast (Timsort), "},{"type":"text","text":"stable","marks":[{"type":"bold"}]},{"type":"text","text":", and customised with a "},{"type":"text","text":"key","marks":[{"type":"code"}]},{"type":"text","text":" function — rarely with a comparator. Master "},{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":" and most ordering problems become one line."}]}]}}'),
  ('721227ae-cfda-7c94-9144-79d8926b0283', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"sorted()","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"list.sort()","marks":[{"type":"code"}]}]}'),
  ('7ed7828f-f125-7f13-8cb6-733f0570bde8', 'a2', 'code', '{"language":"python","code":"nums = [5, 2, 9, 1]\nprint(sorted(nums), nums)          # [1, 2, 5, 9] [5, 2, 9, 1]\nresult = nums.sort(reverse=True)   # in place\nprint(result, nums)                # None [9, 5, 2, 1]\nprint(sorted(\"hello\"))             # [''e'', ''h'', ''l'', ''l'', ''o'']\nprint(sorted({\"b\": 1, \"a\": 2}))    # [''a'', ''b'']   ← iterating a dict gives keys","filename":"Python"}'),
  ('b96e5650-d2c3-7446-b29d-3258c396625f', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"sorted(iterable)","marks":[{"type":"code"}]}],[{"type":"text","text":"lst.sort()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Works on"}],[{"type":"text","text":"Any iterable (str, dict, set, generator…)"}],[{"type":"text","text":"Lists only"}]],[[{"type":"text","text":"Returns"}],[{"type":"text","text":"A "},{"type":"text","text":"new","marks":[{"type":"bold"}]},{"type":"text","text":" list"}],[{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" — sorts in place"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"Copies the data"}],[{"type":"text","text":"No extra list"}]],[[{"type":"text","text":"Options"}],[{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reverse=","marks":[{"type":"code"}]}],[{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reverse=","marks":[{"type":"code"}]}]]]}'),
  ('9cb700af-011f-7e1b-a4b4-b7d955558340', 'a4', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"xs = xs.sort()","marks":[{"type":"code"}]},{"type":"text","text":" sets "},{"type":"text","text":"xs","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". Either "},{"type":"text","text":"xs.sort()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"xs = sorted(xs)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('accd2902-79f9-7ae5-89d8-b71bc714474a', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"key","marks":[{"type":"code"}]},{"type":"text","text":" function"}]}'),
  ('eb60ff34-9365-7dac-b585-fa08573f9e5a', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"key","marks":[{"type":"code"}]},{"type":"text","text":" is called "},{"type":"text","text":"once per item","marks":[{"type":"bold"}]},{"type":"text","text":"; items are ordered by those computed keys. Any callable works: a built-in, a method, a lambda, an "},{"type":"text","text":"operator","marks":[{"type":"code"}]},{"type":"text","text":" helper."}]}]}}'),
  ('bde2d9f1-5f71-70b4-b4ca-a00d41952f93', 'a7', 'code', '{"language":"python","code":"words = [\"banana\", \"Apple\", \"fig\", \"cherry\"]\nprint(sorted(words))                           # [''Apple'', ''banana'', ''cherry'', ''fig'']\nprint(sorted(words, key=str.lower))            # [''Apple'', ''banana'', ''cherry'', ''fig'']\nprint(sorted(words, key=len))                  # [''fig'', ''Apple'', ''banana'', ''cherry'']\nprint(sorted(words, key=lambda w: w[-1]))      # [''banana'', ''Apple'', ''fig'', ''cherry'']\nprint(sorted([-4, 1, -2, 3], key=abs))         # [1, -2, 3, -4]","filename":"Python"}'),
  ('ec895d4c-150d-7db5-a1de-a4082c44f007', 'a8', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Uppercase letters sort before lowercase ("},{"type":"text","text":"''Z'' < ''a''","marks":[{"type":"code"}]},{"type":"text","text":") because strings compare by code point. Use "},{"type":"text","text":"key=str.lower","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"str.casefold","marks":[{"type":"code"}]},{"type":"text","text":" for full Unicode) for human order."}]}]}}'),
  ('9f67dbaf-6832-7509-9020-1ff93ed7757b', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Multi-level ordering"}]}'),
  ('16b94791-ee69-7d95-b5a0-1b0c05be8339', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return a "},{"type":"text","text":"tuple","marks":[{"type":"bold"}]},{"type":"text","text":" from the key: ties on the first element fall through to the second. Negate numbers to flip one level to descending."}]}]}}'),
  ('04f2c183-1b3d-7f2e-b257-dfb7393ddfcd', 'aB', 'code', '{"language":"python","code":"students = [(\"asha\", 90, 21), (\"ravi\", 85, 22), (\"kiran\", 90, 20), (\"meera\", 85, 20)]\n\n# marks descending, then name ascending\nprint([s[0] for s in sorted(students, key=lambda s: (-s[1], s[0]))])\n# [''asha'', ''kiran'', ''meera'', ''ravi'']","filename":"Python"}'),
  ('8c587982-85b3-7700-b99b-dee76f6b37f9', 'aC', 'code', '{"language":"text","code":"[''asha'', ''kiran'', ''meera'', ''ravi'']","filename":"Output"}'),
  ('d75255b2-c2e5-7f96-9d60-a9c1a223565b', 'aD', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can''t negate a string? Use "},{"type":"text","text":"stability","marks":[{"type":"bold"}]},{"type":"text","text":": sort by the secondary key first, then by the primary key. Each pass keeps the previous order among ties."}]}]}}'),
  ('ce6608e8-cb91-7fe4-9f40-22f37380e9de', 'aE', 'code', '{"language":"python","code":"people = [(\"asha\", \"dev\"), (\"ravi\", \"ops\"), (\"kiran\", \"dev\"), (\"meera\", \"ops\")]\nby_name_desc = sorted(people, key=lambda p: p[0], reverse=True)   # secondary first\nresult = sorted(by_name_desc, key=lambda p: p[1])                 # then primary\nprint(result)   # [(''kiran'', ''dev''), (''asha'', ''dev''), (''ravi'', ''ops''), (''meera'', ''ops'')]","filename":"Python"}'),
