  ('b176b871-dd08-74fc-8c50-508f8409ce29', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"random & statistics"}]}'),
  ('9097ba9e-7bcd-7aa5-8104-8544ab445e26', 'a4', 'code', '{"language":"python","code":"import random, statistics\n\nrandom.seed(42)                         # same seed → same sequence (reproducible experiments)\nfirst = [random.randint(1, 6) for _ in range(5)]\nrandom.seed(42)\nprint(first == [random.randint(1, 6) for _ in range(5)])   # True\n\nrng = random.Random(7)                  # an independent generator with its own state\ndeck = list(\"AKQJ\")\nrng.shuffle(deck)                       # in place\nprint(len(rng.sample(range(100), 3)), rng.choice(deck) in deck)   # 3 True\n\ndata = [2, 4, 4, 4, 5, 5, 7, 9]\nprint(statistics.mean(data), statistics.median(data), statistics.mode(data))   # 5 4.5 4\nprint(statistics.pstdev(data), round(statistics.stdev(data), 3))             # 2.0 2.138","filename":"Python"}'),
  ('05dceace-cf2a-71dc-96b0-55a2d7a52548', 'a5', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"random","marks":[{"type":"code"}]},{"type":"text","text":" is predictable by design — never use it for passwords, tokens or anything security-related. Use "},{"type":"text","text":"secrets","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('2c6e87a7-1140-7838-b63b-7eb0a350b5e6', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"secrets, hashlib, uuid, base64"}]}'),
  ('8de05005-79cc-7eee-917a-d92e329af799', 'a7', 'code', '{"language":"python","code":"import secrets, hashlib, hmac, uuid, base64\n\ntoken = secrets.token_urlsafe(16)                  # unpredictable, URL-safe\nprint(len(token) >= 16)                            # True\nprint(secrets.compare_digest(\"abc\", \"abc\"))        # True   ← constant-time comparison\n\nprint(hashlib.sha256(b\"hello\").hexdigest()[:16])   # 2cf24dba5fb0a30e\nsig = hmac.new(b\"secret-key\", b\"payload\", hashlib.sha256).hexdigest()\nprint(len(sig))                                    # 64\n\nu = uuid.uuid4()                                   # random unique id\nprint(u.version, len(str(u)))                      # 4 36\n\nencoded = base64.b64encode(b\"hi there\")\nprint(encoded, base64.b64decode(encoded))          # b''aGkgdGhlcmU='' b''hi there''","filename":"Python"}'),
  ('ff21f0da-8e04-774c-9f74-fa6b85aa0ebc', 'a8', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash passwords with a slow, salted algorithm — "},{"type":"text","text":"hashlib.scrypt","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"pbkdf2_hmac","marks":[{"type":"code"}]},{"type":"text","text":" (or the "},{"type":"text","text":"argon2","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"bcrypt","marks":[{"type":"code"}]},{"type":"text","text":" packages) — never plain "},{"type":"text","text":"sha256","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
