ype":"text","text":"!s","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"!a","marks":[{"type":"code"}]}],[{"type":"text","text":"repr()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"str()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ascii()","marks":[{"type":"code"}]},{"type":"text","text":" of the value"}]],[[{"type":"text","text":"Format spec"}],[{"type":"text","text":"{expr:spec}","marks":[{"type":"code"}]}],[{"type":"text","text":"f''{pi:.3f}''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Self-documenting"}],[{"type":"text","text":"{expr=}","marks":[{"type":"code"}]}],[{"type":"text","text":"f''{x=}''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"x=5","marks":[{"type":"code"}]},{"type":"text","text":" (3.8+)"}]],[[{"type":"text","text":"Nested spec"}],[{"type":"text","text":"{expr:{width}.{prec}f}","marks":[{"type":"code"}]}],[{"type":"text","text":"Width/precision from variables"}]],[[{"type":"text","text":"Literal brace"}],[{"type":"text","text":"{{","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"}}","marks":[{"type":"code"}]}],[{"type":"text","text":"f''{{x}}''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"{x}","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"534756ed-c46d-7c9f-918a-9209e1ca8b63","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Debugging with "},{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":" and conversions"}]},"revision":1},{"id":"a55b3eac-81ad-7054-82f9-84157b1f8bea","type":"code","position":"a5","content":{"language":"python","code":"x, word = 42, \"café\"\nprint(f\"{x=}\")                  # x=42\nprint(f\"{x * 2 = }\")            # x * 2 = 84\nprint(f\"{word=}\")               # word=''café''   ← = uses repr() by default\nprint(f\"{word!s}\", f\"{word!r}\", f\"{word!a}\")   # café ''café'' ''caf\\xe9''\nprint(f\"{x = :>6}|\")            # x =     42|","filename":"Python"},"revision":1},{"id":"5ec43983-0639-75cc-9bb5-0f1323b9926c","type":"callout","position":"a6","content":{"variant":"note","title":"Tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"{x=}","marks":[{"type":"code"}]},{"type":"text","text":" prints the expression text, then the value''s "},{"type":"text","text":"repr()","marks":[{"type":"code"}]},{"type":"text","text":" — the quickest print-debugging tool in Python."}]}]}},"revision":1},{"id":"9690dbe5-a672-7c8f-b1ab-e038dd8069bf","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"The format-spec mini-language"}]},"revision":1},{"id":"a178fed3-561e-7e4c-b45e-052732b0e78f","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[[fill]align][sign][z][#][0][width][grouping][.precision][type]","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"0121ca99-bd44-7953-83e6-4206fe5ed918","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Field"}],[{"type":"text","text":"Options"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"fill"}],[{"type":"text","text":"any character"}],[{"type":"text","text":"Pad character (needs an align after it)"}]],[[{"type":"text","text":"align"}],[{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"^","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"=","marks":[{"type":"code"}]}],[{"type":"text","text":"Left / right / centre / pad after the sign"}]],[[{"type":"text","text":"sign"}],[{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"-","marks":[{"type":"code"}]},{"type":"text","text":" space"}],[{"type":"text","text":"Always show sign / only negatives (default) / space for positives"}]],[[{"type":"text","text":"#","marks":[{"type":"code"}]}],[],[{"type":"text","text":"Alternate form: "},{"type":"text","text":"0b","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"0o","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"0x","marks":[{"type":"code"}]},{"type":"text","text":" prefixes"}]],[[{"type":"text","text":"0","marks":[{"type":"code"}]}],[],[{"type":"text","text":"Zero-pad numbers (sign-aware)"}]],[[{"type":"text","text":"width"}],[{"type":"text","text":"integer"}],[{"type":"text","text":"Minimum field width"}]],[[{"type":"text","text":"grouping"}],[{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"_","marks":[{"type":"code"}]}],[{"type":"text","text":"Thousands separator"}]],[[{"type":"text","text":".precision"}],[{"type":"text","text":"integer"}],[{"type":"text","text":"Digits after the point ("},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":"), significant digits ("},{"type":"text","text":"g","marks":[{"type":"code"}]},{"type":"text","text":"), or max chars for strings"}]],[[{"type":"text","text":"type"}],[{"type":"text","text":"d b o x X e f g % n s c","marks":[{"type":"code"}]}],[{"type":"text","text":"Presentation: decimal, binary, octal, hex, exponent, fixed, general, percent…"}]]]},"revision":1},{"id":"62492508-d951-7a6d-9ba4-b871d0884170","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Alignment & padding"}]},"revision":1},{"id":"bca840a3-3b51-75a4-9e18-118d361e8c28","type":"code","position":"aB","content":{"language":"python","code":"s = \"py\"\nprint(f\"[{s:<6}] [{s:>6}] [{s:^6}]\")      # [py    ] [    py] [  py  ]\nprint(f\"[{s:*^8}] [{s:->5}]\")             # [***py***] [---py]\nprint(f\"[{42:5}] [{''ab'':5}]\")             # [   42] [ab   ]   ← numbers right, strings left by default\nprint(f\"[{-42:=+7}] [{-42:07}]\")          # [-    42] [-000042]\nprint(f\"[{''truncate me'':.5}]\")            # [trunc]","filename":"Python"},"revision":1},{"id":"8e74594b-cb53-70c4-bd8f-8f6e37712c26","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Numbers: precision, signs, grouping"}]},"revision":1},{"id":"ef87265e-35d5-73cc-a3b7-4ca00cbb8420","type":"code","position":"aD","content":{"language":"python","code":"pi, big, ratio = 3.14159265, 1234567.891, 0.4567\nprint(f\"{pi:.2f} {pi:.4f} {pi:8.3f}|\")    # 3.14 3.1416    3.142|\nprint(f\"{big:,.2f} {big:_.1f}\")           # 1,234,567.89 1_234_567.9\nprint(f\"{ratio:.1%} {ratio:%}\")           # 45.7% 45.670000%\nprint(f\"{big:e} {big:.2e}\")               # 1.234568e+06 1.23e+06\nprint(f\"{pi:g} {big:g} {0.00001234:g}\")   # 3.14159 1.23457e+06 1.234e-05\nprint(f\"{5:+d} {-5:+d} {5: d}\")           # +5 -5  5\nprint(f\"{1_000_000:,}\")                   # 1,000,000","filename":"Python"},"revision":1},{"id":"3a5b090a-9668-74d0-8d94-bcf95e07fe08","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Integers in other bases"}]},"revision":1},{"id":"42789acd-eded-7906-9365-9dcf436fd796","type":"code","position":"aF","content":{"language":"python","code":"n = 255\nprint(f\"{n:b} {n:o} {n:x} {n:X}\")         # 11111111 377 ff FF\nprint(f\"{n:#b} {n:#o} {n:#x}\")            # 0b11111111 0o377 0xff\nprint(f\"{5:08b}\")                         # 00000101\nprint(f\"{n:#06x}\")                        # 0x00ff   ← width counts the prefix\nprint(f\"{65:c}\")                          # A\nprint(format(n, \"x\"), int(\"ff\", 16))      # ff 255","filename":"Python"},"revision":1},{"id":"0ed8dc73-e405-7be3-bc15-084f677bea03","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Nested & dynamic specs"}]},"revision":1},{"id":"2bb51525-f0cd-7986-aa0d-cc96301c2206","type":"code","position":"aH","content":{"language":"python","code":"rows = [(\"apple\", 1.5), (\"kiwi\", 12.25)]\nw = max(len(name) for name, _ in rows)\nfor name, cost in rows:\n    print(f\"{name:<{w}} | {cost:>{8}.{2}f}\")","filename":"Python"},"revision":1},{"id":"e0be9b67-6e11-7cf8-b087-b12a0dcc26bc","type":"code","position":"aI","content":{"language":"text","code":"apple |     1.50\nkiwi  |    12.25","filename":"Output"},"revision":1},{"id":"7f37c313-8509-7ced-82cb-248ca236841d","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Dates in f-strings"}]},"revision":1},{"id":"58b97000-83d5-7f41-9f4c-11fdd7c023af","type":"code","position":"aK","content":{"language":"python","code":"from datetime import datetime\nd = datetime(2026, 9, 29, 14, 5)\nprint(f\"{d:%Y-%m-%d %H:%M}\")        # 2026-09-29 14:05\nprint(f\"{d:%d %b %Y, %A}\")          # 29 Sep 2026, Tuesday\nprint(f\"{d:%I:%M %p}\")              # 02:05 PM","filename":"Python"},"revision":1},{"id":"79e37f9d-984b-709f-926a-12c9e15bc16e","type":"callout","position":"aL","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A format spec is passed to the object''s "},{"type":"text","text":"__format__","marks":[{"type":"code"}]},{"type":"text","text":" method — that is why "},{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":" understands "},{"type":"text","text":"strftime","marks":[{"type":"code"}]},{"type":"text","text":" codes after the colon."}]}]}},"revision":1},{"id":"81e242bd-d9dd-768e-a159-10a0806ef11c","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"__format__","marks":[{"type":"code"}]},{"type":"text","text":" for your own classes"}]},"revision":1},{"id":"7558823d-0631-7a6e-ac61-677292b14479","type":"code","position":"aN","content":{"language":"python","code":"class Money:\n    def __init__(self, amount):\n        self.amount = amount\n    def __format__(self, spec):\n        if spec == \"inr\":\n            return f\"₹{self.amount:,.2f}\"\n        return format(self.amount, spec)     # fall back to float formatting\n\nm = Money(1234.5)\nprint(f\"{m:inr}\")              # ₹1,234.50\nprint(f\"{m:>10.1f}|\")          #     1234.5|\nprint(format(m, \"inr\"))        # ₹1,234.50","filename":"Python"},"revision":1},{"id":"cd5e12d4-1b5b-720f-83ca-b9014a74fd58","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Older styles: "},{"type":"text","text":"str.format","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Template","marks":[{"type":"code"}]}]},"revision":1},{"id":"33b4b286-b563-7985-8cc1-cadab14ab0bc","type":"code","position":"aP","content":{"language":"python","code":"print(\"{} + {} = {}\".format(1, 2, 3))              # 1 + 2 = 3\nprint(\"{0}{1}{0}\".format(\"ab\", \"-\"))               # ab-ab\nprint(\"{name} is {age}\".format(name=\"Ravi\", age=30))   # Ravi is 30\npoint = {\"x\": 3, \"y\": 4}\nprint(\"({p[x]}, {p[y]})\".format(p=point))          # (3, 4)\nprint(\"{:>6.2f}|\".format(3.14159))                 #   3.14|\n\nprint(\"%s has %d items (%.1f%%)\" % (\"cart\", 3, 42.456))   # cart has 3 items (42.5%)\nprint(\"%(who)s says hi\" % {\"who\": \"Asha\"})         # Asha says hi\n\nfrom string import Template\nt = Template(\"Hello $name, you owe $$${amount}\")\nprint(t.substitute(name=\"Kiran\", amount=20))       # Hello Kiran, you owe $20\nprint(t.safe_substitute(name=\"Kiran\"))             # Hello Kiran, you owe $${amount}","filename":"Python"},"revision":1},{"id":"37b04015-f30d-763d-88e7-c6cc6ef958bc","type":"table","position":"aQ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Style"}],[{"type":"text","text":"Use it for"}]],[[{"type":"text","text":"f-strings"}],[{"type":"text","text":"Default choice","marks":[{"type":"bold"}]},{"type":"text","text":" — fastest and most readable (3.6+)"}]],[[{"type":"text","text":"str.format","marks":[{"type":"code"}]}],[{"type":"text","text":"Templates stored separately from the values, e.g. "},{"type":"text","text":"FMT.format(**row)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" formatting"}],[{"type":"text","text":"Legacy code and "},{"type":"text","text":"logging","marks":[{"type":"code"}]},{"type":"text","text":" calls ("},{"type":"text","text":"log.info(''%s'', x)","marks":[{"type":"code"}]},{"type":"text","text":" formats lazily)"}]],[[{"type":"text","text":"string.Template","marks":[{"type":"code"}]}],[{"type":"text","text":"Templates written by "},{"type":"text","text":"users","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"$name","marks":[{"type":"code"}]},{"type":"text","text":" only, no expressions, so it''s safe"}]]]},"revision":1},{"id":"35514e26-0bae-703c-ad47-0ef51738aa3b","type":"callout","position":"aR","content":{"variant":"warning","title":"Security","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never call "},{"type":"text","text":".format()","marks":[{"type":"code"}]},{"type":"text","text":" or build f-strings from untrusted template text — "},{"type":"text","text":"''{0.__class__}''.format(obj)","marks":[{"type":"code"}]},{"type":"text","text":" can read attributes. Use "},{"type":"text","text":"string.Template","marks":[{"type":"code"}]},{"type":"text","text":" for user-supplied templates."}]}]}},"revision":1},{"id":"964302eb-4923-79bd-afe9-c690aae0add3","type":"heading","position":"aS","content":{"level":1,"content":[{"type":"text","text":"Python 3.12+: f-strings grew up"}]},"revision":1},{"id":"4d6e92d6-3995-70af-8a6c-d5512365994b","type":"code","position":"aT","content":{"language":"python","code":"songs = [\"a\", \"b\"]\nprint(f\"{\", \".join(songs)}\")          # a, b     ← same quotes inside (3.12+)\nprint(f\"{''\\n''.join(songs)!r}\")        # ''a\\nb''   ← backslashes allowed in expressions\ntotal = f\"{\n    sum([1, 2, 3])                   # comments and line breaks inside {} are fine\n}\"\nprint(total)                          # 6","filename":"Python"},"revision":1},{"id":"5a58c863-972e-7d37-80a1-1b44d256947d","type":"callout","position":"aU","content":{"variant":"note","title":"Version","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PEP 701 (3.12) made f-strings part of the real grammar: reuse the outer quote type, write backslashes and comments inside the braces, and nest arbitrarily. Python 3.14 adds "},{"type":"text","text":"t-strings","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"t''…''","marks":[{"type":"code"}]},{"type":"text","text":") that produce a "},{"type":"text","text":"Template","marks":[{"type":"code"}]},{"type":"text","text":" object for safe, deferred processing (e.g. SQL/HTML escaping)."}]}]}},"revision":1},{"id":"3b587537-8dc9-77cb-82eb-4913bdde32ca","type":"heading","position":"aV","content":{"level":1,"content":[{"type":"text","text":"Pitfalls"}]},"revision":1},{"id":"91b4fbea-e066-7616-a6d7-3f3b01d6b11c","type":"text","position":"aW","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"f''{x:.2f}''","marks":[{"type":"code"}]},{"type":"text","text":" on a string raises "},{"type":"text","text":"ValueError: Unknown format code ''f''","marks":[{"type":"code"}]},{"type":"text","text":" — convert first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"round(x, 2)","marks":[{"type":"code"}]},{"type":"text","text":" changes the value; "},{"type":"text","text":"f''{x:.2f}''","marks":[{"type":"code"}]},{"type":"text","text":" only changes how it is "},{"type":"text","text":"displayed","marks":[{"type":"italic"}]},{"type":"text","text":". For money use "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"{x=}","marks":[{"type":"code"}]},{"type":"text","text":" uses "},{"type":"text","text":"repr","marks":[{"type":"code"}]},{"type":"text","text":", so strings appear quoted — add "},{"type":"text","text":"!s","marks":[{"type":"code"}]},{"type":"text","text":" for the plain form."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgetting the "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" prefix silently prints the braces: "},{"type":"text","text":"''{name}''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"4dee5224-8fe5-70cc-8d26-160c588f85e6","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you print a float with 2 decimals and thousands separators, right-aligned in 12 characters?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print(f\"{1234567.891:>12,.2f}|\")   # 1,234,567.89|","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Spec parts in order: align "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":", width "},{"type":"text","text":"12","marks":[{"type":"code"}]},{"type":"text","text":", grouping "},{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":", precision "},{"type":"text","text":".2","marks":[{"type":"code"}]},{"type":"text","text":", type "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8fcacb09-a7a4-7d76-8327-90c888f75ee4","type":"question","position":"aY","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which string formatting method is fastest?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f-strings — they compile to direct bytecode ("},{"type":"text","text":"FORMAT_VALUE","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"BUILD_STRING","marks":[{"type":"code"}]},{"type":"text","text":") with no method lookup or argument parsing, so they beat "},{"type":"text","text":"str.format","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
