  ('c9c32583-7706-7d62-8471-af1cdce54811', 'a8', 'code', '{"language":"python","code":"path = \"reports/2026/q1.final.csv\"\nprint(path.find(\"/\"), path.rfind(\"/\"), path.find(\"zip\"))   # 7 12 -1\nprint(path[path.rfind(\".\") + 1:])                         # csv\nprint(path.endswith((\".csv\", \".tsv\")))                    # True\nprint(\"aaaa\".count(\"aa\"), \"2026\" in path)                 # 2 True\nprint(\"banana\".find(\"a\", 2), \"banana\".find(\"a\", 2, 3))    # 3 -1","filename":"Python"}'),
