  ('b3b9319e-5c89-7382-b5e8-c70d919886db', 'aP', 'code', '{"language":"python","code":"for s in [\"123\", \"²\", \"½\", \"٣\", \"-5\", \"3.5\", \"\"]:\n    print(repr(s), s.isdecimal(), s.isdigit(), s.isnumeric())","filename":"Python"}'),
  ('8968508c-b466-7d43-87e2-564bcb346b74', 'aQ', 'code', '{"language":"text","code":"''123'' True True True\n''²'' False True True\n''½'' False False True\n''٣'' True True True\n''-5'' False False False\n''3.5'' False False False\n'''' False False False","filename":"Output"}'),
  ('6025d49d-6fc5-737d-b696-1a941324d958', 'aR', 'code', '{"language":"python","code":"print(\"abc123\".isalnum(), \"abc\".isalpha(), \"ABC\".isupper())    # True True True\nprint(\" \\t\\n\".isspace(), \"\".isspace())                          # True False\nprint(\"my_var\".isidentifier(), \"2fast\".isidentifier())          # True False\nprint(int(\"٣\") + 1)                                             # 4","filename":"Python"}'),
