SELECT 'ae8a316c-50f8-7a81-bc19-28e6b8882562', '38e80eea-5bf3-757c-8453-072bb3bbf379', 1, 'PUBLISHED', 'Syntax, Comments & Keywords', '[{"id":"b764ebb4-6961-784c-822d-0c370937e2de","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The rules of how Python code is "},{"type":"text","text":"written","marks":[{"type":"italic"}]},{"type":"text","text":": indentation instead of braces, comments and docstrings, how lines continue, what you may name things, and the reserved keywords."}]}]}},"revision":1},{"id":"964f0f65-2e6c-74d3-b5dd-d4cd56a052ba","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Indentation is the block structure"}]},"revision":1},{"id":"941b9d22-a232-7f5b-a694-f61c28ff2793","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where C and Java use "},{"type":"text","text":"{ }","marks":[{"type":"code"}]},{"type":"text","text":", Python uses a colon "},{"type":"text","text":":","marks":[{"type":"code"}]},{"type":"text","text":" followed by an "},{"type":"text","text":"indented block","marks":[{"type":"bold"}]},{"type":"text","text":". Every line in a block must use the same indentation — the convention is "},{"type":"text","text":"4 spaces","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5682b039-25d7-7fc5-a221-67abd6736b66","type":"code","position":"a3","content":{"language":"python","code":"def classify(n):\n    if n < 0:\n        return \"negative\"        # inside the if-block\n    elif n == 0:\n        return \"zero\"\n    return \"positive\"            # back at the function-block level\n\nprint(classify(-3), classify(0), classify(7))   # negative zero positive","filename":"Python"},"revision":1},{"id":"aaf1813d-a1b6-7e42-987f-229c234a2eb3","type":"code","position":"a4","content":{"language":"python","code":"src = \"def f():\\nreturn 1\\n\"          # body not indented\ntry:\n    compile(src, \"<demo>\", \"exec\")\nexcept IndentationError as e:\n    print(type(e).__name__, \"-\", e.msg)   # IndentationError - expected an indented block after function definition on line 1","filename":"Python"},"revision":1},{"id":"fb865fd7-ac35-75e8-933b-754ecb146ea9","type":"callout","position":"a5","content":{"variant":"warning","title":"Tabs vs spaces","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mixing tabs and spaces raises "},{"type":"text","text":"TabError","marks":[{"type":"code"}]},{"type":"text","text":" in Python 3. Configure your editor to insert 4 spaces when you press Tab."}]}]}},"revision":1},{"id":"759ab4fd-5f3f-76bf-9e04-d1096677ba47","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Comments & docstrings"}]},"revision":1},{"id":"cf6ac79e-4de0-7eba-b8ce-40bd19b0b5ac","type":"callout","position":"a7","content":{"variant":"note","title":"# comment","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ignored by the interpreter. Explains "},{"type":"text","text":"why","marks":[{"type":"italic"}]},{"type":"text","text":" the code does something — the code already says "},{"type":"text","text":"what","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b00e20c9-55f9-74d1-91fb-694ce4843b5a","type":"callout","position":"a8","content":{"variant":"note","title":"Docstring","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A string literal as the "},{"type":"text","text":"first statement","marks":[{"type":"bold"}]},{"type":"text","text":" of a module, class or function. Stored in "},{"type":"text","text":"__doc__","marks":[{"type":"code"}]},{"type":"text","text":", shown by "},{"type":"text","text":"help()","marks":[{"type":"code"}]},{"type":"text","text":" and IDEs."}]}]}},"revision":1},{"id":"dc494eaf-7c3b-713d-838e-3d5c930d9b22","type":"code","position":"a9","content":{"language":"python","code":"def area(r):\n    \"\"\"Return the area of a circle of radius r.\n\n    Uses 3.14159 for pi; pass a float or int.\n    \"\"\"\n    # the formula is pi * r squared\n    return 3.14159 * r * r\n\nprint(area.__doc__.splitlines()[0])   # Return the area of a circle of radius r.\nprint(round(area(2), 2))              # 12.57","filename":"Python"},"revision":1},{"id":"eb2dc616-41e1-7b86-bd12-8bbf87b0c078","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python has no block-comment syntax. Use several "},{"type":"text","text":"#","marks":[{"type":"code"}]},{"type":"text","text":" lines. A bare triple-quoted string in the middle of code is "},{"type":"text","text":"evaluated and thrown away","marks":[{"type":"italic"}]},{"type":"text","text":" — it works as a comment but is not one."}]}]}},"revision":1},{"id":"775775f4-81a8-771d-869e-7d1006976000","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Statements vs expressions"}]},"revision":1},{"id":"c1f99c8a-d8fe-73c2-94ca-6e7a844fbba2","type":"callout","position":"aC","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Expression","marks":[{"type":"bold"}]},{"type":"text","text":" — anything that produces a value: "},{"type":"text","text":"2 + 3","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"len(xs)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x if c else y","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lambda n: n * 2","marks":[{"type":"code"}]},{"type":"text","text":". Expressions can appear inside other expressions."}]}]}},"revision":1},{"id":"0ff9ead8-6288-7950-9b48-de8642cac537","type":"callout","position":"aD","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement","marks":[{"type":"bold"}]},{"type":"text","text":" — an instruction that does something: "},{"type":"text","text":"x = 5","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"import","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":". A statement cannot be used where a value is expected."}]}]}},"revision":1},{"id":"2ce68110-0d88-7b11-889d-023d008a1aac","type":"code","position":"aE","content":{"language":"python","code":"x = 5                                   # assignment statement\ny = (x * 2) + 1                         # the right side is an expression\nprint(y, (z := x + 1), z)               # 11 6 6   ← := is an assignment *expression*\nprint(eval(\"x * 10\"))                   # 50       ← eval evaluates one expression\nexec(\"w = x + 100\")                     # exec runs statements\nprint(w)                                # 105","filename":"Python"},"revision":1},{"id":"16a9c9fe-2539-75df-8f78-e6346e16e6bf","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"That''s why "},{"type":"text","text":"lambda","marks":[{"type":"code"}]},{"type":"text","text":" bodies must be a single expression (no "},{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":", no "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":"), and why "},{"type":"text","text":"if x = 5:","marks":[{"type":"code"}]},{"type":"text","text":" is a syntax error — assignment is a statement."}]}]}},"revision":1},{"id":"19dfab35-7d5b-7d63-9537-619625ea041f","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Long lines & multiple statements"}]},"revision":1},{"id":"901b44de-fd44-7602-b063-0f2b7166a588","type":"code","position":"aH","content":{"language":"python","code":"total = (1 + 2 +\n         3 + 4)                # implicit continuation inside ( ) [ ] { }\nfruits = [\n    \"apple\",\n    \"banana\",                  # a trailing comma is allowed — cleaner diffs\n]\nlegacy = 1 + \\\n         2                     # explicit backslash continuation (avoid)\na = 1; b = 2                   # ; separates statements (discouraged)\nprint(total, len(fruits), legacy, a + b)   # 10 2 3 3","filename":"Python"},"revision":1},{"id":"4a0ebdf0-34ca-77b4-94d4-cacc18708146","type":"callout","position":"aI","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrap long expressions in parentheses and break after an operator or comma."}]}]}},"revision":1},{"id":"6ca22a5b-b675-72b0-8940-9be8bef1d71c","type":"callout","position":"aJ","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Backslash continuations — a single trailing space after "},{"type":"text","text":"\\","marks":[{"type":"code"}]},{"type":"text","text":" becomes a syntax error."}]}]}},"revision":1},{"id":"8430c6ce-0853-7590-a296-40c39aa21409","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Names (identifiers)"}]},"revision":1},{"id":"8a49f80c-1f6e-7d80-927a-bce034c2c5fb","type":"table","position":"aL","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Rule / convention"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Letters, digits, "},{"type":"text","text":"_","marks":[{"type":"code"}]},{"type":"text","text":"; can''t start with a digit"}],[{"type":"text","text":"total_2","marks":[{"type":"code"}]},{"type":"text","text":" ✓ · "},{"type":"text","text":"2total","marks":[{"type":"code"}]},{"type":"text","text":" ✗"}]],[[{"type":"text","text":"Case-sensitive"}],[{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Count","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"COUNT","marks":[{"type":"code"}]},{"type":"text","text":" are three names"}]],[[{"type":"text","text":"Can''t be a keyword"}],[{"type":"text","text":"class = 1","marks":[{"type":"code"}]},{"type":"text","text":" ✗ → "},{"type":"text","text":"class_ = 1","marks":[{"type":"code"}]},{"type":"text","text":" ✓"}]],[[{"type":"text","text":"Unicode letters allowed"}],[{"type":"text","text":"π = 3.14159","marks":[{"type":"code"}]},{"type":"text","text":" works (but stick to ASCII in shared code)"}]],[[{"type":"text","text":"snake_case","marks":[{"type":"code"}]}],[{"type":"text","text":"variables, functions, modules"}]],[[{"type":"text","text":"PascalCase","marks":[{"type":"code"}]}],[{"type":"text","text":"classes"}]],[[{"type":"text","text":"UPPER_CASE","marks":[{"type":"code"}]}],[{"type":"text","text":"constants (by convention only — nothing stops reassignment)"}]],[[{"type":"text","text":"_leading","marks":[{"type":"code"}]}],[{"type":"text","text":"internal / private by convention"}]],[[{"type":"text","text":"__dunder__","marks":[{"type":"code"}]}],[{"type":"text","text":"reserved for Python''s special names"}]],[[{"type":"text","text":"_","marks":[{"type":"code"}]}],[{"type":"text","text":"a throwaway value: "},{"type":"text","text":"for _ in range(3)","marks":[{"type":"code"}]},{"type":"text","text":"; in the REPL it''s the last result"}]]]},"revision":1},{"id":"f84e6c72-685d-79bd-a14a-23ed22c71310","type":"code","position":"aM","content":{"language":"python","code":"print(\"my_var\".isidentifier(), \"2cool\".isidentifier())   # True False\nπ = 3.14159\nprint(round(2 * π, 2))                                    # 6.28","filename":"Python"},"revision":1},{"id":"ed47a117-73ba-73fa-9bc1-dbbcae0dfa32","type":"callout","position":"aN","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t shadow built-ins: "},{"type":"text","text":"list = [1, 2]","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"id = 5","marks":[{"type":"code"}]},{"type":"text","text":" hides the built-in "},{"type":"text","text":"list()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"id()","marks":[{"type":"code"}]},{"type":"text","text":" for the rest of the scope, leading to confusing "},{"type":"text","text":"TypeError: ''list'' object is not callable","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d7e745a2-9eb4-78c1-8f76-a7a26f2d5833","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Keywords & soft keywords"}]},"revision":1},{"id":"ba887911-0ccc-7017-8dfa-0bba2b5f98dd","type":"text","position":"aP","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keywords are reserved words you can''t use as names. "},{"type":"text","text":"Soft keywords","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"case","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_","marks":[{"type":"code"}]},{"type":"text","text":") are keywords only in specific positions, so old code using "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" as a variable still works."}]}]}},"revision":1},{"id":"652f75a5-15a6-7e28-9393-522a31f8547b","type":"code","position":"aQ","content":{"language":"python","code":"import keyword\nprint(len(keyword.kwlist))                                     # 35\nprint(keyword.iskeyword(\"class\"), keyword.iskeyword(\"match\"))  # True False\nprint(keyword.softkwlist)                                      # [''_'', ''case'', ''match'', ''type'']\nmatch = \"still a valid variable name\"\nprint(match.split()[0])                                        # still","filename":"Python"},"revision":1},{"id":"d4dcefb1-dbb5-7261-ba32-f11453ba4fb7","type":"table","position":"aR","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Purpose"}],[{"type":"text","text":"Keywords"}]],[[{"type":"text","text":"Values"}],[{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"None","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Logic & tests"}],[{"type":"text","text":"and","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"or","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"not","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"in","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Branching"}],[{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"elif","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"else","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Loops"}],[{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"continue","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Functions"}],[{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"lambda","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"global","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"nonlocal","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Classes & modules"}],[{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"import","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"from","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"as","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Errors & resources"}],[{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"raise","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"with","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Async"}],[{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"await","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Misc"}],[{"type":"text","text":"pass","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"del","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"a358e022-c781-7ee2-ae2e-7078ea8b3d4e","type":"heading","position":"aS","content":{"level":1,"content":[{"type":"text","text":"Placeholders: "},{"type":"text","text":"pass","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"...","marks":[{"type":"code"}]}]},"revision":1},{"id":"bc010286-590f-76d1-8483-1caadf7d116e","type":"code","position":"aT","content":{"language":"python","code":"def todo():\n    pass                  # a statement that does nothing\n\nclass Config: ...         # Ellipsis — a common \"fill in later\" body\n\nprint(todo(), Config.__name__, ...)   # None Config Ellipsis","filename":"Python"},"revision":1},{"id":"0ae1442f-b730-7484-b1af-f8293734ffa9","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Exploring from the REPL: "},{"type":"text","text":"help","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dir","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type","marks":[{"type":"code"}]}]},"revision":1},{"id":"a0993bf4-9e39-7b60-997f-3d5f36223f47","type":"code","position":"aV","content":{"language":"python","code":"print(type(3.0).__name__)                             # float\nprint([n for n in dir(str) if n.startswith(\"st\")])    # [''startswith'', ''strip'']\nprint(len.__doc__.splitlines()[0])                    # Return the number of items in a container.","filename":"Python"},"revision":1},{"id":"043bfe07-6bd2-77a2-bf37-62945571bc4c","type":"code","position":"aW","content":{"language":"","code":">>> help(str.split)       # full documentation (q to quit)\n>>> dir([])               # every attribute/method of a list\n>>> 2 + 3\n5\n>>> _ * 10                # _ holds the last REPL result\n50","filename":"REPL"},"revision":1},{"id":"8b32ad8c-38c6-7cbc-b1ca-9ea2d9c313d1","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does Python use indentation instead of braces?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To make the visual structure "},{"type":"text","text":"be","marks":[{"type":"italic"}]},{"type":"text","text":" the actual structure — code that looks nested is nested. It removes a whole class of bugs (misleading indentation) and style debates, and keeps code readable."}]}]}},"revision":1},{"id":"82fb1c3f-9b71-7eb8-b39b-dc284080c65a","type":"question","position":"aY","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a comment and a docstring?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A comment ("},{"type":"text","text":"#","marks":[{"type":"code"}]},{"type":"text","text":") is discarded by the parser. A docstring is a real string object stored in the "},{"type":"text","text":"__doc__","marks":[{"type":"code"}]},{"type":"text","text":" attribute of a module, class or function, so "},{"type":"text","text":"help()","marks":[{"type":"code"}]},{"type":"text","text":", IDEs and documentation tools can read it at runtime."}]}]}},"revision":1},{"id":"e0c44f88-885b-754c-bcbe-91c15f683e01","type":"question","position":"aZ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is match a keyword?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s a "},{"type":"text","text":"soft keyword","marks":[{"type":"bold"}]},{"type":"text","text":": it acts as a keyword only at the start of a "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" statement, so "},{"type":"text","text":"match = 5","marks":[{"type":"code"}]},{"type":"text","text":" is still a legal assignment. The same applies to "},{"type":"text","text":"case","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"_","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
