SELECT '1536ea5e-60e5-753f-8bc7-b8f3e243dd86', '34affb0f-a9e7-7660-baa6-afc51ed4ef1d', 1, 'PUBLISHED', 'Testing: unittest & pytest', '[{"id":"e893bfa5-85b1-768b-9d3e-2a0c266bb73d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Automated tests prove your code works today and keep it working tomorrow. Python ships "},{"type":"text","text":"unittest","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"doctest","marks":[{"type":"code"}]},{"type":"text","text":"; most projects use "},{"type":"text","text":"pytest","marks":[{"type":"code"}]},{"type":"text","text":" for its plain "},{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":"s and fixtures."}]}]}},"revision":1},{"id":"1f2d7ea1-e9d4-769b-a2c2-a60689445d48","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Why and what to test"}]},"revision":1},{"id":"5454cabd-7832-7719-8f59-d4e49a2d936a","type":"callout","position":"a2","content":{"variant":"note","title":"Unit tests","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One function or class in isolation. Fast (milliseconds) — the bulk of your suite."}]}]}},"revision":1},{"id":"19360cc7-37bb-73d1-b87a-f9650f52da35","type":"callout","position":"a3","content":{"variant":"note","title":"Integration tests","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Several parts together: your code + a real database, file system or HTTP layer."}]}]}},"revision":1},{"id":"771d593b-64dc-70b9-8698-210f021d83e5","type":"callout","position":"a4","content":{"variant":"note","title":"End-to-end tests","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The whole system as a user sees it. Slow and brittle — keep few of them."}]}]}},"revision":1},{"id":"2889df06-6c1f-75f1-8d8c-4fa9c4674cf3","type":"callout","position":"a5","content":{"variant":"note","title":"Regression tests","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every fixed bug gets a test that failed before the fix, so it can''t come back."}]}]}},"revision":1},{"id":"a7747129-a650-7ea9-87cd-dbaa4e733b51","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A good test follows "},{"type":"text","text":"Arrange → Act → Assert","marks":[{"type":"bold"}]},{"type":"text","text":": set up inputs, call the code once, check the result."}]}]}},"revision":1},{"id":"e884cf51-79db-75b1-bb32-fa02a29485ff","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"assert — the building block"}]},"revision":1},{"id":"e2d7f11c-1a9c-79b7-a80c-fc5b55255665","type":"code","position":"a8","content":{"language":"python","code":"def slugify(title: str) -> str:\n    return \"-\".join(title.lower().split())\n\n# Arrange, Act, Assert — a test is just code that raises if something is wrong\nassert slugify(\"Hello World\") == \"hello-world\"\nassert slugify(\"  Python   Notes \") == \"python-notes\"\ntry:\n    assert slugify(\"A B\") == \"a_b\", \"separator should be a hyphen\"\nexcept AssertionError as e:\n    print(\"failed:\", e)             # failed: separator should be a hyphen","filename":"Python"},"revision":1},{"id":"01b2d6d3-fdd0-7434-8020-628ddc3b5ae2","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":" statements are removed when Python runs with "},{"type":"text","text":"-O","marks":[{"type":"code"}]},{"type":"text","text":". Use them in tests and for internal sanity checks — never to validate user input in production code."}]}]}},"revision":1},{"id":"a864a452-820b-7d7b-ace0-4fe6713d73d9","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"unittest — the built-in framework"}]},"revision":1},{"id":"985316fc-c4cc-76d4-b5dd-bd92bb62a102","type":"code","position":"aB","content":{"language":"python","code":"import io, unittest\n\nclass Stack:\n    def __init__(self):\n        self._items = []\n    def push(self, x):\n        self._items.append(x)\n    def pop(self):\n        if not self._items:\n            raise IndexError(\"pop from empty stack\")\n        return self._items.pop()\n\nclass StackTest(unittest.TestCase):\n    def setUp(self):                         # runs before EACH test method\n        self.s = Stack()\n\n    def test_push_then_pop(self):\n        self.s.push(1)\n        self.s.push(2)\n        self.assertEqual(self.s.pop(), 2)\n\n    def test_pop_empty_raises(self):\n        with self.assertRaises(IndexError):\n            self.s.pop()\n\n    def test_many_values(self):\n        for value in [0, \"x\", None]:\n            with self.subTest(value=value):  # each case reported separately\n                self.s.push(value)\n                self.assertIs(self.s.pop(), value)\n\nsuite = unittest.defaultTestLoader.loadTestsFromTestCase(StackTest)\nresult = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)\nprint(result.testsRun, len(result.failures), len(result.errors))   # 3 0 0\nprint(result.wasSuccessful())                                        # True","filename":"Python"},"revision":1},{"id":"1750570b-24a3-71f9-9788-5e2a9921ee57","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Assertion"}],[{"type":"text","text":"Checks"}]],[[{"type":"text","text":"assertEqual(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"assertNotEqual","marks":[{"type":"code"}]}],[{"type":"text","text":"a == b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"assertTrue(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"assertFalse(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Truthiness"}]],[[{"type":"text","text":"assertIs(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"assertIsNone(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Identity"}]],[[{"type":"text","text":"assertIn(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"Membership"}]],[[{"type":"text","text":"assertRaises(E)","marks":[{"type":"code"}]}],[{"type":"text","text":"The block raises "},{"type":"text","text":"E","marks":[{"type":"code"}]},{"type":"text","text":" (use as a context manager)"}]],[[{"type":"text","text":"assertAlmostEqual(a, b, places=7)","marks":[{"type":"code"}]}],[{"type":"text","text":"Floats close enough"}]],[[{"type":"text","text":"assertCountEqual(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"Same items, any order"}]]]},"revision":1},{"id":"935bee6e-2170-7c99-b3ec-5973ce2f2099","type":"callout","position":"aD","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"setUp","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"tearDown","marks":[{"type":"code"}]},{"type":"text","text":" run around every test; "},{"type":"text","text":"setUpClass","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"tearDownClass","marks":[{"type":"code"}]},{"type":"text","text":" once per class. Test methods must start with "},{"type":"text","text":"test","marks":[{"type":"code"}]},{"type":"text","text":". Run everything with "},{"type":"text","text":"python -m unittest discover","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"af19969f-b070-7a4d-98f9-8c8e44dfef1a","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"pytest — less boilerplate"}]},"revision":1},{"id":"ec53a0ff-d153-73d1-bf75-d68a30511da7","type":"code","position":"aF","content":{"language":"python","code":"# test_cart.py\nimport pytest\nfrom shop.cart import Cart\n\n@pytest.fixture\ndef cart():                                   # fresh object for every test that asks for it\n    c = Cart()\n    c.add(\"pen\", price=10, qty=2)\n    return c\n\ndef test_total(cart):\n    assert cart.total() == 20                 # plain assert — pytest shows both sides on failure\n\n@pytest.mark.parametrize(\"qty, expected\", [(1, 10), (3, 30), (0, 0)])\ndef test_line_total(qty, expected):\n    c = Cart()\n    c.add(\"pen\", price=10, qty=qty)\n    assert c.total() == expected\n\ndef test_negative_qty_rejected():\n    with pytest.raises(ValueError, match=\"qty\"):\n        Cart().add(\"pen\", price=10, qty=-1)\n\ndef test_export(cart, tmp_path):              # built-in fixture: a fresh temp directory\n    path = tmp_path / \"cart.json\"\n    cart.save(path)\n    assert path.exists()","filename":"Python"},"revision":1},{"id":"7268b016-7c30-7198-854a-36117ec731ae","type":"code","position":"aG","content":{"language":"","code":"$ pip install pytest\n$ pytest                       # finds test_*.py files and test_* functions\n$ pytest -q -k \"total\"         # quiet, only tests whose name matches\n$ pytest -x --lf               # stop at first failure; rerun last failures\n$ pytest --cov=shop            # coverage report (pytest-cov plugin)","filename":"Terminal"},"revision":1},{"id":"7f613e33-8787-7fcc-a750-644b4aa72e28","type":"code","position":"aH","content":{"language":"text","code":"============================= test session starts ==============================\ncollected 6 items\n\ntest_cart.py ......                                                      [100%]\n\n============================== 6 passed in 0.02s ===============================","filename":"pytest output"},"revision":1},{"id":"164ccc06-1655-7cd5-a6f6-a42cf8838191","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"unittest","marks":[{"type":"code"}]}],[{"type":"text","text":"pytest","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Install"}],[{"type":"text","text":"Built in"}],[{"type":"text","text":"pip install pytest","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Style"}],[{"type":"text","text":"Classes + "},{"type":"text","text":"self.assertX","marks":[{"type":"code"}]},{"type":"text","text":" methods"}],[{"type":"text","text":"Plain functions + "},{"type":"text","text":"assert","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Setup"}],[{"type":"text","text":"setUp","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"tearDown","marks":[{"type":"code"}]}],[{"type":"text","text":"Fixtures, injected by name, with scopes"}]],[[{"type":"text","text":"Parametrise"}],[{"type":"text","text":"subTest","marks":[{"type":"code"}]}],[{"type":"text","text":"@pytest.mark.parametrize","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Runs the other''s tests?"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes — pytest runs unittest suites too"}]]]},"revision":1},{"id":"8d54a05d-8095-73c3-bfda-8f434413ca95","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"doctest — examples that are tests"}]},"revision":1},{"id":"76b17e3d-bae3-7bb7-af75-29e220d95bcf","type":"code","position":"aK","content":{"language":"python","code":"import doctest, io\n\ndef median(xs):\n    \"\"\"Return the median of a non-empty list.\n\n    >>> median([3, 1, 2])\n    2\n    >>> median([4, 1, 3, 2])\n    2.5\n    \"\"\"\n    s = sorted(xs)\n    mid = len(s) // 2\n    return s[mid] if len(s) % 2 else (s[mid - 1] + s[mid]) / 2\n\nrunner = doctest.DocTestRunner()\nfor test in doctest.DocTestFinder().find(median, globs={\"median\": median}):\n    runner.run(test, out=io.StringIO().write)\nprint(runner.tries, runner.failures)       # 2 0","filename":"Python"},"revision":1},{"id":"4e7fc184-5f98-7a21-8659-7d32109f8d75","type":"code","position":"aL","content":{"language":"","code":"$ python -m doctest -v stats.py     # run every docstring example in a module\n$ pytest --doctest-modules          # or let pytest collect them","filename":"Terminal"},"revision":1},{"id":"d8a723fb-c57d-7702-a60a-b49e7f825835","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Coverage & the TDD loop"}]},"revision":1},{"id":"f9f68320-b00c-743d-90c3-b67ee674ca61","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Red","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Write a small failing test for the next bit of behaviour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Green","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Write the simplest code that makes it pass."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Refactor","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Clean up with the tests as a safety net; rerun them."}]}]}]}]}},"revision":1},{"id":"16bca675-cd86-7b26-806f-048372f22c02","type":"callout","position":"aO","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Coverage ("},{"type":"text","text":"coverage run -m pytest && coverage report","marks":[{"type":"code"}]},{"type":"text","text":") shows which lines never ran. High coverage doesn''t prove correctness, but "},{"type":"text","text":"uncovered code is definitely untested","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ee71cc63-e904-7bb7-a93f-635b9ae47dcf","type":"callout","position":"aP","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep tests fast, independent and deterministic; one behaviour per test; descriptive names like "},{"type":"text","text":"test_pop_empty_raises","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"43a76ec6-099b-7fb7-87a4-002815316e89","type":"callout","position":"aQ","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tests that depend on each other''s order, the current time, the network or random data without a fixed seed."}]}]}},"revision":1},{"id":"3e70ef35-c1c2-7b97-8f00-f00468c130da","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a fixture in pytest?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function decorated with "},{"type":"text","text":"@pytest.fixture","marks":[{"type":"code"}]},{"type":"text","text":" that prepares something a test needs (an object, a temp directory, a DB connection). Tests receive it by naming it as a parameter. Fixtures can "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" to run teardown and have scopes ("},{"type":"text","text":"function","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"module","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"session","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"a4189c9c-ee4c-7346-8e13-0b482bd20b2a","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"unittest or pytest?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pytest for most projects: less boilerplate, better failure output, fixtures and a large plugin ecosystem — and it runs existing unittest tests. unittest when you can''t add dependencies."}]}]}},"revision":1},{"id":"d10111b5-d921-7014-baa1-617a6f1043bb","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you test code that raises an exception?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"with pytest.raises(ValueError, match=\"...\"):","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"with self.assertRaises(ValueError):","marks":[{"type":"code"}]},{"type":"text","text":" around the call. The test fails if the exception is "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" raised."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
