SELECT 'c4d55349-2bd2-719c-ba9e-a6b25e3d020f', 'cffc86bc-1fa8-7bbd-acfa-a68ff3b5a174', 1, 'PUBLISHED', 'Threading & Synchronisation', '[{"id":"032987ec-81e5-75d3-b2ac-3c8d62ac46b3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"threading","marks":[{"type":"code"}]},{"type":"text","text":" runs functions in OS threads that share one memory space. Sharing is the superpower and the danger — the synchronisation primitives ("},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Event","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Queue","marks":[{"type":"code"}]},{"type":"text","text":", …) are how you stay correct."}]}]}},"revision":1},{"id":"50ca03a3-215c-77a2-8d30-6f537d85bfda","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread","marks":[{"type":"bold"}]},{"type":"text","text":" — an independent flow of execution inside one process. All threads see the same globals and heap objects, so they can communicate cheaply — and corrupt each other''s data if they write without coordination."}]}]}},"revision":1},{"id":"1b5acc59-acf6-721e-8617-bf0188959948","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Creating, starting & joining threads"}]},"revision":1},{"id":"f9f5ec15-34b7-78c2-a8aa-f75919ca3e24","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pass a "},{"type":"text","text":"target","marks":[{"type":"code"}]},{"type":"text","text":" callable (plus "},{"type":"text","text":"args","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"kwargs","marks":[{"type":"code"}]},{"type":"text","text":"), or subclass "},{"type":"text","text":"Thread","marks":[{"type":"code"}]},{"type":"text","text":" and override "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":" launches the thread; "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" waits for it to finish."}]}]}},"revision":1},{"id":"5f9d111f-5eb6-74a6-85a3-803b1e40b30d","type":"code","position":"a4","content":{"language":"python","code":"import threading\n\nresults = {}\n\ndef square(n):\n    results[n] = n * n                    # each thread writes its own key\n\nthreads = [threading.Thread(target=square, args=(i,), name=f\"worker-{i}\") for i in range(4)]\nfor t in threads:\n    t.start()\nfor t in threads:\n    t.join()                              # wait for all of them\nprint(sorted(results.items()))            # [(0, 0), (1, 1), (2, 4), (3, 9)]\nprint(threads[0].name, threads[0].is_alive())   # worker-0 False\n\nclass Downloader(threading.Thread):       # subclass style\n    def __init__(self, url):\n        super().__init__()\n        self.url = url\n        self.size = None\n    def run(self):                        # called in the new thread by start()\n        self.size = len(self.url)         # stands in for a real download\n\nd = Downloader(\"https://example.com\")\nd.start(); d.join()\nprint(d.size)                             # 19","filename":"Python"},"revision":1},{"id":"4c6138b8-be19-7b26-a06a-bc5d76887625","type":"callout","position":"a5","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Call "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"t.run()","marks":[{"type":"code"}]},{"type":"text","text":" just executes the function in the "},{"type":"text","text":"current","marks":[{"type":"italic"}]},{"type":"text","text":" thread — no concurrency at all, and no error to tell you."}]}]}},"revision":1},{"id":"b8370ccf-d356-7232-85c0-60a31f305728","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method / attribute"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"t.start()","marks":[{"type":"code"}]}],[{"type":"text","text":"Begin running "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":" in a new OS thread (once per thread object)"}]],[[{"type":"text","text":"t.join(timeout=None)","marks":[{"type":"code"}]}],[{"type":"text","text":"Block until the thread ends (or the timeout passes)"}]],[[{"type":"text","text":"t.is_alive()","marks":[{"type":"code"}]}],[{"type":"text","text":"Still running?"}]],[[{"type":"text","text":"t.daemon","marks":[{"type":"code"}]}],[{"type":"text","text":"Daemon threads don''t keep the program alive"}]],[[{"type":"text","text":"threading.current_thread()","marks":[{"type":"code"}]}],[{"type":"text","text":"The "},{"type":"text","text":"Thread","marks":[{"type":"code"}]},{"type":"text","text":" object running this code"}]],[[{"type":"text","text":"threading.active_count()","marks":[{"type":"code"}]}],[{"type":"text","text":"Number of live threads"}]]]},"revision":1},{"id":"85a60d63-35df-7f58-bfb8-fe9bf944cf19","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Daemon threads"}]},"revision":1},{"id":"404bf239-e771-7977-8c3b-b9f87c754415","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The interpreter exits when all "},{"type":"text","text":"non-daemon","marks":[{"type":"bold"}]},{"type":"text","text":" threads have finished. Daemon threads are killed abruptly at exit — fine for background heartbeats, dangerous for anything that writes files or commits transactions."}]}]}},"revision":1},{"id":"5fbd51ed-4167-7601-be9b-423e2a0e54c9","type":"code","position":"a9","content":{"language":"python","code":"import threading\n\ndef heartbeat(stop):\n    while not stop.is_set():\n        stop.wait(0.01)                   # sleep, but wake up immediately when stopped\n\nstop = threading.Event()\nt = threading.Thread(target=heartbeat, args=(stop,), daemon=True)\nt.start()\nprint(t.daemon, t.is_alive())             # True True\nstop.set(); t.join()                      # a clean shutdown is still better\nprint(t.is_alive())                       # False","filename":"Python"},"revision":1},{"id":"095155b2-0f7b-750f-ae06-ece9c8bc2066","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Race conditions: why "},{"type":"text","text":"x += 1","marks":[{"type":"code"}]},{"type":"text","text":" isn''t safe"}]},"revision":1},{"id":"276864b1-69bb-7860-87ca-88e80ae438a8","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A thread switch can happen "},{"type":"text","text":"between any two bytecodes","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"counter += 1","marks":[{"type":"code"}]},{"type":"text","text":" is a read, an add and a write — three steps:"}]}]}},"revision":1},{"id":"16ca5757-002d-74a7-83b0-4a6efd2fa85d","type":"code","position":"aC","content":{"language":"python","code":"import dis\n\ndef increment():\n    global counter\n    counter += 1\n\nops = [i.opname for i in dis.get_instructions(increment)]\nprint([op for op in ops if op in (\"LOAD_GLOBAL\", \"BINARY_OP\", \"STORE_GLOBAL\")])\n# [''LOAD_GLOBAL'', ''BINARY_OP'', ''STORE_GLOBAL'']","filename":"Python"},"revision":1},{"id":"ad13fd7d-603f-7d2d-9c92-998dfbd73da8","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Step"}],[{"type":"text","text":"Thread A"}],[{"type":"text","text":"Thread B"}],[{"type":"text","text":"counter","marks":[{"type":"code"}]}]],[[{"type":"text","text":"1"}],[{"type":"text","text":"reads 5"}],[],[{"type":"text","text":"5"}]],[[{"type":"text","text":"2"}],[],[{"type":"text","text":"reads 5"}],[{"type":"text","text":"5"}]],[[{"type":"text","text":"3"}],[{"type":"text","text":"computes 6, writes 6"}],[],[{"type":"text","text":"6"}]],[[{"type":"text","text":"4"}],[],[{"type":"text","text":"computes 6, writes 6"}],[{"type":"text","text":"6 — one increment "},{"type":"text","text":"lost","marks":[{"type":"bold"}]}]]]},"revision":1},{"id":"da7c78e8-63d7-7564-b4bc-c9ed24bc5b78","type":"callout","position":"aE","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Races are non-deterministic: the code may pass a thousand runs and fail in production. The fix is to make the read-modify-write "},{"type":"text","text":"atomic","marks":[{"type":"bold"}]},{"type":"text","text":" with a lock."}]}]}},"revision":1},{"id":"093cd4b8-4493-7cb5-b3c9-98e11990b228","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Lock & RLock"}]},"revision":1},{"id":"31824a86-92d1-7148-9e0b-6e738a267278","type":"code","position":"aG","content":{"language":"python","code":"import threading\n\nclass BankAccount:\n    def __init__(self):\n        self.balance = 0\n        self._lock = threading.Lock()\n\n    def deposit(self, amount):\n        with self._lock:                  # acquire … release, even on exceptions\n            self.balance += amount\n\nacct = BankAccount()\n\ndef worker():\n    for _ in range(10_000):\n        acct.deposit(1)\n\nthreads = [threading.Thread(target=worker) for _ in range(5)]\nfor t in threads: t.start()\nfor t in threads: t.join()\nprint(acct.balance)                       # 50000\n\nlock = threading.Lock()\nlock.acquire()\nprint(lock.acquire(timeout=0.01))         # False  ← a Lock is not re-entrant\nlock.release()","filename":"Python"},"revision":1},{"id":"3a7ba476-6dd0-7197-9452-7ee856fcf162","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A plain "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":" deadlocks if the "},{"type":"text","text":"same","marks":[{"type":"bold"}]},{"type":"text","text":" thread tries to take it twice. An "},{"type":"text","text":"RLock","marks":[{"type":"code"}]},{"type":"text","text":" (re-entrant lock) counts acquisitions by its owner — handy when one locked method calls another."}]}]}},"revision":1},{"id":"d22082b6-ba44-7f74-82bd-5d0eeb56b3d6","type":"code","position":"aI","content":{"language":"python","code":"import threading\n\nclass Inventory:\n    def __init__(self):\n        self._lock = threading.RLock()\n        self.items = {}\n\n    def add(self, name, qty=1):\n        with self._lock:\n            self.items[name] = self.items.get(name, 0) + qty\n\n    def add_many(self, names):\n        with self._lock:                  # held here…\n            for n in names:\n                self.add(n)               # …and re-acquired inside add(): OK with RLock\n\ninv = Inventory()\ninv.add_many([\"pen\", \"pen\", \"ink\"])\nprint(inv.items)                          # {''pen'': 2, ''ink'': 1}","filename":"Python"},"revision":1},{"id":"89f5fddb-a528-74c7-83f1-e5b8ccb8c2ac","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Semaphore, Event & Condition"}]},"revision":1},{"id":"d4125872-c6a1-7c65-94db-f8f26475b8dd","type":"callout","position":"aK","content":{"variant":"note","title":"Semaphore(n)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lock that up to "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" threads can hold at once — limit concurrent DB connections or API calls. "},{"type":"text","text":"BoundedSemaphore","marks":[{"type":"code"}]},{"type":"text","text":" also errors if released too often."}]}]}},"revision":1},{"id":"0fa527e1-a668-73a9-95f7-e78aaae9bf33","type":"callout","position":"aL","content":{"variant":"note","title":"Event","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A thread-safe boolean flag: "},{"type":"text","text":"set()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"clear()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":". Great for “start now” and “please stop” signals."}]}]}},"revision":1},{"id":"dad903eb-4517-7b10-8ce0-22a6190d7276","type":"callout","position":"aM","content":{"variant":"note","title":"Condition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lock plus wait/notify: threads sleep until "},{"type":"text","text":"some predicate","marks":[{"type":"italic"}]},{"type":"text","text":" becomes true — the building block of queues."}]}]}},"revision":1},{"id":"be752462-fe81-759b-8192-16d721c06d91","type":"callout","position":"aN","content":{"variant":"note","title":"Barrier(n)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" threads each call "},{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":"; all are released together once the last one arrives."}]}]}},"revision":1},{"id":"e35b0b99-d65a-7448-a775-5ef9eb9a8603","type":"code","position":"aO","content":{"language":"python","code":"import threading, time\n\nsem = threading.Semaphore(2)              # at most 2 inside at a time\nactive = peak = 0\nguard = threading.Lock()\n\ndef task():\n    global active, peak\n    with sem:\n        with guard:\n            active += 1\n            peak = max(peak, active)\n        time.sleep(0.01)\n        with guard:\n            active -= 1\n\nthreads = [threading.Thread(target=task) for _ in range(6)]\nfor t in threads: t.start()\nfor t in threads: t.join()\nprint(peak <= 2)                          # True\n\nready = threading.Event()\nlog = []\n\ndef waiter():\n    ready.wait()                          # blocks until set()\n    log.append(\"go\")\n\nw = threading.Thread(target=waiter); w.start()\nlog.append(\"setting up\")\nready.set(); w.join()\nprint(log)                                # [''setting up'', ''go'']\n\ncond = threading.Condition()\nitems, got = [], []\n\ndef consumer():\n    with cond:\n        cond.wait_for(lambda: len(items) >= 3)   # sleeps; re-checks after each notify\n        got.extend(items)\n\nc = threading.Thread(target=consumer); c.start()\nfor i in range(3):\n    with cond:\n        items.append(i)\n        cond.notify()\nc.join()\nprint(got)                                # [0, 1, 2]","filename":"Python"},"revision":1},{"id":"a693613c-5ecf-7337-9296-49cb25257507","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"Producer–consumer with "},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]}]},"revision":1},{"id":"a4a0dec7-5562-72c1-862b-573b0aec55f6","type":"text","position":"aQ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":" is already thread-safe and does all the locking for you. It''s the cleanest way for threads to hand work to each other — prefer it to sharing lists and locks."}]}]}},"revision":1},{"id":"c2a87ed2-5e37-7f99-80da-ba11fe843c9c","type":"code","position":"aR","content":{"language":"python","code":"import queue, threading\n\nq = queue.Queue(maxsize=5)                # put() blocks when full → back-pressure\nresults = []\nSTOP = object()                           # a unique sentinel\n\ndef consumer():\n    while True:\n        n = q.get()\n        if n is STOP:\n            q.task_done()\n            break\n        results.append(n * n)             # list.append is safe; fancier updates need a lock\n        q.task_done()\n\nworkers = [threading.Thread(target=consumer) for _ in range(3)]\nfor w in workers: w.start()\nfor n in range(10):                       # the producer\n    q.put(n)\nfor _ in workers:\n    q.put(STOP)                           # one sentinel per consumer\nq.join()                                  # wait until every item is task_done()\nfor w in workers: w.join()\nprint(sorted(results))                    # [0, 1, 4, 9, 16, 25, 36, 49, 64, 81]","filename":"Python"},"revision":1},{"id":"2e4225e7-6ae3-7464-8ec2-3a08259ccc94","type":"table","position":"aS","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Queue class"}],[{"type":"text","text":"Order"}]],[[{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]}],[{"type":"text","text":"FIFO"}]],[[{"type":"text","text":"queue.LifoQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"LIFO (a stack)"}]],[[{"type":"text","text":"queue.PriorityQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"Smallest item first — put "},{"type":"text","text":"(priority, item)","marks":[{"type":"code"}]},{"type":"text","text":" tuples"}]],[[{"type":"text","text":"queue.SimpleQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"Unbounded FIFO without "},{"type":"text","text":"task_done","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"join","marks":[{"type":"code"}]},{"type":"text","text":" — simpler, faster"}]]]},"revision":1},{"id":"7c31b2dc-e941-71e8-9b74-a4939d0da330","type":"callout","position":"aT","content":{"variant":"note","title":"3.13+","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Since 3.13, "},{"type":"text","text":"Queue.shutdown()","marks":[{"type":"code"}]},{"type":"text","text":" wakes blocked "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"put()","marks":[{"type":"code"}]},{"type":"text","text":" callers with "},{"type":"text","text":"queue.ShutDown","marks":[{"type":"code"}]},{"type":"text","text":" — an alternative to sentinel values."}]}]}},"revision":1},{"id":"8bd98af7-9fa9-7b9e-9446-ffcd3f09c515","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Per-thread data: "},{"type":"text","text":"threading.local","marks":[{"type":"code"}]}]},"revision":1},{"id":"a8c2def1-d7bf-7d0a-8d85-c39413ed4c23","type":"code","position":"aV","content":{"language":"python","code":"import threading\n\nctx = threading.local()                   # each thread sees its own attributes\nseen = {}\n\ndef current_user_greeting():\n    return f\"hi {ctx.user}\"               # no need to pass user down the call chain\n\ndef handle(user):\n    ctx.user = user\n    seen[user] = current_user_greeting()\n\nthreads = [threading.Thread(target=handle, args=(u,)) for u in (\"asha\", \"ravi\")]\nfor t in threads: t.start()\nfor t in threads: t.join()\nprint(sorted(seen.values()))              # [''hi asha'', ''hi ravi'']\nprint(hasattr(ctx, \"user\"))               # False  ← the main thread never set it","filename":"Python"},"revision":1},{"id":"e96c6e1e-af34-7a8a-b3a9-800b3b961b8e","type":"heading","position":"aW","content":{"level":1,"content":[{"type":"text","text":"Deadlocks & lock ordering"}]},"revision":1},{"id":"dadc2c00-641f-7d64-adb6-b07e11b41e63","type":"text","position":"aX","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread 1 holds lock A and waits for B; thread 2 holds B and waits for A — both wait forever. The standard cure is to "},{"type":"text","text":"always acquire locks in one global order","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"1dc02e39-27f0-7bdf-83f9-84fea9442606","type":"code","position":"aY","content":{"language":"python","code":"import threading\n\nclass Account:\n    def __init__(self, id, balance):\n        self.id, self.balance = id, balance\n        self.lock = threading.Lock()\n\ndef transfer(src, dst, amount):\n    first, second = sorted((src, dst), key=lambda a: a.id)   # fixed order, whatever the direction\n    with first.lock, second.lock:\n        src.balance -= amount\n        dst.balance += amount\n\na, b = Account(1, 100), Account(2, 100)\nt1 = threading.Thread(target=lambda: [transfer(a, b, 1) for _ in range(1000)])\nt2 = threading.Thread(target=lambda: [transfer(b, a, 1) for _ in range(1000)])\nt1.start(); t2.start(); t1.join(); t2.join()\nprint(a.balance, b.balance)               # 100 100","filename":"Python"},"revision":1},{"id":"6b6ebcb1-9aad-7f23-988e-82a16f633836","type":"text","position":"aZ","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Take locks in a consistent order (by id, by name, by address)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hold locks for as short a time as possible; never call unknown code (callbacks, I/O) while holding one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"lock.acquire(timeout=…)","marks":[{"type":"code"}]},{"type":"text","text":" to detect a stuck lock instead of hanging forever."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer message passing ("},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":") over many fine-grained locks."}]}]}]}]}},"revision":1},{"id":"e3d2cbea-543d-724a-82c0-e192723e8992","type":"heading","position":"aa","content":{"level":1,"content":[{"type":"text","text":"Timer"}]},"revision":1},{"id":"0500c2a2-0384-79b0-a8c5-109581a2f00d","type":"code","position":"ab","content":{"language":"python","code":"import threading\n\nfired = threading.Event()\nt = threading.Timer(0.01, fired.set)      # run fired.set() after 10 ms, in a new thread\nt.start()\nprint(fired.wait(timeout=1))              # True\n\nnever = threading.Timer(10, print, args=(\"never printed\",))\nnever.start()\nnever.cancel(); never.join()              # cancel before it fires\nprint(never.is_alive())                   # False","filename":"Python"},"revision":1},{"id":"94e090fd-b3b7-7dfa-b95d-b04b5b835481","type":"heading","position":"ac","content":{"level":1,"content":[{"type":"text","text":"Which built-in operations are thread-safe?"}]},"revision":1},{"id":"5e01e350-125a-76e6-98b6-515484cc9d81","type":"table","position":"ad","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Usually atomic (single operation on a built-in)"}],[{"type":"text","text":"NOT atomic — needs a lock"}]],[[{"type":"text","text":"L.append(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"L.pop()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"L.extend(ys)","marks":[{"type":"code"}]}],[{"type":"text","text":"x += 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"L[i] += 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"d[k] += 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"d[k] = v","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"d.get(k)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"d.pop(k, None)","marks":[{"type":"code"}]}],[{"type":"text","text":"if k not in d: d[k] = v","marks":[{"type":"code"}]},{"type":"text","text":" (check-then-act)"}]],[[{"type":"text","text":"x = L[i]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"q.put(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"q.get()","marks":[{"type":"code"}]}],[{"type":"text","text":"d[k] = d.get(k, 0) + 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"d.setdefault(k, v)","marks":[{"type":"code"}]}],[{"type":"text","text":"Any sequence of several operations that must stay consistent"}]]]},"revision":1},{"id":"3316c01b-54b3-7b4c-8a4b-c86b57595a86","type":"callout","position":"ae","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Atomicity of single built-in operations is a CPython implementation detail (the GIL on the default build, per-object locks on the free-threaded build). It''s fine to rely on "},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":"; for your own invariants, use a lock."}]}]}},"revision":1},{"id":"e8ed442e-8e11-71a1-9803-9368a14f226f","type":"question","position":"af","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a race condition and how do you prevent one?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The result depends on the unpredictable interleaving of threads — typically two threads doing read-modify-write on shared data. Prevent it by making the critical section atomic with a "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":", by confining data to one thread ("},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"threading.local","marks":[{"type":"code"}]},{"type":"text","text":"), or by using immutable data."}]}]}},"revision":1},{"id":"2cf68bff-4af5-77dc-a615-ebddbccdaa98","type":"question","position":"ag","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lock vs RLock?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":" can be acquired once; a second "},{"type":"text","text":"acquire()","marks":[{"type":"code"}]},{"type":"text","text":" — even from the same thread — blocks. An "},{"type":"text","text":"RLock","marks":[{"type":"code"}]},{"type":"text","text":" records its owner and a counter, so the owning thread can re-acquire it (it must release it the same number of times). Use "},{"type":"text","text":"RLock","marks":[{"type":"code"}]},{"type":"text","text":" when locked methods call other locked methods."}]}]}},"revision":1},{"id":"8f3792ad-2ee3-75f7-b73e-57d03c7ba05a","type":"question","position":"ah","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a deadlock and how do you avoid it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two or more threads each wait for a lock held by another, so none can proceed. Avoid it with a global lock-ordering rule, minimal lock scope, timeouts on "},{"type":"text","text":"acquire","marks":[{"type":"code"}]},{"type":"text","text":", and message passing instead of shared locks."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'cffc86bc-1fa8-7bbd-acfa-a68ff3b5a174' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
