0]\n\ndef largest[N: (int, float)](a: N, b: N) -> N:   # constrained type parameter\n    return a if a > b else b\n\nclass Box[T]:\n    def __init__(self, item: T) -> None:\n        self.item = item\n    def get(self) -> T:\n        return self.item\n\ntype Matrix = list[list[float]]           # type alias statement (3.12+)\n\nprint(first_old([\"a\"]), first([1, 2]), largest(2.5, 1.0), Box(\"x\").get())   # a 1 2.5 x\nprint(Matrix.__value__)                    # list[list[float]]","filename":"Python"},"revision":1},{"id":"72da2483-a5f4-7c72-96a9-9fef9206feec","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Overloads, "},{"type":"text","text":"Self","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cast","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"TYPE_CHECKING","marks":[{"type":"code"}]}]},"revision":1},{"id":"092a4e01-b672-7e0c-b559-7f791ea860e1","type":"code","position":"aD","content":{"language":"python","code":"from typing import overload, Self, cast, TYPE_CHECKING\n\nif TYPE_CHECKING:                   # only True for the type checker — avoids import cycles\n    from decimal import Decimal\n\n@overload\ndef parse(x: str) -> int: ...\n@overload\ndef parse(x: bytes) -> str: ...\ndef parse(x):                       # the one real implementation\n    return int(x) if isinstance(x, str) else x.decode()\n\nclass Query:\n    def __init__(self) -> None:\n        self.parts: list[str] = []\n    def where(self, cond: str) -> Self:   # subclasses get their own type back\n        self.parts.append(cond)\n        return self\n\ndef to_money(x: object) -> \"Decimal\":\n    return cast(\"Decimal\", x)       # tells the checker \"trust me\" — no runtime effect\n\nprint(parse(\"42\"), parse(b\"hi\"), Query().where(\"a\").where(\"b\").parts)   # 42 hi [''a'', ''b'']","filename":"Python"},"revision":1},{"id":"93ada62e-5c0c-73f6-85e4-da109961a08b","type":"heading","position":"a