  ('253fe8bf-1ab0-73cc-bb82-477371b9dc1b', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":" is a sequence of Unicode "},{"type":"text","text":"code points","marks":[{"type":"bold"}]},{"type":"text","text":"; "},{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":" is a sequence of raw 8-bit values. An "},{"type":"text","text":"encoding","marks":[{"type":"italic"}]},{"type":"text","text":" such as UTF-8 is the bridge — and most text bugs come from crossing that bridge carelessly."}]}]}}'),
  ('27a3eccc-36bd-7604-b767-914b38f94cba', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Code point","marks":[{"type":"bold"}]},{"type":"text","text":" — a number that identifies one Unicode character, written "},{"type":"text","text":"U+0041","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"ord()","marks":[{"type":"code"}]},{"type":"text","text":" gives it, "},{"type":"text","text":"chr()","marks":[{"type":"code"}]},{"type":"text","text":" goes back. Python strings index and measure in code points."}]}]}}'),
  ('ce23084d-d8b0-779b-b4ab-05de69144c49', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":" (text) → "},{"type":"text","text":".encode(''utf-8'')","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":" (disk / network) → "},{"type":"text","text":".decode(''utf-8'')","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"str","marks":[{"type":"code"}]}]}]}}'),
  ('1d67e859-2137-7e53-b9aa-1206ca3eb5a1', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Code points & escapes"}]}'),
  ('0c639256-3a33-740d-ba60-b9104ca8c028', 'a4', 'code', '{"language":"python","code":"print(ord(\"A\"), hex(ord(\"€\")), chr(0x1F600))       # 65 0x20ac 😀\nprint(\"\\u00e9\", \"\\U0001F40D\", \"\\N{GREEK SMALL LETTER PI}\")   # é 🐍 π\nimport unicodedata\nprint(unicodedata.name(\"€\"))                       # EURO SIGN\nprint(unicodedata.category(\"A\"), unicodedata.category(\"5\"))   # Lu Nd","filename":"Python"}'),
  ('b5888363-78c1-7a1e-9256-dc7e0cc51e20', 'a5', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Escape"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"\\xhh","marks":[{"type":"code"}]}],[{"type":"text","text":"Code point with 2 hex digits"}],[{"type":"text","text":"''\\xe9''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"é","marks":[{"type":"code"}]}]],[[{"type":"text","text":"\\uhhhh","marks":[{"type":"code"}]}],[{"type":"text","text":"4 hex digits (BMP)"}],[{"type":"text","text":"''\\u20ac''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"€","marks":[{"type":"code"}]}]],[[{"type":"text","text":"\\Uhhhhhhhh","marks":[{"type":"code"}]}],[{"type":"text","text":"8 hex digits (any code point)"}],[{"type":"text","text":"''\\U0001F600''","marks":[{"type":"code"}]},{"type":"text","text":" → 😀"}]],[[{"type":"text","text":"\\N{name}","marks":[{"type":"code"}]}],[{"type":"text","text":"By official Unicode name"}],[{"type":"text","text":"''\\N{SNOWMAN}''","marks":[{"type":"code"}]},{"type":"text","text":" → ☃"}]]]}'),
  ('6d538d6e-153b-7681-874d-ec74497c0f27', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"UTF-8: variable-length encoding"}]}'),
  ('cac9aba7-4f9c-7d48-9408-9857eec26546', 'a7', 'code', '{"language":"python","code":"for ch in [\"A\", \"é\", \"€\", \"😀\"]:\n    b = ch.encode(\"utf-8\")\n    print(ch, len(b), b)","filename":"Python"}'),
  ('46f512c1-e9ab-7b0f-9530-820104b459da', 'a8', 'code', '{"language":"text","code":"A 1 b''A''\né 2 b''\\xc3\\xa9''\n€ 3 b''\\xe2\\x82\\xac''\n😀 4 b''\\xf0\\x9f\\x98\\x80''","filename":"Output"}'),
  ('676dab7f-20cb-770b-aec7-2e32dffcb486', 'a9', 'code', '{"language":"python","code":"s = \"naïve café\"\nprint(len(s), len(s.encode(\"utf-8\")), len(s.encode(\"utf-16\")))   # 10 12 22\nprint(s.encode(\"utf-8\")[:3])                                    # b''na\\xc3''","filename":"Python"}'),
  ('634f8938-b178-79ad-b903-a05512e1d890', 'aA', 'callout', '{"variant":"note","title":"UTF-8","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"1–4 bytes per code point, ASCII-compatible, no byte-order issues. "},{"type":"text","text":"The default everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" — web, Linux, Python source files."}]}]}}'),
  ('2e74353f-d339-7947-abc5-6c1178e46721', 'aB', 'callout', '{"variant":"note","title":"UTF-16 / UTF-32","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"2–4 / always 4 bytes. Used internally by Windows, Java and JavaScript. Need a byte-order mark (BOM)."}]}]}}'),
  ('3df0f435-f25d-75d8-995b-8f44b01c4128', 'aC', 'callout', '{"variant":"note","title":"Latin-1 (ISO-8859-1)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One byte per character, only 256 characters. Decoding "},{"type":"text","text":"never fails","marks":[{"type":"bold"}]},{"type":"text","text":" — every byte maps to something (often wrong)."}]}]}}'),
  ('2aedfc58-3bdc-7203-bcaa-5e592a271afe', 'aD', 'callout', '{"variant":"note","title":"ASCII","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"7-bit, 128 characters. Any non-English text raises "},{"type":"text","text":"UnicodeEncodeError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('ef2c737d-e342-7ab3-93d4-d0de1a67b7ab', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Encoding errors and "},{"type":"text","text":"errors=","marks":[{"type":"code"}]}]}'),
  ('540e243b-3cac-7788-8f89-502cb76c6d3a', 'aF', 'code', '{"language":"python","code":"data = \"café\".encode(\"utf-8\")\nprint(data.decode(\"utf-8\"))                        # café\nprint(data.decode(\"latin-1\"))                      # cafÃ©   ← mojibake: wrong codec\ntry:\n    data.decode(\"ascii\")\nexcept UnicodeDecodeError as e:\n    print(e.reason, e.start)                       # ordinal not in range(128) 3\nprint(data.decode(\"ascii\", errors=\"replace\"))      # caf��\nprint(data.decode(\"ascii\", errors=\"ignore\"))       # caf\nprint(\"café\".encode(\"ascii\", errors=\"xmlcharrefreplace\"))   # b''caf&#233;''\nprint(\"café\".encode(\"ascii\", errors=\"backslashreplace\"))    # b''caf\\\\xe9''","filename":"Python"}'),
  ('8567add5-c7a0-7a62-bbb8-d315ed4099b6', 'aG', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"errors=","marks":[{"type":"code"}]}],[{"type":"text","text":"On bad data"}]],[[{"type":"text","text":"''strict''","marks":[{"type":"code"}]},{"type":"text","text":" (default)"}],[{"type":"text","text":"Raise "},{"type":"text","text":"UnicodeEncodeError","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"UnicodeDecodeError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"''replace''","marks":[{"type":"code"}]}],[{"type":"text","text":"Substitute "},{"type":"text","text":"?","marks":[{"type":"code"}]},{"type":"text","text":" (encode) or "},{"type":"text","text":"U+FFFD","marks":[{"type":"code"}]},{"type":"text","text":" � (decode)"}]],[[{"type":"text","text":"''ignore''","marks":[{"type":"code"}]}],[{"type":"text","text":"Silently drop — loses data"}]],[[{"type":"text","text":"''backslashreplace''","marks":[{"type":"code"}]}],[{"type":"text","text":"Write escapes like "},{"type":"text","text":"\\xe9","marks":[{"type":"code"}]}]],[[{"type":"text","text":"''surrogateescape''","marks":[{"type":"code"}]}],[{"type":"text","text":"Round-trip undecodable bytes (used for OS file names)"}]]]}'),
  ('0a214632-da3a-7fa8-9b1e-ad22346b4787', 'aH', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mojibake","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"cafÃ©","marks":[{"type":"code"}]},{"type":"text","text":") means text was encoded with one codec and decoded with another. Fix it at the boundary — always state the encoding when you read or write."}]}]}}'),
  ('55d2f50d-32ea-7061-a57b-64d043f1f880', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bytearray","marks":[{"type":"code"}]},{"type":"text","text":" & "},{"type":"text","text":"memoryview","marks":[{"type":"code"}]}]}'),
  ('1f490510-9628-7a4b-9613-6ca1f9e484cd', 'aJ', 'code', '{"language":"python","code":"b = b\"hi\\x00\\xff\"\nprint(b[0], b[-1], list(b))            # 104 255 [104, 105, 0, 255]\nprint(b[:2], type(b[:2]).__name__)     # b''hi'' bytes\nprint(b.hex(), bytes.fromhex(\"48 69\"))  # 686900ff b''Hi''\nprint(bytes([72, 105]), bytes(3))      # b''Hi'' b''\\x00\\x00\\x00''\n\nbuf = bytearray(b\"hello\")              # mutable\nbuf[0] = ord(\"J\")\nbuf.extend(b\"!\")\nprint(buf, bytes(buf))                 # bytearray(b''Jello!'') b''Jello!''\n\nview = memoryview(buf)[1:4]            # zero-copy slice\nview[0] = ord(\"E\")\nprint(buf)                             # bytearray(b''JEllo!'')","filename":"Python"}'),
  ('c2cee993-97b2-73de-b65c-ef6976f5dce4', 'aK', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Mutable"}],[{"type":"text","text":"Indexing gives"}],[{"type":"text","text":"Use for"}]],[[{"type":"text","text":"str","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"a 1-char "},{"type":"text","text":"str","marks":[{"type":"code"}]}],[{"type":"text","text":"Human text"}]],[[{"type":"text","text":"bytes","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"an "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" 0–255"}],[{"type":"text","text":"Binary data, network payloads, hashes"}]],[[{"type":"text","text":"bytearray","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"an "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" 0–255"}],[{"type":"text","text":"Building/patching binary buffers"}]],[[{"type":"text","text":"memoryview","marks":[{"type":"code"}]}],[{"type":"text","text":"Follows the buffer"}],[{"type":"text","text":"an "},{"type":"text","text":"int","marks":[{"type":"code"}]}],[{"type":"text","text":"Zero-copy slices of large buffers"}]]]}'),
  ('446b6d53-4539-7c87-988e-bbc03711b57b', 'aL', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You can''t mix them: "},{"type":"text","text":"''a'' + b''b''","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":". Decode bytes to text as early as possible and encode as late as possible (the "},{"type":"text","text":"Unicode sandwich","marks":[{"type":"italic"}]},{"type":"text","text":")."}]}]}}'),
  ('dd8b840e-17e9-7d4e-8cc6-0d6f68a3a51b', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Normalization: same text, different code points"}]}'),
  ('982eaa71-e4ec-70dc-8f53-6b01fe979399', 'aN', 'code', '{"language":"python","code":"import unicodedata\na = \"café\"                        # é as one code point U+00E9\nb = \"cafe\\u0301\"                  # e + COMBINING ACUTE ACCENT\nprint(a == b)                     # False   ← both render as \"café\"\nprint(len(a), len(b))             # 4 5\nnfc = lambda s: unicodedata.normalize(\"NFC\", s)\nprint(nfc(a) == nfc(b))           # True\nprint(len(unicodedata.normalize(\"NFD\", a)))   # 5\nprint(unicodedata.normalize(\"NFKC\", \"ﬁ①\"))   # fi1","filename":"Python"}'),
  ('8f8b8c31-edd2-7656-a15c-6060d82e3db0', 'aO', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Does"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"NFC"}],[{"type":"text","text":"Compose into single code points where possible"}],[{"type":"text","text":"Storing and comparing text (the web default)"}]],[[{"type":"text","text":"NFD"}],[{"type":"text","text":"Decompose into base + combining marks"}],[{"type":"text","text":"Stripping accents"}]],[[{"type":"text","text":"NFKC / NFKD"}],[{"type":"text","text":"Also fold "},{"type":"text","text":"compatibility","marks":[{"type":"italic"}]},{"type":"text","text":" forms: "},{"type":"text","text":"ﬁ","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"fi","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"①","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"1","marks":[{"type":"code"}]}],[{"type":"text","text":"Search, identifiers, user names"}]]]}'),
  ('78493654-ac0b-7aaf-b0a0-1a7f35fe3342', 'aP', 'code', '{"language":"python","code":"import unicodedata\ndef strip_accents(s):\n    decomposed = unicodedata.normalize(\"NFD\", s)\n    return \"\".join(c for c in decomposed if not unicodedata.combining(c))\n\nprint(strip_accents(\"Crème brûlée à São Paulo\"))   # Creme brulee a Sao Paulo\ndef same_text(x, y):\n    norm = lambda s: unicodedata.normalize(\"NFC\", s).casefold()\n    return norm(x) == norm(y)\nprint(same_text(\"STRASSE\", \"straße\"))             # True","filename":"Python"}'),
  ('f131c090-98e4-7e87-bd9a-f9ba2099be0f', 'aQ', 'heading', '{"level":1,"content":[{"type":"text","text":"Length isn''t what users see"}]}'),
  ('d913cec9-46b6-7c75-b724-0acf91c5abdd', 'aR', 'code', '{"language":"python","code":"thumbs = \"👍🏽\"                        # thumbs up + skin-tone modifier\nfamily = \"👨\\u200d👩\\u200d👧\"           # joined with ZERO WIDTH JOINERs\nflag = \"🇮🇳\"                           # two regional-indicator letters\nprint(len(thumbs), len(family), len(flag))   # 2 5 2\nprint(thumbs[::-1] == thumbs)              # False   ← reversing splits the emoji","filename":"Python"}'),
  ('d39747c1-5a1e-7e25-a881-a7826287bdae', 'aS', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A user-perceived character (a "},{"type":"text","text":"grapheme cluster","marks":[{"type":"italic"}]},{"type":"text","text":") can be several code points. "},{"type":"text","text":"len","marks":[{"type":"code"}]},{"type":"text","text":", slicing and "},{"type":"text","text":"[::-1]","marks":[{"type":"code"}]},{"type":"text","text":" work on code points, so they can cut emoji or accented letters in half. For true grapheme handling use the third-party "},{"type":"text","text":"grapheme","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"regex","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"\\X","marks":[{"type":"code"}]},{"type":"text","text":") modules."}]}]}}'),
  ('8365adfe-244c-748d-b808-281c7be7d7a6', 'aT', 'heading', '{"level":1,"content":[{"type":"text","text":"Files & encodings"}]}'),
  ('671f3bbe-7bad-7dfb-97ca-3cdd8967b8f2', 'aU', 'code', '{"language":"python","code":"import tempfile, os\npath = os.path.join(tempfile.mkdtemp(), \"bom.csv\")\nwith open(path, \"w\", encoding=\"utf-8-sig\") as f:     # writes a BOM (Excel likes it)\n    f.write(\"name\\nAsha\\n\")\nwith open(path, \"rb\") as f:\n    print(f.read(3))                                  # b''\\xef\\xbb\\xbf''\nwith open(path, encoding=\"utf-8\") as f:\n    print(repr(f.readline()))                         # ''\\ufeffname\\n''\nwith open(path, encoding=\"utf-8-sig\") as f:           # strips the BOM\n    print(repr(f.readline()))                         # ''name\\n''","filename":"Python"}'),
  ('885d638c-7aee-71ee-9fa8-69c0a73aed37', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always pass "},{"type":"text","text":"encoding=''utf-8''","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"open()","marks":[{"type":"code"}]},{"type":"text","text":" in text mode — the default depends on the OS locale (Python 3.15 makes UTF-8 the default)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open binary files ("},{"type":"text","text":"''rb''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"''wb''","marks":[{"type":"code"}]},{"type":"text","text":") for images, zips and anything you''ll hash — you get "},{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":", no decoding."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"utf-8-sig","marks":[{"type":"code"}]},{"type":"text","text":" reads files with or without a BOM; use it for CSVs from Excel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"sys.getdefaultencoding()","marks":[{"type":"code"}]},{"type":"text","text":" is always "},{"type":"text","text":"''utf-8''","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"locale.getpreferredencoding()","marks":[{"type":"code"}]},{"type":"text","text":" is what "},{"type":"text","text":"open()","marks":[{"type":"code"}]},{"type":"text","text":" uses by default."}]}]}]}]}}'),
  ('74e98d28-83ff-7d29-bf8b-6b5a4701a84a', 'aW', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview questions"}]}'),
  ('a411a1c6-926e-7ef3-8fed-af7cba9275b7', 'aX', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between str and bytes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":" is text: a sequence of Unicode code points. "},{"type":"text","text":"bytes","marks":[{"type":"code"}]},{"type":"text","text":" is binary data: a sequence of integers 0–255. You convert with "},{"type":"text","text":"str.encode(encoding)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"bytes.decode(encoding)","marks":[{"type":"code"}]},{"type":"text","text":"; you can''t concatenate them directly."}]}]}}'),
  ('9e51ec49-42be-7b05-8231-3d9953f14e75', 'aY', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is len(''é'') sometimes 1 and sometimes 2?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"é","marks":[{"type":"code"}]},{"type":"text","text":" can be one precomposed code point (U+00E9) or "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":" plus a combining accent (U+0301). Both render the same. Normalize with "},{"type":"text","text":"unicodedata.normalize(''NFC'', s)","marks":[{"type":"code"}]},{"type":"text","text":" before comparing or measuring."}]}]}}'),
  ('9f14a3d0-4435-7cdf-8931-ddfe3b911e3d', 'aZ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is UTF-8 and why is it the default?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A variable-length encoding of Unicode using 1–4 bytes per code point. It is backward-compatible with ASCII, has no byte-order issues, is compact for English text, and can encode every character — so it became the standard for files, the web and Python source code."}]}]}}')
) AS c(id, position, type, content)
