SELECT '3a46161b-258e-73a2-a75d-9ff1e5cd6428', '3eb92f33-c653-7d2c-8a85-8ca28766d4a7', 1, 'PUBLISHED', 'Arrays', '[{"id":"e7685379-c7c3-7e2c-9ffb-e482f55eb1f7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array is a fixed-size block of "},{"type":"text","text":"contiguous","marks":[{"type":"italic"}]},{"type":"text","text":" elements of one type, indexed from 0. C never checks the index — staying in bounds is your job."}]}]}},"revision":1},{"id":"0c7f2463-1d31-7398-8424-f664fcb1c898","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Declaring and initialising"}]},"revision":1},{"id":"1e8acdac-dd48-7b12-ae93-7b2ba4f81584","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[5] = {10, 20, 30, 40, 50};\n    int b[5] = {1, 2};              /* rest are zero: 1 2 0 0 0 */\n    int c[] = {7, 8, 9};            /* size deduced: 3 */\n    int d[5] = {0};                 /* all zeros */\n    int e[6] = {[2] = 5, [4] = 9};  /* designated initializers (C99) */\n\n    size_t n = sizeof a / sizeof a[0];     /* element count */\n    printf(\"n=%zu sizeof(c)=%zu\\n\", n, sizeof c);\n    for (int i = 0; i < 5; i++) printf(\"%d \", b[i]);\n    printf(\"| %d | \", d[3]);\n    for (int i = 0; i < 6; i++) printf(\"%d \", e[i]);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"afe9b4b7-71ac-7ab0-864d-11c86bd6014f","type":"code","position":"a3","content":{"language":"text","code":"n=5 sizeof(c)=12\n1 2 0 0 0 | 0 | 0 0 5 0 9 0","filename":"Output"},"revision":1},{"id":"21ebe482-d24a-77be-b4dc-fe120fb16fbb","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"sizeof arr / sizeof arr[0]","marks":[{"type":"code"}]},{"type":"text","text":" gives the element count — but "},{"type":"text","text":"only","marks":[{"type":"bold"}]},{"type":"text","text":" where "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":" is a real array. Inside a function that received it as a parameter, "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":" is a pointer and the trick silently returns 2 (8 / 4)."}]}]}},"revision":1},{"id":"bb149b7f-6870-736d-88d5-744eb548af1c","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Memory layout"}]},"revision":1},{"id":"a16661af-805b-7e28-b12e-dba2648550eb","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Index"}],[{"type":"text","text":"0"}],[{"type":"text","text":"1"}],[{"type":"text","text":"2"}],[{"type":"text","text":"3"}],[{"type":"text","text":"4"}]],[[{"type":"text","text":"Value"}],[{"type":"text","text":"10"}],[{"type":"text","text":"20"}],[{"type":"text","text":"30"}],[{"type":"text","text":"40"}],[{"type":"text","text":"50"}]],[[{"type":"text","text":"Offset (bytes)"}],[{"type":"text","text":"0"}],[{"type":"text","text":"4"}],[{"type":"text","text":"8"}],[{"type":"text","text":"12"}],[{"type":"text","text":"16"}]]]},"revision":1},{"id":"37639e3b-8c5c-740b-b415-3b9434da601b","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"a[i]","marks":[{"type":"code"}]},{"type":"text","text":" is defined as "},{"type":"text","text":"*(a + i)","marks":[{"type":"code"}]},{"type":"text","text":": start address plus "},{"type":"text","text":"i × sizeof(int)","marks":[{"type":"code"}]},{"type":"text","text":". That is why indexing is O(1) — and why an index past the end silently reads whatever lies next in memory."}]}]}},"revision":1},{"id":"a7307554-0467-7048-a220-5d0e5036f939","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Passing arrays to functions"}]},"revision":1},{"id":"2737626f-2640-742c-b483-cc39014e6a1d","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n\n/* the array decays to a pointer: the size must travel separately */\nint max_of(const int arr[], size_t n) {\n    int best = arr[0];\n    for (size_t i = 1; i < n; i++)\n        if (arr[i] > best) best = arr[i];\n    return best;\n}\n\nvoid double_all(int *arr, size_t n) {     /* same as int arr[] */\n    for (size_t i = 0; i < n; i++) arr[i] *= 2;\n}\n\nint main(void) {\n    int v[] = {3, 9, 2, 7};\n    size_t n = sizeof v / sizeof v[0];\n    double_all(v, n);                      /* modifies the caller''s array */\n    printf(\"max = %d, v[0] = %d\\n\", max_of(v, n), v[0]);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"9efa87d9-72bc-7140-a874-ad7886901650","type":"code","position":"aA","content":{"language":"text","code":"max = 18, v[0] = 6","filename":"Output"},"revision":1},{"id":"4c6bd96b-1e4a-7b82-9032-bc985693f790","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Common array algorithms"}]},"revision":1},{"id":"76c6c287-eba1-7303-8761-ad86e7152a4f","type":"code","position":"aC","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[] = {4, -1, 7, 3, 7, 0};\n    int n = sizeof a / sizeof a[0];\n\n    int sum = 0, maxi = 0;\n    for (int i = 0; i < n; i++) {\n        sum += a[i];\n        if (a[i] > a[maxi]) maxi = i;\n    }\n    printf(\"sum=%d max=%d at %d\\n\", sum, a[maxi], maxi);\n\n    /* linear search */\n    int key = 3, pos = -1;\n    for (int i = 0; i < n; i++) if (a[i] == key) { pos = i; break; }\n    printf(\"3 found at %d\\n\", pos);\n\n    /* rotate left by one */\n    int first = a[0];\n    for (int i = 0; i < n - 1; i++) a[i] = a[i + 1];\n    a[n - 1] = first;\n    for (int i = 0; i < n; i++) printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"34bf6be8-76a2-7c01-b037-626dd160a969","type":"code","position":"aD","content":{"language":"text","code":"sum=20 max=7 at 2\n3 found at 3\n-1 7 3 7 0 4","filename":"Output"},"revision":1},{"id":"a7c15a62-7541-78ab-ad3a-a24bb227c7bc","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Variable-length arrays (C99)"}]},"revision":1},{"id":"b2f44206-15e2-70d3-bd04-6777a8629eea","type":"code","position":"aF","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int n = 4;\n    int squares[n];                   /* size known only at run time: VLA on the stack */\n    for (int i = 0; i < n; i++) squares[i] = i * i;\n    printf(\"%d %zu\\n\", squares[3], sizeof squares);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"0c268d72-6a07-71e0-8225-424dd1359241","type":"code","position":"aG","content":{"language":"text","code":"9 16","filename":"Output"},"revision":1},{"id":"b68c48d5-3c8b-7d5c-b5cc-77e913ee60c1","type":"callout","position":"aH","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"VLAs live on the stack: a large or attacker-controlled size overflows the stack with no error reported. They became "},{"type":"text","text":"optional","marks":[{"type":"italic"}]},{"type":"text","text":" in C11, and the Linux kernel bans them. Prefer "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" for run-time sizes."}]}]}},"revision":1},{"id":"8bcfaa17-6759-71c8-a6fa-fb7fe56ea017","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Out of bounds is undefined behaviour"}]},"revision":1},{"id":"c1cbcb6b-24c5-77ec-93d9-92caae94e75c","type":"code","position":"aJ","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[5] = {1, 2, 3, 4, 5};\n    int sum = 0;\n    for (int i = 0; i <= 5; i++)    /* off by one: touches a[5] */\n        sum += a[i];\n    printf(\"%d\\n\", sum);\n    return 0;\n}","filename":"C — caught by the sanitizer"},"revision":1},{"id":"7825e774-1aa7-70dc-9650-b03551e058d7","type":"code","position":"aK","content":{"language":"text","code":"main.c:7:16: runtime error: index 5 out of bounds for type ''int[5]''","filename":"UBSan"},"revision":1},{"id":"b34650e2-dc32-73ed-9f6f-230bc193c4f6","type":"callout","position":"aL","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the length next to the pointer ("},{"type":"text","text":"const int *a, size_t n","marks":[{"type":"code"}]},{"type":"text","text":"), and loop with "},{"type":"text","text":"i < n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e78f2e52-e5e9-79a8-84e9-d2cbd83be5ed","type":"callout","position":"aM","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rely on a sentinel you never wrote, or on "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" of a parameter."}]}]}},"revision":1},{"id":"2bb709b4-3f07-7880-9b45-15b36ae02967","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t you assign one array to another with =?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array is not a modifiable lvalue: in most expressions its name decays to a pointer to its first element, so "},{"type":"text","text":"a = b","marks":[{"type":"code"}]},{"type":"text","text":" would mean assigning to an address. Copy element by element or with "},{"type":"text","text":"memcpy(a, b, sizeof a)","marks":[{"type":"code"}]},{"type":"text","text":". (Wrapping an array in a "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" makes it copyable by assignment.)"}]}]}},"revision":1},{"id":"1115e40e-7563-7bbc-bff5-c02139710552","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is array decay?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In almost every expression, an array of "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" is converted to a pointer to its first element ("},{"type":"text","text":"T *","marks":[{"type":"code"}]},{"type":"text","text":"). The exceptions are "},{"type":"text","text":"sizeof arr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"&arr","marks":[{"type":"code"}]},{"type":"text","text":" and a string literal used to initialise a "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" array. Decay is why functions cannot know an array''s length."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
