  ('3fda1882-afec-70f7-b4c9-df27f7f23386', 'aF', 'heading', '{"level":1,"content":[{"type":"text","text":"Debugging workflow"}]}'),
  ('79af3a27-5bed-75a9-8329-f1330be6e39f', 'aG', 'code', '{"language":"","code":"$ gcc -g -O0 -Wall -Wextra -fsanitize=address,undefined app.c -o app\n$ ./app                       # sanitizer reports file:line of the first bad access\n$ gdb ./app                   # or: lldb ./app\n(gdb) break parse_line        # stop in a function\n(gdb) run input.txt\n(gdb) next / step / finish    # step over / into / out of\n(gdb) print *node             # inspect memory\n(gdb) bt                      # backtrace after a crash\n(gdb) watch count             # stop when a variable changes","filename":"Terminal"}'),
  ('201453f9-2ddf-75db-af7a-efba16c7be4e', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you debug a segmentation fault?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rebuild with "},{"type":"text","text":"-g -fsanitize=address,undefined","marks":[{"type":"code"}]},{"type":"text","text":" and rerun — the sanitizer usually names the exact bad access and where the memory was allocated/freed. Otherwise run under "},{"type":"text","text":"gdb","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"lldb","marks":[{"type":"code"}]},{"type":"text","text":" (or load the core dump) and take a backtrace ("},{"type":"text","text":"bt","marks":[{"type":"code"}]},{"type":"text","text":") to see the crashing line, then inspect the pointers involved. Valgrind is the alternative when you cannot recompile."}]}]}}')
