INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '32969b21-d979-7e62-bf73-d00cfcf40e11', '79003f5f-b10f-700f-ba25-0b37b9a1f2e9', 1, 'PUBLISHED', 'Binary Search Tree', '[{"id":"5cc44a7d-724d-7b95-bd42-81ad075fa247","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A binary tree where every left descendant is smaller and every right descendant is larger than the node. Search, insert and delete are O(h) — O(log n) when balanced, O(n) when degenerate."}]}]}},"revision":1},{"id":"3b2d2a35-e184-70a6-9329-c6317e21dcef","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Tree { int key; struct Tree *left, *right; } Tree;\n\nTree *insert(Tree *t, int key) {\n    if (!t) {\n        t = malloc(sizeof *t);\n        if (!t) exit(1);\n        t->key = key; t->left = t->right = NULL;\n    } else if (key < t->key) t->left = insert(t->left, key);\n    else if (key > t->key)   t->right = insert(t->right, key);\n    return t;                                  /* duplicates ignored */\n}\n\nconst Tree *search(const Tree *t, int key) {\n    while (t && t->key != key) t = key < t->key ? t->left : t->right;\n    return t;\n}\n\nTree *delete(Tree *t, int key) {\n    if (!t) return NULL;\n    if (key < t->key) t->left = delete(t->left, key);\n    else if (key > t->key) t->right = delete(t->right, key);\n    else if (!t->left || !t->right) {          /* 0 or 1 child */\n        Tree *child = t->left ? t->left : t->right;\n        free(t);\n        return child;\n    } else {                                   /* 2 children: copy in-order successor */\n        Tree *s = t->right;\n        while (s->left) s = s->left;\n        t->key = s->key;\n        t->right = delete(t->right, s->key);\n    }\n    return t;\n}\n\nvoid inorder(const Tree *t)  { if (t) { inorder(t->left); printf(\"%d \", t->key); inorder(t->right); } }\nvoid preorder(const Tree *t) { if (t) { printf(\"%d \", t->key); preorder(t->left); preorder(t->right); } }\nint height(const Tree *t) {\n    if (!t) return 0;\n    int l = height(t->left), r = height(t->right);\n    return 1 + (l > r ? l : r);\n}\nvoid destroy(Tree *t) { if (t) { destroy(t->left); destroy(t->right); free(t); } }  /* postorder */\n\nint main(void) {\n    Tree *root = NULL;\n    int keys[] = {50, 30, 70, 20, 40, 60, 80};\n    for (int i = 0; i < 7; i++) root = insert(root, keys[i]);\n\n    printf(\"inorder:  \"); inorder(root);  printf(\"\\n\");\n    printf(\"preorder: \"); preorder(root); printf(\"\\n\");\n    printf(\"height %d, has 60? %s, has 65? %s\\n\", height(root),\n           search(root, 60) ? \"yes\" : \"no\", search(root, 65) ? \"yes\" : \"no\");\n\n    root = delete(root, 50);                   /* root with two children */\n    printf(\"after deleting 50: \"); inorder(root); printf(\"(root %d)\\n\", root->key);\n    destroy(root);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"6dd8eb53-b0e1-7628-89d4-1c679305219a","type":"code","position":"a2","content":{"language":"text","code":"inorder:  20 30 40 50 60 70 80\npreorder: 50 30 20 40 70 60 80\nheight 3, has 60? yes, has 65? no\nafter deleting 50: 20 30 40 60 70 80 (root 60)","filename":"Output"},"revision":1},{"id":"4416454a-1821-7069-a357-1c950be714eb","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Traversal"}],[{"type":"text","text":"Order"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"In-order"}],[{"type":"text","text":"left, node, right"}],[{"type":"text","text":"Sorted output of a BST"}]],[[{"type":"text","text":"Pre-order"}],[{"type":"text","text":"node, left, right"}],[{"type":"text","text":"Copy / serialise a tree"}]],[[{"type":"text","text":"Post-order"}],[{"type":"text","text":"left, right, node"}],[{"type":"text","text":"Free a tree (children before parent)"}]],[[{"type":"text","text":"Level-order"}],[{"type":"text","text":"breadth-first with a queue"}],[{"type":"text","text":"Print by levels, shortest path in unweighted trees"}]]]},"revision":1},{"id":"351f8bf8-9ad0-76d9-af73-35b9d11d7f14","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inserting already-sorted keys produces a linked list (height n) and O(n) operations. Self-balancing trees (AVL, red-black) keep the height O(log n)."}]}]}},"revision":1},{"id":"21265980-a7ec-78dc-857a-5b2974ac1a63","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you check whether a binary tree is a valid BST?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurse with an allowed range: every node’s key must lie strictly between a lower and upper bound inherited from its ancestors ("},{"type":"text","text":"check(node->left, lo, node->key)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"check(node->right, node->key, hi)","marks":[{"type":"code"}]},{"type":"text","text":"). Comparing a node only with its direct children is not enough."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
