SELECT 'a9fda758-3db9-7913-9a60-d34e56a670f1', '4f0fc33e-1fdf-7e36-8824-fac1047aefa2', 1, 'PUBLISHED', 'Bit-fields', '[{"id":"24ce8d28-27b4-7017-aa3d-8dbcc13de9f0","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bit-field is a struct member with an explicit width in bits. It packs several small values into one integer — flags, compact records, protocol headers."}]}]}},"revision":1},{"id":"5ed33598-6aef-7bff-b18c-e58951b0992d","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n\nstruct Flags {\n    unsigned int visible  : 1;\n    unsigned int editable : 1;\n    unsigned int priority : 3;     /* 0..7 */\n    unsigned int reserved : 3;\n};\n\nstruct Date {                      /* day 1-31, month 1-12, year offset 0-127 */\n    unsigned int day   : 5;\n    unsigned int month : 4;\n    unsigned int year  : 7;\n};\n\nint main(void) {\n    struct Flags f = {.visible = 1, .priority = 5};\n    f.editable = 1;\n    printf(\"%u %u %u, sizeof = %zu\\n\", f.visible, f.editable, f.priority, sizeof f);\n\n    f.priority = 9;                /* 9 doesn''t fit in 3 bits: stored modulo 8 */\n    printf(\"priority now %u\\n\", f.priority);\n\n    struct Date d = {29, 9, 26};   /* 2026 as an offset from 2000 */\n    printf(\"%02u/%02u/%u in %zu bytes\\n\", d.day, d.month, 2000 + d.year, sizeof d);\n    return 0;\n}","filename":"C — compiled with -Wno-bitfield-constant-conversion to show the truncation"},"revision":1},{"id":"0c7bcf94-7fc4-75e0-a653-b9fd5b603371","type":"code","position":"a2","content":{"language":"text","code":"1 1 5, sizeof = 4\npriority now 1\n29/09/2026 in 4 bytes","filename":"Output"},"revision":1},{"id":"ae24e952-1dfb-7f41-917f-b6c1619ec74b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Rules and limits"}]},"revision":1},{"id":"1f54857b-2baf-7d06-80dd-f4a620780840","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allowed types: "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"signed int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_Bool","marks":[{"type":"code"}]},{"type":"text","text":" (and others as an extension). Use "},{"type":"text","text":"unsigned","marks":[{"type":"code"}]},{"type":"text","text":" — the signedness of a plain "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" bit-field is implementation-defined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You "},{"type":"text","text":"cannot","marks":[{"type":"bold"}]},{"type":"text","text":" take the address of a bit-field ("},{"type":"text","text":"&f.visible","marks":[{"type":"code"}]},{"type":"text","text":" is an error) or make arrays of them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Layout (bit order, whether fields straddle storage units, padding) is "},{"type":"text","text":"implementation-defined","marks":[{"type":"bold"}]},{"type":"text","text":" — don’t use bit-fields to match an external binary format portably."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An unnamed field "},{"type":"text","text":"unsigned : 0;","marks":[{"type":"code"}]},{"type":"text","text":" forces the next field to start in a new storage unit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reading/writing a bit-field compiles to load-mask-shift-store — slower than a plain "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", and not atomic."}]}]}]}]}},"revision":1},{"id":"fef9c33c-48e9-731b-bb2a-a31c5b02e596","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Bit-fields vs masks"}]},"revision":1},{"id":"384c187b-f7d8-7569-a4bd-16fecf008b49","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Bit-fields"}],[{"type":"text","text":"Manual masks ("},{"type":"text","text":"flags & MASK","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Readable: "},{"type":"text","text":"f.priority = 5","marks":[{"type":"code"}]}],[{"type":"text","text":"Verbose: "},{"type":"text","text":"f = (f & ~PRIO_MASK) | (5u << PRIO_SHIFT)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Layout implementation-defined"}],[{"type":"text","text":"Layout exactly what you write"}]],[[{"type":"text","text":"Can’t take address, can’t pass a set of flags easily"}],[{"type":"text","text":"Flags combine naturally: "},{"type":"text","text":"READ | WRITE","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Good for in-memory compact records"}],[{"type":"text","text":"Good for hardware registers, file/network formats"}]]]},"revision":1},{"id":"cd59859e-ef6f-7010-8705-70caa1d375cb","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you take the address of a bit-field member?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Bit-fields may start in the middle of a byte, and pointers address whole bytes, so "},{"type":"text","text":"&s.field","marks":[{"type":"code"}]},{"type":"text","text":" is a compile error. "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" can''t be applied to a bit-field either."}]}]}},"revision":1},{"id":"cffeb713-fa59-750c-a317-a5f9bcab51a8","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the size of struct { unsigned a:3; unsigned b:5; }?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Typically 4 bytes: both fields fit into one "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":" storage unit (8 bits used), and the struct is padded to the alignment of "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":". The exact layout is implementation-defined."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
