  ('1f54857b-2baf-7d06-80dd-f4a620780840', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allowed types: "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"signed int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_Bool","marks":[{"type":"code"}]},{"type":"text","text":" (and others as an extension). Use "},{"type":"text","text":"unsigned","marks":[{"type":"code"}]},{"type":"text","text":" — the signedness of a plain "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" bit-field is implementation-defined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You "},{"type":"text","text":"cannot","marks":[{"type":"bold"}]},{"type":"text","text":" take the address of a bit-field ("},{"type":"text","text":"&f.visible","marks":[{"type":"code"}]},{"type":"text","text":" is an error) or make arrays of them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Layout (bit order, whether fields straddle storage units, padding) is "},{"type":"text","text":"implementation-defined","marks":[{"type":"bold"}]},{"type":"text","text":" — don’t use bit-fields to match an external binary format portably."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An unnamed field "},{"type":"text","text":"unsigned : 0;","marks":[{"type":"code"}]},{"type":"text","text":" forces the next field to start in a new storage unit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reading/writing a bit-field compiles to load-mask-shift-store — slower than a plain "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", and not atomic."}]}]}]}]}}'),
