SELECT '9c1abeeb-a6a5-7827-bc98-bcd74bb7634b', 'd1e547bc-5341-798c-9900-fffb0f17c659', 1, 'PUBLISHED', 'Bitwise Operators & Bit Tricks', '[{"id":"d06b7736-9890-779b-b45b-87dddd39dc1c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C lets you manipulate individual bits — the basis of flags, masks, hardware registers, compression, hashing and many interview puzzles."}]}]}},"revision":1},{"id":"624434c9-9333-74ec-bd82-f6f1468f27f5","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operator"}],[{"type":"text","text":"Name"}],[{"type":"text","text":"Example (a = 12 = "},{"type":"text","text":"1100","marks":[{"type":"code"}]},{"type":"text","text":", b = 10 = "},{"type":"text","text":"1010","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Result"}]],[[{"type":"text","text":"a & b","marks":[{"type":"code"}]}],[{"type":"text","text":"AND"}],[{"type":"text","text":"1100 & 1010","marks":[{"type":"code"}]}],[{"type":"text","text":"1000","marks":[{"type":"code"}]},{"type":"text","text":" = 8"}]],[[{"type":"text","text":"a | b","marks":[{"type":"code"}]}],[{"type":"text","text":"OR"}],[{"type":"text","text":"1100 | 1010","marks":[{"type":"code"}]}],[{"type":"text","text":"1110","marks":[{"type":"code"}]},{"type":"text","text":" = 14"}]],[[{"type":"text","text":"a ^ b","marks":[{"type":"code"}]}],[{"type":"text","text":"XOR"}],[{"type":"text","text":"1100 ^ 1010","marks":[{"type":"code"}]}],[{"type":"text","text":"0110","marks":[{"type":"code"}]},{"type":"text","text":" = 6"}]],[[{"type":"text","text":"~a","marks":[{"type":"code"}]}],[{"type":"text","text":"NOT (one’s complement)"}],[{"type":"text","text":"~12","marks":[{"type":"code"}]}],[{"type":"text","text":"−13 (for "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"a << n","marks":[{"type":"code"}]}],[{"type":"text","text":"left shift"}],[{"type":"text","text":"12 << 1","marks":[{"type":"code"}]}],[{"type":"text","text":"24 (× 2ⁿ)"}]],[[{"type":"text","text":"a >> n","marks":[{"type":"code"}]}],[{"type":"text","text":"right shift"}],[{"type":"text","text":"12 >> 2","marks":[{"type":"code"}]}],[{"type":"text","text":"3 (÷ 2ⁿ for non-negative)"}]]]},"revision":1},{"id":"16db3e2d-1647-7664-aa84-945e8499e167","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\nvoid print_bits(unsigned x, int width) {\n    for (int i = width - 1; i >= 0; i--)\n        putchar((x >> i) & 1u ? ''1'' : ''0'');\n    putchar(''\\n'');\n}\n\nint main(void) {\n    unsigned a = 12, b = 10;\n    printf(\"%u %u %u %u %u\\n\", a & b, a | b, a ^ b, a << 1, a >> 2);\n    print_bits(a, 8);\n    print_bits(~a & 0xFFu, 8);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"0cc0e215-dd9d-7749-96ee-a07909004e67","type":"code","position":"a3","content":{"language":"text","code":"8 14 6 24 3\n00001100\n11110011","filename":"Output"},"revision":1},{"id":"090fd4ef-ed51-7a1a-b1d6-ec317ec98d84","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Set, clear, toggle, test"}]},"revision":1},{"id":"64743a42-263f-79f6-9ab2-f25e9b116a2d","type":"code","position":"a5","content":{"language":"c","code":"#include <stdio.h>\n\n#define BIT(n) (1u << (n))\n\nint main(void) {\n    unsigned flags = 0;\n    flags |= BIT(3);              /* set bit 3     */\n    flags |= BIT(0);              /* set bit 0     */\n    printf(\"%u\\n\", flags);        /* 1001 = 9      */\n    flags &= ~BIT(0);             /* clear bit 0   */\n    flags ^= BIT(1);              /* toggle bit 1  */\n    printf(\"%u\\n\", flags);        /* 1010 = 10     */\n    printf(\"bit 3 is %s\\n\", (flags & BIT(3)) ? \"set\" : \"clear\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b6068636-d459-77fd-ac22-30e04fdafc9f","type":"code","position":"a6","content":{"language":"text","code":"9\n10\nbit 3 is set","filename":"Output"},"revision":1},{"id":"a3b3b2e2-9ea0-71a6-a61f-d96a1392e4af","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Flags as a set of options"}]},"revision":1},{"id":"bd9e3366-a455-7c9e-990c-d4c2e139da87","type":"code","position":"a8","content":{"language":"c","code":"#include <stdio.h>\n\nenum Perm { READ = 1 << 0, WRITE = 1 << 1, EXEC = 1 << 2 };\n\nint main(void) {\n    unsigned perms = READ | WRITE;\n    printf(\"can write? %s\\n\", (perms & WRITE) ? \"yes\" : \"no\");\n    printf(\"can exec?  %s\\n\", (perms & EXEC) ? \"yes\" : \"no\");\n    perms |= EXEC;\n    printf(\"rwx = %u\\n\", perms);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"ae7fac20-18fc-7055-a0b1-406e34a2daa2","type":"code","position":"a9","content":{"language":"text","code":"can write? yes\ncan exec?  no\nrwx = 7","filename":"Output"},"revision":1},{"id":"7910f3c5-1a39-729b-b60f-5f03067c0dc2","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Classic bit tricks"}]},"revision":1},{"id":"ce361848-ce70-7c57-805a-b87c78cb725f","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n\nint is_power_of_two(unsigned x) { return x && !(x & (x - 1)); }\n\nint popcount(unsigned x) {          /* Kernighan: clear lowest set bit each step */\n    int n = 0;\n    while (x) { x &= x - 1; n++; }\n    return n;\n}\n\nint main(void) {\n    printf(\"%d %d %d\\n\", is_power_of_two(64), is_power_of_two(96), is_power_of_two(0));\n    printf(\"popcount(255) = %d, popcount(96) = %d\\n\", popcount(255), popcount(96));\n    printf(\"lowest set bit of 96 = %u\\n\", 96u & -96u);\n    printf(\"odd? %d %d\\n\", 7 & 1, 10 & 1);\n\n    int x = 5, y = 9;\n    x ^= y; y ^= x; x ^= y;         /* XOR swap (a curiosity; use a temp in real code) */\n    printf(\"x=%d y=%d\\n\", x, y);\n\n    int nums[] = {4, 1, 2, 1, 2};   /* every number twice except one */\n    int single = 0;\n    for (int i = 0; i < 5; i++) single ^= nums[i];\n    printf(\"single = %d\\n\", single);\n    printf(\"builtin popcount = %d\\n\", __builtin_popcount(255u));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"55bfe335-eeaa-71b9-8855-f185ace37db6","type":"code","position":"aC","content":{"language":"text","code":"1 0 0\npopcount(255) = 8, popcount(96) = 2\nlowest set bit of 96 = 32\nodd? 1 0\nx=9 y=5\nsingle = 4\nbuiltin popcount = 8","filename":"Output"},"revision":1},{"id":"0f73eee4-81a7-71da-8c26-4d38db944829","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Trick"}],[{"type":"text","text":"Expression"}]],[[{"type":"text","text":"Is power of two"}],[{"type":"text","text":"x && !(x & (x - 1))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Clear lowest set bit"}],[{"type":"text","text":"x & (x - 1)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Isolate lowest set bit"}],[{"type":"text","text":"x & -x","marks":[{"type":"code"}]},{"type":"text","text":" (unsigned)"}]],[[{"type":"text","text":"Multiply / divide by 2ⁿ"}],[{"type":"text","text":"x << n","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"x >> n","marks":[{"type":"code"}]},{"type":"text","text":" (unsigned)"}]],[[{"type":"text","text":"Check odd"}],[{"type":"text","text":"x & 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Swap without temp"}],[{"type":"text","text":"a ^= b; b ^= a; a ^= b;","marks":[{"type":"code"}]},{"type":"text","text":" (breaks if "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" alias!)"}]],[[{"type":"text","text":"Round up to multiple of 8"}],[{"type":"text","text":"(x + 7) & ~7u","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"33616f87-0c40-7610-bd07-74af2717cab5","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Shift pitfalls"}]},"revision":1},{"id":"72ce7d0c-efcd-7753-9ead-ae5c0afaf3ff","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shifting by ≥ the width of the type ("},{"type":"text","text":"1u << 32","marks":[{"type":"code"}]},{"type":"text","text":" for a 32-bit "},{"type":"text","text":"unsigned","marks":[{"type":"code"}]},{"type":"text","text":") is "},{"type":"text","text":"undefined","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Left-shifting a negative value, or shifting a "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" into the sign bit of a signed "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"1 << 31","marks":[{"type":"code"}]},{"type":"text","text":"), is "},{"type":"text","text":"undefined","marks":[{"type":"bold"}]},{"type":"text","text":" — use unsigned types for bit work."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Right-shifting a negative signed value is implementation-defined (usually arithmetic, copying the sign bit)."}]}]}]}]}},"revision":1},{"id":"a84da96b-80a6-740a-a5ef-440d1119c318","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int shift = 32;\n    unsigned x = 1u << shift;     /* UB: shift >= width of unsigned int */\n    printf(\"%u\\n\", x);\n    return 0;\n}","filename":"C — oversized shift (caught by UBSan)"},"revision":1},{"id":"b7c578dc-7740-7753-8079-a4ce8be02150","type":"code","position":"aH","content":{"language":"text","code":"main.c:5:21: runtime error: shift exponent 32 is too large for 32-bit type ''unsigned int''","filename":"UBSan"},"revision":1},{"id":"f6026a32-7f65-79cc-9458-b9bced464b8d","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you check whether the k-th bit of n is set?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"(n >> k) & 1","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"n & (1u << k)","marks":[{"type":"code"}]},{"type":"text","text":" (non-zero means set). Use unsigned operands so shifts into the top bit are well defined."}]}]}},"revision":1},{"id":"80f25776-2c7d-7458-b3ce-9eadcc882c79","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the element that appears once when all others appear twice?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"XOR all elements: "},{"type":"text","text":"x ^ x == 0","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"x ^ 0 == x","marks":[{"type":"code"}]},{"type":"text","text":", and XOR is commutative, so pairs cancel and only the single element remains. O(n) time, O(1) space."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
