  WHERE n.id = 'd1e547bc-5341-798c-9900-fffb0f17c659' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '9c1abeeb-a6a5-7827-bc98-bcd74bb7634b' AND n."deletedAt" IS NULL
)
