SELECT '4efbbbdf-a9fb-7de4-862e-258136cd3e7c', 'ba39edee-458a-7d6c-b04e-069f4553e49f', 1, 'PUBLISHED', 'Introduction to C', '[{"id":"43a024c5-6e89-7d24-ab93-42995df45ed0","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A small, fast, portable systems language — the language of operating systems, embedded devices, databases and the runtimes of most other languages."}]}]}},"revision":1},{"id":"efa3992d-0490-7fa1-aea0-3bb7ddfc3584","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C","marks":[{"type":"bold"}]},{"type":"text","text":" — a statically typed, compiled, "},{"type":"text","text":"procedural","marks":[{"type":"italic"}]},{"type":"text","text":" language that gives you direct access to memory through pointers and maps closely to what the hardware actually does. It trusts the programmer: there is no garbage collector, no bounds checking and no exceptions."}]}]}},"revision":1},{"id":"d8d128e4-3e4a-7ef0-8524-df980f1c1f4f","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"A short history"}]},"revision":1},{"id":"76c6f95f-b308-7dc1-80f3-2c41f09923ee","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Year"}],[{"type":"text","text":"Milestone"}]],[[{"type":"text","text":"1972"}],[{"type":"text","text":"Dennis Ritchie creates C at Bell Labs (successor of B) to rewrite "},{"type":"text","text":"UNIX","marks":[{"type":"bold"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"1978"}],[{"type":"text","text":"The C Programming Language","marks":[{"type":"italic"}]},{"type":"text","text":" (K&R) by Kernighan & Ritchie — the de-facto standard, “K&R C”."}]],[[{"type":"text","text":"1989 / 1990"}],[{"type":"text","text":"C89 / C90","marks":[{"type":"bold"}]},{"type":"text","text":" — the first ANSI / ISO standard (“ANSI C”). Function prototypes, "},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"1999"}],[{"type":"text","text":"C99","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"//","marks":[{"type":"code"}]},{"type":"text","text":" comments, "},{"type":"text","text":"long long","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<stdint.h>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bool","marks":[{"type":"code"}]},{"type":"text","text":", VLAs, designated initializers, "},{"type":"text","text":"inline","marks":[{"type":"code"}]},{"type":"text","text":", mixed declarations."}]],[[{"type":"text","text":"2011"}],[{"type":"text","text":"C11","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"_Generic","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_Static_assert","marks":[{"type":"code"}]},{"type":"text","text":", anonymous structs/unions, "},{"type":"text","text":"<threads.h>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<stdatomic.h>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_Alignas","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"gets","marks":[{"type":"code"}]},{"type":"text","text":" removed."}]],[[{"type":"text","text":"2018"}],[{"type":"text","text":"C17","marks":[{"type":"bold"}]},{"type":"text","text":" (C18) — bug-fix release of C11, no new features. The default standard for these notes."}]],[[{"type":"text","text":"2024"}],[{"type":"text","text":"C23","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"bool","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":" as keywords, "},{"type":"text","text":"nullptr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"constexpr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typeof","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"#embed","marks":[{"type":"code"}]},{"type":"text","text":", binary literals "},{"type":"text","text":"0b1010","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[[attributes]]","marks":[{"type":"code"}]},{"type":"text","text":"."}]]]},"revision":1},{"id":"1bf4ea72-ffec-7a4d-8b05-52d2174a318e","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Why learn C?"}]},"revision":1},{"id":"be5d344c-99e0-7b28-a7bb-56c62c15c189","type":"callout","position":"a5","content":{"variant":"note","title":"Close to the machine","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You see memory, addresses and bytes. Understanding C explains how every higher-level language works underneath."}]}]}},"revision":1},{"id":"c99617ba-37b8-7d55-9cc7-d8f8c9cb0ab3","type":"callout","position":"a6","content":{"variant":"note","title":"Everywhere","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linux, Windows and macOS kernels, embedded firmware, SQLite, Redis, Git, CPython, the JVM, Nginx — all C."}]}]}},"revision":1},{"id":"0051d3cb-7844-763e-835a-21bc00201bc4","type":"callout","position":"a7","content":{"variant":"note","title":"Fast & small","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No runtime or VM; a C binary is just machine code. Predictable performance and tiny footprint."}]}]}},"revision":1},{"id":"94d8800f-137a-701c-89ca-bf554b7d6977","type":"callout","position":"a8","content":{"variant":"note","title":"Portable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A C compiler exists for practically every CPU ever made. The standard library is small and everywhere."}]}]}},"revision":1},{"id":"59f1aea0-06a3-7b12-916b-b354cc789745","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"The trade-off"}]},"revision":1},{"id":"57382404-acfc-7807-a025-888130afb3f4","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"C gives you"}],[{"type":"text","text":"C does NOT give you"}]],[[{"type":"text","text":"Raw pointers and manual memory control"}],[{"type":"text","text":"Garbage collection, bounds checks, null safety"}]],[[{"type":"text","text":"Structs, unions, functions"}],[{"type":"text","text":"Classes, inheritance, templates, exceptions"}]],[[{"type":"text","text":"A tiny standard library"}],[{"type":"text","text":"Built-in strings, lists, maps, networking"}]],[[{"type":"text","text":"Speed and control"}],[{"type":"text","text":"Protection from "},{"type":"text","text":"undefined behaviour","marks":[{"type":"bold"}]},{"type":"text","text":" — mistakes compile and silently misbehave"}]]]},"revision":1},{"id":"59e4936f-2c95-739c-80e4-bc6d58724435","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Hello, world"}]},"revision":1},{"id":"1484ec07-14ef-731b-a4e8-a5adcb4b1caa","type":"code","position":"aC","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    printf(\"Hello, world!\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"76275bf3-c617-76ac-87a8-3ca2aae1f527","type":"code","position":"aD","content":{"language":"text","code":"Hello, world!","filename":"Output"},"revision":1},{"id":"0ee689bc-9625-7a6e-91f2-9198ed235b33","type":"code","position":"aE","content":{"language":"","code":"$ gcc hello.c -o hello        # compile (or: clang hello.c -o hello)\n$ ./hello                     # run\nHello, world!\n$ echo $?                     # exit status returned by main\n0","filename":"Terminal"},"revision":1},{"id":"d8c6a504-4455-714d-82ae-52d7673cd6a9","type":"callout","position":"aF","content":{"variant":"note","title":"Syntax basics","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C is case-sensitive, every statement ends with "},{"type":"text","text":";","marks":[{"type":"code"}]},{"type":"text","text":", and blocks are delimited by "},{"type":"text","text":"{ }","marks":[{"type":"code"}]},{"type":"text","text":". Whitespace and indentation don’t matter to the compiler."}]}]}},"revision":1},{"id":"0721eaea-4ecf-776a-8ecc-c94e0e532a9f","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is C a high-level or low-level language?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It is usually called a "},{"type":"text","text":"middle-level","marks":[{"type":"italic"}]},{"type":"text","text":" language: it has high-level constructs (functions, loops, structs, types) but also low-level access (pointers, bit manipulation, manual memory) that maps almost one-to-one onto machine instructions."}]}]}},"revision":1},{"id":"e73fb843-7f37-749a-9fb7-965bf42ad909","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between C and C++?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C++ started as “C with classes” and is (almost) a superset of C. It adds classes, templates, references, RAII, exceptions, namespaces and a large standard library (STL). C stays small and procedural. Some valid C is not valid C++ (e.g. implicit "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" conversion from "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":", designated-initializer order, "},{"type":"text","text":"int new;","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'ba39edee-458a-7d6c-b04e-069f4553e49f' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
