0;\n    long v = strtol(s, &end, 10);\n    if (end == s || *end != ''\\0'' || errno == ERANGE) return -1;\n    *out = v;\n    return 0;\n}\n\nint main(int argc, char *argv[]) {\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s NUM...\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n    long sum = 0;\n    for (int i = 1; i < argc; i++) {\n        long v;\n        if (parse_int(argv[i], &v) != 0) { printf(\"skipping ''%s''\\n\", argv[i]); continue; }\n        sum += v;\n    }\n    printf(\"sum = %ld\\n\", sum);\n    return EXIT_SUCCESS;\n}","filename":"C — run as: ./prog 10 20 x7 -5"},"revision":1},{"id":"a237267a-063c-77a5-aad3-9b616cc26d07","type":"code","position":"a5","content":{"language":"text","code":"skipping ''x7''\nsum = 25","filename":"Output"},"revision":1},{"id":"56fc4852-5bfa-7a68-a4f9-29b83d2b7924","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Parsing options"}]},"revision":1},{"id":"7ca08255-9697-70e6-b677-d80070b8cfdc","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main(int argc, char **argv) {\n    int verbose = 0, count = 1;\n    const char *name = \"world\";\n    for (int i = 1; i < argc; i++) {\n        if (strcmp(argv[i], \"-v\") == 0) verbose = 1;\n        else if (strcmp(argv[i], \"-n\") == 0 && i + 1 < argc) count = atoi(argv[++i]);\n        else name = argv[i];\n    }\n    for (int i = 0; i < count; i++) printf(\"hello, %s\\n\", name);\n    if (verbose) printf(\"(printed %d times)\\n\", count);\n    return 0;\n}","filename":"C — run as: ./prog -n 2 -v C"},"revision":1},{"id":"2f88f799-5614-74d8-ae84-3c4eaffcbe99","type":"code","position":"a8","content":{"language":"text","code":"hello, C\nhello, C\n(printed 2 times)","filename":"Output"},"revision":1},{"id":"238a1c44-a171-7bb9-8afd-6e53a86a4470","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On POSIX systems, "},{"type":"text","text":"getopt()","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"<unistd.h>","marks":[{"type":"code"}]},{"type":"text","text":") and GNU "},{"type":"text","text":"getopt_long()","marks":[{"type":"code"}]},{"type":"text","text":" handle combined flags ("},{"type":"text","text":"-vn 2","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"--","marks":[{"type":"code"}]},{"type":"text","text":" and error messages for you."}]}]}},"revision":1},{"id":"bba07fb4-64b0-72b9-a07d-c1b7c4f3a25f","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"argv[0]","marks":[{"type":"code"}]},{"type":"text","text":" is the program name "},{"type":"text","text":"as invoked","marks":[{"type":"italic"}]},{"type":"text","text":" — it may be a path, or anything the parent process chose."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The shell does quoting and globbing: "},{"type":"text","text":"./prog \"a b\" *.c","marks":[{"type":"code"}]},{"type":"text","text":" passes "},{"type":"text","text":"a b","marks":[{"type":"code"}]},{"type":"text","text":" as one argument and expands "},{"type":"text","text":"*.c","marks":[{"type":"code"}]},{"type":"text","text":" before your program starts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The strings in "},{"type":"text","text":"argv","marks":[{"type":"code"}]},{"type":"text","text":" are modifiable and live until the program ends."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Environment variables: "},{"type":"text","text":"getenv(\"HOME\")","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"<stdlib.h>","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"ed5dd9d2-6746-7fd0-bf78-905cb82736a4","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is argv[argc]?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always a null pointer — the standard guarantees it. You can loop with "},{"type":"text","text":"for (char **p = argv; *p; p++)","marks":[{"type":"code"}]},{"type":"text","text":" instead of counting."}]}]}},"revision":1},{"id":"bd4699d1-8a63-7398-9133-79ef580cbb89","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is argv declared as char *argv[] and char **argv interchangeably?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because an array parameter is adjusted to a pointer: "},{"type":"text","text":"char *argv[]","marks":[{"type":"code"}]},{"type":"text","text":" in a parameter list "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"char **argv","marks":[{"type":"code"}]},{"type":"text","text":". It points to the first element of an array of "},{"type":"text","text":"char *","marks":[{"type":"code"}]},{"type":"text","text":", each pointing to a NUL-terminated argument string."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
