SELECT 'f1053753-046b-7cc5-80ce-5c88c28a0a1e', '18239900-a4bc-7aef-b3c6-7b83a1019895', 1, 'PUBLISHED', 'Threads & Atomics (Intro)', '[{"id":"c8f9c4a5-025d-72fd-afb4-1405db8d131c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C11 standardised a memory model, "},{"type":"text","text":"<stdatomic.h>","marks":[{"type":"code"}]},{"type":"text","text":" and an optional "},{"type":"text","text":"<threads.h>","marks":[{"type":"code"}]},{"type":"text","text":". In practice most C code uses POSIX threads ("},{"type":"text","text":"pthread","marks":[{"type":"code"}]},{"type":"text","text":"). Shared data needs a mutex or atomics — otherwise it is a "},{"type":"text","text":"data race","marks":[{"type":"italic"}]},{"type":"text","text":" (undefined behaviour)."}]}]}},"revision":1},{"id":"336f5224-2101-79fa-b584-19b32067e1a3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Creating and joining threads"}]},"revision":1},{"id":"ac3a17a8-117e-72d3-b912-8c190de20c20","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n#include <pthread.h>\n\ntypedef struct { int id; long from, to, result; } Job;\n\nvoid *sum_range(void *arg) {                 /* thread entry: void *(*)(void *) */\n    Job *job = arg;\n    long s = 0;\n    for (long i = job->from; i < job->to; i++) s += i;\n    job->result = s;                          /* each thread writes only its own Job */\n    return NULL;\n}\n\nint main(void) {\n    enum { N = 4 };\n    pthread_t tid[N];\n    Job jobs[N];\n    for (int i = 0; i < N; i++) {\n        jobs[i] = (Job){i, i * 250000L, (i + 1) * 250000L, 0};\n        pthread_create(&tid[i], NULL, sum_range, &jobs[i]);\n    }\n    long total = 0;\n    for (int i = 0; i < N; i++) {\n        pthread_join(tid[i], NULL);           /* wait, then read the result */\n        total += jobs[i].result;\n    }\n    printf(\"sum 0..999999 = %ld\\n