SELECT 'edc1f1ca-fba8-7446-84f2-abab28c06b2f', 'b96050dd-ecda-7cd6-870a-3527af3acbf9', 1, 'PUBLISHED', 'Integer Promotion & Type Conversions', '[{"id":"ef109916-25b8-7925-b6b0-26b556c4e15c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before most arithmetic, C silently converts operands: small integers are "},{"type":"text","text":"promoted","marks":[{"type":"italic"}]},{"type":"text","text":" to "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", and mixed types are brought to a "},{"type":"text","text":"common type","marks":[{"type":"italic"}]},{"type":"text","text":". Signed/unsigned mixing is the classic source of bugs."}]}]}},"revision":1},{"id":"4453ecce-67a6-741c-8519-8aa3dede3b9e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Integer promotion"}]},"revision":1},{"id":"8101f4d0-ab8a-787a-a6df-e34594eda6bc","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"short","marks":[{"type":"code"}]},{"type":"text","text":" or bit-field (signed or unsigned) used in an expression is first converted to "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" can’t hold all its values)."}]}]}},"revision":1},{"id":"b8487024-9efd-76d5-9bed-fad1c35c68f1","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    unsigned char a = 200, b = 100;\n    int sum = a + b;                 /* promoted to int: 300, no wrap */\n    unsigned char stored = a + b;    /* converted back: 300 mod 256 */\n    printf(\"%d %d\\n\", sum, stored);\n\n    char c = ''x'';\n    printf(\"%zu %zu\\n\", sizeof c, sizeof(c + 0));   /* char vs int */\n\n    unsigned char ones = 0xFF;\n    printf(\"%d\\n\", ~ones);           /* ~ applied to int 255 → -256, not 0 */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"88f7bbe8-0f1e-7510-b2f0-58719193f953","type":"code","position":"a4","content":{"language":"text","code":"300 44\n1 4\n-256","filename":"Output"},"revision":1},{"id":"e2606b08-08c8-7a47-b72d-c24f6223ef74","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The usual arithmetic conversions"}]},"revision":1},{"id":"3ad56df1-174e-7364-926b-08612f6dced1","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Any floating operand?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Convert the other to the widest floating type involved ("},{"type":"text","text":"long double","marks":[{"type":"code"}]},{"type":"text","text":" > "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" > "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otherwise promote","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Apply integer promotion to both operands."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Same signedness","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Convert to the higher-rank type ("},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" < "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":" < "},{"type":"text","text":"long long","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mixed signedness","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If the unsigned type has rank ≥ the signed one, the "},{"type":"text","text":"signed operand becomes unsigned","marks":[{"type":"bold"}]},{"type":"text","text":". Otherwise, if the signed type can represent every unsigned value, convert to the signed type; else to its unsigned counterpart."}]}]}]}]}},"revision":1},{"id":"27d5e569-7c94-78f8-a323-5f95622f7e3c","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int neg = -1;\n    unsigned int one = 1;\n    /* -1 is converted to unsigned: 4294967295 > 1 */\n    if ((unsigned)neg > one) printf(\"-1 > 1u as unsigned!\\n\");\n    printf(\"%u\\n\", (unsigned)neg);\n\n    long long big = -1;\n    printf(\"%d\\n\", big < one);     /* long long can hold every unsigned int: stays signed */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"2d0c9e3e-2664-77d8-a32f-7597e100cfb4","type":"code","position":"a8","content":{"language":"text","code":"-1 > 1u as unsigned!\n4294967295\n1","filename":"Output"},"revision":1},{"id":"688662b3-e94f-78e0-a318-b8fcdf6b568d","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clang warns about the implicit version of this comparison ("},{"type":"text","text":"-Wsign-compare","marks":[{"type":"code"}]},{"type":"text","text":", part of "},{"type":"text","text":"-Wextra","marks":[{"type":"code"}]},{"type":"text","text":") — one more reason to keep warnings on:"}]}]}},"revision":1},{"id":"5653ab27-e907-7d13-9879-7cc117c621ec","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    int i = -1;\n    if (i < strlen(\"abc\"))       /* int vs size_t: i becomes huge */\n        printf(\"smaller\\n\");\n    return 0;\n}","filename":"C — signed/unsigned comparison (rejected by -Wextra -Werror)"},"revision":1},{"id":"945b62aa-9e8b-7848-a0cd-4ae3916bf4f1","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Explicit casts and narrowing"}]},"revision":1},{"id":"52f5a34b-d48e-72d4-84b1-9db948dbd64a","type":"code","position":"aC","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    double d = 3.99;\n    int truncated = (int)d;          /* toward zero, not rounded */\n    int negative = (int)-3.99;\n    printf(\"%d %d\\n\", truncated, negative);\n\n    int total = 7, count = 2;\n    printf(\"%d %.1f\\n\", total / count, (double)total / count);\n\n    int big = 300;\n    unsigned char small = (unsigned char)big;   /* modulo 256 */\n    signed char sc = (signed char)200;          /* implementation-defined */\n    printf(\"%d %d\\n\", small, sc);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"95b3e1a1-9728-7f6f-80b1-ddf173d182ff","type":"code","position":"aD","content":{"language":"text","code":"3 -3\n3 3.5\n44 -56","filename":"Output"},"revision":1},{"id":"a2e736f9-5576-7854-a987-c3ae1e0606d2","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Conversion"}],[{"type":"text","text":"Result"}]],[[{"type":"text","text":"Any integer → unsigned type"}],[{"type":"text","text":"Well defined: value modulo 2ᴺ"}]],[[{"type":"text","text":"Out-of-range integer → signed type"}],[{"type":"text","text":"Implementation-defined (wraps on all real compilers; C23 mandates two’s complement)"}]],[[{"type":"text","text":"Floating → integer"}],[{"type":"text","text":"Truncates toward zero; "},{"type":"text","text":"UB","marks":[{"type":"bold"}]},{"type":"text","text":" if the value doesn’t fit"}]],[[{"type":"text","text":"Integer → floating"}],[{"type":"text","text":"May lose precision for large values"}]],[[{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"float","marks":[{"type":"code"}]}],[{"type":"text","text":"Rounded; UB/inf if out of range"}]]]},"revision":1},{"id":"c9058bd0-d00a-7f40-80d0-d5a4ae9bfc9a","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does (unsigned char)255 + 1 give 256 and not 0?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because of integer promotion: the "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" operand is promoted to "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" before the addition, so the arithmetic is done in "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":". The result only wraps to 0 if it is stored back into an "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"1aaa7318-c623-78c5-b437-d1ef6c4668d6","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the result of -1 < 0u?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" (false). "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" is converted to "},{"type":"text","text":"unsigned int","marks":[{"type":"code"}]},{"type":"text","text":" (becoming "},{"type":"text","text":"UINT_MAX","marks":[{"type":"code"}]},{"type":"text","text":") because both operands have the same rank and one is unsigned. This is why comparing an "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"strlen()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" can go wrong."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
