SELECT '1fac5621-a2f5-7d5a-a059-38a8a35e0144', '37987bbf-89ab-774d-9f4b-075a9d545818', 1, 'PUBLISHED', 'Data Types & Sizes', '[{"id":"5508cd83-2a0c-7a9b-a88c-6a8a87d230e7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C has a handful of built-in arithmetic types whose sizes are "},{"type":"text","text":"implementation-defined","marks":[{"type":"italic"}]},{"type":"text","text":" — the standard only guarantees minimum ranges. Always measure with "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4d250b1c-870d-7ae0-8acc-5a48cf0a943c","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The basic types"}]},"revision":1},{"id":"33753e5d-0f0d-7983-be43-0228a5755194","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Guaranteed minimum"}],[{"type":"text","text":"Typical size (64-bit Linux/macOS)"}],[{"type":"text","text":"Format"}]],[[{"type":"text","text":"char","marks":[{"type":"code"}]}],[{"type":"text","text":"8 bits"}],[{"type":"text","text":"1 byte"}],[{"type":"text","text":"%c","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%d","marks":[{"type":"code"}]}]],[[{"type":"text","text":"short","marks":[{"type":"code"}]}],[{"type":"text","text":"16 bits"}],[{"type":"text","text":"2 bytes"}],[{"type":"text","text":"%hd","marks":[{"type":"code"}]}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]}],[{"type":"text","text":"16 bits"}],[{"type":"text","text":"4 bytes"}],[{"type":"text","text":"%d","marks":[{"type":"code"}]}]],[[{"type":"text","text":"long","marks":[{"type":"code"}]}],[{"type":"text","text":"32 bits"}],[{"type":"text","text":"8 bytes (4 on 64-bit Windows)"}],[{"type":"text","text":"%ld","marks":[{"type":"code"}]}]],[[{"type":"text","text":"long long","marks":[{"type":"code"}]}],[{"type":"text","text":"64 bits"}],[{"type":"text","text":"8 bytes"}],[{"type":"text","text":"%lld","marks":[{"type":"code"}]}]],[[{"type":"text","text":"float","marks":[{"type":"code"}]}],[{"type":"text","text":"~6 decimal digits"}],[{"type":"text","text":"4 bytes (IEEE 754 single)"}],[{"type":"text","text":"%f","marks":[{"type":"code"}]}]],[[{"type":"text","text":"double","marks":[{"type":"code"}]}],[{"type":"text","text":"~10 digits (15 in practice)"}],[{"type":"text","text":"8 bytes (IEEE 754 double)"}],[{"type":"text","text":"%f","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%lf","marks":[{"type":"code"}]}]],[[{"type":"text","text":"long double","marks":[{"type":"code"}]}],[{"type":"text","text":"≥ "},{"type":"text","text":"double","marks":[{"type":"code"}]}],[{"type":"text","text":"16 bytes x86-64 Linux, "},{"type":"text","text":"8","marks":[{"type":"bold"}]},{"type":"text","text":" on Apple arm64"}],[{"type":"text","text":"%Lf","marks":[{"type":"code"}]}]],[[{"type":"text","text":"_Bool","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"bool","marks":[{"type":"code"}]}],[{"type":"text","text":"holds 0 or 1"}],[{"type":"text","text":"1 byte"}],[{"type":"text","text":"%d","marks":[{"type":"code"}]}]],[[{"type":"text","text":"void","marks":[{"type":"code"}]}],[{"type":"text","text":"no value"}],[{"type":"text","text":"—"}],[{"type":"text","text":"—"}]]]},"revision":1},{"id":"a4cf4f36-ca61-7819-8f67-7a8db95db39a","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Size ordering is guaranteed: "},{"type":"text","text":"sizeof(char) == 1 ≤ sizeof(short) ≤ sizeof(int) ≤ sizeof(long) ≤ sizeof(long long)","marks":[{"type":"code"}]},{"type":"text","text":". A “byte” in C is "},{"type":"text","text":"CHAR_BIT","marks":[{"type":"code"}]},{"type":"text","text":" bits — 8 on every mainstream platform."}]}]}},"revision":1},{"id":"231ba7ff-2ed6-7a96-aa7a-1a2d60c5620c","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Measure with sizeof"}]},"revision":1},{"id":"869c4382-9d7d-768f-a887-ad7ac362a7ae","type":"code","position":"a5","content":{"language":"c","code":"#include <stdio.h>\n#include <stdbool.h>\n\nint main(void) {\n    printf(\"char        %zu\\n\", sizeof(char));\n    printf(\"short       %zu\\n\", sizeof(short));\n    printf(\"int         %zu\\n\", sizeof(int));\n    printf(\"long        %zu\\n\", sizeof(long));\n    printf(\"long long   %zu\\n\", sizeof(long long));\n    printf(\"float       %zu\\n\", sizeof(float));\n    printf(\"double      %zu\\n\", sizeof(double));\n    printf(\"long double %zu\\n\", sizeof(long double));\n    printf(\"bool        %zu\\n\", sizeof(bool));\n    printf(\"pointer     %zu\\n\", sizeof(void *));\n    return 0;\n}","filename":"C — output from a 64-bit Apple arm64 machine"},"revision":1},{"id":"c5514f96-8dec-72fa-9ea8-417a1a8c6d95","type":"code","position":"a6","content":{"language":"text","code":"char        1\nshort       2\nint         4\nlong        8\nlong long   8\nfloat       4\ndouble      8\nlong double 8\nbool        1\npointer     8","filename":"Output"},"revision":1},{"id":"4cfa2562-2edc-741d-9648-e37bb0242f64","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" is an "},{"type":"text","text":"operator","marks":[{"type":"italic"}]},{"type":"text","text":", not a function: it is evaluated at compile time (except for VLAs), and its result has type "},{"type":"text","text":"size_t","marks":[{"type":"code"}]},{"type":"text","text":" — print it with "},{"type":"text","text":"%zu","marks":[{"type":"code"}]},{"type":"text","text":". Parentheses are only needed around a type: "},{"type":"text","text":"sizeof x","marks":[{"type":"code"}]},{"type":"text","text":" works for a variable."}]}]}},"revision":1},{"id":"e0cd2491-2207-7f76-93df-175452a55d4b","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"signed and unsigned"}]},"revision":1},{"id":"4d8f8cd6-a942-7653-a5da-8355875c629c","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Range with 32-bit int"}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" (= "},{"type":"text","text":"signed int","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"−2 147 483 648 … 2 147 483 647"}]],[[{"type":"text","text":"unsigned int","marks":[{"type":"code"}]}],[{"type":"text","text":"0 … 4 294 967 295"}]],[[{"type":"text","text":"signed char","marks":[{"type":"code"}]}],[{"type":"text","text":"−128 … 127"}]],[[{"type":"text","text":"unsigned char","marks":[{"type":"code"}]}],[{"type":"text","text":"0 … 255 (the type for raw bytes)"}]],[[{"type":"text","text":"plain "},{"type":"text","text":"char","marks":[{"type":"code"}]}],[{"type":"text","text":"either","marks":[{"type":"bold"}]},{"type":"text","text":" — signed on x86 and Apple arm64, unsigned on Linux ARM"}]]]},"revision":1},{"id":"9fa5ea94-13b5-781e-81d6-eed0679c6f2e","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    unsigned int u = 0;\n    u = u - 1;                    /* unsigned arithmetic wraps modulo 2^32 — well defined */\n    printf(\"%u\\n\", u);\n\n    unsigned char byte = 250;\n    byte += 10;                   /* 260 mod 256 */\n    printf(\"%d\\n\", byte);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"fb177bea-aea5-7161-900c-69cdffce7585","type":"code","position":"aB","content":{"language":"text","code":"4294967295\n4","filename":"Output"},"revision":1},{"id":"18d4909a-76e4-7a5c-b34d-fdb0c2e7ac91","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsigned overflow wraps around (defined). "},{"type":"text","text":"Signed","marks":[{"type":"bold"}]},{"type":"text","text":" overflow is "},{"type":"text","text":"undefined behaviour","marks":[{"type":"italic"}]},{"type":"text","text":" — the compiler may assume it never happens. See the UB topic."}]}]}},"revision":1},{"id":"d8b7c821-5a50-7a5f-9cb2-6eea126a9180","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Floating point"}]},"revision":1},{"id":"bfa42559-1b93-74c1-b38d-a9c81e5bc2f6","type":"code","position":"aE","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    double a = 0.1 + 0.2;\n    printf(\"%.17f\\n\", a);\n    printf(\"%s\\n\", a == 0.3 ? \"equal\" : \"not equal\");\n\n    float f = 16777217.0f;        /* 2^24 + 1 cannot be stored in a float */\n    printf(\"%.1f\\n\", f);\n    printf(\"%f %f\\n\", 7 / 2.0, (double)(7 / 2));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"d5312b09-dd40-7d23-b0c4-6c06a0f46a09","type":"code","position":"aF","content":{"language":"text","code":"0.30000000000000004\nnot equal\n16777216.0\n3.500000 3.000000","filename":"Output"},"revision":1},{"id":"95dfbf1f-8f14-7e05-a088-5c8cd70e389b","type":"callout","position":"aG","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never compare floating-point values with "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":". Compare with a tolerance: "},{"type":"text","text":"fabs(a - b) < 1e-9","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" by default — "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" only when memory matters (large arrays, GPUs)."}]}]}},"revision":1},{"id":"b4d9a2c4-a13e-7727-b0f4-822b01958c96","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Characters are small integers"}]},"revision":1},{"id":"414f868a-6087-73d6-af27-6b4d8eefd701","type":"code","position":"aI","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    char c = ''A'';\n    printf(\"%c %d %c %d\\n\", c, c, c + 2, ''0'');\n    printf(\"digit value: %d\\n\", ''7'' - ''0'');\n    printf(\"sizeof ''A'' = %zu\\n\", sizeof ''A'');   /* a char literal has type int in C */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"df655396-9750-77b5-98f3-49848a2ee046","type":"code","position":"aJ","content":{"language":"text","code":"A 65 C 48\ndigit value: 7\nsizeof ''A'' = 4","filename":"Output"},"revision":1},{"id":"3329ff4c-9f5b-7a1e-9599-f2d6f66ddf96","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the size of int in C?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Implementation-defined; the standard only requires at least 16 bits. On virtually every modern desktop/server platform (ILP32, LP64, LLP64) it is 32 bits. That is why portable code uses "},{"type":"text","text":"<stdint.h>","marks":[{"type":"code"}]},{"type":"text","text":" types such as "},{"type":"text","text":"int32_t","marks":[{"type":"code"}]},{"type":"text","text":" when the exact width matters."}]}]}},"revision":1},{"id":"066b80ac-6477-715c-bb24-f7a55368df49","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is char signed or unsigned?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Implementation-defined. "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"signed char","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" are three distinct types. Use "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" for raw bytes and cast to "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" before passing a "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"<ctype.h>","marks":[{"type":"code"}]},{"type":"text","text":" functions."}]}]}},"revision":1},{"id":"00a9c9a3-233a-7d22-864b-e601d20061af","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does sizeof(''A'') return in C and in C++?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In C a character constant has type "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"sizeof(''A'')","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"sizeof(int)","marks":[{"type":"code"}]},{"type":"text","text":" (usually 4). In C++ it has type "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":", so the result is 1."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
