SELECT 'd39ccb7d-77bc-7a27-a4e9-5cab25639cfd', '4be4a998-77d8-7be0-8372-fca8b838d29d', 1, 'PUBLISHED', 'malloc, calloc, realloc & free', '[{"id":"48ce10aa-7944-76ee-b97c-a594aaf7bc78","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the size or lifetime of data isn’t known at compile time, request memory from the "},{"type":"text","text":"heap","marks":[{"type":"bold"}]},{"type":"text","text":" at run time. Every successful allocation must be released with exactly one "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8dbe94bf-f8cd-776b-9030-0aaaa36bc57c","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function ("},{"type":"text","text":"<stdlib.h>","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Does"}],[{"type":"text","text":"Contents"}],[{"type":"text","text":"On failure"}]],[[{"type":"text","text":"malloc(size)","marks":[{"type":"code"}]}],[{"type":"text","text":"Allocate "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" bytes"}],[{"type":"text","text":"Uninitialised (garbage)"}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]}]],[[{"type":"text","text":"calloc(n, size)","marks":[{"type":"code"}]}],[{"type":"text","text":"Allocate "},{"type":"text","text":"n × size","marks":[{"type":"code"}]},{"type":"text","text":" bytes (overflow-checked)"}],[{"type":"text","text":"All bits zero"}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]}]],[[{"type":"text","text":"realloc(p, size)","marks":[{"type":"code"}]}],[{"type":"text","text":"Grow/shrink a block; may move it"}],[{"type":"text","text":"Old contents kept, new part uninitialised"}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"old block still valid","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"free(p)","marks":[{"type":"code"}]}],[{"type":"text","text":"Release a block"}],[{"type":"text","text":"—"}],[{"type":"text","text":"free(NULL)","marks":[{"type":"code"}]},{"type":"text","text":" is a no-op"}]],[[{"type":"text","text":"aligned_alloc(al, size)","marks":[{"type":"code"}]},{"type":"text","text":" (C11)"}],[{"type":"text","text":"Allocate with a given alignment"}],[{"type":"text","text":"Uninitialised"}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"8dd8a328-590b-7b39-98d2-c040ff654e12","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"malloc and free"}]},"revision":1},{"id":"7c6e6275-aa22-7885-b9de-d5c2d43391a3","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int n = 5;\n    int *a = malloc(n * sizeof *a);     /* sizeof *a: stays right if the type changes */\n    if (a == NULL) {                    /* always check */\n        fprintf(stderr, \"out of memory\\n\");\n        return 1;\n    }\n    for (int i = 0; i < n; i++) a[i] = i * i;\n    for (int i = 0; i < n; i++) printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    free(a);\n    a = NULL;                           /* defensive: no dangling pointer */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"5851c5c8-0d00-7362-9a26-48e1c65a88f3","type":"code","position":"a4","content":{"language":"text","code":"0 1 4 9 16","filename":"Output"},"revision":1},{"id":"aceb1bb9-f0b4-7002-a213-f26453f4537e","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"calloc: zeroed memory"}]},"revision":1},{"id":"338abed6-16e1-78d3-8be9-5822575c181c","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    size_t n = 4;\n    double *v = calloc(n, sizeof *v);    /* all zeros, and n * size cannot overflow silently */\n    if (!v) return 1;\n    v[2] = 3.5;\n    for (size_t i = 0; i < n; i++) printf(\"%.1f \", v[i]);\n    printf(\"\\n\");\n    free(v);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"1d21536c-8119-714a-a233-e6b45c781513","type":"code","position":"a7","content":{"language":"text","code":"0.0 0.0 3.5 0.0","filename":"Output"},"revision":1},{"id":"59a8c623-29e9-7144-8a3f-11ae4cd9c616","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"realloc: a growable array"}]},"revision":1},{"id":"dc18e046-7b7d-76f2-9cdc-2f5b86130c99","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    size_t len, cap;\n} Vec;\n\nint vec_push(Vec *v, int x) {\n    if (v->len == v->cap) {\n        size_t new_cap = v->cap ? v->cap * 2 : 1;          /* geometric growth: amortised O(1) */\n        int *tmp = realloc(v->data, new_cap * sizeof *tmp);\n        if (!tmp) return -1;                              /* v->data is still valid */\n        v->data = tmp;\n        v->cap = new_cap;\n        printf(\"grew to %zu\\n\", new_cap);\n    }\n    v->data[v->len++] = x;\n    return 0;\n}\n\nint main(void) {\n    Vec v = {NULL, 0, 0};                 /* realloc(NULL, n) acts like malloc(n) */\n    for (int i = 1; i <= 5; i++) vec_push(&v, i * 10);\n    printf(\"len=%zu cap=%zu last=%d\\n\", v.len, v.cap, v.data[v.len - 1]);\n    free(v.data);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"4bd54109-3d60-770d-9267-697ab4692f7c","type":"code","position":"aA","content":{"language":"text","code":"grew to 1\ngrew to 2\ngrew to 4\ngrew to 8\nlen=5 cap=8 last=50","filename":"Output"},"revision":1},{"id":"d02a40b6-d15d-798d-bb63-25ce8402e511","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never write "},{"type":"text","text":"p = realloc(p, n);","marks":[{"type":"code"}]},{"type":"text","text":" — if "},{"type":"text","text":"realloc","marks":[{"type":"code"}]},{"type":"text","text":" fails it returns "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", you overwrite your only pointer to the old block, and it leaks. Assign to a temporary first."}]}]}},"revision":1},{"id":"6d8cb242-3e5e-70be-bc7b-834ca7d69056","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Allocating strings and structs"}]},"revision":1},{"id":"6c836d1a-c894-7738-9001-02ef31960254","type":"code","position":"aD","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct { char *name; int age; } Person;\n\nchar *dup_string(const char *s) {           /* like POSIX / C23 strdup */\n    size_t n = strlen(s) + 1;               /* +1 for the terminator! */\n    char *copy = malloc(n);\n    if (copy) memcpy(copy, s, n);\n    return copy;\n}\n\nPerson *person_new(const char *name, int age) {\n    Person *p = malloc(sizeof *p);\n    if (!p) return NULL;\n    p->name = dup_string(name);\n    if (!p->name) { free(p); return NULL; }\n    p->age = age;\n    return p;\n}\n\nvoid person_free(Person *p) {\n    if (!p) return;\n    free(p->name);                          /* inner allocations first */\n    free(p);\n}\n\nint main(void) {\n    Person *p = person_new(\"Ada\", 36);\n    if (!p) return 1;\n    printf(\"%s is %d\\n\", p->name, p->age);\n    person_free(p);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"9908591a-3a20-77ef-8385-c3110cca8203","type":"code","position":"aE","content":{"language":"text","code":"Ada is 36","filename":"Output"},"revision":1},{"id":"13c053dd-58b0-71d6-92ad-c6d486af0417","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Rules of ownership"}]},"revision":1},{"id":"1b3d1800-e99b-7606-8db8-66277ded36df","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"calloc","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"realloc","marks":[{"type":"code"}]},{"type":"text","text":" success is matched by "},{"type":"text","text":"exactly one","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" of the same pointer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only pass "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" a pointer that came from an allocation function (not a stack array, not "},{"type":"text","text":"p + 1","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide and document "},{"type":"text","text":"who owns","marks":[{"type":"italic"}]},{"type":"text","text":" each allocation — the function that creates it, or the caller."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Free nested allocations before the struct that points to them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check sizes for overflow: "},{"type":"text","text":"n * size","marks":[{"type":"code"}]},{"type":"text","text":" can wrap; "},{"type":"text","text":"calloc","marks":[{"type":"code"}]},{"type":"text","text":" checks for you."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leak checkers: Valgrind ("},{"type":"text","text":"valgrind --leak-check=full ./app","marks":[{"type":"code"}]},{"type":"text","text":"), LeakSanitizer ("},{"type":"text","text":"-fsanitize=address","marks":[{"type":"code"}]},{"type":"text","text":" on Linux)."}]}]}]}]}},"revision":1},{"id":"35aaec69-d493-7f9e-80b4-1f8b1ded89d4","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between malloc and calloc?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"malloc(bytes)","marks":[{"type":"code"}]},{"type":"text","text":" returns uninitialised memory. "},{"type":"text","text":"calloc(count, size)","marks":[{"type":"code"}]},{"type":"text","text":" returns zero-filled memory for "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":" elements and checks the multiplication for overflow. "},{"type":"text","text":"calloc","marks":[{"type":"code"}]},{"type":"text","text":" can be as fast as "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" for large blocks because the OS hands out pre-zeroed pages."}]}]}},"revision":1},{"id":"d5a96008-3c96-7edd-bd92-4e2e2b73d677","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if you call free twice on the same pointer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Undefined behaviour — a "},{"type":"text","text":"double free","marks":[{"type":"italic"}]},{"type":"text","text":". It typically corrupts the allocator’s internal lists, can crash later in an unrelated "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":", and is exploitable. Setting the pointer to "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" after freeing makes a second "},{"type":"text","text":"free(NULL)","marks":[{"type":"code"}]},{"type":"text","text":" harmless."}]}]}},"revision":1},{"id":"c0604a03-c509-7a98-8ef4-250154357687","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does free return memory to the operating system?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not necessarily. "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" returns the block to the allocator’s free lists so later "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":"s can reuse it. Large blocks (served by "},{"type":"text","text":"mmap","marks":[{"type":"code"}]},{"type":"text","text":") are usually returned immediately; small ones typically stay with the process."}]}]}},"revision":1},{"id":"9d7bf3d2-990c-78a8-9375-6773c89ed020","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Should you cast the result of malloc in C?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" converts implicitly to any object pointer type in C, and a cast can hide a missing "},{"type":"text","text":"#include <stdlib.h>","marks":[{"type":"code"}]},{"type":"text","text":" in old compilers. The cast is required only in C++."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
