SELECT '7441abda-5b58-7023-9112-e33447bfaebf', '46c63463-3061-790a-a6d6-ba2749704f17', 1, 'PUBLISHED', 'Error Handling: errno & Return Codes', '[{"id":"64c5613e-e331-7480-86ff-c608e513b27c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C has no exceptions. Functions report failure through their "},{"type":"text","text":"return value","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"EOF","marks":[{"type":"code"}]},{"type":"text","text":"), and the library adds detail in the global "},{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":". Checking every result is the programmer’s job."}]}]}},"revision":1},{"id":"08dc78bd-1450-7283-aee2-7d958db13e7f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Library conventions"}]},"revision":1},{"id":"f548f1c5-0086-78eb-9657-de4229027c9e","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function kind"}],[{"type":"text","text":"Failure signal"}],[{"type":"text","text":"Details"}]],[[{"type":"text","text":"Returns a pointer ("},{"type":"text","text":"fopen","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" set (by POSIX)"}]],[[{"type":"text","text":"Returns a count ("},{"type":"text","text":"fread","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"scanf","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Fewer items than requested / "},{"type":"text","text":"EOF","marks":[{"type":"code"}]}],[{"type":"text","text":"feof","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"ferror","marks":[{"type":"code"}]}]],[[{"type":"text","text":"POSIX system calls ("},{"type":"text","text":"open","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"read","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"-1","marks":[{"type":"code"}]}],[{"type":"text","text":"errno","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Conversions ("},{"type":"text","text":"strtol","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Result + "},{"type":"text","text":"end","marks":[{"type":"code"}]},{"type":"text","text":" pointer"}],[{"type":"text","text":"errno == ERANGE","marks":[{"type":"code"}]},{"type":"text","text":" on overflow"}]],[[{"type":"text","text":"Math ("},{"type":"text","text":"sqrt(-1)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"log(0)","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"NaN / ±HUGE_VAL"}],[{"type":"text","text":"errno == EDOM","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"ERANGE","marks":[{"type":"code"}]},{"type":"text","text":" (if "},{"type":"text","text":"math_errhandling","marks":[{"type":"code"}]},{"type":"text","text":" says so)"}]]]},"revision":1},{"id":"2ec5568f-f7f1-7d49-bcae-8808cac18d9e","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"errno, strerror, perror"}]},"revision":1},{"id":"d5c6040e-10cc-7837-9e2e-5252f6996719","type":"code","position":"a4","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n#include <errno.h>\n#include <stdlib.h>\n\nint main(void) {\n    FILE *f = fopen(\"does-not-exist.txt\", \"r\");\n    if (f == NULL) {\n        int saved = errno;                 /* save it: the next call may overwrite it */\n        printf(\"fopen failed: errno=%d (%s)\\n\", saved, strerror(saved));\n        printf(\"is ENOENT? %s\\n\", saved == ENOENT ? \"yes\" : \"no\");\n        perror(\"fopen\");                   /* prints \"fopen: No such file...\" to stderr */\n    }\n\n    errno = 0;                             /* strtol only sets errno on error: reset first */\n    long v = strtol(\"99999999999999999999\", NULL, 10);\n    if (errno == ERANGE) printf(\"overflow, clamped to %ld\\n\", v);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"dfe350f7-5b54-7278-a0a9-6a97b0938ea9","type":"code","position":"a5","content":{"language":"text","code":"fopen failed: errno=2 (No such file or directory)\nis ENOENT? yes\noverflow, clamped to 9223372036854775807","filename":"Output"},"revision":1},{"id":"f3cd3401-9934-7b3d-9b96-a41f0572e529","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" is only meaningful right after a function has "},{"type":"text","text":"reported","marks":[{"type":"italic"}]},{"type":"text","text":" failure. Successful calls may leave any value in it, so never test "},{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" alone to detect an error."}]}]}},"revision":1},{"id":"e6522ba3-c9f8-741f-95e5-c1c5e701b473","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Designing your own error reporting"}]},"revision":1},{"id":"afd9a551-4a49-769f-94c8-a9424781a993","type":"code","position":"a8","content":{"language":"c","code":"#include <stdio.h>\n\ntypedef enum { ERR_OK = 0, ERR_EMPTY, ERR_RANGE, ERR_PARSE } Err;\n\nconst char *err_str(Err e) {\n    static const char *msg[] = {\"ok\", \"empty input\", \"out of range\", \"not a number\"};\n    return msg[e];\n}\n\n/* return the status; deliver the result through an out-parameter */\nErr parse_percent(const char *s, int *out) {\n    if (!s || !*s) return ERR_EMPTY;\n    int v = 0;\n    for (; *s; s++) {\n        if (*s < ''0'' || *s > ''9'') return ERR_PARSE;\n        v = v * 10 + (*s - ''0'');\n        if (v > 100) return ERR_RANGE;\n    }\n    *out = v;\n    return ERR_OK;\n}\n\nint main(void) {\n    const char *inputs[] = {\"42\", \"\", \"250\", \"4x\"};\n    for (int i = 0; i < 4; i++) {\n        int p;\n        Err e = parse_percent(inputs[i], &p);\n        if (e == ERR_OK) printf(\"''%s'' -> %d%%\\n\", inputs[i], p);\n        else printf(\"''%s'' -> error: %s\\n\", inputs[i], err_str(e));\n    }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"2f932962-77cd-77a6-913f-38c3c16420b4","type":"code","position":"a9","content":{"language":"text","code":"''42'' -> 42%\n'''' -> error: empty input\n''250'' -> error: out of range\n''4x'' -> error: not a number","filename":"Output"},"revision":1},{"id":"9f5475c3-4933-7c1a-b4a6-2915c332ed6e","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Cleanup with goto"}]},"revision":1},{"id":"552b949e-4b28-7c1f-b2d1-7f5db96feb6c","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint process(const char *path) {\n    int rc = -1;\n    char *buf = NULL;\n    FILE *f = fopen(path, \"w+\");\n    if (!f) goto out;\n\n    buf = malloc(64);\n    if (!buf) goto close_file;\n\n    if (fputs(\"data\\n\", f) == EOF) goto free_buf;\n    rewind(f);\n    if (!fgets(buf, 64, f)) goto free_buf;\n    printf(\"read back: %s\", buf);\n    rc = 0;                                 /* success */\n\nfree_buf:                                   /* release in reverse order of acquisition */\n    free(buf);\nclose_file:\n    fclose(f);\nout:\n    return rc;\n}\n\nint main(void) {\n    printf(\"rc = %d\\n\", process(\"work.txt\"));\n    printf(\"rc = %d\\n\", process(\"no-such-dir/work.txt\"));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"8a41f4d2-b87a-73df-8b4c-34ea480932ad","type":"code","position":"aC","content":{"language":"text","code":"read back: data\nrc = 0\nrc = -1","filename":"Output"},"revision":1},{"id":"d972b5b1-288c-74d1-b92e-3eb4ab3302de","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Terminating"}]},"revision":1},{"id":"c022d351-59af-7519-9bcf-7d548235b1c6","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Call"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"return n;","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"main","marks":[{"type":"code"}]}],[{"type":"text","text":"Same as "},{"type":"text","text":"exit(n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"exit(status)","marks":[{"type":"code"}]}],[{"type":"text","text":"Runs "},{"type":"text","text":"atexit","marks":[{"type":"code"}]},{"type":"text","text":" handlers, flushes and closes streams, then ends the process"}]],[[{"type":"text","text":"_Exit(status)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"_exit","marks":[{"type":"code"}]}],[{"type":"text","text":"Ends immediately — no handlers, no flushing"}]],[[{"type":"text","text":"abort()","marks":[{"type":"code"}]}],[{"type":"text","text":"Raises "},{"type":"text","text":"SIGABRT","marks":[{"type":"code"}]},{"type":"text","text":" — abnormal termination, core dump; used by "},{"type":"text","text":"assert","marks":[{"type":"code"}]}]],[[{"type":"text","text":"quick_exit","marks":[{"type":"code"}]},{"type":"text","text":" (C11)"}],[{"type":"text","text":"Runs "},{"type":"text","text":"at_quick_exit","marks":[{"type":"code"}]},{"type":"text","text":" handlers only"}]]]},"revision":1},{"id":"cd329cd9-9fbe-7984-9e4e-5bed8a1f3c8c","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you handle errors in C without exceptions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return a status code (or "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":") from every fallible function and pass results through out-parameters; check every return value; propagate errors upward; use "},{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"strerror","marks":[{"type":"code"}]},{"type":"text","text":" for library failures; and structure cleanup with the "},{"type":"text","text":"goto cleanup","marks":[{"type":"code"}]},{"type":"text","text":" pattern so each resource is released exactly once on every path. "},{"type":"text","text":"setjmp","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"longjmp","marks":[{"type":"code"}]},{"type":"text","text":" exist for non-local jumps but skip cleanup and are rarely appropriate."}]}]}},"revision":1},{"id":"5ecd492b-73fd-7bbf-aaf0-c13cf9feb201","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is errno thread-safe?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes on modern systems: since C11, "},{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" is a macro that expands to a "},{"type":"text","text":"thread-local","marks":[{"type":"italic"}]},{"type":"text","text":" lvalue (often "},{"type":"text","text":"(*__errno_location())","marks":[{"type":"code"}]},{"type":"text","text":"), so each thread has its own copy."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
