SELECT 'd272a274-4636-7a7b-a5cb-d438faacbac1', 'b7f7e3d1-bfcd-7ecf-ab8d-eaf665753971', 1, 'PUBLISHED', 'Function Pointers & Callbacks', '[{"id":"c80eeed7-ac20-75b2-94c2-26ce3b11ff4a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function’s name decays to its address. Storing that in a "},{"type":"text","text":"function pointer","marks":[{"type":"italic"}]},{"type":"text","text":" lets you pass behaviour as data — callbacks, dispatch tables, plug-in strategies, "},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":" comparators."}]}]}},"revision":1},{"id":"410aa865-f952-7e72-b698-137a8682b341","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Syntax"}]},"revision":1},{"id":"4ecfc35e-9b56-767f-a721-7dba3c109cc4","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\nint add(int a, int b) { return a + b; }\nint mul(int a, int b) { return a * b; }\n\nint main(void) {\n    int (*op)(int, int) = add;        /* pointer to function taking (int,int) returning int */\n    printf(\"%d\\n\", op(3, 4));\n    op = &mul;                        /* & is optional */\n    printf(\"%d\\n\", (*op)(3, 4));      /* explicit * is optional too */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"a71e82e3-cc1b-75a5-ac49-b677e189fee9","type":"code","position":"a3","content":{"language":"text","code":"7\n12","filename":"Output"},"revision":1},{"id":"5e9d90ca-44d6-7ba2-8a0e-c1b7890377f0","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"int (*op)(int, int)","marks":[{"type":"code"}]},{"type":"text","text":" — the parentheses matter. "},{"type":"text","text":"int *op(int, int)","marks":[{"type":"code"}]},{"type":"text","text":" would declare a "},{"type":"text","text":"function","marks":[{"type":"italic"}]},{"type":"text","text":" returning "},{"type":"text","text":"int *","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"typedef","marks":[{"type":"code"}]},{"type":"text","text":" makes it readable: "},{"type":"text","text":"typedef int (*binop)(int, int);","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2ebecf64-aad0-71dc-be6c-51c025d91566","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Callbacks: qsort"}]},"revision":1},{"id":"05f99213-adfc-7a37-b298-71d66f83c800","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint cmp_int_asc(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);         /* avoids overflow of x - y */\n}\n\nint cmp_str(const void *a, const void *b) {\n    return strcmp(*(const char *const *)a, *(const char *const *)b);\n}\n\nint main(void) {\n    int nums[] = {42, -7, 19, 0, 3};\n    qsort(nums, 5, sizeof nums[0], cmp_int_asc);\n    for (int i = 0; i < 5; i++) printf(\"%d \", nums[i]);\n    printf(\"\\n\");\n\n    const char *words[] = {\"pear\", \"apple\", \"fig\"};\n    qsort(words, 3, sizeof words[0], cmp_str);\n    printf(\"%s %s %s\\n\", words[0], words[1], words[2]);\n\n    int key = 19;\n    int *hit = bsearch(&key, nums, 5, sizeof nums[0], cmp_int_asc);\n    printf(\"19 at index %td\\n\", hit - nums);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"f9fb6a94-c8d7-7743-a444-961a1872a24a","type":"code","position":"a7","content":{"language":"text","code":"-7 0 3 19 42\napple fig pear\n19 at index 3","filename":"Output"},"revision":1},{"id":"f2fe03f0-396e-7185-81bb-21dfc6d1250e","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"return x - y;","marks":[{"type":"code"}]},{"type":"text","text":" in a comparator overflows for large values of opposite sign ("},{"type":"text","text":"INT_MIN - 1","marks":[{"type":"code"}]},{"type":"text","text":"). Use "},{"type":"text","text":"(x > y) - (x < y)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"50901296-66ba-722f-bfae-7987fb004c0c","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Your own higher-order function"}]},"revision":1},{"id":"f2d04448-92e0-76d1-9388-3d509e50db2b","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n\ntypedef int (*transform_fn)(int);\n\nint square(int x) { return x * x; }\nint negate(int x) { return -x; }\n\nvoid map(int *a, int n, transform_fn f) {\n    for (int i = 0; i < n; i++) a[i] = f(a[i]);\n}\n\nint main(void) {\n    int v[] = {1, 2, 3};\n    map(v, 3, square);\n    map(v, 3, negate);\n    printf(\"%d %d %d\\n\", v[0], v[1], v[2]);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b30fd5f0-fdbf-7dbc-ac15-9c0abfb618bd","type":"code","position":"aB","content":{"language":"text","code":"-1 -4 -9","filename":"Output"},"revision":1},{"id":"692d2a8b-d5a7-77d8-9e97-36ed7d4f8216","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Dispatch tables"}]},"revision":1},{"id":"7b21a007-55b3-7e76-88a2-dd11a0e68b4d","type":"code","position":"aD","content":{"language":"c","code":"#include <stdio.h>\n\ndouble add(double a, double b) { return a + b; }\ndouble sub(double a, double b) { return a - b; }\ndouble mul(double a, double b) { return a * b; }\ndouble dvd(double a, double b) { return a / b; }\n\nint main(void) {\n    struct { char sym; double (*fn)(double, double); } ops[] = {\n        {''+'', add}, {''-'', sub}, {''*'', mul}, {''/'', dvd},\n    };\n    for (int i = 0; i < 4; i++)\n        printf(\"8 %c 2 = %g\\n\", ops[i].sym, ops[i].fn(8, 2));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"73ac329b-5020-7dff-ae77-12f14f3a440c","type":"code","position":"aE","content":{"language":"text","code":"8 + 2 = 10\n8 - 2 = 6\n8 * 2 = 16\n8 / 2 = 4","filename":"Output"},"revision":1},{"id":"f49c7b79-d137-757e-9ae7-fb56caf8a7ac","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Callbacks with context"}]},"revision":1},{"id":"f106c841-47a2-770d-8b0f-74a1910e3e48","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n\n/* C has no closures: pass state through a void * \"user data\" pointer */\nvoid for_each(const int *a, int n, void (*visit)(int, void *), void *ctx) {\n    for (int i = 0; i < n; i++) visit(a[i], ctx);\n}\n\nvoid accumulate(int x, void *ctx) { *(long *)ctx += x; }\n\nint main(void) {\n    int a[] = {5, 10, 20};\n    long total = 0;\n    for_each(a, 3, accumulate, &total);\n    printf(\"total = %ld\\n\", total);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"4af661c1-4bef-7289-9931-ca76bd46a365","type":"code","position":"aH","content":{"language":"text","code":"total = 35","filename":"Output"},"revision":1},{"id":"f4e85ad6-a9d3-7c9a-b1ef-0d1c7abaf41b","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you declare a function that returns a function pointer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Directly: "},{"type":"text","text":"int (*get_op(char c))(int, int);","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"get_op","marks":[{"type":"code"}]},{"type":"text","text":" takes a "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" and returns a pointer to a function "},{"type":"text","text":"(int, int) -> int","marks":[{"type":"code"}]},{"type":"text","text":". With a typedef it is readable: "},{"type":"text","text":"typedef int (*binop)(int, int); binop get_op(char c);","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b10ae417-8e49-78de-abee-263a78f9cdce","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are function pointers used for in real systems?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Callbacks ("},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bsearch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"atexit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"signal","marks":[{"type":"code"}]},{"type":"text","text":", event handlers), dispatch/jump tables for interpreters and state machines, plug-in interfaces (a struct of function pointers is C''s version of a vtable — e.g. Linux "},{"type":"text","text":"struct file_operations","marks":[{"type":"code"}]},{"type":"text","text":"), and dynamic loading with "},{"type":"text","text":"dlsym","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
