SELECT 'd14b9583-9b65-7dd7-9929-7beb93418ecd', '73913991-5557-719e-8f2c-f0998811b947', 1, 'PUBLISHED', 'Functions & Call by Value', '[{"id":"a01c31aa-207c-79c2-8256-d4b664d17456","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function packages a computation behind a name and a "},{"type":"text","text":"prototype","marks":[{"type":"italic"}]},{"type":"text","text":". C passes every argument "},{"type":"text","text":"by value","marks":[{"type":"bold"}]},{"type":"text","text":" — the function receives copies; to modify the caller’s variable you pass its address."}]}]}},"revision":1},{"id":"4b49ea0e-5ffb-7345-bd30-07ad8286886d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Declaration, definition, call"}]},"revision":1},{"id":"6ec2552a-aa6a-71ec-b77c-3e54cd61e262","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\ndouble average(const int *values, int count);   /* prototype */\n\nint main(void) {\n    int marks[] = {70, 85, 90};\n    printf(\"%.2f\\n\", average(marks, 3));\n    return 0;\n}\n\ndouble average(const int *values, int count) {  /* definition */\n    if (count == 0) return 0.0;\n    long sum = 0;\n    for (int i = 0; i < count; i++) sum += values[i];\n    return (double)sum / count;\n}","filename":"C"},"revision":1},{"id":"a6251cf5-787f-7c18-9854-caa968cc3695","type":"code","position":"a3","content":{"language":"text","code":"81.67","filename":"Output"},"revision":1},{"id":"e1598b0f-6d45-77e5-a926-0c28cf8b2bd7","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Part"}],[{"type":"text","text":"Example"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Return type"}],[{"type":"text","text":"double","marks":[{"type":"code"}]}],[{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":" if nothing is returned"}]],[[{"type":"text","text":"Name"}],[{"type":"text","text":"average","marks":[{"type":"code"}]}],[{"type":"text","text":"External linkage by default; "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" to hide it"}]],[[{"type":"text","text":"Parameters"}],[{"type":"text","text":"(const int *values, int count)","marks":[{"type":"code"}]}],[{"type":"text","text":"(void)","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"no","marks":[{"type":"italic"}]},{"type":"text","text":" parameters; "},{"type":"text","text":"()","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"unspecified","marks":[{"type":"italic"}]},{"type":"text","text":" (pre-C23)"}]],[[{"type":"text","text":"Body"}],[{"type":"text","text":"{ … }","marks":[{"type":"code"}]}],[{"type":"text","text":"return expr;","marks":[{"type":"code"}]},{"type":"text","text":" ends the call"}]]]},"revision":1},{"id":"66a25bc0-5abd-771e-9ce0-ac5db520e4c8","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Call by value"}]},"revision":1},{"id":"82bb8e5c-3ead-7dfe-9fa5-c542a9c490f1","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n\nvoid broken_swap(int a, int b) {    /* swaps the copies only */\n    int t = a; a = b; b = t;\n}\n\nvoid swap(int *a, int *b) {         /* receives addresses (\"call by reference\" emulation) */\n    int t = *a; *a = *b; *b = t;\n}\n\nint main(void) {\n    int x = 1, y = 2;\n    broken_swap(x, y);\n    printf(\"after broken_swap: %d %d\\n\", x, y);\n    swap(&x, &y);\n    printf(\"after swap:        %d %d\\n\", x, y);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"de5c0de3-632e-71ef-8a60-338f7d448f32","type":"code","position":"a7","content":{"language":"text","code":"after broken_swap: 1 2\nafter swap:        2 1","filename":"Output"},"revision":1},{"id":"cff493af-9d78-77bd-8443-ee7dd082b900","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Even the pointer is passed by value: "},{"type":"text","text":"swap","marks":[{"type":"code"}]},{"type":"text","text":" gets "},{"type":"text","text":"copies","marks":[{"type":"italic"}]},{"type":"text","text":" of the addresses. It can change what they point to, but not where the caller’s pointer variables point. To change a caller’s pointer, pass a pointer to it ("},{"type":"text","text":"int **","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"4d3c64d2-b6b0-717e-9219-dd8c775900f6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Arrays and structs as parameters"}]},"revision":1},{"id":"b91f0328-f65b-73c8-83d1-2f70f1004802","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An array argument "},{"type":"text","text":"decays","marks":[{"type":"italic"}]},{"type":"text","text":" to a pointer to its first element: "},{"type":"text","text":"void f(int a[])","marks":[{"type":"code"}]},{"type":"text","text":" is exactly "},{"type":"text","text":"void f(int *a)","marks":[{"type":"code"}]},{"type":"text","text":". The size is lost — pass it separately."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" is copied in full. For big structs pass "},{"type":"text","text":"const struct T *","marks":[{"type":"code"}]},{"type":"text","text":" to avoid the copy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark pointer parameters you don’t modify as "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" — it documents intent and lets the compiler check it."}]}]}]}]}},"revision":1},{"id":"a11cb776-e9cb-7544-b883-5187b58615a6","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Returning several values"}]},"revision":1},{"id":"9f10f6fb-0772-7f62-b680-27137c387b4c","type":"code","position":"aC","content":{"language":"c","code":"#include <stdio.h>\n\n/* return a status, deliver results through out-parameters */\nint divide(int a, int b, int *quot, int *rem) {\n    if (b == 0) return -1;\n    *quot = a / b;\n    *rem = a % b;\n    return 0;\n}\n\nint main(void) {\n    int q, r;\n    if (divide(17, 5, &q, &r) == 0)\n        printf(\"17 = 5 * %d + %d\\n\", q, r);\n    if (divide(1, 0, &q, &r) != 0)\n        printf(\"division by zero rejected\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"f4884fca-cc12-711f-bc6e-908933b47509","type":"code","position":"aD","content":{"language":"text","code":"17 = 5 * 3 + 2\ndivision by zero rejected","filename":"Output"},"revision":1},{"id":"f842ab52-17f8-74cc-a70b-f3c2b4a03cde","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"inline and the order of evaluation"}]},"revision":1},{"id":"fc920270-6dd2-7365-ab62-cbd375ea6b7d","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"static inline int sq(int x) { return x * x; }","marks":[{"type":"code"}]},{"type":"text","text":" — a hint to expand the body at the call site; typical in headers as a type-safe macro replacement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The order in which arguments are evaluated is "},{"type":"text","text":"unspecified","marks":[{"type":"bold"}]},{"type":"text","text":": in "},{"type":"text","text":"f(g(), h())","marks":[{"type":"code"}]},{"type":"text","text":" either may run first. Never depend on it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A function with a non-"},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":" return type that falls off the end without "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" — and whose value is used — is undefined behaviour ("},{"type":"text","text":"-Wreturn-type","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"8bb135f8-f83f-72fb-8a70-c2271bd13357","type":"code","position":"aG","content":{"language":"c","code":"int sign(int x) {\n    if (x > 0) return 1;\n    if (x < 0) return -1;\n}   /* missing return when x == 0 */","filename":"C — rejected: non-void function does not return a value in all paths"},"revision":1},{"id":"fc03cdb1-5c24-73d5-943d-3ae178560476","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does C support call by reference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — C only has call by value. Passing a pointer "},{"type":"text","text":"emulates","marks":[{"type":"italic"}]},{"type":"text","text":" call by reference: the pointer is copied, but both copies point to the same object, so the callee can modify it through "},{"type":"text","text":"*p","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"dfc39eaf-db35-7967-acdf-692c26c65a9a","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a function prototype and why is it needed?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A declaration giving the return type and parameter types ("},{"type":"text","text":"int max(int, int);","marks":[{"type":"code"}]},{"type":"text","text":"). It lets the compiler check calls, convert arguments to the right types and catch mistakes, even if the definition appears later or in another file."}]}]}},"revision":1},{"id":"0cb7cbbb-e8a6-747a-84df-916ece7f1bcb","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between f() and f(void) in a declaration?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before C23, "},{"type":"text","text":"int f();","marks":[{"type":"code"}]},{"type":"text","text":" declares a function taking an "},{"type":"text","text":"unspecified","marks":[{"type":"italic"}]},{"type":"text","text":" number of arguments (old K&R style — no checking), while "},{"type":"text","text":"int f(void);","marks":[{"type":"code"}]},{"type":"text","text":" declares a function that takes "},{"type":"text","text":"no","marks":[{"type":"italic"}]},{"type":"text","text":" arguments. C23 makes them equivalent, but "},{"type":"text","text":"(void)","marks":[{"type":"code"}]},{"type":"text","text":" is still the portable choice."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
