SELECT 'cb8e8029-0027-71ac-80c8-32db061368fd', 'f401f335-ba4e-71cf-8e44-fc342be0f649', 1, 'PUBLISHED', 'Hash Table', '[{"id":"87a9a120-a6ca-75b6-bbd7-8124dd9e90e9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array of buckets indexed by "},{"type":"text","text":"hash(key) % capacity","marks":[{"type":"code"}]},{"type":"text","text":". With a good hash function and a reasonable load factor, lookup, insert and delete are O(1) on average."}]}]}},"revision":1},{"id":"bc3dacc7-1cda-7ef9-a273-e5b4de011fae","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#define NBUCKETS 8\n\ntypedef struct Entry {\n    char *key;\n    int value;\n    struct Entry *next;               /* separate chaining */\n} Entry;\n\ntypedef struct { Entry *buckets[NBUCKETS]; size_t count; } Map;\n\nunsigned long hash(const char *s) {   /* djb2 by Dan Bernstein */\n    unsigned long h = 5381;\n    for (; *s; s++) h = h * 33 + (unsigned char)*s;\n    return h;\n}\n\nvoid map_put(Map *m, const char *key, int value) {\n    size_t i = hash(key) % NBUCKETS;\n    for (Entry *e = m->buckets[i]; e; e = e->next)\n        if (strcmp(e->key, key) == 0) { e->value = value; return; }   /* update */\n    Entry *e = malloc(sizeof *e);\n    if (!e) exit(1);\n    size_t n = strlen(key) + 1;\n    e->key = malloc(n);\n    if (!e->key) exit(1);\n    memcpy(e->key, key, n);\n    e->value = value;\n    e->next = m->buckets[i];          /* insert at bucket head */\n    m->buckets[i] = e;\n    m->count++;\n}\n\nint *map_get(Map *m, const char *key) {\n    for (Entry *e = m->buckets[hash(key) % NBUCKETS]; e; e = e->next)\n        if (strcmp(e->key, key) == 0) return &e->value;\n    return NULL;\n}\n\nvoid map_free(Map *m) {\n    for (int i = 0; i < NBUCKETS; i++)\n        for (Entry *e = m->buckets[i], *next; e; e = next) {\n            next = e->next;\n            