\n    printf(\"read %d items: %s is %d years, %.2f m\\n\", got, name, age, height);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"25642d91-cf23-7a52-9447-4c7a11a02e5d","type":"code","position":"a9","content":{"language":"text","code":"read 3 items: Asha is 21 years, 1.68 m","filename":"Output"},"revision":1},{"id":"cd062fa4-5779-796c-a55b-8f18046acdf8","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"scanf","marks":[{"type":"code"}]},{"type":"text","text":" returns the number of items successfully converted (or "},{"type":"text","text":"EOF","marks":[{"type":"code"}]},{"type":"text","text":"). Always check it — on bad input the variables are left untouched:"}]}]}},"revision":1},{"id":"1d9096eb-2610-7412-a162-13ddce07c8e3","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int x = -1;\n    if (scanf(\"%d\", &x) != 1) {\n        printf(\"not a number, x still %d\\n\", x);\n    } else {\n        printf(\"x = %d\\n\", x);\n    }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"711dcdd1-3096-7d45-b8f8-140e5d38012c","type":"code","position":"aC","content":{"language":"text","code":"not a number, x still -1","filename":"Output"},"revision":1},{"id":"6794075f-7bd5-7c1f-a03c-8adf094ba95c","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Reading a whole line: fgets"}]},"revision":1},{"id":"134d935c-7e3d-77fb-bfb1-2b8fa3208754","type":"code","position":"aE","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char line[64];\n    while (fgets(line, sizeof line, stdin) != NULL) {\n        line[strcspn(line, \"\\n\")] = ''\\0'';   /* strip the trailing newline */\n        printf(\"got \\\"%s\\\" (%zu chars)\\n\", line, strlen(line));\n    }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"dd5eca4f-fb39-7bf0-a270-eb9494c51fa9","type":"code","position":"aF","content":{"language":"text","code":"got \"hello world\" (11 chars)\ngot \"second line\" (11 chars)","filename":"Output"},"revision":1},{"id":"3110a67d-fbfc-76f3-92f5-6e38c3e7b3f1","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Character I/O"}]},"revision":1},{"id":"6808a100-5d17-754e-b665-f0d30c243d85","type":"code","position":"aH","content":{"language":"c","code":"#include <stdio.h>\n#include <ctype.h>\n\nint main(void) {\n    int c;                         /* int, not char: must hold EOF (-1) too */\n    while ((c = getchar()) != EOF) {\n        putchar(toupper(c));\n    }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b6f9390c-50e1-77ed-b325-4cb9b40650f9","type":"code","position":"aI","content":{"language":"text","code":"SHOUT THIS","filename":"Output"},"revision":1},{"id":"7d39fea2-098b-7512-bd55-fd480666671c","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Pitfalls"}]},"revision":1},{"id":"19d17918-c522-736b-9c66-eaeef2b3b88c","type":"table","position":"aK","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Mistake"}],[{"type":"text","text":"Consequence"}],[{"type":"text","text":"Fix"}]],[[{"type":"text","text":"scanf(\"%d\", x)","marks":[{"type":"code"}]},{"type":"text","text":" — missing "},{"type":"text","text":"&","marks":[{"type":"code"}]}],[{"type":"text","text":"Writes to a garbage address → crash"}],[{"type":"text","text":"scanf(\"%d\", &x)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"scanf(\"%s\", buf)","marks":[{"type":"code"}]},{"type":"text","text":" with no width"}],[{"type":"text","text":"Buffer overflow on long input"}],[{"type":"text","text":"scanf(\"%19s\", buf)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"char buf[20]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%f","marks":[{"type":"code"}]},{"type":"text","text":" to read a "},{"type":"text","text":"double","marks":[{"type":"code"}]}],[{"type":"text","text":"Writes only 4 bytes → wrong value"}],[{"type":"text","text":"Use "},{"type":"text","text":"%lf","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"scanf","marks":[{"type":"code"}]}]],[[{"type":"text","text":"gets(buf)","marks":[{"type":"code"}]}],[{"type":"text","text":"Unbounded — removed in C11"}],[{"type":"text","text":"fgets(buf, sizeof buf, stdin)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"scanf(\"%d\")","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"fgets","marks":[{"type":"code"}]}],[{"type":"text","text":"fgets","marks":[{"type":"code"}]},{"type":"text","text":" reads the leftover "},{"type":"text","text":"\\n","marks":[{"type":"code"}]},{"type":"text","text":" → empty line"}],[{"type":"text","text":"Consume the rest of the line first"}]],[[{"type":"text","text":"printf(user_input)","marks":[{"type":"code"}]}],[{"type":"text","text":"Format-string vulnerability"}],[{"type":"text","text":"printf(\"%s\", user_input)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"ed4dd071-45cc-72ac-b837-c401fef28491","type":"callout","position":"aL","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"stdout","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"line-buffered","marks":[{"type":"italic"}]},{"type":"text","text":" on a terminal but "},{"type":"text","text":"fully buffered","marks":[{"type":"italic"}]},{"type":"text","text":" when redirected to a file or pipe. Output may appear later than you expect — use "},{"type":"text","text":"fflush(stdout)","marks":[{"type":"code"}]},{"type":"text","text":" or print to "},{"type":"text","text":"stderr","marks":[{"type":"code"}]},{"type":"text","text":" (unbuffered) for diagnostics."}]}]}},"revision":1},{"id":"6abfb089-9e98-7824-8701-aad47821fc3b","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is getchar''s result stored in an int?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"getchar","marks":[{"type":"code"}]},{"type":"text","text":" returns every possible "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" value (0–255) "},{"type":"text","text":"plus","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"EOF","marks":[{"type":"code"}]},{"type":"text","text":" (a negative value, usually −1). A "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" cannot represent all 257 values, so "},{"type":"text","text":"EOF","marks":[{"type":"code"}]},{"type":"text","text":" would be confused with a real character (or never detected if "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" is unsigned)."}]}]}},"revision":1},{"id":"426f7455-715e-7a05-a3ca-eeeb07902d56","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does printf use %f for both float and double, but scanf needs %lf for double?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arguments to variadic functions undergo "},{"type":"text","text":"default argument promotions","marks":[{"type":"italic"}]},{"type":"text","text":": a "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" passed to "},{"type":"text","text":"printf","marks":[{"type":"code"}]},{"type":"text","text":" is converted to "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"%f","marks":[{"type":"code"}]},{"type":"text","text":" always receives a "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"scanf","marks":[{"type":"code"}]},{"type":"text","text":" receives "},{"type":"text","text":"pointers","marks":[{"type":"italic"}]},{"type":"text","text":", which are not promoted — it must know whether to write 4 bytes ("},{"type":"text","text":"float *","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"%f","marks":[{"type":"code"}]},{"type":"text","text":") or 8 bytes ("},{"type":"text","text":"double *","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"%lf","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
