  WHERE n.id = '1ae72c46-99a1-7eb6-af88-167e6f3adace' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '5b2864a3-7732-72ba-9e15-9d0c852db4b7' AND n."deletedAt" IS NULL
)
