SELECT '18543eac-718f-70ed-8c76-76451a95a720', 'f20c4761-cecc-73c6-b09c-f66127a0321b', 1, 'PUBLISHED', 'C Interview Questions', '[{"id":"0b7beae1-af40-7c2f-a075-818c8100c322","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The questions that come up again and again in C and embedded interviews — each with a crisp answer. Most are covered in depth in the earlier topics."}]}]}},"revision":1},{"id":"e821652e-9331-77b5-a40f-4b651fe74e89","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Output prediction warm-ups"}]},"revision":1},{"id":"77880e41-299a-7109-8feb-2712f98ba7d5","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char s[] = \"interview\";\n    char *p = s;\n    printf(\"%zu %zu\\n\", sizeof s, strlen(s));        /* 10 9 */\n    printf(\"%c %c\\n\", *p + 1, *(p + 1));             /* ''i''+1 = ''j'', then ''n'' */\n\n    int a[] = {1, 2, 3, 4, 5};\n    int *q = a + 1;\n    printf(\"%d %d %td\\n\", q[2], *(a + 4), &a[4] - q);\n\n    unsigned int u = 5;\n    int i = -10;\n    printf(\"%s\\n\", u + i > 5 ? \"big\" : \"small\");     /* i converts to unsigned */\n\n    int x = 10;\n    printf(\"%d\\n\", x >> 1 << 2);                     /* (10 >> 1) << 2 = 20 */\n    printf(\"%d\\n\", 3 == 3.0);                        /* 3 converts to double */\n    printf(\"%d\\n\", ''A'' + 1);\n    return 0;\n}","filename":"C — compiled with -Wno-sign-compare to allow the trap"},"revision":1},{"id":"8a6cdd38-ba5a-7bfe-8236-e473b48958b4","type":"code","position":"a3","content":{"language":"text","code":"10 9\nj n\n4 5 3\nbig\n20\n1\n66","filename":"Output"},"revision":1},{"id":"2124ea0a-0b32-74a4-97fb-5d18ecf2a6b6","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Language fundamentals"}]},"revision":1},{"id":"9376b40c-9d9e-77d8-b42a-a3dfb69ab1bb","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the storage classes in C?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"auto","marks":[{"type":"code"}]},{"type":"text","text":" (default for locals: block scope, automatic lifetime), "},{"type":"text","text":"register","marks":[{"type":"code"}]},{"type":"text","text":" (auto + no address; historic hint), "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" (static lifetime; internal linkage at file scope; value persists between calls as a local), "},{"type":"text","text":"extern","marks":[{"type":"code"}]},{"type":"text","text":" (declares an object/function defined elsewhere, external linkage), and C11 "},{"type":"text","text":"_Thread_local","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"typedef","marks":[{"type":"code"}]},{"type":"text","text":" is grammatically a storage-class specifier too."}]}]}},"revision":1},{"id":"7aadf4dc-6368-7f45-8dcf-bc9537e40d98","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between declaration and definition?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A declaration tells the compiler a name and its type ("},{"type":"text","text":"extern int x;","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int f(void);","marks":[{"type":"code"}]},{"type":"text","text":"). A definition also creates the object or supplies the function body ("},{"type":"text","text":"int x = 0;","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int f(void) { … }","marks":[{"type":"code"}]},{"type":"text","text":"). A name can be declared many times but defined exactly once."}]}]}},"revision":1},{"id":"4eed56b5-71a9-7db2-9007-a549ac35825d","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a volatile variable? Give examples."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A variable whose value can change outside the program’s visible control flow, so the compiler must perform every read and write exactly as written: memory-mapped hardware registers, variables modified in signal handlers ("},{"type":"text","text":"volatile sig_atomic_t","marks":[{"type":"code"}]},{"type":"text","text":"), and memory changed by DMA. It does not provide thread synchronisation."}]}]}},"revision":1},{"id":"2d5ef491-cc6f-769b-94d3-c04b797b28f1","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain const int *p, int *const p and const int *const p."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pointer to const int (can’t modify "},{"type":"text","text":"*p","marks":[{"type":"code"}]},{"type":"text","text":", can move "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"); const pointer to int (can modify "},{"type":"text","text":"*p","marks":[{"type":"code"}]},{"type":"text","text":", can’t move "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"); const pointer to const int (neither). Read the declaration right to left."}]}]}},"revision":1},{"id":"b3a64553-632a-7ea6-bf62-1f08d57d947f","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between ++i and i++ in a for loop?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"None for "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" in a standalone increment — compilers generate identical code. The difference only matters when the expression’s value is used: "},{"type":"text","text":"i++","marks":[{"type":"code"}]},{"type":"text","text":" yields the old value, "},{"type":"text","text":"++i","marks":[{"type":"code"}]},{"type":"text","text":" the new one."}]}]}},"revision":1},{"id":"6118d1a1-3489-73b7-8380-0d44f76f555d","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are sequence points and why do they matter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Points in execution where all previous side effects are complete: the end of a full expression ("},{"type":"text","text":";","marks":[{"type":"code"}]},{"type":"text","text":"), after the first operand of "},{"type":"text","text":"&&","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"||","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"?:","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":", and before a function call. Modifying an object twice (or modifying and reading it for another purpose) without an intervening sequence point is undefined behaviour — e.g. "},{"type":"text","text":"i = i++","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"a[i] = i++","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"43bc37d6-0c3f-7f7a-96cc-648ab0493059","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Pointers and memory"}]},"revision":1},{"id":"53f751f6-b567-7a1b-b06f-c14e0c5769b5","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between malloc and calloc? What does realloc do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"malloc(n)","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" uninitialised bytes; "},{"type":"text","text":"calloc(count, size)","marks":[{"type":"code"}]},{"type":"text","text":" returns zeroed memory for "},{"type":"text","text":"count × size","marks":[{"type":"code"}]},{"type":"text","text":" bytes with overflow checking. "},{"type":"text","text":"realloc(p, n)","marks":[{"type":"code"}]},{"type":"text","text":" resizes a block, possibly moving it (copying the old contents); on failure it returns "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" and leaves the old block intact."}]}]}},"revision":1},{"id":"fc260dc4-ffc2-7b0f-8f20-5ed1aa828c8c","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are dangling pointers, wild pointers and memory leaks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"dangling","marks":[{"type":"italic"}]},{"type":"text","text":" pointer points to memory that has been freed or gone out of scope. A "},{"type":"text","text":"wild","marks":[{"type":"italic"}]},{"type":"text","text":" pointer was never initialised and holds a garbage address. A "},{"type":"text","text":"leak","marks":[{"type":"italic"}]},{"type":"text","text":" is allocated memory that is no longer referenced by any pointer, so it can never be freed."}]}]}},"revision":1},{"id":"755640c6-3965-7144-b52d-3876278cc73a","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a NULL pointer vs a void pointer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A null pointer is a "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":" — a pointer of any type that points to nothing. A "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"type","marks":[{"type":"italic"}]},{"type":"text","text":" — a generic pointer that can hold the address of any object but must be cast before dereferencing. A "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" can itself be null."}]}]}},"revision":1},{"id":"2e5c1450-22bc-7472-8617-56f6bd647d11","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you return a pointer to a local variable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — the local’s lifetime ends when the function returns, so the pointer dangles. Return by value, use a "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" local (not reentrant), write into a caller-provided buffer, or return heap memory that the caller frees."}]}]}},"revision":1},{"id":"45d7aa33-d8c0-7470-9f04-59a1f5afb4dd","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between arrays and pointers?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array is a block of storage whose name decays to a pointer to its first element in most expressions; a pointer is a variable storing an address. "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" differs (whole array vs pointer size), an array name can’t be assigned, and "},{"type":"text","text":"&array","marks":[{"type":"code"}]},{"type":"text","text":" has type pointer-to-array."}]}]}},"revision":1},{"id":"9383385b-4e27-7896-888d-ebaf9d737a21","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the size of an array passed to a function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You can’t — it has decayed to a pointer. Pass the length as a separate parameter (or use a sentinel such as "},{"type":"text","text":"''\\0''","marks":[{"type":"code"}]},{"type":"text","text":" for strings, or wrap the array in a struct)."}]}]}},"revision":1},{"id":"be4169ad-f8cc-7e27-b69d-5a1b0e5d09c6","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is memory alignment and structure padding?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each type must be stored at an address that is a multiple of its alignment; the compiler inserts padding bytes between struct members and at the end to satisfy that for every member and for arrays of the struct. Ordering members from largest to smallest minimises padding."}]}]}},"revision":1},{"id":"4083b35b-8810-790d-a638-8e490026fac8","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain stack vs heap."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The stack holds function frames (locals, return addresses); allocation is automatic and very fast but the size is limited and data dies when the function returns. The heap holds "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":"’d memory; it is large and lives until "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":", but allocation is slower and the programmer manages the lifetime (leaks, use-after-free)."}]}]}},"revision":1},{"id":"2adbf5ef-7aa8-7c3f-96df-be42318dac0a","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Classic coding questions"}]},"revision":1},{"id":"622a2357-c7f2-7142-bb52-8bb8730af837","type":"code","position":"aL","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\n/* 1. reverse words in place: \"the sky is blue\" -> \"blue is sky the\" */\nstatic void rev(char *a, char *b) { while (a < b) { char t = *a; *a++ = *b; *b-- = t; } }\nvoid reverse_words(char *s) {\n    size_t n = strlen(s);\n    if (n == 0) return;\n    rev(s, s + n - 1);                               /* reverse whole string */\n    for (char *w = s; *w; ) {                        /* then each word */\n        while (*w == '' '') w++;\n        char *e = w;\n        while (*e && *e != '' '') e++;\n        if (e > w) rev(w, e - 1);\n        w = e;\n    }\n}\n\n/* 2. endianness check */\nint is_little_endian(void) { unsigned x = 1; return *(unsigned char *)&x == 1; }\n\n/* 3. my_atoi with sign and overflow saturation */\nint my_atoi(const char *s) {\n    long v = 0;\n    int sign = 1;\n    while (*s == '' '') s++;\n    if (*s == ''-'' || *s == ''+'') sign = (*s++ == ''-'') ? -1 : 1;\n    while (*s >= ''0'' && *s <= ''9'') {\n        v = v * 10 + (*s++ - ''0'');\n        if (v > 2147483648L) break;\n    }\n    v *= sign;\n    if (v > 2147483647L) return 2147483647;\n    if (v < -2147483648L) return (int)-2147483648L;\n    return (int)v;\n}\n\n/* 4. count set bits, reverse bits of a byte */\nunsigned char reverse_byte(unsigned char b) {\n    unsigned char r = 0;\n    for (int i = 0; i < 8; i++) { r = (unsigned char)((r << 1) | (b & 1)); b >>= 1; }\n    return r;\n}\n\nint main(void) {\n    char s[] = \"the sky is blue\";\n    reverse_words(s);\n    printf(\"%s\\n\", s);\n    printf(\"little endian: %d\\n\", is_little_endian());\n    printf(\"%d %d %d %d\\n\", my_atoi(\"  -42\"), my_atoi(\"+17abc\"), my_atoi(\"99999999999\"), my_atoi(\"-99999999999\"));\n    printf(\"0x%02X\\n\", reverse_byte(0x01));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"20168336-dd95-78a5-a2c7-88e549c58943","type":"code","position":"aM","content":{"language":"text","code":"blue is sky the\nlittle endian: 1\n-42 17 2147483647 -2147483648\n0x80","filename":"Output"},"revision":1},{"id":"891bc4be-8e23-7441-9eb5-40a2fac99fcb","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"Tricky questions"}]},"revision":1},{"id":"241ccc0e-c18c-7f5a-a538-e3d491c925dd","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does printf return?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of characters written (excluding the terminating NUL), or a negative value on error. So "},{"type":"text","text":"printf(\"%d\", printf(\"hello\"))","marks":[{"type":"code"}]},{"type":"text","text":" prints "},{"type":"text","text":"hello5","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d7677bf6-cf32-773a-bebf-4815e29dec54","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the output of sizeof on an expression with side effects, e.g. sizeof(i++)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is not incremented: "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" does not evaluate its operand (except for variable-length arrays); it only inspects the type at compile time."}]}]}},"revision":1},{"id":"21c2b41f-64fe-7fb8-a941-97ad398c0018","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How can you swap two variables without a temporary?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"a ^= b; b ^= a; a ^= b;","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"a = a + b; b = a - b; a = a - b;","marks":[{"type":"code"}]},{"type":"text","text":". Both are curiosities: the XOR version fails if "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" are the same object (it zeroes it), and the arithmetic version can overflow. A temporary is clearer and just as fast."}]}]}},"revision":1},{"id":"f9388cfa-fa76-7919-ad8a-f4d8fe732680","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between #include guards and #pragma once?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both stop a header from being processed twice in one translation unit. Guards ("},{"type":"text","text":"#ifndef X_H","marks":[{"type":"code"}]},{"type":"text","text":") are standard and work everywhere; "},{"type":"text","text":"#pragma once","marks":[{"type":"code"}]},{"type":"text","text":" is shorter, avoids guard-name collisions, and is supported by GCC, Clang and MSVC, but is not in the standard."}]}]}},"revision":1},{"id":"fd117b34-ec9c-7b26-a4bb-597335b40764","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is gets() dangerous and what replaces it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"gets","marks":[{"type":"code"}]},{"type":"text","text":" reads a line into a buffer without knowing the buffer’s size, so any long input overflows it — it was the vector of the 1988 Morris worm. It was removed in C11. Use "},{"type":"text","text":"fgets(buf, sizeof buf, stdin)","marks":[{"type":"code"}]},{"type":"text","text":" (and strip the newline)."}]}]}},"revision":1},{"id":"f2e65a43-b24a-7a44-9898-311b207ebd91","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a memory-mapped register and how do you access it in C?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hardware device register exposed at a fixed physical address. Access it through a pointer to "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" of the right width: "},{"type":"text","text":"#define GPIO_OUT (*(volatile uint32_t *)0x40020014u)","marks":[{"type":"code"}]},{"type":"text","text":", then "},{"type":"text","text":"GPIO_OUT |= 1u << 5;","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" ensures every access actually reaches the hardware."}]}]}},"revision":1},{"id":"2953b851-6c54-7124-a39a-316015cfc747","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens when you write int *p = malloc(10); p[10] = 1;?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Undefined behaviour twice over: "},{"type":"text","text":"malloc(10)","marks":[{"type":"code"}]},{"type":"text","text":" gives 10 "},{"type":"text","text":"bytes","marks":[{"type":"italic"}]},{"type":"text","text":" (2 ints on a 4-byte-int system, not 10 ints), and index 10 is far past the end. It may corrupt allocator metadata and crash later. Correct: "},{"type":"text","text":"int *p = malloc(10 * sizeof *p);","marks":[{"type":"code"}]},{"type":"text","text":" and indexes 0–9."}]}]}},"revision":1},{"id":"d0c59df9-f6f8-7d08-aedb-9b6d570ae9f9","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does C use name mangling?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C has no name mangling: the symbol for "},{"type":"text","text":"int add(int, int)","marks":[{"type":"code"}]},{"type":"text","text":" is just "},{"type":"text","text":"add","marks":[{"type":"code"}]},{"type":"text","text":" (sometimes "},{"type":"text","text":"_add","marks":[{"type":"code"}]},{"type":"text","text":"). That is why C functions can’t be overloaded, and why C++ code calling C uses "},{"type":"text","text":"extern \"C\"","marks":[{"type":"code"}]},{"type":"text","text":" to turn off C++ mangling."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'f20c4761-cecc-73c6-b09c-f66127a0321b' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

