INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT 'f20c4761-cecc-73c6-b09c-f66127a0321b', '18543eac-718f-70ed-8c76-76451a95a720', 'C Interview Questions', 'C Interview Questions', 'The questions that come up again and again in C and embedded interviews — each with a crisp answer. Most are covered in depth in the earlier topics.
Output prediction warm-ups
#include <stdio.h>
#include <string.h>

int main(void) {
    char s[] = "interview";
    char *p = s;
    printf("%zu %zu\n", sizeof s, strlen(s));        /* 10 9 */
    printf("%c %c\n", *p + 1, *(p + 1));             /* ''i''+1 = ''j'', then ''n'' */

    int a[] = {1, 2, 3, 4, 5};
    int *q = a + 1;
    printf("%d %d %td\n", q[2], *(a + 4), &a[4] - q);

    unsigned int u = 5;
    int i = -10;
    printf("%s\n", u + i > 5 ? "big" : "small");     /* i converts to unsigned */

    int x = 10;
    printf("%d\n", x >> 1 << 2);                     /* (10 >> 1) << 2 = 20 */
    printf("%d\n", 3 == 3.0);                        /* 3 converts to double */
    printf("%d\n", ''A'' + 1);
    return 0;
