SELECT 'c69ecb08-c185-7a07-afba-2f40bd21f459', '9612bea0-9536-7669-9c1f-2db836eb351c', 1, 'PUBLISHED', 'Singly Linked List', '[{"id":"e56eb9dc-644f-7d4a-959f-20ccf1a425f2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A chain of heap-allocated nodes, each pointing to the next. O(1) insertion at the head, O(n) search — and the most common C interview data structure."}]},{"type":"paragraph","content":[{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" → [1 | •] → [2 | •] → [3 | •] → "},{"type":"text","text":"NULL","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"9fd51a7e-f6cb-7dc0-8f49-d641fb1644c6","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Node {\n    int data;\n    struct Node *next;\n} Node;\n\nNode *new_node(int v) {\n    Node *n = malloc(sizeof *n);\n    if (!n) { perror(\"malloc\"); exit(EXIT_FAILURE); }\n    n->data = v;\n    n->next = NULL;\n    return n;\n}\n\nvoid push_front(Node **head, int v) {        /* O(1) */\n    Node *n = new_node(v);\n    n->next = *head;\n    *head = n;\n}\n\nvoid push_back(Node **head, int v) {         /* O(n): walk to the tail */\n    Node **pp = head;\n    while (*pp) pp = &(*pp)->next;\n    *pp = new_node(v);\n}\n\nint remove_value(Node **head, int v) {       /* pointer-to-pointer: no special case for head */\n    for (Node **pp = head; *pp; pp = &(*pp)->next) {\n        if ((*pp)->data == v) {\n            Node *dead = *pp;\n            *pp = dead->next;\n            free(dead);\n            return 1;\n        }\n    }\n    return 0;\n}\n\nvoid reverse(Node **head) {                  /* O(n), O(1) space */\n    Node *prev = NULL, *cur = *head;\n    while (cur) {\n        Node *next = cur->next;\n        cur->next = prev;\n        prev = cur;\n        cur = next;\n    }\n    *head = prev;\n}\n\nvoid print(const Node *n) {\n    for (; n; n = n->next) printf(\"%d -> \", n->data);\n    printf(\"NULL\\n\");\n}\n\nvoid free_list(Node *n) {\n    while (n) { Node *next = n->next; free(n); n = next; }\n}\n\nint main(void) {\n    Node *head = NULL;\n    push_back(&head, 2);\n    push_back(&head, 3);\n    push_front(&head, 1);\n    push_back(&head, 4);\n    print(head);\n    remove_value(&head, 1);\n    remove_value(&head, 3);\n    print(head);\n    reverse(&head);\n    print(head);\n    free_list(head);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"dee7b437-8512-7a93-a9f6-43de2673e49c","type":"code","position":"a2","content":{"language":"text","code":"1 -> 2 -> 3 -> 4 -> NULL\n2 -> 4 -> NULL\n4 -> 2 -> NULL","filename":"Output"},"revision":1},{"id":"cab6135d-515b-7f56-aec4-9e44a9b15662","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Classic interview operations"}]},"revision":1},{"id":"cd6f64ae-9bcf-7a39-be46-10e4c0395b2a","type":"code","position":"a4","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Node { int data; struct Node *next; } Node;\n\nNode *build(const int *a, int n) {\n    Node *head = NULL, **tail = &head;\n    for (int i = 0; i < n; i++) {\n        *tail = malloc(sizeof **tail);\n        if (!*tail) exit(1);\n        (*tail)->data = a[i];\n        (*tail)->next = NULL;\n        tail = &(*tail)->next;\n    }\n    return head;\n}\n\nNode *middle(Node *head) {                   /* slow/fast pointers */\n    Node *slow = head, *fast = head;\n    while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }\n    return slow;\n}\n\nint has_cycle(const Node *head) {            /* Floyd''s tortoise and hare */\n    const Node *slow = head, *fast = head;\n    while (fast && fast->next) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) return 1;\n    }\n    return 0;\n}\n\nNode *merge_sorted(Node *a, Node *b) {       /* splice two sorted lists */\n    Node dummy = {0, NULL}, *t = &dummy;\n    while (a && b) {\n        if (a->data <= b->data) { t->next = a; a = a->next; }\n        else                    { t->next = b; b = b->next; }\n        t = t->next;\n    }\n    t->next = a ? a : b;\n    return dummy.next;\n}\n\nint main(void) {\n    int x[] = {1, 4, 7, 9, 12};\n    int y[] = {2, 3, 10};\n    Node *a = build(x, 5), *b = build(y, 3);\n    printf(\"middle of a: %d\\n\", middle(a)->data);\n    printf(\"cycle? %d\\n\", has_cycle(a));\n\n    Node *m = merge_sorted(a, b);\n    for (Node *n = m; n; n = n->next) printf(\"%d \", n->data);\n    printf(\"\\n\");\n\n    Node *last = m;                          /* make a cycle to test detection */\n    while (last->next) last = last->next;\n    last->next = m->next->next;\n    printf(\"cycle? %d\\n\", has_cycle(m));\n    last->next = NULL;                       /* break it again before freeing */\n\n    while (m) { Node *next = m->next; free(m); m = next; }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"8b3995fa-35ef-7a05-a10a-09e8ec57b872","type":"code","position":"a5","content":{"language":"text","code":"middle of a: 7\ncycle? 0\n1 2 3 4 7 9 10 12\ncycle? 1","filename":"Output"},"revision":1},{"id":"96caa720-0db2-773d-b8d3-8c36560d8a35","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Singly linked list"}],[{"type":"text","text":"Array"}]],[[{"type":"text","text":"Access k-th"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Insert/delete at head"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Insert/delete after a known node"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n) (O(log n) if sorted)"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"Extra pointer per node; scattered (cache-unfriendly)"}],[{"type":"text","text":"Contiguous"}]]]},"revision":1},{"id":"23b482c9-9cc6-7f4d-be85-d50f6f57841b","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you reverse a singly linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iteratively with three pointers: "},{"type":"text","text":"prev = NULL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cur = head","marks":[{"type":"code"}]},{"type":"text","text":"; for each node save "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":", point "},{"type":"text","text":"cur->next","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", then advance "},{"type":"text","text":"prev = cur","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cur = next","marks":[{"type":"code"}]},{"type":"text","text":". At the end "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" is the new head. O(n) time, O(1) space."}]}]}},"revision":1},{"id":"82ed2fb7-053f-75be-ab94-6a3d9fcf8d76","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you detect a cycle in a linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Floyd’s algorithm: move a slow pointer one step and a fast pointer two steps; if they ever meet there is a cycle, if the fast pointer reaches "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" there isn’t. To find the cycle start, reset one pointer to the head and move both one step at a time — they meet at the entry."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-0