SELECT 'c0a74ad7-7cdd-7a16-9318-08952a03ebc3', 'a05196d5-1f58-723a-8a8f-bd53051ffa44', 1, 'PUBLISHED', 'Loops: for, while, do-while', '[{"id":"b90ead50-0570-7341-b1cb-cdc078cf04bd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three loop forms, plus "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"continue","marks":[{"type":"code"}]},{"type":"text","text":" and (rarely) "},{"type":"text","text":"goto","marks":[{"type":"code"}]},{"type":"text","text":". Pick "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" when you count, "},{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" when you wait for a condition, "},{"type":"text","text":"do-while","marks":[{"type":"code"}]},{"type":"text","text":" when the body must run at least once."}]}]}},"revision":1},{"id":"ff2910ea-a466-7c00-80f5-a5accbbf1964","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The three loops"}]},"revision":1},{"id":"f741aa6f-8bff-793a-9820-80c46fcf1255","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    for (int i = 0; i < 5; i++)          /* init; condition; step */\n        printf(\"%d \", i);\n    printf(\"\\n\");\n\n    int n = 1234, digits = 0;\n    while (n != 0) {                     /* test before each iteration */\n        n /= 10;\n        digits++;\n    }\n    printf(\"digits = %d\\n\", digits);\n\n    int k = 100;\n    do {                                 /* body runs at least once */\n        printf(\"k = %d\\n\", k);\n    } while (k < 10);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"21d7b333-c535-74d3-8280-fa3713227e41","type":"code","position":"a3","content":{"language":"text","code":"0 1 2 3 4\ndigits = 4\nk = 100","filename":"Output"},"revision":1},{"id":"d6e366b6-bc7a-73ec-9875-d0bb734b9426","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"break and continue"}]},"revision":1},{"id":"43ed7017-fa5a-774b-a636-8f480997b684","type":"code","position":"a5","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 10; i++) {\n        if (i % 2 == 0) continue;   /* skip even numbers */\n        if (i > 7) break;           /* leave the loop entirely */\n        printf(\"%d \", i);\n    }\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"02b41931-06ea-79d9-8f32-2c63c05abfc7","type":"code","position":"a6","content":{"language":"text","code":"1 3 5 7","filename":"Output"},"revision":1},{"id":"a331396f-5b21-73af-a7bc-ce2230d0c1c4","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Nested loops and patterns"}]},"revision":1},{"id":"e98f1e7f-4cbc-7c07-bf0a-c1b53324c433","type":"code","position":"a8","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int n = 4;\n    for (int row = 1; row <= n; row++) {\n        for (int s = 0; s < n - row; s++) putchar(''.'');\n        for (int star = 0; star < 2 * row - 1; star++) putchar(''*'');\n        putchar(''\\n'');\n    }\n    return 0;\n}","filename":"C"},"revision":1},{"id":"2386403e-7a08-7a89-875f-7cfb645a0ef4","type":"code","position":"a9","content":{"language":"text","code":"...*\n..***\n.*****\n*******","filename":"Output"},"revision":1},{"id":"b28ae68f-12c2-7a74-be62-bd4d84810cab","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Breaking out of nested loops: goto"}]},"revision":1},{"id":"59a8889c-d333-766d-8f38-9e6bae0d3365","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int grid[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};\n    int target = 5;\n    for (int r = 0; r < 3; r++)\n        for (int c = 0; c < 3; c++)\n            if (grid[r][c] == target) {\n                printf(\"found at (%d,%d)\\n\", r, c);\n                goto done;              /* one of the few acceptable uses */\n            }\n    printf(\"not found\\n\");\ndone:\n    return 0;\n}","filename":"C"},"revision":1},{"id":"1907e8d7-16a9-731c-80f5-58d27d52eaaf","type":"code","position":"aC","content":{"language":"text","code":"found at (1,1)","filename":"Output"},"revision":1},{"id":"11f22485-44df-777a-80f8-a1c01a0ce0f4","type":"callout","position":"aD","content":{"variant":"note","title":"goto","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"goto","marks":[{"type":"code"}]},{"type":"text","text":" is legitimate in C for two idioms: leaving deeply nested loops and the "},{"type":"text","text":"single cleanup exit","marks":[{"type":"italic"}]},{"type":"text","text":" pattern ("},{"type":"text","text":"goto cleanup;","marks":[{"type":"code"}]},{"type":"text","text":" to free resources in reverse order — used throughout the Linux kernel). Never jump backwards to build loops."}]}]}},"revision":1},{"id":"3fed78c8-b322-78e7-bbbb-fe3d2e50c0bf","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Loop idioms"}]},"revision":1},{"id":"916504c7-96c3-72f6-8ed0-2b6d96a68f4b","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Idiom"}],[{"type":"text","text":"Code"}]],[[{"type":"text","text":"Infinite loop"}],[{"type":"text","text":"for (;;) { … }","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"while (1) { … }","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Iterate an array"}],[{"type":"text","text":"for (size_t i = 0; i < n; i++)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Count down with "},{"type":"text","text":"size_t","marks":[{"type":"code"}]}],[{"type":"text","text":"for (size_t i = n; i-- > 0; )","marks":[{"type":"code"}]},{"type":"text","text":" (avoids the unsigned wrap trap)"}]],[[{"type":"text","text":"Read until EOF"}],[{"type":"text","text":"while ((c = getchar()) != EOF)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two indexes"}],[{"type":"text","text":"for (int i = 0, j = n - 1; i < j; i++, j--)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"65b31c4d-d234-736e-a9f4-4740fae4946b","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[] = {1, 2, 3, 4, 5};\n    size_t n = sizeof a / sizeof a[0];\n    for (size_t i = n; i-- > 0; )           /* safe reverse loop with unsigned index */\n        printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    for (int i = 0, j = (int)n - 1; i < j; i++, j--) {   /* reverse in place */\n        int t = a[i]; a[i] = a[j]; a[j] = t;\n    }\n    for (size_t i = 0; i < n; i++) printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"098f7580-da2f-7a8c-a8b5-01c0f8f57d5c","type":"code","position":"aH","content":{"language":"text","code":"5 4 3 2 1\n5 4 3 2 1","filename":"Output"},"revision":1},{"id":"feb6a5d6-5598-7089-97e5-c618e7ad16b3","type":"callout","position":"aI","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Off-by-one: "},{"type":"text","text":"for (i = 0; i <= n; i++)","marks":[{"type":"code"}]},{"type":"text","text":" over an array of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements touches "},{"type":"text","text":"a[n]","marks":[{"type":"code"}]},{"type":"text","text":" — one past the end. That is a buffer overflow (see Memory Bugs)."}]}]}},"revision":1},{"id":"57dd54c1-4502-75d1-8162-3d2ce14d95a7","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between while and do-while?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" checks the condition "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" each iteration, so the body may run zero times. "},{"type":"text","text":"do-while","marks":[{"type":"code"}]},{"type":"text","text":" checks "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":", so the body always runs at least once — useful for menus and input validation loops."}]}]}},"revision":1},{"id":"d6a4b857-ad7f-70f0-b414-a8e9a96db9a1","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is for (unsigned i = n - 1; i >= 0; i--) an infinite loop?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An unsigned value is always "},{"type":"text","text":">= 0","marks":[{"type":"code"}]},{"type":"text","text":"; when "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is 0, "},{"type":"text","text":"i--","marks":[{"type":"code"}]},{"type":"text","text":" wraps to "},{"type":"text","text":"UINT_MAX","marks":[{"type":"code"}]},{"type":"text","text":". Use a signed index or the "},{"type":"text","text":"for (size_t i = n; i-- > 0; )","marks":[{"type":"code"}]},{"type":"text","text":" idiom."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
