INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT 'a05196d5-1f58-723a-8a8f-bd53051ffa44', 'c0a74ad7-7cdd-7a16-9318-08952a03ebc3', 'Loops: for, while, do-while', 'Loops: for, while, do-while', 'Three loop forms, plus break, continue and (rarely) goto. Pick for when you count, while when you wait for a condition, do-while when the body must run at least once.
The three loops
#include <stdio.h>

int main(void) {
    for (int i = 0; i < 5; i++)          /* init; condition; step */
        printf("%d ", i);
    printf("\n");

    int n = 1234, digits = 0;
    while (n != 0) {                     /* test before each iteration */
        n /= 10;
        digits++;
    }
    printf("digits = %d\n", digits);

    int k = 100;
    do {                                 /* body runs at least once */
        printf("k = %d\n", k);
    } while (k < 10);
