The three loops
#include <stdio.h>

int main(void) {
    for (int i = 0; i < 5; i++)          /* init; condition; step */
        printf("%d ", i);
    printf("\n");

    int n = 1234, digits = 0;
    while (n != 0) {                     /* test before each iteration */
        n /= 10;
        digits++;
    }
    printf("digits = %d\n", digits);

    int k = 100;
    do {                                 /* body runs at least once */
        printf("k = %d\n", k);
    } while (k < 10);
    return 0;
}
