SELECT '9692f763-12a4-7a73-b77c-8b9b6991c2b5', 'b3e966e4-c0ec-7920-bcae-d24890a599e5', 1, 'PUBLISHED', 'Common Memory Bugs', '[{"id":"608c0c78-0cbc-7889-9328-e53b65d67a61","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C’s most expensive bugs are memory errors: they compile silently, often "},{"type":"text","text":"seem","marks":[{"type":"italic"}]},{"type":"text","text":" to work, and later crash or become security holes. Sanitizers ("},{"type":"text","text":"-fsanitize=address,undefined","marks":[{"type":"code"}]},{"type":"text","text":") and Valgrind find them."}]}]}},"revision":1},{"id":"abf7bd6c-a186-7681-a3b0-e9d95fd1d7fb","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Bug"}],[{"type":"text","text":"What it is"}],[{"type":"text","text":"Caught by"}]],[[{"type":"text","text":"Buffer overflow"}],[{"type":"text","text":"Read/write past the end (or before the start) of a buffer"}],[{"type":"text","text":"ASan, "},{"type":"text","text":"-D_FORTIFY_SOURCE","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Use after free"}],[{"type":"text","text":"Access through a pointer to freed memory"}],[{"type":"text","text":"ASan, Valgrind"}]],[[{"type":"text","text":"Double free"}],[{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" the same block twice"}],[{"type":"text","text":"ASan, glibc checks"}]],[[{"type":"text","text":"Memory leak"}],[{"type":"text","text":"Lose the last pointer to a block without freeing it"}],[{"type":"text","text":"LeakSanitizer, Valgrind"}]],[[{"type":"text","text":"Dangling stack pointer"}],[{"type":"text","text":"Use a pointer to a local after its function returned"}],[{"type":"text","text":"Compiler warning, ASan (use-after-return)"}]],[[{"type":"text","text":"Uninitialised read"}],[{"type":"text","text":"Read a variable / malloc’d memory before writing it"}],[{"type":"text","text":"-Wuninitialized","marks":[{"type":"code"}]},{"type":"text","text":", MSan, Valgrind"}]],[[{"type":"text","text":"Invalid free"}],[{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" a pointer not from "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" (stack array, "},{"type":"text","text":"p + 1","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"ASan"}]],[[{"type":"text","text":"NULL dereference"}],[{"type":"text","text":"Use a pointer that is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. unchecked "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Crash (SIGSEGV), UBSan"}]]]},"revision":1},{"id":"0bdc858a-ee16-77ff-ae0f-06c19e18fe79","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Heap buffer overflow"}]},"revision":1},{"id":"23e5652e-309b-7777-ab58-7727a77e2a44","type":"code","position":"a3","content":{"language":"c","code":"#include <stdlib.h>\n#include <string.h>\n\nint main(void) {\n    char *name = malloc(5);\n    strcpy(name, \"Alice\");        /* needs 6 bytes: 5 letters + ''\\0'' */\n    free(name);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"242db183-e6d6-76a8-b5da-bbb8f7da49e8","type":"code","position":"a4","content":{"language":"text","code":"==ERROR: AddressSanitizer: heap-buffer-overflow on address 0x602000000955\nWRITE of size 6 at 0x602000000955 thread T0\n0x602000000955 is located 0 bytes after 5-byte region [0x602000000950,0x602000000955)","filename":"AddressSanitizer (trimmed)"},"revision":1},{"id":"db90fed4-ca76-7ea8-8a66-d1270dfa5efc","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Use after free"}]},"revision":1},{"id":"35bb9ab1-d87f-72c2-a970-8795d96f3c43","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof *p);\n    if (!p) return 1;\n    *p = 42;\n    free(p);\n    printf(\"%d\\n\", *p);           /* the block now belongs to the allocator */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"539eec27-0bc2-768f-9a30-21fdb3d79522","type":"code","position":"a7","content":{"language":"text","code":"==ERROR: AddressSanitizer: heap-use-after-free on address 0x602000000950\nREAD of size 4 at 0x602000000950 thread T0\nfreed by thread T0 here: ... in free\npreviously allocated by thread T0 here: ... in malloc","filename":"AddressSanitizer (trimmed)"},"revision":1},{"id":"27d6036a-0c65-7a22-b7fd-9204a60fddd1","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Double free"}]},"revision":1},{"id":"325b3dc1-0821-7bb7-b9ee-ccbee1a1c2ff","type":"code","position":"a9","content":{"language":"c","code":"#include <stdlib.h>\n\nint main(void) {\n    char *buf = malloc(16);\n    free(buf);\n    free(buf);                    /* second free of the same block */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"ec9cb7cf-d023-74af-ae83-424220a5f80d","type":"code","position":"aA","content":{"language":"text","code":"==ERROR: AddressSanitizer: attempting double-free on 0x602000000950 in thread T0","filename":"AddressSanitizer (trimmed)"},"revision":1},{"id":"ebe9e6c1-59c5-7318-b438-091f0a981344","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Invalid free"}]},"revision":1},{"id":"28a09361-1c56-727b-9975-32840de4c387","type":"code","position":"aC","content":{"language":"c","code":"#include <stdlib.h>\n\nint main(void) {\n    int *a = malloc(4 * sizeof *a);\n    if (!a) return 1;\n    a++;                          /* lost the original pointer */\n    free(a);                      /* not the address malloc returned */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"cbdb21bc-a661-7b2f-9d98-ac2ed3868528","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Stack buffer overflow & use after scope"}]},"revision":1},{"id":"6d1081bb-f096-77fb-8539-150c7cb7d442","type":"code","position":"aE","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int *p;\n    {\n        int inner = 7;\n        p = &inner;\n    }                             /* inner''s lifetime ends here */\n    printf(\"%d\\n\", *p);\n    return 0;\n}","filename":"C — stack-use-after-scope caught by AddressSanitizer"},"revision":1},{"id":"cb464662-589f-7ceb-931c-15122dd8c19c","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Memory leak"}]},"revision":1},{"id":"38f99717-3d7d-7ecd-9fe4-21718883baa0","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *greet(const char *name) {\n    char *s = malloc(strlen(name) + 7);\n    if (s) { strcpy(s, \"Hello \"); strcat(s, name); }\n    return s;                      /* the caller now owns s */\n}\n\nint main(void) {\n    for (int i = 0; i < 3; i++) {\n        char *msg = greet(\"Bob\");\n        if (msg) puts(msg);\n        /* missing free(msg): each iteration leaks 10 bytes */\n    }\n    return 0;\n}","filename":"C — a leak runs “fine”, which is exactly the danger"},"revision":1},{"id":"e5838905-b485-7bb7-9395-261d1125f0c7","type":"code","position":"aH","content":{"language":"text","code":"Hello Bob\nHello Bob\nHello Bob","filename":"Output"},"revision":1},{"id":"0aa3a36b-27ce-7ea0-ba8e-35af7cea2464","type":"code","position":"aI","content":{"language":"text","code":"==ERROR: LeakSanitizer: detected memory leaks\nDirect leak of 30 byte(s) in 3 object(s) allocated from:\n    #0 in malloc\n    #1 in greet main.c:6","filename":"LeakSanitizer on Linux (illustrative)"},"revision":1},{"id":"13385678-b757-7698-8c99-56b05b87bd06","type":"callout","position":"aJ","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Leaks don’t crash — they grow memory use until a long-running server is killed. Run tests under "},{"type":"text","text":"-fsanitize=address","marks":[{"type":"code"}]},{"type":"text","text":" on Linux (LeakSanitizer is on by default there) or "},{"type":"text","text":"valgrind --leak-check=full","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6d8bcdd7-ae2e-7847-a47d-6a3974d2246b","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Uninitialised reads"}]},"revision":1},{"id":"ef22e506-a475-712d-be36-4e104f637420","type":"code","position":"aL","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int total;\n    for (int i = 0; i < 3; i++) total += i;    /* total starts as garbage */\n    printf(\"%d\\n\", total);\n    return 0;\n}","filename":"C — rejected: variable ''total'' is uninitialized when used"},"revision":1},{"id":"14ec5718-1ddd-7910-84fb-917acc6cd4cb","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Defensive habits"}]},"revision":1},{"id":"0c9b9ef1-7bcd-7064-be9d-70d3b803ddb4","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialise every variable at declaration; "},{"type":"text","text":"= {0}","marks":[{"type":"code"}]},{"type":"text","text":" for arrays and structs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check every "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"fopen","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"realloc","marks":[{"type":"code"}]},{"type":"text","text":" result."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set pointers to "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" after "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":"; keep one clear owner per allocation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pass buffer sizes everywhere; prefer "},{"type":"text","text":"snprintf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fgets","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"strncat","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"memcpy","marks":[{"type":"code"}]},{"type":"text","text":" with explicit lengths."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build debug and test runs with "},{"type":"text","text":"-g -fsanitize=address,undefined","marks":[{"type":"code"}]},{"type":"text","text":"; run Valgrind in CI."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"goto cleanup","marks":[{"type":"code"}]},{"type":"text","text":" pattern so every exit path frees what was allocated."}]}]}]}]}},"revision":1},{"id":"2ae05446-0366-739f-9ca2-dfcb19e0b81f","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a dangling pointer and how do you avoid it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pointer that still holds the address of an object whose lifetime has ended — freed heap memory, or a local of a function that returned. Avoid it by setting pointers to "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" after "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":", never returning addresses of locals, and having a clear ownership rule for every allocation."}]}]}},"revision":1},{"id":"f6565f6f-0cd5-7315-a8c9-c5d17a26ff46","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a memory leak and a dangling pointer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A leak is memory that is still allocated but no longer reachable (no pointer to it) — wasted but harmless to correctness. A dangling pointer is the opposite: a pointer still exists but the memory is gone — using it is undefined behaviour."}]}]}},"revision":1},{"id":"7843b6dd-a455-7c9d-8014-efd0df6ae906","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does AddressSanitizer work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The compiler instruments every memory access with a check against "},{"type":"text","text":"shadow memory","marks":[{"type":"italic"}]},{"type":"text","text":" that records which bytes are addressable. The runtime surrounds allocations with poisoned "},{"type":"text","text":"redzones","marks":[{"type":"italic"}]},{"type":"text","text":" and quarantines freed blocks, so overflows and use-after-free hit poisoned bytes and are reported immediately with stack traces. Cost: ~2× slowdown and more memory."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
