SELECT 'a2ad4e7d-85d6-75e4-9817-d960bb4ee0cf', 'ddcdc60c-23c1-77c2-92aa-6345278d2278', 1, 'PUBLISHED', 'Memory Layout of a C Program', '[{"id":"8641fcc5-e3db-7fe1-a9f3-048c567f20ea","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A running C program’s address space is split into segments: code, read-only data, initialised data, zero-initialised data (bss), the heap growing up and the stack growing down."}]}]}},"revision":1},{"id":"ed64b1fe-0708-7ce1-8e85-2d56bc6a8e8f","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Segment"}],[{"type":"text","text":"Holds"}],[{"type":"text","text":"Lifetime"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Text","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".text","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Machine code of functions"}],[{"type":"text","text":"Program"}],[{"type":"text","text":"Read-only + executable; shared between processes"}]],[[{"type":"text","text":"Read-only data","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".rodata","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"String literals, "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" globals"}],[{"type":"text","text":"Program"}],[{"type":"text","text":"Writing crashes"}]],[[{"type":"text","text":"Data","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".data","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Initialised globals / "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":"s ("},{"type":"text","text":"int g = 5;","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Program"}],[{"type":"text","text":"Values stored in the executable file"}]],[[{"type":"text","text":"BSS","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".bss","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Zero / uninitialised globals / "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":"s"}],[{"type":"text","text":"Program"}],[{"type":"text","text":"Only the size is stored; zero-filled at load"}]],[[{"type":"text","text":"Heap","marks":[{"type":"bold"}]}],[{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"calloc","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"realloc","marks":[{"type":"code"}]}],[{"type":"text","text":"Until "},{"type":"text","text":"free","marks":[{"type":"code"}]}],[{"type":"text","text":"Grows upward; managed by the allocator"}]],[[{"type":"text","text":"Stack","marks":[{"type":"bold"}]}],[{"type":"text","text":"Locals, parameters, return addresses"}],[{"type":"text","text":"Until the function returns"}],[{"type":"text","text":"Grows downward; ~8 MB default on Linux/macOS main thread"}]]]},"revision":1},{"id":"3a28ad90-fb46-7235-bed8-012623efc614","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"high addresses: "},{"type":"text","text":"stack","marks":[{"type":"bold"}]},{"type":"text","text":" ↓ → (free space) → ↑ "},{"type":"text","text":"heap","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":".bss","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":".data","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":".rodata","marks":[{"type":"bold"}]},{"type":"text","text":" → low addresses: "},{"type":"text","text":".text","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"e0f12129-4b6e-79be-8afd-42a54e9ee686","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint initialised = 42;          /* .data */\nint zeroed;                    /* .bss  */\nconst char *msg = \"literal\";   /* pointer in .data, the characters in .rodata */\n\nvoid where(void) { }           /* .text */\n\nint main(void) {\n    int local = 1;                              /* stack */\n    static int counter;                         /* .bss (static, zero) */\n    int *heap = malloc(sizeof *heap);           /* heap  */\n    if (!heap) return 1;\n    printf(\"text   %p\\n\", (void *)(size_t)where);\n    printf(\"rodata %p\\n\", (const void *)msg);\n    printf(\"data   %p\\n\", (void *)&initialised);\n    printf(\"bss    %p %p\\n\", (void *)&zeroed, (void *)&counter);\n    printf(\"heap   %p\\n\", (void *)heap);\n    printf(\"stack  %p\\n\", (void *)&local);\n    free(heap);\n    return 0;\n}","filename":"C — addresses differ per run and platform (no fixed output)"},"revision":1},{"id":"e5944bbb-df61-77d7-a2b0-a343e3eed235","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Inspecting the segments"}]},"revision":1},{"id":"7be394fe-962d-78f1-affd-0a021b79a41d","type":"code","position":"a5","content":{"language":"","code":"$ size ./app                      # text / data / bss sizes (Linux)\n   text    data     bss     dec     hex filename\n   1845     616       8    2469     9a5 ./app\n$ objdump -h ./app                # section headers\n$ nm ./app | grep '' [bBdD] ''      # symbols in bss (b/B) and data (d/D)\n$ ulimit -s                       # stack size limit in KB\n8192","filename":"Terminal"},"revision":1},{"id":"fa7ffba1-3031-7660-a399-b398876c8785","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Stack vs heap"}]},"revision":1},{"id":"a8c3c882-31bd-7449-b813-64c051924d62","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Stack"}],[{"type":"text","text":"Heap"}]],[[{"type":"text","text":"Allocation"}],[{"type":"text","text":"Automatic (move the stack pointer)"}],[{"type":"text","text":"Explicit "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"free","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Speed"}],[{"type":"text","text":"Very fast"}],[{"type":"text","text":"Slower (allocator bookkeeping, possible system call)"}]],[[{"type":"text","text":"Size"}],[{"type":"text","text":"Small, fixed limit"}],[{"type":"text","text":"Large — limited by RAM / address space"}]],[[{"type":"text","text":"Lifetime"}],[{"type":"text","text":"Ends when the function returns"}],[{"type":"text","text":"Until you "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":" it"}]],[[{"type":"text","text":"Failure mode"}],[{"type":"text","text":"Stack overflow (crash)"}],[{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"; leaks, fragmentation"}]],[[{"type":"text","text":"Typical bugs"}],[{"type":"text","text":"Returning addresses of locals, huge arrays, deep recursion"}],[{"type":"text","text":"Leaks, use-after-free, double free"}]]]},"revision":1},{"id":"225199a4-b0d4-7a96-9488-4f5b454ee6c3","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Stack frames"}]},"revision":1},{"id":"aeedde53-9a0e-78f8-ad26-a909026b087f","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each call pushes a "},{"type":"text","text":"frame","marks":[{"type":"italic"}]},{"type":"text","text":": return address, saved registers, parameters that don’t fit in registers, and locals. Returning pops it — which is exactly why a pointer to a local is dangling after the return."}]}]}},"revision":1},{"id":"53aa1fd0-8de4-7e0f-8a83-ba46671ca9d5","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n\nint depth(int n) {\n    char pad[1024];                /* 1 KB of stack per call */\n    pad[0] = (char)n;\n    if (n == 0) return pad[0];\n    return depth(n - 1) + 1;\n}\n\nint main(void) {\n    printf(\"%d frames deep, fine\\n\", depth(100));    /* ~100 KB of stack */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"29ff5ecc-b675-79b7-91d6-814b08d73656","type":"code","position":"aB","content":{"language":"text","code":"100 frames deep, fine","filename":"Output"},"revision":1},{"id":"ca4d59ae-eeb3-7fb7-90ee-f51dbb594bcb","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"char big[16 * 1024 * 1024];","marks":[{"type":"code"}]},{"type":"text","text":" as a local, or unbounded recursion, overflows the stack. Put large buffers on the heap or make them "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"13c5193e-8312-7ad9-a139-0e9f7f630281","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where are string literals stored?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a read-only data segment ("},{"type":"text","text":".rodata","marks":[{"type":"code"}]},{"type":"text","text":"), with static storage duration. Identical literals may share storage. Modifying one is undefined behaviour and usually crashes."}]}]}},"revision":1},{"id":"abcd1c39-2c0f-78ad-9737-ad9bc500f426","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between .data and .bss?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both hold objects with static storage duration. "},{"type":"text","text":".data","marks":[{"type":"code"}]},{"type":"text","text":" holds those with a non-zero initialiser — their initial bytes are stored in the executable. "},{"type":"text","text":".bss","marks":[{"type":"code"}]},{"type":"text","text":" holds zero-initialised ones; the file records only the total size and the loader zero-fills it, keeping executables small."}]}]}},"revision":1},{"id":"f9b424c7-9550-7ecc-9c28-f2f4d52cc677","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does the stack grow down and the heap grow up?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Historically, so both could share one free region between them and each could grow until they met, without choosing a fixed split in advance. Modern systems use separate mappings with guard pages, but the convention remains on most architectures."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
