SELECT '40588f34-857d-7e58-beb3-2ab706fbd6ac', '3c41c26c-29e1-7682-8268-4ea9f421d7a0', 1, 'PUBLISHED', 'C99, C11, C17 & C23 Features', '[{"id":"1f9feee9-6d8b-7600-9af3-0d3b9a242310","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern C is much nicer than the C89 many tutorials still teach. Use "},{"type":"text","text":"-std=c17","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"-std=c23","marks":[{"type":"code"}]},{"type":"text","text":") and these features freely."}]}]}},"revision":1},{"id":"48d4e6bf-8237-7930-94c2-878a7ccd4216","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"C99"}]},"revision":1},{"id":"437bf8f4-cd64-74bb-8d8f-50b938ce719d","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n#include <stdbool.h>\n#include <stdint.h>\n\nstruct Point { int x, y; };\n\nstatic inline int sq(int v) { return v * v; }        /* inline functions */\n\nint main(void) {\n    // line comments\n    for (int i = 0; i < 1; i++) { }                   /* declarations in for */\n    bool ready = true;                                 /* <stdbool.h> */\n    int64_t big = 1LL << 40;                           /* <stdint.h>, long long */\n    struct Point p = {.y = 2, .x = 1};                 /* designated initializers */\n    int arr[5] = {[4] = 9};\n    int n = 3;\n    int vla[n];                                        /* variable-length array */\n    vla[0] = sq(n);\n    struct Point *q = &(struct Point){5, 6};           /* compound literal */\n    printf(\"%d %lld %d %d %d %d %d\\n\", ready, (long long)big, p.x, arr[4], vla[0], q->y, __func__[0]);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"c8cba3e8-4d64-7f3f-8523-3ec08138292d","type":"code","position":"a3","content":{"language":"text","code":"1 1099511627776 1 9 9 6 109","filename":"Output"},"revision":1},{"id":"12b301f8-9ffc-7984-b39f-ef8998a0f74b","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"C11"}]},"revision":1},{"id":"0f6ea0e9-dfe1-7924-8e9d-e5ac79256f65","type":"code","position":"a5","content":{"language":"c","code":"#include <stdio.h>\n#include <stdalign.h>\n#include <stdnoreturn.h>\n#include <stdlib.h>\n\n/* _Generic: compile-time dispatch on the type of an expression */\n#define type_name(x) _Generic((x), \\\n    int: \"int\", double: \"double\", char *: \"char *\", default: \"other\")\n\n#define print_any(x) _Generic((x), int: print_int, double: print_double)(x)\nvoid print_int(int v) { printf(\"int %d\\n\", v); }\nvoid print_double(double v) { printf(\"double %.2f\\n\", v); }\n\n_Static_assert(sizeof(int) >= 4, \"need 32-bit int\");   /* compile-time check */\n\nstruct Packet {\n    int kind;\n    union { int code; float value; };                    /* anonymous union */\n};\n\nnoreturn void die(const char *msg) { fprintf(stderr, \"%s\\n\", msg); exit(1); }\n\nint main(void) {\n    char *s = \"hi\";\n    printf(\"%s %s %s %s\\n\", type_name(42), type_name(3.0), type_name(s), type_name(1L));\n    print_any(7);\n    print_any(2.5);\n    struct Packet pk = {.kind = 1, .code = 404};\n    printf(\"%d %zu\\n\", pk.code, alignof(double));\n    if (pk.code != 404) die(\"unexpected\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"39adffbd-6dac-7f4a-8a78-07c2f0c33420","type":"code","position":"a6","content":{"language":"text","code":"int double char * other\nint 7\ndouble 2.50\n404 8","filename":"Output"},"revision":1},{"id":"4718bc22-41a8-7d46-aca1-aec0b1c760c8","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"C11 feature"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"_Generic","marks":[{"type":"code"}]}],[{"type":"text","text":"Type-generic macros (how "},{"type":"text","text":"<tgmath.h>","marks":[{"type":"code"}]},{"type":"text","text":" works)"}]],[[{"type":"text","text":"_Static_assert","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"static_assert","marks":[{"type":"code"}]}],[{"type":"text","text":"Compile-time assertions"}]],[[{"type":"text","text":"_Alignas","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"_Alignof","marks":[{"type":"code"}]}],[{"type":"text","text":"Control / query alignment"}]],[[{"type":"text","text":"_Noreturn","marks":[{"type":"code"}]}],[{"type":"text","text":"Function never returns ("},{"type":"text","text":"exit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"abort","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Anonymous structs/unions"}],[{"type":"text","text":"Access nested members directly"}]],[[{"type":"text","text":"_Atomic","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<stdatomic.h>","marks":[{"type":"code"}]},{"type":"text","text":", memory model"}],[{"type":"text","text":"Portable concurrency"}]],[[{"type":"text","text":"<threads.h>","marks":[{"type":"code"}]},{"type":"text","text":" (optional)"}],[{"type":"text","text":"Threads, mutexes, condition variables"}]],[[{"type":"text","text":"_Thread_local","marks":[{"type":"code"}]}],[{"type":"text","text":"Thread-local storage"}]],[[{"type":"text","text":"Bounds-checked "},{"type":"text","text":"_s","marks":[{"type":"code"}]},{"type":"text","text":" functions (Annex K)"}],[{"type":"text","text":"Optional; rarely implemented"}]],[[{"type":"text","text":"gets","marks":[{"type":"code"}]},{"type":"text","text":" removed"}],[{"type":"text","text":"Finally"}]],[[{"type":"text","text":"aligned_alloc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"quick_exit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"timespec_get","marks":[{"type":"code"}]}],[{"type":"text","text":"Library additions"}]]]},"revision":1},{"id":"f69b2479-5397-7d1e-bd6a-9bfffd398179","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"C17"}]},"revision":1},{"id":"a162ebd1-9af8-7af7-a454-137f989d5d16","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C17 (also called C18) is a "},{"type":"text","text":"bug-fix","marks":[{"type":"italic"}]},{"type":"text","text":" release: no new features, only clarifications and defect fixes to C11. "},{"type":"text","text":"__STDC_VERSION__","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"201710L","marks":[{"type":"code"}]},{"type":"text","text":". It is the default of GCC 8+ and recent Clang."}]}]}},"revision":1},{"id":"0c63f89f-5851-7894-9384-21d3d1263bbf","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"C23"}]},"revision":1},{"id":"012a8fde-c687-7161-a68f-f6ff80c97561","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n#include <stdckdint.h>\n\n[[nodiscard]] int twice(int x) { return 2 * x; }     /* standard attributes */\n\nenum Small : unsigned char { A, B, C };                  /* fixed underlying type */\n\nint main(void) {\n    constexpr int size = 4;                              /* true compile-time constant */\n    int arr[size] = {};                                  /* empty initializer = zero */\n    bool ok = true;                                      /* bool/true/false are keywords */\n    int *p = nullptr;                                    /* typed null pointer constant */\n    typeof(size) mask = 0b1111''0000;                     /* typeof, binary literal, digit separator */\n    auto ratio = 2.5;                                    /* type inference */\n    int sum;\n    bool overflow = ckd_add(&sum, 2147483647, 1);        /* checked arithmetic */\n    static_assert(sizeof(enum Small) == 1);              /* message optional */\n    printf(\"%d %d %d %d %.1f %d %d\\n\", arr[3], ok, p == nullptr, mask, ratio, twice(size), overflow);\n    return 0;\n}","filename":"C — compiled with -std=c23"},"revision":1},{"id":"df6fe67a-8469-7c34-8d91-c4fb97738553","type":"code","position":"aC","content":{"language":"text","code":"0 1 1 240 2.5 8 1","filename":"Output"},"revision":1},{"id":"c2c3250f-ac97-77d6-99c8-e01b3cf9619d","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"C23 feature"}],[{"type":"text","text":"Replaces"}]],[[{"type":"text","text":"bool","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"static_assert","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"alignas","marks":[{"type":"code"}]},{"type":"text","text":"… as keywords"}],[{"type":"text","text":"<stdbool.h>","marks":[{"type":"code"}]},{"type":"text","text":" etc."}]],[[{"type":"text","text":"nullptr","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"nullptr_t","marks":[{"type":"code"}]}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" (which may be "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"constexpr","marks":[{"type":"code"}]},{"type":"text","text":" objects"}],[{"type":"text","text":"#define","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" constants"}]],[[{"type":"text","text":"typeof","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typeof_unqual","marks":[{"type":"code"}]}],[{"type":"text","text":"GNU "},{"type":"text","text":"__typeof__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"auto","marks":[{"type":"code"}]},{"type":"text","text":" type inference"}],[{"type":"text","text":"Spelling out types"}]],[[{"type":"text","text":"[[nodiscard]]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[[maybe_unused]]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[[deprecated]]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[[fallthrough]]","marks":[{"type":"code"}]}],[{"type":"text","text":"__attribute__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"0b","marks":[{"type":"code"}]},{"type":"text","text":" literals, "},{"type":"text","text":"''","marks":[{"type":"code"}]},{"type":"text","text":" digit separators"}],[{"type":"text","text":"Hex masks"}]],[[{"type":"text","text":"<stdckdint.h>","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"ckd_add","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ckd_sub","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ckd_mul","marks":[{"type":"code"}]}],[{"type":"text","text":"Hand-written overflow checks"}]],[[{"type":"text","text":"#embed","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"#elifdef","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__has_include","marks":[{"type":"code"}]}],[{"type":"text","text":"External tools, nested "},{"type":"text","text":"#ifdef","marks":[{"type":"code"}]}]],[[{"type":"text","text":"f(void)","marks":[{"type":"code"}]},{"type":"text","text":" ≡ "},{"type":"text","text":"f()","marks":[{"type":"code"}]},{"type":"text","text":"; K&R definitions removed"}],[{"type":"text","text":"Unprototyped functions"}]],[[{"type":"text","text":"Two’s complement mandatory"}],[{"type":"text","text":"Implementation-defined representations"}]]]},"revision":1},{"id":"ee0f1a56-c864-7767-a058-f3dda1a1b518","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is _Generic used for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selecting an expression at compile time based on the type of a controlling expression — the foundation of type-generic macros like "},{"type":"text","text":"<tgmath.h>","marks":[{"type":"code"}]},{"type":"text","text":"’s "},{"type":"text","text":"sqrt","marks":[{"type":"code"}]},{"type":"text","text":" that call "},{"type":"text","text":"sqrtf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sqrt","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"sqrtl","marks":[{"type":"code"}]},{"type":"text","text":" depending on the argument type. It gives C a limited form of overloading."}]}]}},"revision":1},{"id":"d6362581-5283-7280-ab70-173351d17a95","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are designated initializers?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C99 syntax to initialise specific members or indexes by name: "},{"type":"text","text":"struct Point p = {.y = 2, .x = 1};","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int a[10] = {[9] = 1};","marks":[{"type":"code"}]},{"type":"text","text":". Unmentioned members are zero-initialised, the order doesn’t matter, and the code survives reordering of struct fields."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
