SELECT '4470a61f-49ec-7637-9ba8-327175e81047', '00eafe1d-1af4-7844-81bd-4e79912c1313', 1, 'PUBLISHED', 'Header Files & Multi-File Programs', '[{"id":"db261882-4a76-7416-9795-9e68f5e4f427","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real programs split into modules: a "},{"type":"text","text":"header","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".h","marks":[{"type":"code"}]},{"type":"text","text":") declares the interface, a "},{"type":"text","text":"source","marks":[{"type":"bold"}]},{"type":"text","text":" file ("},{"type":"text","text":".c","marks":[{"type":"code"}]},{"type":"text","text":") implements it, and the linker joins the compiled objects."}]}]}},"revision":1},{"id":"5abf87f8-1950-77ac-9779-a6dedf6a059a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"A module: header + implementation"}]},"revision":1},{"id":"82267148-d1fa-7573-8eff-e9d9dd9d7cbd","type":"code","position":"a2","content":{"language":"c","code":"/* ---------- mathx.h ---------- */\n#ifndef MATHX_H              /* include guard: safe to include twice */\n#define MATHX_H\n\n#include <stddef.h>\n\n#define MATHX_PI 3.14159265358979\n\nextern int mathx_calls;                           /* declaration only */\n\nint    mathx_gcd(int a, int b);                   /* prototypes */\ndouble mathx_mean(const double *v, size_t n);\n\nstatic inline int mathx_sq(int x) { return x * x; }   /* small helpers may live in the header */\n\n#endif /* MATHX_H */","filename":"C — mathx.h (compile-checked)"},"revision":1},{"id":"ee356ac4-fd83-75e2-9e86-d4e8e9e75641","type":"code","position":"a3","content":{"language":"c","code":"/* ---------- mathx.c ---------- */\n#include <stddef.h>\n/* #include \"mathx.h\"  — always include your own header to check the prototypes match */\nextern int mathx_calls;\nint mathx_gcd(int a, int b);\ndouble mathx_mean(const double *v, size_t n);\n\nint mathx_calls = 0;                              /* the one definition */\n\nstatic int abs_int(int x) { return x < 0 ? -x : x; }   /* private helper */\n\nint mathx_gcd(int a, int b) {\n    mathx_calls++;\n    a = abs_int(a); b = abs_int(b);\n    while (b) { int t = a % b; a = b; b = t; }\n    return a;\n}\n\ndouble mathx_mean(const double *v, size_t n) {\n    mathx_calls++;\n    double s = 0;\n    for (size_t i = 0; i < n; i++) s += v[i];\n    return n ? s / n : 0.0;\n}","filename":"C — mathx.c (compile-checked)"},"revision":1},{"id":"c4ec77d6-7845-75f3-b1c6-91bd094dd06a","type":"code","position":"a4","content":{"language":"c","code":"/* ---------- main.c ---------- */\n#include <stdio.h>\n/* #include \"mathx.h\" */\n#include <stddef.h>\nextern int mathx_calls;\nint mathx_gcd(int a, int b);\ndouble mathx_mean(const double *v, size_t n);\nstatic inline int mathx_sq(int x) { return x * x; }\n\nint main(void) {\n    double v[] = {2, 4, 9};\n    printf(\"gcd=%d mean=%.1f sq=%d calls=%d\\n\",\n           mathx_gcd(-48, 18), mathx_mean(v, 3), mathx_sq(7), mathx_calls);\n    return 0;\n}\n\n/* (the definitions from mathx.c, pasted here so this sample runs as one file) */\nint mathx_calls = 0;\nint mathx_gcd(int a, int b) {\n    mathx_calls++;\n    a = a < 0 ? -a : a; b = b < 0 ? -b : b;\n    while (b) { int t = a % b; a = b; b = t; }\n    return a;\n}\ndouble mathx_mean(const double *v, size_t n) {\n    mathx_calls++;\n    double s = 0;\n    for (size_t i = 0; i < n; i++) s += v[i];\n    return n ? s / n : 0.0;\n}","filename":"C — main.c (run as one file)"},"revision":1},{"id":"6649f295-100a-7d90-8e4b-47ad6ce36b62","type":"code","position":"a5","content":{"language":"text","code":"gcd=6 mean=5.0 sq=49 calls=2","filename":"Output"},"revision":1},{"id":"bd33b6fa-607b-72a6-b620-3f8fcf03e7c2","type":"code","position":"a6","content":{"language":"","code":"$ gcc -c mathx.c -o mathx.o                 # compile each module separately\n$ gcc -c main.c  -o main.o\n$ gcc main.o mathx.o -o app                 # link them\n$ ./app\ngcd=6 mean=5.0 sq=49 calls=2\n\n# or in one step\n$ gcc -Wall -Wextra main.c mathx.c -o app\n\n# build a static library and link against it\n$ ar rcs libmathx.a mathx.o\n$ gcc main.c -L. -lmathx -o app","filename":"Terminal"},"revision":1},{"id":"9925f323-c1a1-78ce-b03e-dae0eb2bf49c","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"What goes where"}]},"revision":1},{"id":"6d0bd651-cd56-7d1b-b6c0-9acac1f6a436","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"In the header ("},{"type":"text","text":".h","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"In the source ("},{"type":"text","text":".c","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Function prototypes"}],[{"type":"text","text":"Function definitions"}]],[[{"type":"text","text":"extern","marks":[{"type":"code"}]},{"type":"text","text":" variable declarations"}],[{"type":"text","text":"The one definition of each global"}]],[[{"type":"text","text":"Type definitions ("},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typedef","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" helper functions and file-private globals"}]],[[{"type":"text","text":"Macros and "},{"type":"text","text":"static inline","marks":[{"type":"code"}]},{"type":"text","text":" helpers"}],[{"type":"text","text":"#include","marks":[{"type":"code"}]},{"type":"text","text":" of its own header first"}]],[[{"type":"text","text":"Include guard / "},{"type":"text","text":"#pragma once","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}]]]},"revision":1},{"id":"61f8281f-212a-73fc-9a50-b9f63867e3ee","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never "},{"type":"text","text":"define","marks":[{"type":"italic"}]},{"type":"text","text":" a non-"},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" variable or function in a header ("},{"type":"text","text":"int count = 0;","marks":[{"type":"code"}]},{"type":"text","text":"). Every "},{"type":"text","text":".c","marks":[{"type":"code"}]},{"type":"text","text":" file that includes it gets its own definition, and the linker fails with “duplicate symbol” / “multiple definition”."}]}]}},"revision":1},{"id":"3ca65eea-acde-749f-892b-a92d2031ce55","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"A minimal Makefile"}]},"revision":1},{"id":"e45c39ed-60dc-729c-bf92-e1aaeea69500","type":"code","position":"aB","content":{"language":"","code":"CC      = gcc\nCFLAGS  = -std=c17 -Wall -Wextra -O2\nOBJS    = main.o mathx.o\n\napp: $(OBJS)\n\t$(CC) $(CFLAGS) $(OBJS) -o $@\n\n%.o: %.c mathx.h\n\t$(CC) $(CFLAGS) -c $< -o $@\n\nclean:\n\trm -f $(OBJS) app","filename":"Makefile"},"revision":1},{"id":"98f676c0-4b06-723f-9c68-2a4976042699","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Make recompiles only the files whose sources (or headers) changed. Larger projects use CMake or Meson to generate the build."}]}]}},"revision":1},{"id":"66801cf9-693b-7013-9b7c-08239557c5f4","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an include guard and why is it needed?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"#ifndef X_H / #define X_H / … / #endif","marks":[{"type":"code"}]},{"type":"text","text":" around a header’s content. If the header is included twice in one translation unit (directly or via other headers), the second copy expands to nothing, avoiding redefinition errors for types and macros. "},{"type":"text","text":"#pragma once","marks":[{"type":"code"}]},{"type":"text","text":" does the same and is supported by all major compilers, though non-standard."}]}]}},"revision":1},{"id":"61570995-f3f8-713c-8ddb-f92a33cd525c","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why separate declarations and definitions into .h and .c files?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It gives each module a public interface and a private implementation, allows separate compilation (only changed files are recompiled), lets many files share one set of declarations so the compiler checks every call, and keeps exactly one definition of each symbol for the linker."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
