INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'f61a774d-84c6-7ba0-a1c5-14d119297221', '9a3bbf7a-5659-7241-b622-dd66ca5628b5', 1, 'PUBLISHED', 'Operators & Precedence', '[{"id":"2150025c-91aa-7630-a3b4-a1428aecce4e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C’s operators are compact and powerful. Most bugs come from precedence surprises, integer division, and unsequenced side effects — use parentheses generously."}]}]}},"revision":1},{"id":"dac0ec27-b4c9-7a48-a2a8-bb5d8b3625c3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Arithmetic"}]},"revision":1},{"id":"5b1897c2-c350-799e-aeaf-ede6ed3437f9","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    printf(\"%d %d %d %d\\n\", 17 / 5, 17 % 5, -17 / 5, -17 % 5);   /* truncates toward 0 */\n    printf(\"%.2f\\n\", 17 / 5.0);                                   /* one double → real division */\n    int i = 5;\n    int a = i++;      /* a = 5, then i = 6 */\n    int b = ++i;      /* i = 7, then b = 7 */\n    printf(\"a=%d b=%d i=%d\\n\", a, b, i);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"e29c58c0-dce8-757c-a366-84b14320cd54","type":"code","position":"a3","content":{"language":"text","code":"3 2 -3 -2\n3.40\na=5 b=7 i=7","filename":"Output"},"revision":1},{"id":"5997fd70-3366-737c-a67f-232fb248e3a6","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Integer "},{"type":"text","text":"/","marks":[{"type":"code"}]},{"type":"text","text":" truncates toward zero (since C99) and "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" takes the sign of the left operand, so "},{"type":"text","text":"(a / b) * b + a % b == a","marks":[{"type":"code"}]},{"type":"text","text":" always holds."}]}]}},"revision":1},{"id":"d21a3e4e-8a10-7893-9bc5-ef0fc346d7a9","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Relational, logical and short-circuit"}]},"revision":1},{"id":"5edf5b35-55a4-7f81-a444-bfe8ade6c90b","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n\nint calls = 0;\nint check(int v) { calls++; return v; }\n\nint main(void) {\n    printf(\"%d %d %d\\n\", 3 > 2, 3 == 2, !5);      /* results are int 1 or 0 */\n    if (check(0) && check(1)) { }                 /* right side skipped */\n    if (check(1) || check(1)) { }                 /* right side skipped */\n    printf(\"calls = %d\\n\", calls);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"c086dcaf-36c2-7c50-ab34-cc61535d9e8b","type":"code","position":"a7","content":{"language":"text","code":"1 0 0\ncalls = 2","filename":"Output"},"revision":1},{"id":"5d5e97eb-6ef7-7077-8fd6-9b85888469e7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Assignment, comma, ternary, sizeof"}]},"revision":1},{"id":"08cb9051-fae8-76cc-a596-53f63027265c","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int x = 10;\n    x += 5; x *= 2; x -= 6; x /= 4; x %= 4;\n    printf(\"x = %d\\n\", x);\n\n    int a, b;\n    a = b = 7;                          /* assignment is an expression, right-assoc */\n    int max = (a > 3) ? a : 3;          /* conditional operator */\n    int last = (a++, b++, a + b);       /* comma: evaluate left, yield right */\n    printf(\"%d %d %d %d\\n\", a, b, max, last);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"49c30310-2dd9-7315-8eb1-0d2e07c0f674","type":"code","position":"aA","content":{"language":"text","code":"x = 2\n8 8 7 16","filename":"Output"},"revision":1},{"id":"6d768fea-c609-759b-819f-a5510b6ededc","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Precedence table (high → low)"}]},"revision":1},{"id":"b03fa5e8-39c1-7a88-a