INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '33414f3b-4e63-721a-98d0-2220640fcc8e', '8f9a761a-af8e-70a4-bcea-8f4297847a93', 1, 'PUBLISHED', 'Padding & Alignment', '[{"id":"a9bc50af-c3a0-7239-ba4c-22ab87e64d46","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CPUs load data fastest (or only) at addresses that are multiples of its size. The compiler therefore inserts invisible "},{"type":"text","text":"padding","marks":[{"type":"bold"}]},{"type":"text","text":" bytes into structs, so "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" is often larger than the sum of the members."}]}]}},"revision":1},{"id":"0513dc13-d3a1-77d6-8f92-51984750553f","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stddef.h>\n\nstruct Bad  { char a; int b; char c; };      /* 1 + 3 pad + 4 + 1 + 3 pad */\nstruct Good { int b; char a; char c; };      /* 4 + 1 + 1 + 2 pad */\n\nint main(void) {\n    printf(\"Bad  = %zu bytes\\n\", sizeof(struct Bad));\n    printf(\"Good = %zu bytes\\n\", sizeof(struct Good));\n    printf(\"offsets in Bad: a=%zu b=%zu c=%zu\\n\",\n           offsetof(struct Bad, a), offsetof(struct Bad, b), offsetof(struct Bad, c));\n    printf(\"alignof(int)=%zu alignof(double)=%zu\\n\", _Alignof(int), _Alignof(double));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"4d8fa975-aacc-79e9-87f7-388a33106788","type":"code","position":"a2","content":{"language":"text","code":"Bad  = 12 bytes\nGood = 8 bytes\noffsets in Bad: a=0 b=4 c=8\nalignof(int)=4 alignof(double)=8","filename":"Output"},"revision":1},{"id":"d701cb9c-52b7-7a02-b987-22e0fa7fb5aa","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"The rules"}]},"revision":1},{"id":"156f59ee-e564-794e-979b-ebd3cc5cbf0f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each member is aligned","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A member of type "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" starts at an offset that is a multiple of "},{"type":"text","text":"_Alignof(T)","marks":[{"type":"code"}]},{"type":"text","text":" — padding is inserted before it if needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The struct is aligned","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The struct’s alignment is the largest alignment of any member."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tail padding","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" is rounded up to a multiple of the struct’s alignment, so that in an array every element is aligned too."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Order is kept","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The compiler never reorders members — the first member is always at offset 0."}]}]}]}]}},"revision":1},{"id":"2ec36001-fdec-7e0a-b005-8b8c2a043e8f","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Offset"}],[{"type":"text","text":"0"}],[{"type":"text","text":"1"}],[{"type":"text","text":"2"}],[{"type":"text","text":"3"}],[{"type":"text","text":"4–7"}],[{"type":"text","text":"8"}],[{"type":"text","text":"9–11"}]],[[{"type":"text","text":"struct Bad","marks":[{"type":"code"}]}],[{"type":"text","text":"a","marks":[{"type":"code"}]}],[{"type":"text","text":"pad"}],[{"type":"text","text":"pad"}],[{"type":"text","text":"pad"}],[{"type":"text","text":"b","marks":[{"type":"code"}]}],[{"type":"text","text":"c","marks":[{"type":"code"}]}],[{"type":"text","text":"pad"}]]]},"revision":1},{"id":"d157f904-3f6b-79ef-8d1c-c3cf6f9f87e3","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Minimising padding"}]},"revision":1},{"id":"9a78b9b6-453c-7a2c-b8fc-185b5b65458f","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n\nstruct Messy  { char c1; double d; char c2; int i; short s; };\nstruct Sorted { double d; int i; short s; char c1; char c2; };   /* largest first */\n\nint main(void) {\n    printf(\"%zu %zu\\n\", sizeof(struct Messy), sizeof(struct Sorted));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"91c55181-bf2a-7663-8ad9-83bd43edd8fd","type":"code","position":"a8","content":{"language":"text","code":"32 16","filename":"Output"},"revision":1},{"id":"64600b5c-f866-7f11-ac85-795abb3ebc23","type":"callout","position":"a9","content":{"variant":"note","title":"Tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Order members from largest to smallest alignment. With arrays of millions of structs this halves memory use and improves cache behaviour."}]}]}},"revision":1},{"id":"b1f1adc6-27dc-7e57-88b7-87d0285c7ab2","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Packing (compiler extension)"}]},"revision":1},{"id":"df6d35f3-bb7b-7731-bb48-1bfb2e204b57","type":"code","position":"aB","content":{"language":"c","code":"#include <stdio.h>\n#include <stdint.h>\n\nstruct __attribute__((packed)) Header {     /* GCC/Clang; MSVC uses #pragma pack(1) */\n    uint8_t  type;\n    uint32_t length;\n    uint16_t flags;\n};\n\nint main(void) {\n    printf(\"packed size = %zu\\n\", sizeof(struct Header));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"4a878603-42f5-795b-80ba-888510ab03bb","type":"code","position":"aC","content":{"language":"text","code":"packed size = 7","filename":"Output"},"revision":1},{"id":"8e221fa7-d532-7e02-9daa-8be838e18131","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Packed structs cause misaligned accesses — slower on x86, and a crash on some ARM/RISC CPUs if you take a pointer to a member. For file and network formats prefer reading bytes and assembling fields with shifts or "},{"type":"text","text":"memcpy","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f9b27edd-580c-749e-854f-6b1f3073f437","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Explicit alignment (C11)"}]},"revision":1},{"id":"b14e7bfa-a4a0-70ce-912d-d48eee536a1d","type":"code","position":"aF","content":{"language":"c","code":"#include <stdio.h>\n#include <stdalign.h>\n#include <stdint.h>\n\nstruct Cacheline { alignas(64) char data[64]; };   /* avoid false sharing between threads */\n\nint main(void) {\n    alignas(16) float v[4] = {0};\n    printf(\"%zu %zu %d\\n\", alignof(struct Cacheline), sizeof(struct Cacheline),\n           (int)((uintptr_t)v % 16 == 0));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"dee1c75d-e093-7900-8be3-fc9bef72e737","type":"code","position":"aG","content":{"language":"text","code":"64 64 1","filename":"Output"},"revision":1},{"id":"779ab8c6-5b2b-7d57-9c26-7a195a271bc5","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is structure padding and why does it exist?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unused bytes the compiler inserts between (and after) struct members so that each member sits at an address that is a multiple of its alignment. Aligned loads/stores are a single fast instruction; misaligned ones are slower or fault on some architectures."}]}]}},"revision":1},{"id":"73f7ba04-acc7-71d3-bd35-19ea5b6e7a9b","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is sizeof(struct { char c; double d; })?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"16 on typical 64-bit platforms: "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" at offset 0, 7 bytes of padding, "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" at offset 8 (aligned to 8), total 16. Reversing the members gives 9 bytes of data rounded up to 16 as well (tail padding)."}]}]}},"revision":1},{"id":"fd049700-e4fc-72aa-a71b-7482cf7b9309","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the offset of a member?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"offsetof(type, member)","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"<stddef.h>","marks":[{"type":"code"}]},{"type":"text","text":". It is used for serialisation, for generic containers and in the Linux kernel’s "},{"type":"text","text":"container_of","marks":[{"type":"code"}]},{"type":"text","text":" macro to get from a member pointer back to the enclosing struct."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
