SELECT '0b501bc4-2eea-7b1b-8a10-c57c4fd90c97', '5f62a83d-0e6c-7a10-9b3b-981394ed51fb', 1, 'PUBLISHED', 'Pointer Arithmetic', '[{"id":"11a108cf-3272-78fa-9afe-a99042ff7f78","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" to a pointer moves it by "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"elements","marks":[{"type":"italic"}]},{"type":"text","text":", not bytes: "},{"type":"text","text":"p + 1","marks":[{"type":"code"}]},{"type":"text","text":" advances by "},{"type":"text","text":"sizeof *p","marks":[{"type":"code"}]},{"type":"text","text":". Arithmetic is only valid within one array (plus one-past-the-end)."}]}]}},"revision":1},{"id":"c08f44dc-24df-7d73-8b3e-f4c8609b5c16","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[] = {10, 20, 30, 40};\n    int *p = a;                  /* &a[0] */\n    char *c = (char *)a;\n\n    printf(\"%d %d %d\\n\", *p, *(p + 1), *(p + 3));\n    printf(\"int step  = %td bytes\\n\", (char *)(p + 1) - (char *)p);\n    printf(\"char step = %td bytes\\n\", (c + 1) - c);\n\n    int *end = a + 4;            /* one past the end: may be compared, never dereferenced */\n    printf(\"elements between = %td\\n\", end - p);\n    for (int *q = a; q < end; q++) printf(\"%d \", *q);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"7ae861b4-3a5f-7aea-bf2b-1bf867c8b4bb","type":"code","position":"a2","content":{"language":"text","code":"10 20 40\nint step  = 4 bytes\nchar step = 1 bytes\nelements between = 4\n10 20 30 40","filename":"Output"},"revision":1},{"id":"ab8e0269-6b3d-7a92-94f7-558cc46f6f57","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"What is allowed"}]},"revision":1},{"id":"8df4d033-ae21-