#include <stdio.h>

int main(void) {
    int x = 5;
    int *p = &x;
    int **pp = &p;
    **pp = 50;                         /* x = 50 */
    printf("%d %d %d\n", x, *p, **pp);
    printf("%d %d\n", *pp == p, p == &x);
    return 0;
}
