SELECT 'c7c2e1fd-5fd9-7d05-bd60-a4a22e31c95e', 'fe7a8add-8fd9-7d3a-af99-634845df2caf', 1, 'PUBLISHED', 'Pointers & Arrays', '[{"id":"b106f56e-e16f-7603-9fe0-d9401c597690","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays and pointers are closely related but "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" the same thing: an array "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" storage; a pointer "},{"type":"text","text":"refers to","marks":[{"type":"italic"}]},{"type":"text","text":" storage. The link is decay — an array name converts to a pointer to its first element."}]},{"type":"paragraph","content":[{"type":"text","text":"a[i] ≡ *(a + i) ≡ *(i + a) ≡ i[a]","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"3d18b5c2-6f46-7c16-b8df-f66c495dca9a","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    int a[4] = {1, 2, 3, 4};\n    int *p = a;                      /* decay: p = &a[0] */\n\n    printf(\"%d %d %d %d\\n\", a[2], *(a + 2), p[2], 2[a]);   /* all the same */\n    printf(\"sizeof a = %zu, sizeof p = %zu\\n\", sizeof a, sizeof p);\n\n    p++;                             /* a pointer can move... */\n    printf(\"*p = %d\\n\", *p);\n    /* a++;  ...an array cannot: error, array type is not assignable */\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b7f8a7b4-2814-78e6-830f-c6a844fb0ef1","type":"code","position":"a2","content":{"language":"text","code":"3 3 3 3\nsizeof a = 16, sizeof p = 8\n*p = 2","filename":"Output"},"revision":1},{"id":"8295a667-77e5-71de-85b2-e1e13bf0bb8d","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Array "},{"type":"text","text":"int a[4]","marks":[{"type":"code"}]}],[{"type":"text","text":"Pointer "},{"type":"text","text":"int *p","marks":[{"type":"code"}]}]],[[{"type":"text