SELECT '01031d69-a75d-7abb-83e2-34627893a7c5', '2e7ff878-970b-7f5c-931d-494d29fad2bf', 1, 'PUBLISHED', 'Preprocessor & Macros', '[{"id":"c610963b-2865-78cb-bd9e-1839078850ae","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before compilation, the preprocessor rewrites the source text: it pastes in headers, expands macros and keeps or drops code with conditionals. It knows nothing about C types or scope."}]}]}},"revision":1},{"id":"d66855e7-2ed3-75cb-87ad-db450c58f79c","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Directive"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"#include <x.h>","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"\"x.h\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Paste a file (angle brackets: system paths; quotes: current dir first)"}]],[[{"type":"text","text":"#define NAME value","marks":[{"type":"code"}]}],[{"type":"text","text":"Object-like macro"}]],[[{"type":"text","text":"#define F(a, b) (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Function-like macro"}]],[[{"type":"text","text":"#undef NAME","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove a definition"}]],[[{"type":"text","text":"#if","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#elif","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#else","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#endif","marks":[{"type":"code"}]}],[{"type":"text","text":"Conditional compilation on constant expressions"}]],[[{"type":"text","text":"#ifdef","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#ifndef","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"defined(X)","marks":[{"type":"code"}]}],[{"type":"text","text":"Is a macro defined?"}]],[[{"type":"text","text":"#error \"msg\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Stop compilation with a message"}]],[[{"type":"text","text":"#pragma","marks":[{"type":"code"}]}],[{"type":"text","text":"Implementation-specific ("},{"type":"text","text":"#pragma once","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"#pragma pack","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"#line","marks":[{"type":"code"}]}],[{"type":"text","text":"Change reported line numbers (used by code generators)"}]]]},"revision":1},{"id":"30c8b5cc-4190-79f1-9ea5-8a177f3c7b5a","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Macros and their pitfalls"}]},"revision":1},{"id":"b2062406-83d1-7387-88c3-35b541a11219","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n\n#define SQUARE_BAD(x) x * x\n#define SQUARE(x) ((x) * (x))            /* parenthesise every argument AND the whole body */\n#define MAX(a, b) ((a) > (b) ? (a) : (b))\n\nint main(void) {\n    printf(\"%d\\n\", SQUARE_BAD(2 + 3));   /* 2 + 3 * 2 + 3 = 11 */\n    printf(\"%d\\n\", SQUARE(2 + 3));       /* 25 */\n    printf(\"%d\\n\", 100 / SQUARE(5));     /* 4 — without outer parens: 100 / 5 * 5 = 100 */\n\n    int i = 5, j = 3;\n    int m = MAX(i++, j);                 /* i++ is evaluated TWICE */\n    printf(\"m = %d, i = %d\\n\", m, i);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"1ab47c69-5848-73ca-b986-d971e443889b","type":"code","position":"a4","content":{"language":"text","code":"11\n25\n4\nm = 6, i = 7","filename":"Output"},"revision":1},{"id":"ca4e5155-4a8e-761d-a5ef-4960579ce44e","type":"callout","position":"a5","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Function-like macros evaluate arguments as many times as they appear. Never pass expressions with side effects ("},{"type":"text","text":"i++","marks":[{"type":"code"}]},{"type":"text","text":", function calls). Prefer "},{"type":"text","text":"static inline","marks":[{"type":"code"}]},{"type":"text","text":" functions — they are type-checked and evaluate arguments once."}]}]}},"revision":1},{"id":"82e27520-5c2d-7da6-be8a-c460dc4afdeb","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Multi-statement macros: do { } while (0)"}]},"revision":1},{"id":"3014bfe4-1cda-7684-bf76-073fa79d5bfb","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n\n#define SWAP(a, b) do { int tmp_ = (a); (a) = (b); (b) = tmp_; } while (0)\n\nint main(void) {\n    int x = 1, y = 2;\n    if (x < y)\n        SWAP(x, y);        /* expands to ONE statement, so the else still pairs correctly */\n    else\n        printf(\"no swap\\n\");\n    printf(\"%d %d\\n\", x, y);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"03a09789-7b1a-78f5-bb49-e687c1a7499e","type":"code","position":"a8","content":{"language":"text","code":"2 1","filename":"Output"},"revision":1},{"id":"4da18f50-2f50-7611-bca3-f91cf8ec6cc4","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Stringising #, token pasting ##, predefined macros"}]},"revision":1},{"id":"f89d70a4-2ae0-7267-b158-205ceb3aa9b4","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n\n#define STR(x) #x\n#define XSTR(x) STR(x)                    /* expand first, then stringise */\n#define VERSION 3\n#define DEBUG_PRINT(var) printf(#var \" = %d\\n\", var)\n#define MAKE_GETTER(field) int get_##field(void) { return field; }\n\nint width = 80;\nMAKE_GETTER(width)                        /* defines int get_width(void) */\n\nint main(void) {\n    int count = 42;\n    DEBUG_PRINT(count);\n    printf(\"%s %s\\n\", STR(VERSION), XSTR(VERSION));\n    printf(\"%d\\n\", get_width());\n    printf(\"line %d of %s, C standard %ld\\n\", __LINE__, __func__, __STDC_VERSION__);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"64d72d29-8766-7ec2-8084-c716c3551daf","type":"code","position":"aB","content":{"language":"text","code":"count = 42\nVERSION 3\n80\nline 17 of main, C standard 201710","filename":"Output"},"revision":1},{"id":"95a08ede-144a-77aa-b5a3-faac9be13edb","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Macro"}],[{"type":"text","text":"Value"}]],[[{"type":"text","text":"__FILE__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__LINE__","marks":[{"type":"code"}]}],[{"type":"text","text":"Current file name and line"}]],[[{"type":"text","text":"__func__","marks":[{"type":"code"}]}],[{"type":"text","text":"Current function name (a predefined identifier, not a macro)"}]],[[{"type":"text","text":"__DATE__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__TIME__","marks":[{"type":"code"}]}],[{"type":"text","text":"Compilation date and time"}]],[[{"type":"text","text":"__STDC_VERSION__","marks":[{"type":"code"}]}],[{"type":"text","text":"199901L","marks":[{"type":"code"}]},{"type":"text","text":" (C99), "},{"type":"text","text":"201112L","marks":[{"type":"code"}]},{"type":"text","text":" (C11), "},{"type":"text","text":"201710L","marks":[{"type":"code"}]},{"type":"text","text":" (C17), "},{"type":"text","text":"202311L","marks":[{"type":"code"}]},{"type":"text","text":" (C23)"}]],[[{"type":"text","text":"__GNUC__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__clang__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_WIN32","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__linux__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__APPLE__","marks":[{"type":"code"}]}],[{"type":"text","text":"Compiler / platform detection"}]]]},"revision":1},{"id":"7c21708b-54cd-77f7-adc8-d1816be7b016","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Conditional compilation"}]},"revision":1},{"id":"dc4c4014-a771-7936-b44d-153f083ba946","type":"code","position":"aE","content":{"language":"c","code":"#include <stdio.h>\n\n#define LOG_LEVEL 2\n\n#ifndef BUFFER_SIZE\n#define BUFFER_SIZE 256                   /* default unless -DBUFFER_SIZE=... is passed */\n#endif\n\n#if LOG_LEVEL >= 2\n#define LOG(msg) printf(\"[debug] %s\\n\", msg)\n#else\n#define LOG(msg) ((void)0)\n#endif\n\nint main(void) {\n    LOG(\"starting\");\n#if defined(__APPLE__)\n    printf(\"macOS build, buffer %d\\n\", BUFFER_SIZE);\n#elif defined(__linux__)\n    printf(\"Linux build, buffer %d\\n\", BUFFER_SIZE);\n#else\n    printf(\"other build, buffer %d\\n\", BUFFER_SIZE);\n#endif\n    return 0;\n}","filename":"C — compiled on macOS with -DBUFFER_SIZE=1024"},"revision":1},{"id":"3fb88f6e-2733-7f20-ba4c-173c0486b19f","type":"code","position":"aF","content":{"language":"text","code":"[debug] starting\nmacOS build, buffer 1024","filename":"Output"},"revision":1},{"id":"10695ace-d10d-7265-8a80-2535878dbb54","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n#include <assert.h>\n\nint main(void) {\n    int balance = 10;\n    assert(balance >= 0);           /* active unless NDEBUG is defined */\n    balance -= 25;\n    assert(balance >= 0 && \"balance went negative\");\n    printf(\"unreachable\\n\");\n    return 0;\n}","filename":"C — assert aborts the program when the condition is false"},"revision":1},{"id":"b44e2d54-dd51-7eb2-872d-f7f65d8b1d2b","type":"code","position":"aH","content":{"language":"text","code":"Assertion failed: (balance >= 0 && \"balance went negative\"), function main, file main.c, line 8.","filename":"stderr"},"revision":1},{"id":"b0231dac-b7a3-7a37-8541-2b18b22d71c9","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a macro and an inline function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A macro is textual substitution before compilation: no type checking, arguments may be evaluated several times, no scope, hard to debug. An "},{"type":"text","text":"inline","marks":[{"type":"code"}]},{"type":"text","text":" function is a real function the compiler may expand in place: arguments are evaluated once and type-checked, and it follows normal scope rules. Macros are still needed for stringising, token pasting, conditional compilation and type-generic tricks."}]}]}},"revision":1},{"id":"3e57bd02-156d-741f-b48c-cad362dbc414","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why wrap a multi-statement macro in do { ... } while (0)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It turns the macro into a single statement that requires a trailing semicolon, so it works correctly as the body of an unbraced "},{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":". A bare "},{"type":"text","text":"{ … }","marks":[{"type":"code"}]},{"type":"text","text":" block followed by "},{"type":"text","text":";","marks":[{"type":"code"}]},{"type":"text","text":" would break an "},{"type":"text","text":"if … else","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"467b0672-0697-76b8-a0e5-4b6336bc0e6a","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does #include <file> vs #include \"file\" do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both paste the file’s contents. "},{"type":"text","text":"\"file\"","marks":[{"type":"code"}]},{"type":"text","text":" searches the directory of the current file first, then the system paths; "},{"type":"text","text":"<file>","marks":[{"type":"code"}]},{"type":"text","text":" searches only the system/"},{"type":"text","text":"-I","marks":[{"type":"code"}]},{"type":"text","text":" paths. Use quotes for your own headers."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
