SELECT '32715708-a20b-7015-9c65-8f14a2b86f0b', '8c7a0848-9966-728b-a621-afdbb0a86dc0', 1, 'PUBLISHED', 'Program Structure & main', '[{"id":"cf3b708d-4ed5-7e80-9cb3-b71e9f52e8a7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A C program is a set of declarations and function definitions; execution starts at "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":", and its return value becomes the process exit status."}]}]}},"revision":1},{"id":"f3bdf5dc-6c37-70f8-bc94-5c4201860745","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Anatomy of a program"}]},"revision":1},{"id":"ccb587e7-392f-7f93-8b99-492fcfa51c5e","type":"code","position":"a2","content":{"language":"c","code":"/* 1. Preprocessor directives */\n#include <stdio.h>\n#define GREETING \"Hi\"\n\n/* 2. Global declarations */\nstatic int counter = 0;\n\n/* 3. Function prototype (declaration) */\nint square(int x);\n\n/* 4. main: the entry point */\nint main(void) {\n    counter++;\n    printf(\"%s! square(7) = %d, counter = %d\\n\", GREETING, square(7), counter);\n    return 0;                /* 0 = success */\n}\n\n/* 5. Function definitions */\nint square(int x) {\n    return x * x;\n}","filename":"C"},"revision":1},{"id":"f9942ce6-f4a6-700a-b673-9d4e7803afef","type":"code","position":"a3","content":{"language":"text","code":"Hi! square(7) = 49, counter = 1","filename":"Output"},"revision":1},{"id":"aee90e9a-96c1-78cd-a511-5e72100b152e","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Valid signatures of main"}]},"revision":1},{"id":"cdb0035d-8735-7b82-89c4-9b36f13adc25","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Signature"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"int main(void)","marks":[{"type":"code"}]}],[{"type":"text","text":"No command-line arguments."}]