/* 4. main: the entry point */
int main(void) {
    counter++;
    printf("%s! square(7) = %d, counter = %d\n", GREETING, square(7), counter);
    return 0;                /* 0 = success */
}

/* 5. Function definitions */
int square(int x) {
    return x * x;
}
Hi! square(7) = 49, counter = 1
