How the call stack unwinds
#include <stdio.h>

void count(int n, int depth) {
    if (n == 0) { printf("%*sbase\n", depth * 2, ""); return; }
    printf("%*senter %d\n", depth * 2, "", n);
    count(n - 1, depth + 1);
    printf("%*sleave %d\n", depth * 2, "", n);
}

int main(void) {
    count(3, 0);
    return 0;
}
