SELECT 'c4c718c5-c90a-71b9-a6e8-657ed9a55ada', '3afd26fb-b9b9-7819-9104-48ef51f4d22a', 1, 'PUBLISHED', 'Sorting & Searching', '[{"id":"8aa736db-d060-74d4-9027-183bfae4dda2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The classic algorithms, implemented on plain "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" arrays. Know their complexity, stability and when to reach for the library’s "},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"bsearch","marks":[{"type":"code"}]},{"type":"text","text":" instead."}]}]}},"revision":1},{"id":"8f69db98-7253-7737-b51c-afb06c2f9a19","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Algorithm"}],[{"type":"text","text":"Best"}],[{"type":"text","text":"Average"}],[{"type":"text","text":"Worst"}],[{"type":"text","text":"Space"}],[{"type":"text","text":"Stable?"}]],[[{"type":"text","text":"Bubble sort"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Selection sort"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Insertion sort"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Merge sort"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Quick sort"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Heap sort"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Counting sort"}],[{"type":"text","text":"O(n + k)"}],[{"type":"text","text":"O(n + k)"}],[{"type":"text","text":"O(n + k)"}],[{"type":"text","text":"O(k)"}],[{"type":"text","text":"Yes"}]]]},"revision":1},{"id":"91297447-a9a0-75f1-a215-3fbc6e5647a6","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Simple O(n²) sorts"}]},"revision":1},{"id":"9225af14-a1c4-7f56-bf3e-16101d5d76cc","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n#include <stdbool.h>\n\nvoid swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }\n\nvoid bubble_sort(int *a, int n) {\n    for (int i = 0; i < n - 1; i++) {\n        bool swapped = false;\n        for (int j = 0; j < n - 1 - i; j++)\n            if (a[j] > a[j + 1]) { swap(&a[j], &a[j + 1]); swapped = true; }\n        if (!swapped) break;                 /* already sorted: O(n) best case */\n    }\n}\n\nvoid selection_sort(int *a, int n) {\n    for (int i = 0; i < n - 1; i++) {\n        int min = i;\n        for (int j = i + 1; j < n; j++) if (a[j] < a[min]) min = j;\n        swap(&a[i], &a[min]);\n    }\n}\n\nvoid insertion_sort(int *a, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = a[i], j = i - 1;\n        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }\n        a[j + 1] = key;\n    }\n}\n\nvoid print(const int *a, int n) { for (int i = 0; i < n; i++) printf(\"%d \", a[i]); printf(\"\\n\"); }\n\nint main(void) {\n    int a[] = {5, 2, 9, 1, 5, 6}, b[] = {5, 2, 9, 1, 5, 6}, c[] = {5, 2, 9, 1, 5, 6};\n    bubble_sort(a, 6); print(a, 6);\n    selection_sort(b, 6); print(b, 6);\n    insertion_sort(c, 6); print(c, 6);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"c10afbcf-8311-7827-97c8-b1c0dc116935","type":"code","position":"a4","content":{"language":"text","code":"1 2 5 5 6 9\n1 2 5 5 6 9\n1 2 5 5 6 9","filename":"Output"},"revision":1},{"id":"d1ef99a4-5d86-7a9b-a99c-2c25785d244e","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Merge sort and quick sort"}]},"revision":1},{"id":"92b4d719-6531-7dc7-968a-752912f54d3a","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstatic void merge(int *a, int *tmp, int lo, int mid, int hi) {\n    int i = lo, j = mid, k = lo;\n    while (i < mid && j < hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];   /* <= keeps it stable */\n    while (i < mid) tmp[k++] = a[i++];\n    while (j < hi)  tmp[k++] = a[j++];\n    memcpy(a + lo, tmp + lo, (size_t)(hi - lo) * sizeof *a);\n}\n\nstatic void msort(int *a, int *tmp, int lo, int hi) {     /* sorts a[lo, hi) */\n    if (hi - lo < 2) return;\n    int mid = lo + (hi - lo) / 2;\n    msort(a, tmp, lo, mid);\n    msort(a, tmp, mid, hi);\n    merge(a, tmp, lo, mid, hi);\n}\n\nvoid merge_sort(int *a, int n) {\n    int *tmp = malloc((size_t)n * sizeof *tmp);\n    if (!tmp) return;\n    msort(a, tmp, 0, n);\n    free(tmp);\n}\n\nvoid quick_sort(int *a, int lo, int hi) {                 /* Lomuto partition, a[lo..hi] */\n    if (lo >= hi) return;\n    int pivot = a[hi], i = lo;\n    for (int j = lo; j < hi; j++)\n        if (a[j] < pivot) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; }\n    int t = a[i]; a[i] = a[hi]; a[hi] = t;                /* pivot to its final place */\n    quick_sort(a, lo, i - 1);\n    quick_sort(a, i + 1, hi);\n}\n\nint main(void) {\n    int a[] = {38, 27, 43, 3, 9, 82, 10}, b[] = {38, 27, 43, 3, 9, 82, 10};\n    merge_sort(a, 7);\n    quick_sort(b, 0, 6);\n    for (int i = 0; i < 7; i++) printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    for (int i = 0; i < 7; i++) printf(\"%d \", b[i]);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"fc7f6982-c5d2-75ad-b3f4-67c2981e2f7a","type":"code","position":"a7","content":{"language":"text","code":"3 9 10 27 38 43 82\n3 9 10 27 38 43 82","filename":"Output"},"revision":1},{"id":"7a1e10b4-dca2-770b-9d77-144edf8946dd","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Binary search"}]},"revision":1},{"id":"b2a54ace-4657-7b47-996f-2fca045889cc","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n\nint binary_search(const int *a, int n, int key) {\n    int lo = 0, hi = n - 1;\n    while (lo <= hi) {\n        int mid = lo + (hi - lo) / 2;     /* not (lo + hi) / 2: that can overflow */\n        if (a[mid] == key) return mid;\n        if (a[mid] < key) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    return -1;\n}\n\nint lower_bound(const int *a, int n, int key) {   /* first index with a[i] >= key */\n    int lo = 0, hi = n;\n    while (lo < hi) {\n        int mid = lo + (hi - lo) / 2;\n        if (a[mid] < key) lo = mid + 1; else hi = mid;\n    }\n    return lo;\n}\n\nint main(void) {\n    int a[] = {2, 5, 8, 8, 8, 13, 21};\n    printf(\"%d %d\\n\", binary_search(a, 7, 13), binary_search(a, 7, 4));\n    printf(\"first 8 at %d, insert 9 at %d\\n\", lower_bound(a, 7, 8), lower_bound(a, 7, 9));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"ab7a537b-4922-7cdf-a66a-f336f41f69e3","type":"code","position":"aA","content":{"language":"text","code":"5 -1\nfirst 8 at 2, insert 9 at 5","filename":"Output"},"revision":1},{"id":"8b460cc6-9428-7a6d-84e9-b90c4c3acb99","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In production C, use "},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":" (see Function Pointers) and "},{"type":"text","text":"bsearch","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"<stdlib.h>","marks":[{"type":"code"}]},{"type":"text","text":". Write your own when you need stability (merge sort), a specialised key, or an interview asks for it."}]}]}},"revision":1},{"id":"563c17d5-ead4-7b48-9c8b-5149afc9d8a4","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is quicksort usually faster than merge sort in practice even though its worst case is O(n²)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It sorts in place with a tight inner loop and excellent cache locality, and choosing the pivot randomly or by median-of-three makes the O(n²) case vanishingly unlikely. Merge sort needs O(n) extra memory and more data movement. Library sorts (introsort) switch to heap sort if recursion gets too deep, guaranteeing O(n log n)."}]}]}},"revision":1},{"id":"83b5a9b4-f9c2-7cd3-82fd-059af9cb1a5b","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does it mean for a sort to be stable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Elements with equal keys keep their original relative order. It matters when sorting records by one field after another (e.g. by name, then stably by department). Merge, insertion and bubble sort are stable; quick, heap and selection sort are not. "},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":" is not guaranteed stable."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
