  ('9225af14-a1c4-7f56-bf3e-16101d5d76cc', 'a3', 'code', '{"language":"c","code":"#include <stdio.h>\n#include <stdbool.h>\n\nvoid swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }\n\nvoid bubble_sort(int *a, int n) {\n    for (int i = 0; i < n - 1; i++) {\n        bool swapped = false;\n        for (int j = 0; j < n - 1 - i; j++)\n            if (a[j] > a[j + 1]) { swap(&a[j], &a[j + 1]); swapped = true; }\n        if (!swapped) break;                 /* already sorted: O(n) best case */\n    }\n}\n\nvoid selection_sort(int *a, int n) {\n    for (int i = 0; i < n - 1; i++) {\n        int min = i;\n        for (int j = i + 1; j < n; j++) if (a[j] < a[min]) min = j;\n        swap(&a[i], &a[min]);\n    }\n}\n\nvoid insertion_sort(int *a, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = a[i], j = i - 1;\n        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }\n        a[j + 1] = key;\n    }\n}\n\nvoid print(const int *a, int n) { for (int i = 0; i < n; i++) printf(\"%d \", a[i]); printf(\"\\n\"); }\n\nint main(void) {\n    int a[] = {5, 2, 9, 1, 5, 6}, b[] = {5, 2, 9, 1, 5, 6}, c[] = {5, 2, 9, 1, 5, 6};\n    bubble_sort(a, 6); print(a, 6);\n    selection_sort(b, 6); print(b, 6);\n    insertion_sort(c, 6); print(c, 6);\n    return 0;\n}","filename":"C"}'),
