SELECT 'd367cd42-913f-7266-842f-cf975d51867c', '8054ab12-716e-7047-93aa-db864725e7c9', 1, 'PUBLISHED', 'Storage Classes: auto, static, extern, register', '[{"id":"5d4662dc-b235-7a18-b8c0-20d8dd05c58f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A storage-class specifier decides "},{"type":"text","text":"where","marks":[{"type":"italic"}]},{"type":"text","text":" a variable lives, "},{"type":"text","text":"how long","marks":[{"type":"italic"}]},{"type":"text","text":" it lives (lifetime) and "},{"type":"text","text":"who can see it","marks":[{"type":"italic"}]},{"type":"text","text":" (linkage)."}]}]}},"revision":1},{"id":"bacd0fe2-5b45-75c4-a6d0-38df216f6c5b","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Specifier"}],[{"type":"text","text":"Lifetime"}],[{"type":"text","text":"Default value"}],[{"type":"text","text":"Scope / linkage"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"auto","marks":[{"type":"code"}]},{"type":"text","text":" (default for locals)"}],[{"type":"text","text":"Until the block ends"}],[{"type":"text","text":"Garbage"}],[{"type":"text","text":"Block, no linkage"}],[{"type":"text","text":"Ordinary local variables"}]],[[{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" (local)"}],[{"type":"text","text":"Whole program"}],[{"type":"text","text":"0"}],[{"type":"text","text":"Block, no linkage"}],[{"type":"text","text":"Remember a value between calls"}]],[[{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" (global / function)"}],[{"type":"text","text":"Whole program"}],[{"type":"text","text":"0"}],[{"type":"text","text":"File only ("},{"type":"text","text":"internal","marks":[{"type":"bold"}]},{"type":"text","text":" linkage)"}],[{"type":"text","text":"Hide helpers from other files"}]],[[{"type":"text","text":"extern","marks":[{"type":"code"}