#include <stdio.h>
#include <string.h>

int main(void) {
    char buf[32];
    strcpy(buf, "Hello");
    strcat(buf, ", ");
    strncat(buf, "world!!!", 6);          /* append at most 6 chars */
    printf("%s (%zu)\n", buf, strlen(buf));

    printf("%d %d %d\n", strcmp("apple", "apple") == 0,
           strcmp("apple", "banana") < 0, strcmp("b", "a") > 0);
    printf("%d\n", strncmp("prefix-match", "prefix-other", 6) == 0);
    return 0;
}
