SELECT '611c413f-c9d7-74a5-a7eb-c209214e857b', 'a4fc9d78-3e17-7d7d-9d22-b834eee1b510', 1, 'PUBLISHED', 'Strings in C', '[{"id":"a3b32a64-4656-70c5-8690-61afcfa1efd1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C has no string type. A string is an array of "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" terminated by a "},{"type":"text","text":"NUL byte","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"''\\0''","marks":[{"type":"code"}]},{"type":"text","text":" — every string function walks the bytes until it finds that terminator."}]}]}},"revision":1},{"id":"f3814545-3cc2-7559-ac9b-9083c2271cc9","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Arrays vs pointers to literals"}]},"revision":1},{"id":"b9520ebe-fd33-7963-ba0a-ce90e2f9a8b9","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char s1[] = \"hello\";            /* array of 6 bytes (a writable copy) */\n    char s2[10] = \"hi\";             /* rest zero-filled */\n    const char *s3 = \"world\";       /* pointer to a read-only literal */\n\n    s1[0] = ''H'';                    /* fine: s1 is our own array */\n    printf(\"%s %s %s\\n\", s1, s2, s3);\n    printf(\"sizeof: %zu %zu %zu\\n\", sizeof s1, sizeof s2, sizeof s3);\n    printf(\"strlen: %zu %zu %zu\\n\", strlen(s1), strlen(s2), strlen(s3));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"e7bf7d44-5c5e-753c-87be-dd98611aec88","type":"code","position":"a3","content":{"language":"text","code":"Hello hi world\nsizeof: 6 10 8\nstrlen: 5 2 5","filename":"Output"},"revision":1},{"id":"c75c6173-c605-725a-a643-1e3d3fd88413","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"char s[] = \"hello\";","marks":[{"type":"code"}]}],[{"type":"text","text":"const char *p = \"hello\";","marks":[{"type":"code"}]}]],[[{"type":"text","text":"What it is"}],[{"type":"text","text":"Array of 6 "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":", initialised from the literal"}],[{"type":"text","text":"Pointer to a literal stored in read-only memory"}]],[[{"type":"text","text":"Modifiable?"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No","marks":[{"type":"bold"}]},{"type":"text","text":" — writing is undefined behaviour (usually a crash)"}]],[[{"type":"text","text":"sizeof","marks":[{"type":"code"}]}],[{"type":"text","text":"6 (includes "},{"type":"text","text":"\\0","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"8 (size of a pointer)"}]],[[{"type":"text","text":"Reassignable?"}],[{"type":"text","text":"No ("},{"type":"text","text":"s = \"x\"","marks":[{"type":"code"}]},{"type":"text","text":" is an error)"}],[{"type":"text","text":"Yes ("},{"type":"text","text":"p = \"x\"","marks":[{"type":"code"}]},{"type":"text","text":" points elsewhere)"}]]]},"revision":1},{"id":"d5443ab7-0037-7ca6-8a08-f97227d6a0d4","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The terminator is everything"}]},"revision":1},{"id":"8c8e5614-2c1b-719d-ad15-8470c6450ad0","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n\nint main(void) {\n    char word[] = {''c'', ''a'', ''t'', ''\\0''};    /* same as \"cat\" */\n    printf(\"%s\\n\", word);\n    word[1] = ''\\0'';                         /* cut the string short */\n    printf(\"%s\\n\", word);\n    for (int i = 0; i < 4; i++) printf(\"%d \", word[i]);\n    printf(\"\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"303fbee9-3e68-7487-b9c5-aa215f16cd6e","type":"code","position":"a7","content":{"language":"text","code":"cat\nc\n99 0 116 0","filename":"Output"},"revision":1},{"id":"64e0f85a-aff6-7a34-a727-40de7ddb3763","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Writing string functions yourself"}]},"revision":1},{"id":"1ba9f6ae-c4f1-7a47-9f2c-cce417bc6730","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n#include <ctype.h>\n\nsize_t my_strlen(const char *s) {\n    const char *p = s;\n    while (*p) p++;\n    return (size_t)(p - s);\n}\n\nvoid reverse(char *s) {\n    size_t n = my_strlen(s);\n    for (size_t i = 0, j = n ? n - 1 : 0; i < j; i++, j--) {\n        char t = s[i]; s[i] = s[j]; s[j] = t;\n    }\n}\n\nint is_palindrome(const char *s) {\n    size_t i = 0, j = my_strlen(s);\n    while (i < j) {\n        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j - 1])) return 0;\n        i++; j--;\n    }\n    return 1;\n}\n\nint count_words(const char *s) {\n    int words = 0, in_word = 0;\n    for (; *s; s++) {\n        if (isspace((unsigned char)*s)) in_word = 0;\n        else if (!in_word) { in_word = 1; words++; }\n    }\n    return words;\n}\n\nint main(void) {\n    char buf[] = \"stressed\";\n    reverse(buf);\n    printf(\"%s %zu\\n\", buf, my_strlen(buf));\n    printf(\"%d %d\\n\", is_palindrome(\"Racecar\"), is_palindrome(\"hello\"));\n    printf(\"%d\\n\", count_words(\"  the quick  brown fox \"));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"0463c132-6a0f-7c23-9808-54ec8fa8af0a","type":"code","position":"aA","content":{"language":"text","code":"desserts 8\n1 0\n4","filename":"Output"},"revision":1},{"id":"26b14a30-b7bc-79dd-aa3c-63885ec40608","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Converting between strings and numbers"}]},"revision":1},{"id":"c0c90e12-2002-7e75-9589-f202218b1a98","type":"code","position":"aC","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    char *end;\n    long n = strtol(\"  1234xyz\", &end, 10);       /* stops at the first non-digit */\n    printf(\"%ld, rest = \\\"%s\\\"\\n\", n, end);\n    printf(\"%ld %ld\\n\", strtol(\"ff\", NULL, 16), strtol(\"101\", NULL, 2));\n    printf(\"%.2f\\n\", strtod(\"3.14159\", NULL));\n    printf(\"%d\\n\", atoi(\"42\"));                   /* no error reporting at all */\n\n    char out[32];\n    int len = snprintf(out, sizeof out, \"%d-%s-%.1f\", 7, \"ab\", 2.5);\n    printf(\"%s (%d chars)\\n\", out, len);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"bcc8baea-061e-7b06-a645-5ce3be65695e","type":"code","position":"aD","content":{"language":"text","code":"1234, rest = \"xyz\"\n255 5\n3.14\n42\n7-ab-2.5 (8 chars)","filename":"Output"},"revision":1},{"id":"b00a741d-10ff-71a9-8ad8-fab657251f96","type":"callout","position":"aE","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"strtol","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"strtod","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"atoi","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"atof","marks":[{"type":"code"}]},{"type":"text","text":": they report where parsing stopped and set "},{"type":"text","text":"errno","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"ERANGE","marks":[{"type":"code"}]},{"type":"text","text":" on overflow. Use "},{"type":"text","text":"snprintf","marks":[{"type":"code"}]},{"type":"text","text":" (never "},{"type":"text","text":"sprintf","marks":[{"type":"code"}]},{"type":"text","text":") to build strings safely."}]}]}},"revision":1},{"id":"d66757c2-0f83-7ace-bd0f-daba16d0830a","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Pitfalls"}]},"revision":1},{"id":"7ae711cc-c3b2-7a8d-a046-3db522840190","type":"code","position":"aG","content":{"language":"c","code":"int main(void) {\n    char *s = \"hello\";      /* legal in C (not C++), but the literal is read-only */\n    s[0] = ''H'';             /* undefined behaviour: crashes on most systems */\n    return 0;\n}","filename":"C — writing to a string literal (bus error / segfault at run time)"},"revision":1},{"id":"d8ea2034-08c2-794f-9899-1050dc2b2813","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgetting room for "},{"type":"text","text":"''\\0''","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"char s[5] = \"hello\";","marks":[{"type":"code"}]},{"type":"text","text":" compiles in C but has no terminator."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparing with "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" compares "},{"type":"text","text":"addresses","marks":[{"type":"italic"}]},{"type":"text","text":" — use "},{"type":"text","text":"strcmp","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning a pointer to a local "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" array from a function (it dies on return)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passing a plain "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" (possibly negative) to "},{"type":"text","text":"isalpha","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"toupper","marks":[{"type":"code"}]},{"type":"text","text":" — cast to "},{"type":"text","text":"unsigned char","marks":[{"type":"code"}]},{"type":"text","text":" first."}]}]}]}]}},"revision":1},{"id":"45a3b254-a1d0-7945-bb5a-695490cd4842","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between char s[] = \"abc\" and char *s = \"abc\"?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first creates a 4-byte array on the stack (or in "},{"type":"text","text":".data","marks":[{"type":"code"}]},{"type":"text","text":") initialised with a copy of the literal — you can modify it. The second creates a pointer to the literal itself, which lives in read-only memory; modifying it is undefined behaviour. "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" gives 4 vs 8."}]}]}},"revision":1},{"id":"22e470ec-a302-7910-b436-8effdf3eea61","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How is the length of a C string determined?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By scanning for the NUL terminator — "},{"type":"text","text":"strlen","marks":[{"type":"code"}]},{"type":"text","text":" is O(n). The length is not stored anywhere, which is why repeated "},{"type":"text","text":"strlen","marks":[{"type":"code"}]},{"type":"text","text":" calls in a loop condition ("},{"type":"text","text":"for (i = 0; i < strlen(s); i++)","marks":[{"type":"code"}]},{"type":"text","text":") make a loop O(n²)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
