SELECT '808e17f5-4166-7692-b750-ab8199021919', '219495e0-7fad-7d90-b8f0-26acbd4f4588', 1, 'PUBLISHED', 'Structures', '[{"id":"33b2df59-411c-761e-afe8-d8ee5cb52c2c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" groups related values of different types into one object — C’s building block for records, and for every data structure."}]}]}},"revision":1},{"id":"52f79a08-0513-7af0-82e4-5b4df520ec92","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Define, initialise, access"}]},"revision":1},{"id":"f650b200-88fd-7bcc-8f88-450b4318624e","type":"code","position":"a2","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nstruct Student {\n    int id;\n    char name[20];\n    double gpa;\n};\n\nint main(void) {\n    struct Student a = {1, \"Asha\", 8.9};                        /* positional */\n    struct Student b = {.name = \"Ravi\", .gpa = 7.5, .id = 2};   /* designated (C99) */\n    struct Student c = {0};                                     /* all zero */\n\n    c.id = 3;\n    strcpy(c.name, \"Meera\");\n    c.gpa = 9.2;\n\n    struct Student *p = &c;\n    p->gpa += 0.1;                     /* p->gpa is (*p).gpa */\n\n    printf(\"%d %s %.1f\\n\", a.id, a.name, a.gpa);\n    printf(\"%d %s %.1f\\n\", b.id, b.name, b.gpa);\n    printf(\"%d %s %.1f\\n\", p->id, (*p).name, p->gpa);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"4d87900e-115d-705b-9bc1-1d71339455d1","type":"code","position":"a3","content":{"language":"text","code":"1 Asha 8.9\n2 Ravi 7.5\n3 Meera 9.3","filename":"Output"},"revision":1},{"id":"93dfa470-a80a-7779-a2c0-638fa9731b13","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operator"}],[{"type":"text","text":"Use with"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":".","marks":[{"type":"code"}]}],[{"type":"text","text":"a struct object"}],[{"type":"text","text":"s.gpa","marks":[{"type":"code"}]}]],[[{"type":"text","text":"->","marks":[{"type":"code"}]}],[{"type":"text","text":"a pointer to a struct"}],[{"type":"text","text":"p->gpa","marks":[{"type":"code"}]},{"type":"text","text":" ≡ "},{"type":"text","text":"(*p).gpa","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"49b0d7a8-7993-7c06-82cf-ecd7a3e39164","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Copying, passing and returning"}]},"revision":1},{"id":"43fbf8dd-5bcd-74ed-b496-4bc5e6e06715","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n\ntypedef struct { double x, y; } Point;\n\nPoint midpoint(Point a, Point b) {          /* by value: copies in, copy out */\n    return (Point){(a.x + b.x) / 2, (a.y + b.y) / 2};    /* compound literal */\n}\n\nvoid translate(Point *p, double dx, double dy) {         /* by pointer: modifies caller */\n    p->x += dx;\n    p->y += dy;\n}\n\nint main(void) {\n    Point a = {0, 0}, b = {4, 2};\n    Point m = midpoint(a, b);\n    Point copy = m;                 /* struct assignment copies every member */\n    translate(&m, 1, 1);\n    printf(\"m=(%.1f,%.1f) copy=(%.1f,%.1f)\\n\", m.x, m.y, copy.x, copy.y);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"7520f345-5707-7d6e-8c69-0217709d38ba","type":"code","position":"a7","content":{"language":"text","code":"m=(3.0,2.0) copy=(2.0,1.0)","filename":"Output"},"revision":1},{"id":"7dd2ecaf-29e9-726f-8ce2-8d6bc24081c6","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structs "},{"type":"text","text":"can","marks":[{"type":"italic"}]},{"type":"text","text":" be assigned, passed and returned by value (arrays can’t). They "},{"type":"text","text":"cannot","marks":[{"type":"bold"}]},{"type":"text","text":" be compared with "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" — compare member by member. Pass large structs as "},{"type":"text","text":"const T *","marks":[{"type":"code"}]},{"type":"text","text":" to avoid copying."}]}]}},"revision":1},{"id":"93295e24-e312-7d05-805f-97366ea061cf","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Nested structs and arrays of structs"}]},"revision":1},{"id":"a4c64179-e952-7e2a-8a97-608faabdd382","type":"code","position":"aA","content":{"language":"c","code":"#include <stdio.h>\n\nstruct Date { int d, m, y; };\nstruct Employee {\n    char name[16];\n    struct Date joined;           /* nested */\n    double salary;\n};\n\nint main(void) {\n    struct Employee staff[] = {\n        {\"Anil\", {1, 4, 2020}, 50000},\n        {\"Bina\", {15, 9, 2018}, 72000},\n        {\"Chen\", {3, 1, 2022}, 61000},\n    };\n    int n = sizeof staff / sizeof staff[0];\n    double total = 0;\n    for (int i = 0; i < n; i++) {\n        total += staff[i].salary;\n        printf(\"%-5s joined %02d/%02d/%d\\n\", staff[i].name,\n               staff[i].joined.d, staff[i].joined.m, staff[i].joined.y);\n    }\n    printf(\"average salary %.0f\\n\", total / n);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"5846420f-8d11-7ea4-9ab1-718cc92d8c7a","type":"code","position":"aB","content":{"language":"text","code":"Anil  joined 01/04/2020\nBina  joined 15/09/2018\nChen  joined 03/01/2022\naverage salary 61000","filename":"Output"},"revision":1},{"id":"900033fe-b9e8-7a97-8198-844f2ef3cec8","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Self-referential structs"}]},"revision":1},{"id":"558d8e81-7679-7146-9d9e-13d77c574874","type":"code","position":"aD","content":{"language":"c","code":"#include <stdio.h>\n\nstruct Node {\n    int value;\n    struct Node *next;        /* a pointer to its own type is fine; a Node member is not */\n};\n\nint main(void) {\n    struct Node c = {3, NULL}, b = {2, &c}, a = {1, &b};\n    for (struct Node *n = &a; n != NULL; n = n->next) printf(\"%d -> \", n->value);\n    printf(\"NULL\\n\");\n    return 0;\n}","filename":"C"},"revision":1},{"id":"1b10efab-5b91-7815-9fc9-7b7c16d3ba13","type":"code","position":"aE","content":{"language":"text","code":"1 -> 2 -> 3 -> NULL","filename":"Output"},"revision":1},{"id":"6dc32c45-2dee-7866-acde-20fa4f4cdf81","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Flexible array member (C99)"}]},"revision":1},{"id":"5705cfce-eab5-7838-a1fd-1a660220b8ea","type":"code","position":"aG","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n    size_t len;\n    char data[];               /* flexible array member: must be last */\n} Buffer;\n\nint main(void) {\n    const char *text = \"variable length\";\n    size_t n = strlen(text) + 1;\n    Buffer *b = malloc(sizeof *b + n);   /* header + payload in ONE allocation */\n    if (!b) return 1;\n    b->len = n - 1;\n    memcpy(b->data, text, n);\n    printf(\"%zu: %s (sizeof Buffer = %zu)\\n\", b->len, b->data, sizeof(Buffer));\n    free(b);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"5762448f-6542-7271-a83d-65367d7eec78","type":"code","position":"aH","content":{"language":"text","code":"15: variable length (sizeof Buffer = 8)","filename":"Output"},"revision":1},{"id":"a1eb8061-60d4-7899-a1da-092493266695","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Opaque types: encapsulation in C"}]},"revision":1},{"id":"d0bbb412-0772-7831-9c17-17599afeb6b5","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Declaring "},{"type":"text","text":"struct Stack;","marks":[{"type":"code"}]},{"type":"text","text":" in a header without its body (an "},{"type":"text","text":"incomplete type","marks":[{"type":"italic"}]},{"type":"text","text":") lets users hold "},{"type":"text","text":"struct Stack *","marks":[{"type":"code"}]},{"type":"text","text":" but not touch the fields — only functions in "},{"type":"text","text":"stack.c","marks":[{"type":"code"}]},{"type":"text","text":" can. This is how "},{"type":"text","text":"FILE","marks":[{"type":"code"}]},{"type":"text","text":" works."}]}]}},"revision":1},{"id":"c04f5964-3512-794b-af72-348039691b0e","type":"code","position":"aK","content":{"language":"c","code":"/* stack.h */\ntypedef struct Stack Stack;           /* opaque: fields hidden */\nStack *stack_new(void);\nvoid   stack_push(Stack *s, int v);\nint    stack_pop(Stack *s);\nvoid   stack_free(Stack *s);","filename":"C — header of an opaque type (compile-checked)"},"revision":1},{"id":"0d963b97-1256-786d-a5c6-385d54bf52e0","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between . and -> ?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":".","marks":[{"type":"code"}]},{"type":"text","text":" accesses a member of a struct "},{"type":"text","text":"object","marks":[{"type":"italic"}]},{"type":"text","text":"; "},{"type":"text","text":"->","marks":[{"type":"code"}]},{"type":"text","text":" accesses a member through a "},{"type":"text","text":"pointer","marks":[{"type":"italic"}]},{"type":"text","text":" to a struct. "},{"type":"text","text":"p->m","marks":[{"type":"code"}]},{"type":"text","text":" is shorthand for "},{"type":"text","text":"(*p).m","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"93c754ef-dcf5-7837-abe9-86eaf2cceaec","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you compare two structs with ==?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — C does not define "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" for structs. Compare members individually. "},{"type":"text","text":"memcmp","marks":[{"type":"code"}]},{"type":"text","text":" is unreliable because padding bytes have unspecified values (and floating-point "},{"type":"text","text":"-0.0","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"NaN","marks":[{"type":"code"}]},{"type":"text","text":" compare differently from their bytes)."}]}]}},"revision":1},{"id":"8f63f08c-5c70-7890-a72f-d67b6bf04b68","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t a struct contain a member of its own type?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It would have infinite size. It can contain a "},{"type":"text","text":"pointer","marks":[{"type":"italic"}]},{"type":"text","text":" to its own type, because a pointer has a fixed size — that is how linked lists and trees are built."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
