  ('f650b200-88fd-7bcc-8f88-450b4318624e', 'a2', 'code', '{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nstruct Student {\n    int id;\n    char name[20];\n    double gpa;\n};\n\nint main(void) {\n    struct Student a = {1, \"Asha\", 8.9};                        /* positional */\n    struct Student b = {.name = \"Ravi\", .gpa = 7.5, .id = 2};   /* designated (C99) */\n    struct Student c = {0};                                     /* all zero */\n\n    c.id = 3;\n    strcpy(c.name, \"Meera\");\n    c.gpa = 9.2;\n\n    struct Student *p = &c;\n    p->gpa += 0.1;                     /* p->gpa is (*p).gpa */\n\n    printf(\"%d %s %.1f\\n\", a.id, a.name, a.gpa);\n    printf(\"%d %s %.1f\\n\", b.id, b.name, b.gpa);\n    printf(\"%d %s %.1f\\n\", p->id, (*p).name, p->gpa);\n    return 0;\n}","filename":"C"}'),
  ('4d87900e-115d-705b-9bc1-1d71339455d1', 'a3', 'code', '{"language":"text","code":"1 Asha 8.9\n2 Ravi 7.5\n3 Meera 9.3","filename":"Output"}'),
  ('93dfa470-a80a-7779-a2c0-638fa9731b13', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operator"}],[{"type":"text","text":"Use with"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":".","marks":[{"type":"code"}]}],[{"type":"text","text":"a struct object"}],[{"type":"text","text":"s.gpa","marks":[{"type":"code"}]}]],[[{"type":"text","text":"->","marks":[{"type":"code"}]}],[{"type":"text","text":"a pointer to a struct"}],[{"type":"text","text":"p->gpa","marks":[{"type":"code"}]},{"type":"text","text":" ≡ "},{"type":"text","text":"(*p).gpa","marks":[{"type":"code"}]}]]]}'),
  ('49b0d7a8-7993-7c06-82cf-ecd7a3e39164', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Copying, passing and returning"}]}'),
  ('43fbf8dd-5bcd-74ed-b496-4bc5e6e06715', 'a6', 'code', '{"language":"c","code":"#include <stdio.h>\n\ntypedef struct { double x, y; } Point;\n\nPoint midpoint(Point a, Point b) {          /* by value: copies in, copy out */\n    return (Point){(a.x + b.x) / 2, (a.y + b.y) / 2};    /* compound literal */\n}\n\nvoid translate(Point *p, double dx, double dy) {         /* by pointer: modifies caller */\n    p->x += dx;\n    p->y += dy;\n}\n\nint main(void) {\n    Point a = {0, 0}, b = {4, 2};\n    Point m = midpoint(a, b);\n    Point copy = m;                 /* struct assignment copies every member */\n    translate(&m, 1, 1);\n    printf(\"m=(%.1f,%.1f) copy=(%.1f,%.1f)\\n\", m.x, m.y, copy.x, copy.y);\n    return 0;\n}","filename":"C"}'),
  ('7520f345-5707-7d6e-8c69-0217709d38ba', 'a7', 'code', '{"language":"text","code":"m=(3.0,2.0) copy=(2.0,1.0)","filename":"Output"}'),
  ('7dd2ecaf-29e9-726f-8ce2-8d6bc24081c6', 'a8', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structs "},{"type":"text","text":"can","marks":[{"type":"italic"}]},{"type":"text","text":" be assigned, passed and returned by value (arrays can’t). They "},{"type":"text","text":"cannot","marks":[{"type":"bold"}]},{"type":"text","text":" be compared with "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" — compare member by member. Pass large structs as "},{"type":"text","text":"const T *","marks":[{"type":"code"}]},{"type":"text","text":" to avoid copying."}]}]}}'),
  ('93295e24-e312-7d05-805f-97366ea061cf', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Nested structs and arrays of structs"}]}'),
  ('a4c64179-e952-7e2a-8a97-608faabdd382', 'aA', 'code', '{"language":"c","code":"#include <stdio.h>\n\nstruct Date { int d, m, y; };\nstruct Employee {\n    char name[16];\n    struct Date joined;           /* nested */\n    double salary;\n};\n\nint main(void) {\n    struct Employee staff[] = {\n        {\"Anil\", {1, 4, 2020}, 50000},\n        {\"Bina\", {15, 9, 2018}, 72000},\n        {\"Chen\", {3, 1, 2022}, 61000},\n    };\n    int n = sizeof staff / sizeof staff[0];\n    double total = 0;\n    for (int i = 0; i < n; i++) {\n        total += staff[i].salary;\n        printf(\"%-5s joined %02d/%02d/%d\\n\", staff[i].name,\n               staff[i].joined.d, staff[i].joined.m, staff[i].joined.y);\n    }\n    printf(\"average salary %.0f\\n\", total / n);\n    return 0;\n}","filename":"C"}'),
