SELECT '9fee68e5-b621-70e4-84c7-4a38b14f0e21', '7837225f-46ae-7366-87ac-25548b8cfed8', 1, 'PUBLISHED', 'Type Qualifiers: const, volatile, restrict', '[{"id":"73fb2532-c265-7c65-8b70-cdfdf8f60416","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Qualifiers add promises about an object: "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" — I won’t write it; "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" — it may change behind the compiler’s back; "},{"type":"text","text":"restrict","marks":[{"type":"code"}]},{"type":"text","text":" — this pointer is the only way to reach that memory."}]}]}},"revision":1},{"id":"815d4e77-4989-71d2-8a7b-5f95b3418014","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Qualifier"}],[{"type":"text","text":"Promise / meaning"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"const","marks":[{"type":"code"}]}],[{"type":"text","text":"Not modified through this name"}],[{"type":"text","text":"Read-only parameters, lookup tables"}]],[[{"type":"text","text":"volatile","marks":[{"type":"code"}]}],[{"type":"text","text":"Every read and write must really happen, in order — no caching in registers"}],[{"type":"text","text":"Memory-mapped hardware registers, variables changed by signal handlers"}]],[[{"type":"text","text":"restrict","marks":[{"type":"code"}]},{"type":"text","text":" (C99)"}],[{"type":"text","text":"For the pointer’s lifetime, the object is accessed only through it"}],[{"type":"text","text":"memcpy","marks":[{"type":"code"}]},{"type":"text","text":", numeric kernels — enables vectorisation"}]],[[{"type":"text","text":"_Atomic","marks":[{"type":"code"}]},{"type":"text","text":" (C11)"}],[{"type":"text","text":"Accesses are atomic"}],[{"type":"text","text":"Lock-free counters shared between threads"}]]]},"revision":1},{"id":"0d49a60e-9b3d-7624-b7bd-7a4683d1d44d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"volatile"}]},"revision":1},{"id":"b4fcbb8c-cd4f-7847-9dd1-5a27f609333f","type":"code","position":"a3","content":{"language":"c","code":"#include <stdio.h>\n#include <signal.h>\n\nstatic volatile sig_atomic_t stop = 0;    /* changed by a signal handler */\n\nvoid on_signal(int sig) { (void)sig; stop = 1; }\n\nint main(void) {\n    signal(SIGINT, on_signal);\n    long spins = 0;\n    while (!stop) {                        /* volatile: re-read every iteration */\n        if (++spins == 1000000) raise(SIGINT);\n    }\n    printf(\"stopped after %ld spins\\n\", spins);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"ac19a1c4-cd9c-71b9-9755-cd01650fc205","type":"code","position":"a4","content":{"language":"text","code":"stopped after 1000000 spins","filename":"Output"},"revision":1},{"id":"b85f6c86-0026-7c39-9736-993dc94df7d3","type":"callout","position":"a5","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" make code thread-safe: it gives no atomicity and no memory ordering between CPUs. For threads use "},{"type":"text","text":"_Atomic","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"<stdatomic.h>","marks":[{"type":"code"}]},{"type":"text","text":" or mutexes."}]}]}},"revision":1},{"id":"16b6edba-910b-7eb5-b7c9-1ccdda9e39bc","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"restrict"}]},"revision":1},{"id":"b1c7963d-264a-71b3-97b5-bed28a62a268","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n\n/* the caller promises dst and src do not overlap, so the compiler may vectorise */\nvoid add_arrays(size_t n, float *restrict dst, const float *restrict src) {\n    for (size_t i = 0; i < n; i++) dst[i] += src[i];\n}\n\nint main(void) {\n    float a[4] = {1, 2, 3, 4}, b[4] = {10, 20, 30, 40};\n    add_arrays(4, a, b);\n    printf(\"%.0f %.0f %.0f %.0f\\n\", a[0], a[1], a[2], a[3]);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b23e18e7-bec9-721c-9c9a-8a7b32f8805a","type":"code","position":"a8","content":{"language":"text","code":"11 22 33 44","filename":"Output"},"revision":1},{"id":"947a0a39-df9e-7908-886d-48abdc448f1e","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The standard library uses it: "},{"type":"text","text":"void *memcpy(void *restrict dst, const void *restrict src, size_t n);","marks":[{"type":"code"}]},{"type":"text","text":" — which is precisely why overlapping "},{"type":"text","text":"memcpy","marks":[{"type":"code"}]},{"type":"text","text":" is undefined and "},{"type":"text","text":"memmove","marks":[{"type":"code"}]},{"type":"text","text":" (no "},{"type":"text","text":"restrict","marks":[{"type":"code"}]},{"type":"text","text":") exists."}]}]}},"revision":1},{"id":"1b0af061-862e-72c3-a119-64b9260b1e24","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a variable be both const and volatile?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — e.g. "},{"type":"text","text":"const volatile uint32_t *status_reg","marks":[{"type":"code"}]},{"type":"text","text":": the program must not write it ("},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":") but hardware can change it at any time, so every read must go to memory ("},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":"). A read-only hardware status register is the classic example."}]}]}},"revision":1},{"id":"d8fdf868-875e-7e79-96f5-54f8df535c01","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if you break a restrict promise?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Undefined behaviour. The compiler optimised assuming no aliasing (e.g. keeping values in registers or reordering loads), so overlapping pointers can produce wrong results silently."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
