SELECT 'd82455d5-c223-7aab-86c4-a71a031ec7f9', 'c442c223-5305-7f90-b335-6a9a433ab2e5', 1, 'PUBLISHED', 'typedef', '[{"id":"544d2071-e9cc-7eea-833d-567f154308d6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"typedef","marks":[{"type":"code"}]},{"type":"text","text":" creates an "},{"type":"text","text":"alias","marks":[{"type":"italic"}]},{"type":"text","text":" for an existing type — shorter names, clearer intent and a single place to change a type. It never creates a new, distinct type."}]}]}},"revision":1},{"id":"b11716b3-74a3-7e09-ad12-e791782658b3","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stdint.h>\n\ntypedef unsigned long ulong;                 /* shorter name */\ntypedef int32_t Meters;                      /* documents intent (still an int32_t) */\ntypedef struct { double re, im; } Complex;   /* anonymous struct, used without ''struct'' */\ntypedef int (*Compare)(int, int);            /* function pointer type */\ntypedef char Name[32];                       /* array type */\n\nint ascending(int a, int b) { return a - b; }\n\nint main(void) {\n    ulong big = 123456789UL;\n    Meters height = 8849;\n    Complex z = {1.5, -2.0};\n    Compare cmp = ascending;\n    Name who = \"Tenzing\";\n    printf(\"%lu %d %.1f%+.1fi %d %s %zu\\n\", big, height, z.re, z.im, cmp(3, 1), who, sizeof(Name));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"95cf7b1d-f1cf-740d-88ad-b25c50890e4f","type":"code","position":"a2","content":{"language":"text","code":"123456789 8849 1.5-2.0i 2 Tenzing 32","filename":"Output"},"revision":1},{"id":"1577c945-5669-7915-ae43-445dde3f0252","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"typedef struct patterns"}]},"revision":1},{"id":"40b566d4-6e25-7523-8908-d364d0f66ca1","type":"code","position":"a4","content":{"language":"c","code":"#include <stdio.h>\n#include <stdlib.h>\n\n/* tag + typedef: the tag is needed for the self-reference inside the body */\ntypedef struct Node {\n    int value;\n    struct Node *next;\n} Node;\n\nint main(void) {\n    Node second = {2, NULL};\n    Node first = {1, &second};\n    struct Node *same = &first;          /* both names work */\n    printf(\"%d %d\\n\", same->value, first.next->value);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"8ff4e0d1-ff6c-7326-b451-b5d1422bf81b","type":"code","position":"a5","content":{"language":"text","code":"1 2","filename":"Output"},"revision":1},{"id":"04367366-ef81-780a-8d89-9139a16fe8d6","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"typedef vs #define"}]},"revision":1},{"id":"3de2de33-1230-70ff-a737-0a4f1aa27f02","type":"code","position":"a7","content":{"language":"c","code":"#include <stdio.h>\n\n#define PTR_D int *\ntypedef int *PtrT;\n\nint main(void) {\n    int x = 1, y = 2;\n    PTR_D a, b;       /* expands to: int *a, b;  -> b is an int! */\n    PtrT  c, d;       /* both are int *                         */\n    a = &x; b = y;\n    c = &x; d = &y;\n    printf(\"%zu %zu %zu %zu\\n\", sizeof a, sizeof b, sizeof c, sizeof d);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"509b6987-7e33-7bfd-b353-8f3e241fd96a","type":"code","position":"a8","content":{"language":"text","code":"8 4 8 8","filename":"Output"},"revision":1},{"id":"39e0160e-e4be-7731-9f9a-1e67d4333aa6","type":"callout","position":"a9","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"typedef","marks":[{"type":"code"}]},{"type":"text","text":" for function-pointer types, opaque handles and platform-dependent types ("},{"type":"text","text":"size_t","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"uint32_t","marks":[{"type":"code"}]},{"type":"text","text":" are typedefs)."}]}]}},"revision":1},{"id":"23f933cf-1c85-7b42-95f0-3e8008b89d52","type":"callout","position":"aA","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hide pointers behind typedefs for ordinary data ("},{"type":"text","text":"typedef struct node *NodePtr;","marks":[{"type":"code"}]},{"type":"text","text":") — readers lose track of what is a pointer. The Linux kernel style bans most struct typedefs for this reason."}]}]}},"revision":1},{"id":"5fd5ca0d-bf17-7bb9-8eaf-37ab90cb8707","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Names ending in "},{"type":"text","text":"_t","marks":[{"type":"code"}]},{"type":"text","text":" are reserved by POSIX for future system types; in portable code prefer "},{"type":"text","text":"Name","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"name_type","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7b69b334-5aee-759c-9f1d-93d79814f108","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does typedef create a new type?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. It creates an alias: "},{"type":"text","text":"typedef int Meters;","marks":[{"type":"code"}]},{"type":"text","text":" makes "},{"type":"text","text":"Meters","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" fully interchangeable, with no extra type checking. To get a distinct type in C, wrap the value in a single-member "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
