SELECT '4b40f30b-e13a-7d7e-9ccc-a2adfe4d2001', '89958418-8086-74cb-aea7-03a294d85913', 1, 'PUBLISHED', 'Variadic Functions', '[{"id":"30d683b5-f6ad-7bc8-ab09-44f67cfb18ca","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions like "},{"type":"text","text":"printf","marks":[{"type":"code"}]},{"type":"text","text":" take a variable number of arguments. "},{"type":"text","text":"<stdarg.h>","marks":[{"type":"code"}]},{"type":"text","text":" lets you write your own: "},{"type":"text","text":"va_start","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"va_arg","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"va_end","marks":[{"type":"code"}]},{"type":"text","text":" walk the extra arguments — with no type safety at all."}]}]}},"revision":1},{"id":"965584ec-bfd9-77d5-b4c6-af95fbce296c","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n#include <stdarg.h>\n\n/* the count is passed explicitly: the callee can''t know how many arguments there are */\nint sum(int count, ...) {\n    va_list ap;\n    va_start(ap, count);                 /* start after the last named parameter */\n    int total = 0;\n    for (int i = 0; i < count; i++)\n        total += va_arg(ap, int);        /* you must know each argument''s type */\n    va_end(ap);\n    return total;\n}\n\n/* a sentinel (negative number) marks the end instead */\ndouble average(double first, ...) {\n    va_list ap;\n    va_start(ap, first);\n    double s = 0;\n    int n = 0;\n    for (double x = first; x >= 0; x = va_arg(ap, double)) { s += x; n++; }\n    va_end(ap);\n    return n ? s / n : 0;\n}\n\nint main(void) {\n    printf(\"%d %d\\n\", sum(3, 10, 20, 30), sum(0));\n    printf(\"%.2f\\n\", average(1.0, 2.0, 4.5, -1.0));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"5d152e54-9886-7c2f-ba8f-cb77254802c9","type":"code","position":"a2","content":{"language":"text","code":"60 0\n2.50","filename":"Output"},"revision":1},{"id":"a6bc1716-f279-7d4c-956e-90bfa7ae20f4","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Forwarding to vprintf: a logging function"}]},"revision":1},{"id":"c7438100-02ce-7604-8d7c-b4610b02fd05","type":"code","position":"a4","content":{"language":"c","code":"#include <stdio.h>\n#include <stdarg.h>\n\n/* the format attribute makes the compiler check calls like printf */\n__attribute__((format(printf, 2, 3)))\nvoid log_msg(const char *level, const char *fmt, ...) {\n    va_list ap;\n    va_start(ap, fmt);\n    printf(\"[%s] \", level);\n    vprintf(fmt, ap);                    /* the v- variants take a va_list */\n    printf(\"\\n\");\n    va_end(ap);\n}\n\nint main(void) {\n    log_msg(\"INFO\", \"server started on port %d\", 8080);\n    log_msg(\"WARN\", \"%s is %.1f%% full\", \"disk\", 91.5);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"6711ba2b-71c4-7011-a5e5-8f7718d7c070","type":"code","position":"a5","content":{"language":"text","code":"[INFO] server started on port 8080\n[WARN] disk is 91.5% full","filename":"Output"},"revision":1},{"id":"bce74cf6-78cc-7a40-9e46-131504cf1507","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Rules"}]},"revision":1},{"id":"39329401-7a7e-71fc-a66f-3538468d20ab","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At least one named parameter is required before "},{"type":"text","text":"...","marks":[{"type":"code"}]},{"type":"text","text":" (until C23)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Default argument promotions","marks":[{"type":"italic"}]},{"type":"text","text":" apply to the variadic part: "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"short","marks":[{"type":"code"}]},{"type":"text","text":" arrive as "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":". So "},{"type":"text","text":"va_arg(ap, float)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"va_arg(ap, char)","marks":[{"type":"code"}]},{"type":"text","text":" is wrong."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The callee must learn the number and types of the arguments some other way: a count, a sentinel, or a format string."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reading more arguments than were passed, or with the wrong type, is undefined behaviour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every "},{"type":"text","text":"va_start","marks":[{"type":"code"}]},{"type":"text","text":" (and "},{"type":"text","text":"va_copy","marks":[{"type":"code"}]},{"type":"text","text":") needs a matching "},{"type":"text","text":"va_end","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"f8fbebce-f963-75b2-a1ce-659a7d5cb5f9","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does printf know how many arguments it received?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It doesn’t — it trusts the format string. Each conversion specifier tells it to fetch one more argument of a given type with "},{"type":"text","text":"va_arg","marks":[{"type":"code"}]},{"type":"text","text":". Too few arguments, or mismatched types, are undefined behaviour, which is why compilers check "},{"type":"text","text":"printf","marks":[{"type":"code"}]},{"type":"text","text":" formats ("},{"type":"text","text":"-Wformat","marks":[{"type":"code"}]},{"type":"text","text":") and why user-controlled format strings are a security hole."}]}]}},"revision":1},{"id":"e6252206-80ed-77ca-9983-20ffb6b2078e","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t you use va_arg(ap, float)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because a "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" passed through "},{"type":"text","text":"...","marks":[{"type":"code"}]},{"type":"text","text":" is promoted to "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" by the caller. The callee must read it as "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":"; asking for a "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" reads the wrong number of bytes / wrong register — undefined behaviour."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
