SELECT '49f2d3ed-d35a-7997-be84-3325aa58fecc', 'd9192868-2b82-7ca1-9520-24dff1292c39', 1, 'PUBLISHED', 'void Pointers & Generic Code', '[{"id":"04b4521d-022c-738d-a910-4a8ebe2cab81","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" is a pointer to "},{"type":"text","text":"something","marks":[{"type":"italic"}]},{"type":"text","text":" of unknown type. Any object pointer converts to and from it implicitly — it is how C writes generic code ("},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"memcpy","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"1fc7ddfa-c974-78ad-852d-41ee2e52b84b","type":"code","position":"a1","content":{"language":"c","code":"#include <stdio.h>\n\nvoid print_value(const void *p, char type) {\n    switch (type) {\n        case ''i'': printf(\"int %d\\n\", *(const int *)p); break;\n        case ''d'': printf(\"double %.2f\\n\", *(const double *)p); break;\n        case ''s'': printf(\"string %s\\n\", (const char *)p); break;\n    }\n}\n\nint main(void) {\n    int i = 7;\n    double d = 2.5;\n    print_value(&i, ''i'');\n    print_value(&d, ''d'');\n    print_value(\"text\", ''s'');\n    return 0;\n}","filename":"C"},"revision":1},{"id":"1f8f4a33-430c-7b6c-8037-0a2dfb6ded8a","type":"code","position":"a2","content":{"language":"text","code":"int 7\ndouble 2.50\nstring text","filename":"Output"},"revision":1},{"id":"8c96d4f7-69fa-78db-9817-85bcc4160099","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Rules"}]},"revision":1},{"id":"50a88fb7-2edd-79ad-b0f2-637e86ea93c3","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You "},{"type":"text","text":"cannot dereference","marks":[{"type":"bold"}]},{"type":"text","text":" a "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" — cast it to a concrete type first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No pointer arithmetic on "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" in standard C (GCC allows it as an extension, treating the size as 1)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T *","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"T *","marks":[{"type":"code"}]},{"type":"text","text":" round-trips safely. Converting to the "},{"type":"text","text":"wrong","marks":[{"type":"italic"}]},{"type":"text","text":" type and dereferencing is undefined behaviour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In C, "},{"type":"text","text":"malloc","marks":[{"type":"code"}]},{"type":"text","text":"’s "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" result needs no cast: "},{"type":"text","text":"int *p = malloc(n * sizeof *p);","marks":[{"type":"code"}]},{"type":"text","text":". (C++ requires one.)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Function pointers are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" guaranteed to convert to "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" (POSIX allows it for "},{"type":"text","text":"dlsym","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"b90dab10-b6dd-73ed-ae79-c5ccc949ed8b","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"A generic swap"}]},"revision":1},{"id":"0ffe0ba3-4c5c-74e9-a0a0-8fb5cf4492c4","type":"code","position":"a6","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\nvoid swap_any(void *a, void *b, size_t size) {\n    unsigned char tmp[64];            /* enough for this demo */\n    if (size > sizeof tmp) return;\n    memcpy(tmp, a, size);\n    memcpy(a, b, size);\n    memcpy(b, tmp, size);\n}\n\nint main(void) {\n    int x = 1, y = 2;\n    double p = 1.5, q = 9.75;\n    swap_any(&x, &y, sizeof x);\n    swap_any(&p, &q, sizeof p);\n    printf(\"%d %d %.2f %.2f\\n\", x, y, p, q);\n    return 0;\n}","filename":"C"},"revision":1},{"id":"06f536bd-a070-7a80-8ca9-e24fcf0a633d","type":"code","position":"a7","content":{"language":"text","code":"2 1 9.75 1.50","filename":"Output"},"revision":1},{"id":"ab60039b-c571-7a4c-80f8-20b8e06544a6","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"A generic linear search"}]},"revision":1},{"id":"3cd34919-b043-79c3-8b56-5f5bd12ecf54","type":"code","position":"a9","content":{"language":"c","code":"#include <stdio.h>\n#include <string.h>\n\n/* returns the index of the first element equal to key, or -1 */\nlong find(const void *base, size_t n, size_t size, const void *key,\n          int (*eq)(const void *, const void *)) {\n    const unsigned char *p = base;             /* byte pointer for arithmetic */\n    for (size_t i = 0; i < n; i++)\n        if (eq(p + i * size, key)) return (long)i;\n    return -1;\n}\n\nint eq_int(const void *a, const void *b) { return *(const int *)a == *(const int *)b; }\nint eq_str(const void *a, const void *b) {\n    return strcmp(*(const char *const *)a, *(const char *const *)b) == 0;\n}\n\nint main(void) {\n    int nums[] = {3, 1, 4, 1, 5};\n    int k = 4;\n    const char *names[] = {\"ann\", \"bob\", \"cy\"};\n    const char *who = \"cy\";\n    printf(\"%ld %ld\\n\", find(nums, 5, sizeof nums[0], &k, eq_int),\n           find(names, 3, sizeof names[0], &who, eq_str));\n    return 0;\n}","filename":"C"},"revision":1},{"id":"b3b2a043-14e0-7325-838c-183b0ce737e7","type":"code","position":"aA","content":{"language":"text","code":"2 2","filename":"Output"},"revision":1},{"id":"aab9feb9-6fcc-7470-a3d3-4f90111a0689","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" throws away type checking — the compiler can no longer catch a wrong cast. Keep the "},{"type":"text","text":"void *","marks":[{"type":"code"}]},{"type":"text","text":" boundary thin and convert back to real types immediately."}]}]}},"revision":1},{"id":"46525f94-3296-719c-8c2e-a202283788d3","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t a void pointer be dereferenced?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dereferencing needs to know the size and interpretation of the object. "},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":" is an incomplete type with no size, so the compiler cannot generate a load or store — you must first cast to a complete type."}]}]}},"revision":1},{"id":"84beb20f-a26e-7368-b9e6-7a510d099ac3","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does qsort''s comparator take const void *?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"qsort","marks":[{"type":"code"}]},{"type":"text","text":" is written once for every element type, so it only knows the base address, the element count and the element size. It hands the comparator pointers to two elements as "},{"type":"text","text":"const void *","marks":[{"type":"code"}]},{"type":"text","text":"; the comparator, which knows the real type, casts them back."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
