SELECT '0d21d498-88de-7e2e-a809-285f781e6d7f', 'fbfd468c-b262-7d1b-9cab-0d9de0d548f6', 1, 'PUBLISHED', 'Atomics & the Memory Model', '[{"id":"6ddf10dd-b277-7b2a-9a3b-d364abb96684","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::atomic<T>","marks":[{"type":"code"}]},{"type":"text","text":" makes individual reads, writes and read-modify-write operations indivisible — lock-free synchronisation for counters, flags and pointers."}]}]}},"revision":1},{"id":"6419e758-da7e-7752-974f-b36608256595","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Atomic counter"}]},"revision":1},{"id":"c03edded-c0d4-7def-82f7-3d67b3bc1677","type":"code","position":"a2","content":{"language":"cpp","code":"#include <atomic>\n#include <iostream>\n#include <thread>\n#include <vector>\n\nint main() {\n    std::atomic<int> hits{0};\n    {\n        std::vector<std::jthread> ts;\n        for (int t = 0; t < 8; ++t)\n            ts.emplace_back([&] { for (int i = 0; i < 10''000; ++i) hits.fetch_add(1); });   // or ++hits\n    }\n    std::cout << hits.load() << '' '' << hits.is_lock_free() << ''\\n'';\n\n    std::atomic<int> value{5};\n    int expected = 5;\n    bool swapped = value.compare_exchange_strong(expected, 10);   // CAS: if value == 5, set 10\n    std::cout << swapped << '' '' << value << ''\\n'';\n    expected = 5;\n    swapped = value.compare_exchange_strong(expected, 20);         // fails; expected becomes 10\n    std::cout << swapped << '' '' << expected << ''\\n'';\n    std::cout << value.exchange(0) << '' '' << value << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"7184aedc-88e7-7239-a36b-d8faf3d1ff24","type":"code","position":"a3","content":{"language":"text","code":"80000 1\n1 10\n0 10\n10 0","filename":"Output"},"revision":1},{"id":"e07ec9ae-54cf-79df-8a9b-fd143e72cb61","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"load()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"store(v)","marks":[{"type":"code"}]}],[{"type":"text","text":"Atomic read / write"}]],[[{"type":"text","text":"fetch_add","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fetch_sub","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"++","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"+=","marks":[{"type":"code"}]}],[{"type":"text","text":"Atomic read-modify-write; return old (fetch_) or new value"}]],[[{"type":"text","text":"exchange(v)","marks":[{"type":"code"}]}],[{"type":"text","text":"Set and return the old value"}]],[[{"type":"text","text":"compare_exchange_strong/weak(expected, desired)","marks":[{"type":"code"}]}],[{"type":"text","text":"CAS — the building block of lock-free algorithms"}]],[[{"type":"text","text":"std::atomic_flag","marks":[{"type":"code"}]}],[{"type":"text","text":"Guaranteed lock-free boolean (spin locks)"}]]]},"revision":1},{"id":"bcd85e78-eb47-75f8-9ea5-5cbbc253c691","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Publishing data with a flag"}]},"revision":1},{"id":"e348fbef-78a6-79ff-bec7-76ae1066f0dc","type":"code","position":"a6","content":{"language":"cpp","code":"#include <atomic>\n#include <iostream>\n#include <string>\n#include <thread>\n\nint main() {\n    std::string payload;\n    std::atomic<bool> ready{false};\n    std::jthread producer([&] {\n        payload = \"config loaded\";                        // 1. write the data\n        ready.store(true, std::memory_order_release);     // 2. publish\n    });\n    while (!ready.load(std::memory_order_acquire)) {}      // 3. wait (spin) for the flag\n    std::cout << payload << ''\\n'';                          // 4. guaranteed to see the write\n}","filename":"C++"},"revision":1},{"id":"45153be5-a6ad-7389-b3d6-e2606335511f","type":"code","position":"a7","content":{"language":"text","code":"config loaded","filename":"Output"},"revision":1},{"id":"33ec58f9-91ad-786f-acb2-2682e3370893","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The default ordering, "},{"type":"text","text":"memory_order_seq_cst","marks":[{"type":"code"}]},{"type":"text","text":", is the easiest to reason about. "},{"type":"text","text":"release","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"acquire","marks":[{"type":"code"}]},{"type":"text","text":" pairs are cheaper on some CPUs: everything written before the release-store is visible after the matching acquire-load. "},{"type":"text","text":"relaxed","marks":[{"type":"code"}]},{"type":"text","text":" guarantees atomicity only — fine for statistics counters."}]}]}},"revision":1},{"id":"e49e1777-2bfc-7921-a75d-a2d7b832bdd3","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"std::mutex","marks":[{"type":"code"}]}],[{"type":"text","text":"std::atomic","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Protects"}],[{"type":"text","text":"Any block of code / several variables"}],[{"type":"text","text":"One variable"}]],[[{"type":"text","text":"Blocking"}],[{"type":"text","text":"Yes (threads sleep)"}],[{"type":"text","text":"No (lock-free for built-in sizes)"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"Invariants spanning multiple fields"}],[{"type":"text","text":"Counters, flags, single pointers"}]]]},"revision":1},{"id":"d9c52e86-b4f1-79f6-968d-1af76ae9d9bc","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" for threads in C++ — it prevents some compiler optimisations for memory-mapped I/O but provides no atomicity or ordering. Use "},{"type":"text","text":"std::atomic","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"3fdd824f-30d7-7dee-b807-b04b975d95fe","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is ++x on a std::atomic<int> thread-safe? What about x = x + 1?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"++x","marks":[{"type":"code"}]},{"type":"text","text":" is a single atomic read-modify-write ("},{"type":"text","text":"fetch_add","marks":[{"type":"code"}]},{"type":"text","text":"), so yes. "},{"type":"text","text":"x = x + 1","marks":[{"type":"code"}]},{"type":"text","text":" is an atomic "},{"type":"text","text":"load","marks":[{"type":"italic"}]},{"type":"text","text":" followed by a separate atomic "},{"type":"text","text":"store","marks":[{"type":"italic"}]},{"type":"text","text":" — another thread can update "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" in between, so increments can be lost."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
