auto type deduction
#include <iostream>
#include <map>
#include <string>
#include <vector>

int main() {
    auto n = 42;              // int
    auto pi = 3.14;           // double
    auto s = std::string("hi");
    std::map<std::string, std::vector<int>> index{{"a", {1, 2}}};
    for (const auto& [key, list] : index)   // instead of spelling out the pair type
        std::cout << key << ": " << list.size() << ''\n'';
    std::cout << n << '' '' << pi << '' '' << s << ''\n'';
}
