SELECT 'd55153dd-fb3b-7f0a-9485-0b5c3edee5cb', 'f8ead5b8-40d3-79f3-8ea7-77cfaaeb45e5', 1, 'PUBLISHED', 'Binary Search: lower_bound & upper_bound', '[{"id":"94e0b6b6-d63f-7842-89dd-1d23729fd911","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a "},{"type":"text","text":"sorted","marks":[{"type":"bold"}]},{"type":"text","text":" range, the STL''s binary searches answer “where would x go?” in O(log n). "},{"type":"text","text":"lower_bound","marks":[{"type":"code"}]},{"type":"text","text":" is the one to remember."}]}]}},"revision":1},{"id":"73266b47-6fbf-79ff-8209-4ce7c0409e27","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The four functions"}]},"revision":1},{"id":"12514fcf-0cb9-7ac2-8620-fbf859069b72","type":"code","position":"a2","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> v{1, 3, 3, 3, 5, 8};\n    //                 0  1  2  3  4  5\n    auto lb = std::lower_bound(v.begin(), v.end(), 3);   // first element >= 3\n    auto ub = std::upper_bound(v.begin(), v.end(), 3);   // first element >  3\n    std::cout << (lb - v.begin()) << '' '' << (ub - v.begin()) << \" count=\" << (ub - lb) << ''\\n'';\n\n    std::cout << std::binary_search(v.begin(), v.end(), 5)\n              << std::binary_search(v.begin(), v.end(), 4) << ''\\n'';\n\n    auto [lo, hi] = std::equal_range(v.begin(), v.end(), 3);\n    std::cout << (lo - v.begin()) << '' '' << (hi - v.begin()) << ''\\n'';\n\n    auto pos = std::lower_bound(v.begin(), v.end(), 6);   // insertion point that keeps v sorted\n    v.insert(pos, 6);\n    for (int x : v) std::cout << x;\n    std::cout << ''\\n'';\n    std::cout << (std::lower_bound(v.begin(), v.end(), 100) == v.end()) << ''\\n'';   // all smaller → end()\n}","filename":"C++"},"revision":1},{"id":"e49da1f8-1258-7dd3-b8d0-df6322bc35ef","type":"code","position":"a3","content":{"language":"text","code":"1 4 count=3\n10\n1 4\n1333568\n1","filename":"Output"},"revision":1},{"id":"d2173c54-9546-71d1-ba9d-efde01b2d6be","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Call"}],[{"type":"text","text":"Returns"}]],[[{"type":"text","text":"lower_bound(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"First position with element "},{"type":"text","text":"≥ x","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"upper_bound(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"First position with element "},{"type":"text","text":"> x","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"equal_range(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"{lower_bound, upper_bound}","marks":[{"type":"code"}]},{"type":"text","text":" — all elements equal to x"}]],[[{"type":"text","text":"binary_search(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"bool","marks":[{"type":"code"}]},{"type":"text","text":" only"}]]]},"revision":1},{"id":"aa898f59-345a-7f05-aa8b-fbed7e0e4e4c","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Common recipes"}]},"revision":1},{"id":"847642ad-13e0-7c78-b271-7b97371ef421","type":"code","position":"a6","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> v{2, 4, 4, 7, 9};\n    int x = 5;\n    // largest element < x\n    auto it = std::lower_bound(v.begin(), v.end(), x);\n    if (it != v.begin()) std::cout << \"floor-ish \" << *std::prev(it) << ''\\n'';\n    // number of elements <= 4\n    std::cout << \"count<=4 \" << (std::upper_bound(v.begin(), v.end(), 4) - v.begin()) << ''\\n'';\n\n    // descending data: pass the same comparator used to sort\n    std::vector<int> d{9, 7, 4, 2};\n    auto p = std::lower_bound(d.begin(), d.end(), 5, std::greater<>());   // first element <= 5\n    std::cout << *p << ''\\n'';\n}","filename":"C++