SELECT 'c510c014-8ee6-7acc-9939-77918034802f', 'ec271287-b156-79fe-b0a4-96e15db17d38', 1, 'PUBLISHED', 'Time with <chrono>', '[{"id":"ec2aa7cc-98ad-7db8-afdc-56b09d6d7a56","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"<chrono>","marks":[{"type":"code"}]},{"type":"text","text":" models time with types: "},{"type":"text","text":"durations","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"5s","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"250ms","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"time points","marks":[{"type":"italic"}]},{"type":"text","text":" (a clock reading) and "},{"type":"text","text":"clocks","marks":[{"type":"italic"}]},{"type":"text","text":". Units are checked at compile time — no more “was that seconds or milliseconds?”."}]}]}},"revision":1},{"id":"83b7b26e-d969-7db1-b906-2e38a411e5fe","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Durations"}]},"revision":1},{"id":"5b5c2615-0c9a-7f84-a7b1-68997e2b33cf","type":"code","position":"a2","content":{"language":"cpp","code":"#include <chrono>\n#include <iostream>\n\nint main() {\n    using namespace std::chrono_literals;\n    using namespace std::chrono;\n\n    auto timeout = 2s + 500ms;                         // std::chrono::milliseconds (2500)\n    std::cout << timeout.count() << \"ms\\n\";\n\n    seconds s = duration_cast<seconds>(timeout);        // lossy conversion must be explicit\n    std::cout << s.count() << \"s\\n\";\n\n    minutes m = 90min;\n    hours h = duration_cast<hours>(m);\n    std::cout << h.count() << \"h \" << (m - h).count() << \"min\\n\";\n\n    duration<double> secs = timeout;                    // floating-point seconds: implicit is fine\n    std::cout << secs.count() << ''\\n'';\n    std::cout << (1h > 59min) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"2e251ba0-7bf4-766f-a29d-34ae20d7821c","type":"code","position":"a3","content":{"language":"text","code":"2500ms\n2s\n1h 30min\n2.5\n1","filename":"Output"},"revision":1},{"id":"a022b129-d992-737f-af5e-aae408b789d0","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Measuring elapsed time"}]},"revision":1},{"id":"c74d956f-7288-71c2-a733-fb7688029ab4","type":"code","position":"a5","content":{"language":"cpp","code":"#include <chrono>\n#include <iostream>\n#include <numeric>\n#include <vector>\n\nint main() {\n    auto start = std::chrono::steady_clock::now();       // monotonic: right clock for measuring\n    std::vector<long long> v(1''000''000);\n    std::iota(v.begin(), v.end(), 1);\n    long long sum = std::accumulate(v.begin(), v.end(), 0LL);\n    auto end = std::chrono::steady_clock::now();\n\n    auto us = std::chrono::duration_cast<std::chrono::microseconds>(end - start);\n    std::cout << \"sum = \" << sum << ''\\n'';\n    std::cout << \"took \" << us.count() << \" us\\n\";      // varies run to run\n}","filename":"C++"},"revision":1},{"id":"62143304-faca-7d1f-85bf-93c0055f72f5","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Clock"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"steady_clock","marks":[{"type":"code"}]}],[{"type":"text","text":"Measuring intervals (never goes backwards)"}]],[[{"type":"text","text":"system_clock","marks":[{"type":"code"}]}],[{"type":"text","text":"Wall-clock time; convertible to calendar dates / "},{"type":"text","text":"time_t","marks":[{"type":"code"}]}]],[[{"type":"text","text":"high_resolution_clock","marks":[{"type":"code"}]}],[{"type":"text","text":"Alias of one of the above — prefer "},{"type":"text","text":"steady_clock","marks":[{"type":"code"}]},{"type":"text","text":" explicitly"}]]]},"revision":1},{"id":"bd57b663-9648-7e28-a6df-7b0c21858e5e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Calendar dates (C++20)"}]},"revision":1},{"id":"3b72001a-4d14-7b4c-9762-00369d38cc7e","type":"code","position":"a8","content":{"language":"cpp","code":"#include <chrono>\n#include <format>\n#include <iostream>\n\nint main() {\n    using namespace std::chrono;\n    year_month_day launch = 2024y / March / 15;\n    sys_days d = launch;\n    sys_days later = d + days(30);\n    std::cout << std::format(\"{} -> {}\\n\", launch, year_month_day{later});\n    std::cout << weekday{d} << '' '' << (2024y).is_leap() << ''\\n'';\n    std::cout << std::format(\"{}\\n\", 1500ms);\n}","filename":"C++"},"revision":1},{"id":"78c94fd7-5417-715d-af9c-fa377cdc08e1","type":"code","position":"a9","content":{"language":"text","code":"2024-03-15 -> 2024-04-14\nFri 1\n1500ms","filename":"Output"},"revision":1},{"id":"3f2815cc-2022-74a3-8fb7-316b411f4332","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use std::chrono instead of plain integers for time?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The unit is part of the type, so "},{"type":"text","text":"sleep_for(5)","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t compile (5 what?) but "},{"type":"text","text":"sleep_for(5s)","marks":[{"type":"code"}]},{"type":"text","text":" does, and conversions between units are exact and automatic when lossless ("},{"type":"text","text":"2s","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"2000ms","marks":[{"type":"code"}]},{"type":"text","text":") but must be explicit when lossy ("},{"type":"text","text":"duration_cast","marks":[{"type":"code"}]},{"type":"text","text":"). That eliminates a whole class of unit bugs at zero run-time cost."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
