SELECT '8d93c430-3b31-77b4-863e-606f51358859', '193e574c-417e-77c1-a31b-a8544c1fae42', 1, 'PUBLISHED', 'Class Templates & Specialisation', '[{"id":"0c709db3-6e92-7e31-87ad-abe3396f69e8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Class templates are how the STL is built: "},{"type":"text","text":"std::vector<T>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::map<K, V>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::array<T, N>","marks":[{"type":"code"}]},{"type":"text","text":". The type parameter becomes part of the class''s type."}]}]}},"revision":1},{"id":"3fa96987-4a36-7b5e-842a-a0b32409b2b6","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"A generic container"}]},"revision":1},{"id":"d8dbe974-e41c-7e85-aa04-39408a4b8cac","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\ntemplate <typename T>\nclass Stack {\npublic:\n    void push(const T& value) { items_.push_back(value); }\n    void pop() {\n        if (items_.empty()) throw std::out_of_range(\"pop on empty stack\");\n        items_.pop_back();\n    }\n    const T& top() const { return items_.back(); }\n    bool empty() const { return items_.empty(); }\n    std::size_t size() const { return items_.size(); }\nprivate:\n    std::vector<T> items_;\n};\n\nint main() {\n    Stack<int> s;\n    s.push(1); s.push(2); s.push(3);\n    s.pop();\n    std::cout << s.top() << '' '' << s.size() << ''\\n'';\n\n    Stack<std::string> words;\n    words.push(\"hello\");\n    std::cout << words.top() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"9db82952-0c07-70d7-ac6d-cff67c26c3d1","type":"code","position":"a3","content":{"language":"text","code":"2 2\nhello","filename":"Output"},"revision":1},{"id":"c8a74248-615e-7414-92b5-1bb89b3bb9f7","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Defaults, non-type parameters and CTAD"}]},"revision":1},{"id":"eec35209-e30f-7f02-bae0-a606257b447f","type":"code","position":"a5","content":{"language":"cpp","code":"#include <array>\n#include <iostream>\n#include <utility>\n#include <vector>\n\ntemplate <typename T, std::size_t Capacity = 4>\nclass RingBuffer {\n    std::array<T, Capacity> data_{};\n    std::size_t head_ = 0, count_ = 0;\npublic:\n    void push(T v) {\n        data_[(head_ + count_) % Capacity] = v;\n        if (count_ < Capacity) ++count_; else head_ = (head_ + 1) % Capacity;\n    }\n    T front() const { return data_[head_]; }\n    std::size_t size() const { return count_; }\n};\n\nint main() {\n    RingBuffer<int, 3> rb;\n    for (int i = 1; i <= 5; ++i) rb.push(i);       // keeps the last 3\n    std::cout << rb.front() << '' '' << rb.size() << ''\\n'';\n\n    std::pair p{1, 2.5};                            // CTAD (C++17): pair<int, double>\n    std::vector v{1, 2, 3};                         // vector<int>\n    std::cout << p.second << '' '' << v.size() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"e4ed6834-da96-7b16-a7a2-1cd4fffef141","type":"code","position":"a6","content":{"language":"text","code":"3 3\n2.5 3","filename":"Output"},"revision":1},{"id":"f494685d-e6fb-7c7b-bfa8-4c1d7f8c39e3","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Full and partial specialisation"}]},"revision":1},{"id":"28644918-a716-7893-a1b1-c7b3bbfb57aa","type":"code","position":"a8","content":{"language":"cpp","code":"#include <iostream>\n\ntemplate <typename T>\nstruct TypeName { static const char* get() { return \"unknown\"; } };\n\ntemplate <>                                   // full specialisation\nstruct TypeName<int> { static const char* get() { return \"int\"; } };\n\ntemplate <typename T>                         // partial specialisation: any pointer\nstruct TypeName<T*> { static const char* get() { return \"pointer\"; } };\n\ntemplate <typename K, typename V>\nstruct Pair { const char* kind() const { return \"general\"; } };\ntemplate <typename T>\nstruct Pair<T, T> { const char* kind() const { return \"same types\"; } };   // partial\n\nint main() {\n    std::cout << TypeName<int>::get() << '' '' << TypeName<double*>::get() << '' '' << TypeName<char>::get() << ''\\n'';\n    std::cout << Pair<int, double>{}.kind() << \", \" << Pair<int, int>{}.kind() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"742ff40f-62d9-733e-85a9-429d61b4c56d","type":"code","position":"a9","content":{"language":"text","code":"int pointer unknown\ngeneral, same types","filename":"Output"},"revision":1},{"id":"b11861f9-6950-7d3b-bcf2-a94dd9939878","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Function templates"}],[{"type":"text","text":"Class templates"}]],[[{"type":"text","text":"Full specialisation"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Partial specialisation"}],[{"type":"text","text":"No","marks":[{"type":"bold"}]},{"type":"text","text":" (overload instead)"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Deduce arguments"}],[{"type":"text","text":"Yes (from call)"}],[{"type":"text","text":"C++17 CTAD (from constructor)"}]]]},"revision":1},{"id":"ab36fd51-734a-7d00-8d39-193e33ce1df0","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Member templates & "},{"type":"text","text":"typename","marks":[{"type":"code"}]}]},"revision":1},{"id":"d1130225-23a9-76f8-b9f6-e3c0e5c756ee","type":"code","position":"aC","content":{"language":"cpp","code":"#include <iostream>\n#include <list>\n#include <vector>\n\ntemplate <typename Container>\ntypename Container::value_type first(const Container& c) {   // `typename`: a dependent *type*\n    return *c.begin();\n}\n\nstruct Printer {\n    template <typename T>\n    void print(const T& x) const { std::cout << x << ''\\n''; }   // member function template\n};\n\nint main() {\n    std::cout << first(std::vector<int>{7, 8}) << '' '' << first(std::list<char>{''z''}) << ''\\n'';\n    Printer{}.print(3.5);\n}","filename":"C++"},"revision":1},{"id":"fc06df9f-9bc4-727a-b078-3377a1e65a8c","type":"code","position":"aD","content":{"language":"text","code":"7 z\n3.5","filename":"Output"},"revision":1},{"id":"caf41103-576e-7a4f-bdfa-e363bf8dca84","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do you sometimes need the typename keyword inside a template?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"Container::value_type","marks":[{"type":"code"}]},{"type":"text","text":", the compiler can''t know whether "},{"type":"text","text":"value_type","marks":[{"type":"code"}]},{"type":"text","text":" is a type or a static member until "},{"type":"text","text":"Container","marks":[{"type":"code"}]},{"type":"text","text":" is known. By default it assumes a value; "},{"type":"text","text":"typename","marks":[{"type":"code"}]},{"type":"text","text":" tells it the dependent name is a type."}]}]}},"revision":1},{"id":"6e825f93-6bd4-7177-9bc7-fbaf04a7d7d1","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between full and partial specialisation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Full specialisation fixes "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" template parameters ("},{"type":"text","text":"TypeName<int>","marks":[{"type":"code"}]},{"type":"text","text":"); partial specialisation fixes some or constrains their form ("},{"type":"text","text":"TypeName<T*>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Pair<T, T>","marks":[{"type":"code"}]},{"type":"text","text":") and is still a template. Only class (and variable) templates can be partially specialised."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
