SELECT '43a886f1-8e66-762e-8467-77777a7244a1', '2a3c5846-1f3a-731b-8879-799998236658', 1, 'PUBLISHED', 'Classes & Objects', '[{"id":"689463fb-03dc-718a-ba1c-1e99b932dd2b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class bundles data (members) with the functions that operate on it (member functions), and controls access with "},{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"protected","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"003231bf-1398-7749-adf3-252b4d77c5b7","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Class","marks":[{"type":"bold"}]},{"type":"text","text":" — a user-defined type. An "},{"type":"text","text":"object","marks":[{"type":"bold"}]},{"type":"text","text":" is an instance of it. The class''s "},{"type":"text","text":"invariant","marks":[{"type":"italic"}]},{"type":"text","text":" (e.g. “balance is never negative”) is protected by keeping data "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" and changing it only through member functions."}]}]}},"revision":1},{"id":"fcc0cfe5-b153-7e3a-9e4b-7fd0b29eb9d7","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Defining a class"}]},"revision":1},{"id":"aa44463f-688b-7767-817b-10161c6768ed","type":"code","position":"a3","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\n#include <string>\n\nclass BankAccount {\npublic:                                          // the interface\n    BankAccount(std::string owner, double balance)\n        : owner_(std::move(owner)), balance_(balance) {}\n\n    void deposit(double amount) {\n        if (amount <= 0) throw std::invalid_argument(\"amount must be positive\");\n        balance_ += amount;\n    }\n    bool withdraw(double amount) {\n        if (amount > balance_) return false;     // invariant: balance_ >= 0\n        balance_ -= amount;\n        return true;\n    }\n    double balance() const { return balance_; }  // const: doesn''t modify the object\n    const std::string& owner() const { return owner_; }\n\nprivate:                                         // the implementation\n    std::string owner_;\n    double balance_;\n};\n\nint main() {\n    BankAccount acc(\"Ada\", 100);\n    acc.deposit(50);\n    std::cout << acc.withdraw(500) << '' '' << acc.withdraw(30) << ''\\n'';\n    std::cout << acc.owner() << \": \" << acc.balance() << ''\\n'';\n    // acc.balance_ = 1e9;   // error: ''balance_'' is a private member\n}","filename":"C++"},"revision":1},{"id":"22b46b16-3535-771a-ab3b-3f5a7bba481d","type":"code","position":"a4","content":{"language":"text","code":"0 1\nAda: 120","filename":"Output"},"revision":1},{"id":"30ed06a8-aa6f-7c90-9ec7-a8f25ddefcbb","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Access"}],[{"type":"text","text":"Accessible from"}]],[[{"type":"text","text":"public","marks":[{"type":"code"}]}],[{"type":"text","text":"Anywhere"}]],[[{"type":"text","text":"protected","marks":[{"type":"code"}]}],[{"type":"text","text":"The class, its friends and derived classes"}]],[[{"type":"text","text":"private","marks":[{"type":"code"}]}],[{"type":"text","text":"Only the class itself and its friends"}]]]},"revision":1},{"id":"dc409c00-f79f-771e-8b41-65e91d09d6fc","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"class","marks":[{"type":"code"}]}]},"revision":1},{"id":"0c6ded7e-8c16-7e1a-8114-624c1896237c","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They are the same thing except for defaults: "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" members and bases are "},{"type":"text","text":"public","marks":[{"type":"bold"}]},{"type":"text","text":" by default, "},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" ones "},{"type":"text","text":"private","marks":[{"type":"bold"}]},{"type":"text","text":". Convention: "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" for plain data bundles, "},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" when there''s an invariant to protect."}]}]}},"revision":1},{"id":"eb2e4519-e260-7cfc-895e-3931c7dde7aa","type":"code","position":"a8","content":{"language":"cpp","code":"#include <iostream>\nstruct Point {                  // aggregate: public data, no constructors needed\n    int x = 0;\n    int y = 0;\n    int manhattan() const { return (x < 0 ? -x : x) + (y < 0 ? -y : y); }\n};\nint main() {\n    Point p{3, -4};                        // aggregate initialisation\n    Point q{.x = 1, .y = 2};               // designated initialisers (C++20)\n    std::cout << p.manhattan() << '' '' << q.y << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"3362b765-0aad-7d25-8f08-9e415b799f28","type":"code","position":"a9","content":{"language":"text","code":"7 2","filename":"Output"},"revision":1},{"id":"14e3b2f4-94ce-721d-bb13-c88c7785d7eb","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" member functions & "},{"type":"text","text":"this","marks":[{"type":"code"}]}]},"revision":1},{"id":"f68e45e3-d939-7f2f-8f8c-6dda00069c60","type":"code","position":"aB","content":{"language":"cpp","code":"#include <iostream>\nclass Counter {\n    int value_ = 0;\n    mutable int reads_ = 0;               // mutable: may change even in const functions\npublic:\n    Counter& increment() { ++value_; return *this; }   // return *this to allow chaining\n    int value() const { ++reads_; return value_; }\n    int reads() const { return reads_; }\n};\nint main() {\n    Counter c;\n    c.increment().increment().increment();\n    const Counter& view = c;\n    std::cout << view.value() << '' '' << view.value() << '' '' << view.reads() << ''\\n'';\n    // view.increment();    // error: increment() is not const\n}","filename":"C++"},"revision":1},{"id":"0e6960fa-b8a3-7053-b005-867135a28cd0","type":"code","position":"aC","content":{"language":"text","code":"3 3 2","filename":"Output"},"revision":1},{"id":"5a269b80-9d04-7593-b479-f21363f190e0","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is a pointer to the object the member function was called on; "},{"type":"text","text":"*this","marks":[{"type":"code"}]},{"type":"text","text":" is the object."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" member function gets a "},{"type":"text","text":"const T* this","marks":[{"type":"code"}]},{"type":"text","text":" — it can''t modify members (except "},{"type":"text","text":"mutable","marks":[{"type":"code"}]},{"type":"text","text":" ones) or call non-const members."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" member functions can be called on "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" objects and through "},{"type":"text","text":"const&","marks":[{"type":"code"}]},{"type":"text","text":" — so mark every non-mutating function "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"6ed3c46e-91a4-78d9-985b-8afc942712de","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Declaring in a header, defining in a "},{"type":"text","text":".cpp","marks":[{"type":"code"}]}]},"revision":1},{"id":"cc1f15d7-c056-7e2d-8c5a-235ba9691d9b","type":"code","position":"aF","content":{"language":"cpp","code":"#include <iostream>\nclass Circle {\npublic:\n    explicit Circle(double r);\n    double area() const;           // declared here (header)\nprivate:\n    double r_;\n};\n\nCircle::Circle(double r) : r_(r) {}                 // defined outside with ClassName::\ndouble Circle::area() const { return 3.14159 * r_ * r_; }\n\nint main() { std::cout << Circle(2).area() << ''\\n''; }","filename":"C++"},"revision":1},{"id":"98b6c287-49d3-7ece-8efd-fde5d9491a15","type":"code","position":"aG","content":{"language":"text","code":"12.5664","filename":"Output"},"revision":1},{"id":"8828adbe-3133-7c06-bab7-8a160d950844","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the four pillars of OOP and how does C++ express them?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Encapsulation","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" data + public member functions. "},{"type":"text","text":"Abstraction","marks":[{"type":"bold"}]},{"type":"text","text":" — abstract classes / pure interfaces. "},{"type":"text","text":"Inheritance","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"class D : public B","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"Polymorphism","marks":[{"type":"bold"}]},{"type":"text","text":" — virtual functions (run time) and overloading/templates (compile time)."}]}]}},"revision":1},{"id":"fec1fe91-8526-7f5f-abfb-84ef7efdd816","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the size of an object?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The sum of its non-static data members plus padding (and a vptr if it has virtual functions). Member functions and static members don''t take space in each object. An empty class has size 1."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
