INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT '2a3c5846-1f3a-731b-8879-799998236658', '43a886f1-8e66-762e-8467-77777a7244a1', 'Classes & Objects', 'Classes & Objects', 'A class bundles data (members) with the functions that operate on it (member functions), and controls access with public, private and protected.
Class — a user-defined type. An object is an instance of it. The class''s invariant (e.g. “balance is never negative”) is protected by keeping data private and changing it only through member functions.
Defining a class
#include <iostream>
#include <stdexcept>
#include <string>

class BankAccount {
public:                                          // the interface
    BankAccount(std::string owner, double balance)
        : owner_(std::move(owner)), balance_(balance) {}

    void deposit(double amount) {
        if (amount <= 0) throw std::invalid_argument("amount must be positive");
        balance_ += amount;
    }
    bool withdraw(double amount) {
        if (amount > balance_) return false;     // invariant: balance_ >= 0
        balance_ -= amount;
        return true;
    }
    double balance() const { return balance_; }  // const: doesn''t modify the object
    const std::string& owner() const { return owner_; }

private:                                         // the implementation
    std::string owner_;
    double balance_;
};

int main() {
    BankAccount acc("Ada", 100);
    acc.deposit(50);
    std::cout << acc.withdraw(500) << '' '' << acc.withdraw(30) << ''\n'';
    std::cout << acc.owner() << ": " << acc.balance() << ''\n'';
    // acc.balance_ = 1e9;   // error: ''balance_'' is a private member
}
