SELECT 'f1a1c6de-ffc9-7c45-af07-0313c86258c2', 'dd71261c-2cbc-7895-bb14-289f5e7697e0', 1, 'PUBLISHED', 'Competitive Programming & Fast I/O', '[{"id":"5f74af1b-fb72-7b54-81d6-5fd9dd854da9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C++ dominates contests because of speed and the STL. A few habits — fast I/O, "},{"type":"text","text":"long long","marks":[{"type":"code"}]},{"type":"text","text":", the right container — prevent most wrong answers and time-limit errors."}]}]}},"revision":1},{"id":"89f5eac0-b3b9-790e-bd8a-02ad9c7d5c51","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The template"}]},"revision":1},{"id":"f15b9257-3852-7a61-bda6-0219ed03e4e3","type":"code","position":"a2","content":{"language":"cpp","code":"#include <bits/stdc++.h>          // GCC-only “everything” header; clang/MSVC: include what you use\nusing namespace std;\nusing ll = long long;\n\nint main() {\n    ios::sync_with_stdio(false);   // don''t sync C++ streams with C stdio\n    cin.tie(nullptr);              // don''t flush cout before every cin\n\n    int t;\n    cin >> t;\n    while (t--) {\n        int n;\n        cin >> n;\n        vector<ll> a(n);\n        for (auto& x : a) cin >> x;\n        ll best = *max_element(a.begin(), a.end());\n        ll sum = accumulate(a.begin(), a.end(), 0LL);\n        cout << best << '' '' << sum << ''\\n'';     // ''\\n'', never endl in hot loops\n    }\n}","filename":"C++ — contest template (GCC)"},"revision":1},{"id":"c0321b9d-a474-7e37-a00f-8669303fcf50","type":"code","position":"a3","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <numeric>\n#include <vector>\nusing namespace std;\nusing ll = long long;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int t;\n    cin >> t;\n    while (t--) {\n        int n;\n        cin >> n;\n        vector<ll> a(n);\n        for (auto& x : a) cin >> x;\n        cout << *max_element(a.begin(), a.end()) << '' '' << accumulate(a.begin(), a.end(), 0LL) << ''\\n'';\n    }\n}","filename":"C++ — the same, portable"},"revision":1},{"id":"b78c545e-803a-7271-a187-d60907090300","type":"code","position":"a4","content":{"language":"text","code":"5 8\n1000000000 2000000000","filename":"Output"},"revision":1},{"id":"aeb94a9a-ee28-772a-b09f-a69a70cb5ddb","type":"callout","position":"a5","content":{"variant":"note","title":"Portability","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"<bits/stdc++.h>","marks":[{"type":"code"}]},{"type":"text","text":" exists only in GCC''s libstdc++ (the usual contest compiler); it doesn''t exist with clang/libc++ on macOS. Include the real headers when you''re not on a judge."}]}]}},"revision":1},{"id":"ed1eaaad-913e-7759-938d-368ba2bdf9b8","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Habits that save you"}]},"revision":1},{"id":"5aef444a-a3e7-7d4c-8197-7c23720a6684","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Trap"}],[{"type":"text","text":"Fix"}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" overflow (sums, products > 2·10⁹)"}],[{"type":"text","text":"long long","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"ll","marks":[{"type":"code"}]},{"type":"text","text":") everywhere sums live; "},{"type":"text","text":"1LL * a * b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Slow I/O with 10⁶ numbers"}],[{"type":"text","text":"sync_with_stdio(false)","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"cin.tie(nullptr)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"''\\n''","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"endl","marks":[{"type":"code"}]}]],[[{"type":"text","text":"unordered_map","marks":[{"type":"code"}]},{"type":"text","text":" hacked with collisions"}],[{"type":"text","text":"Custom hash with a random seed, or "},{"type":"text","text":"map","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Recursion depth 10⁵–10⁶"}],[{"type":"text","text":"Iterative DFS with an explicit stack"}]],[[{"type":"text","text":"Large local arrays → stack overflow"}],[{"type":"text","text":"Global arrays or "},{"type":"text","text":"vector","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Comparing doubles"}],[{"type":"text","text":"Use an epsilon, or stay in integers"}]],[[{"type":"text","text":"v.size() - 1","marks":[{"type":"code"}]},{"type":"text","text":" when empty"}],[{"type":"text","text":"Cast: "},{"type":"text","text":"(int)v.size() - 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Modular arithmetic"}],[{"type":"text","text":"(a % M + M) % M","marks":[{"type":"code"}]},{"type":"text","text":" for negatives; multiply in "},{"type":"text","text":"long long","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"5bfbe054-c55a-78e9-b7fc-f4341b0a1902","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Handy snippets"}]},"revision":1},{"id":"6de1545d-a11a-7441-8f6b-95ae69c3d5a8","type":"code","position":"a9","content":{"language":"cpp","code":"#include <algorithm>\n#include <bit>\n#include <iostream>\n#include <numeric>\n#include <vector>\nusing ll = long long;\nconstexpr ll MOD = 1''000''000''007;\n\nll power(ll base, ll exp, ll mod) {                  // fast modular exponentiation\n    ll result = 1;\n    base %= mod;\n    while (exp > 0) {\n        if (exp & 1) result = result * base % mod;\n        base = base * base % mod;\n        exp >>= 1;\n    }\n    return result;\n}\n\nstd::vector<int> sieve(int n) {                      // primes up to n\n    std::vector<bool> composite(n + 1);\n    std::vector<int> primes;\n    for (int i = 2; i <= n; ++i) {\n        if (composite[i]) continue;\n        primes.push_back(i);\n        for (ll j = 1LL * i * i; j <= n; j += i) composite[j] = true;\n    }\n    return primes;\n}\n\nstruct DSU {                                         // union–find\n    std::vector<int> parent, size;\n    explicit DSU(int n) : parent(n), size(n, 1) { std::iota(parent.begin(), parent.end(), 0); }\n    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }\n    bool unite(int a, int b) {\n        a = find(a); b = find(b);\n        if (a == b) return false;\n        if (size[a] < size[b]) std::swap(a, b);\n        parent[b] = a; size[a] += size[b];\n        return true;\n    }\n};\n\nint main() {\n    std::cout << power(2, 1''000''000, MOD) << ''\\n'';\n    auto p = sieve(30);\n    std::cout << p.size() << '' '' << p.back() << ''\\n'';\n    DSU d(5);\n    d.unite(0, 1); d.unite(3, 4); d.unite(1, 4);\n    std::cout << (d.find(0) == d.find(3)) << (d.find(2) == d.find(0)) << ''\\n'';\n    std::cout << __builtin_popcount(13) << '' '' << __builtin_ctz(8) << '' ''\n              << std::popcount(13u) << '' '' << std::bit_width(1000u) - 1 << ''\\n'';   // portable <bit> versions\n}","filename":"C++"},"revision":1},{"id":"39756709-6da8-7c8f-9f1b-11a3b27a28f1","type":"code","position":"aA","content":{"language":"text","code":"235042059\n10 29\n10\n3 3 3 9","filename":"Output"},"revision":1},{"id":"ead912eb-bc11-7047-9dd8-1b2661e5ffd7","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GCC/Clang builtins: "},{"type":"text","text":"__builtin_popcount(x)","marks":[{"type":"code"}]},{"type":"text","text":" (set bits), "},{"type":"text","text":"__builtin_ctz(x)","marks":[{"type":"code"}]},{"type":"text","text":" (trailing zeros), "},{"type":"text","text":"__builtin_clz(x)","marks":[{"type":"code"}]},{"type":"text","text":" (leading zeros); libstdc++ also has "},{"type":"text","text":"std::__lg(x)","marks":[{"type":"code"}]},{"type":"text","text":" (floor log2). Portable C++20 equivalents live in "},{"type":"text","text":"<bit>","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"std::popcount","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::countr_zero","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::bit_width(x) - 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d61b7db7-fdec-78e5-938d-a38b4fbf1c38","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Operations per second"}]},"revision":1},{"id":"934b6348-396e-7cc0-b7b1-08d6f45e3072","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"n"}],[{"type":"text","text":"Feasible complexity (≈10⁸ simple ops/s)"}]],[[{"type":"text","text":"≤ 10–12"}],[{"type":"text","text":"O(n!)"}]],[[{"type":"text","text":"≤ 20–25"}],[{"type":"text","text":"O(2ⁿ)"}]],[[{"type":"text","text":"≤ 500"}],[{"type":"text","text":"O(n³)"}]],[[{"type":"text","text":"≤ 5 000"}],[{"type":"text","text":"O(n²)"}]],[[{"type":"text","text":"≤ 10⁶"}],[{"type":"text","text":"O(n log n)"}]],[[{"type":"text","text":"≤ 10⁸"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"> 10⁹"}],[{"type":"text","text":"O(log n) or O(1) — math"}]]]},"revision":1},{"id":"05f570a0-e8d2-793c-97ba-ecd8d4c7e675","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What do ios::sync_with_stdio(false) and cin.tie(nullptr) do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first stops C++ streams from synchronising with C''s "},{"type":"text","text":"stdio","marks":[{"type":"code"}]},{"type":"text","text":" buffers after every operation, letting "},{"type":"text","text":"cin","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"cout","marks":[{"type":"code"}]},{"type":"text","text":" buffer independently (after it, don''t mix "},{"type":"text","text":"scanf","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"printf","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"cin","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"cout","marks":[{"type":"code"}]},{"type":"text","text":"). The second unties "},{"type":"text","text":"cin","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"cout","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"cout","marks":[{"type":"code"}]},{"type":"text","text":" isn''t flushed before every read. Together they make stream I/O about as fast as "},{"type":"text","text":"scanf","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"printf","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
