SELECT '4d23c949-afa3-7c20-8c7b-efbde21aa4e5', '2a190d96-58f4-7378-bd79-7bc31e56bd87', 1, 'PUBLISHED', 'Compilation & Toolchain', '[{"id":"3d68d384-8d0e-72bb-8736-7f173325017c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Turning "},{"type":"text","text":".cpp","marks":[{"type":"code"}]},{"type":"text","text":" files into an executable takes four stages — knowing them explains most “undefined reference” and “multiple definition” errors."}]}]}},"revision":1},{"id":"35370564-4765-7c2e-a8da-ca6bdcca2768","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The build pipeline"}]},"revision":1},{"id":"14553e15-66b2-778b-a788-6b9aa278611f","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"main.cpp","marks":[{"type":"code"}]},{"type":"text","text":" → Preprocessor → Compiler → Assembler → Linker → "},{"type":"text","text":"./app","marks":[{"type":"code"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preprocess","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Handles "},{"type":"text","text":"#include","marks":[{"type":"code"}]},{"type":"text","text":" (pastes the header text in), "},{"type":"text","text":"#define","marks":[{"type":"code"}]},{"type":"text","text":" macros and "},{"type":"text","text":"#if","marks":[{"type":"code"}]},{"type":"text","text":" conditionals. Output: one big "},{"type":"text","text":"translation unit","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compile","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Parses and type-checks the translation unit, instantiates templates, optimises, and emits assembly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assemble","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Turns assembly into an "},{"type":"text","text":"object file","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"main.o","marks":[{"type":"code"}]},{"type":"text","text":") — machine code with unresolved symbol references."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Link","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Combines object files and libraries, resolving every symbol to exactly one definition. Output: the executable."}]}]}]}]}},"revision":1},{"id":"eefa28d7-62e0-7722-824d-03f8d182fd9d","type":"code","position":"a3","content":{"language":"","code":"$ clang++ -std=c++20 -Wall -Wextra -O2 main.cpp -o app   # all four stages in one go\n$ ./app\n\n$ clang++ -E main.cpp -o main.ii       # stop after preprocessing\n$ clang++ -S main.cpp -o main.s        # stop after compiling (assembly)\n$ clang++ -c main.cpp -o main.o        # stop after assembling (object file)\n$ clang++ main.o util.o -o app         # link object files","filename":"Terminal"},"revision":1},{"id":"484af016-fa47-700e-897e-43b270d8f985","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Useful compiler flags"}]},"revision":1},{"id":"07bdf6d7-019d-74f1-ad8f-d60c62a993f3","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Flag"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"-std=c++20","marks":[{"type":"code"}]}],[{"type":"text","text":"Pick the language standard ("},{"type":"text","text":"c++17","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"c++23","marks":[{"type":"code"}]},{"type":"text","text":", …)"}]],[[{"type":"text","text":"-Wall -Wextra -Wpedantic","marks":[{"type":"code"}]}],[{"type":"text","text":"Turn on warnings — always use them"}]],[[{"type":"text","text":"-Werror","marks":[{"type":"code"}]}],[{"type":"text","text":"Treat warnings as errors"}]],[[{"type":"text","text":"-O0","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"-O2","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"-O3","marks":[{"type":"code"}]}],[{"type":"text","text":"Optimisation level (debug → release)"}]],[[{"type":"text","text":"-g","marks":[{"type":"code"}]}],[{"type":"text","text":"Include debug info (for "},{"type":"text","text":"gdb","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"lldb","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"-fsanitize=address,undefined","marks":[{"type":"code"}]}],[{"type":"text","text":"Catch memory errors and UB at run time (ASan/UBSan)"}]],[[{"type":"text","text":"-I dir","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"-L dir","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"-lname","marks":[{"type":"code"}]}],[{"type":"text","text":"Header search path / library path / link a library"}]],[[{"type":"text","text":"-D NAME=val","marks":[{"type":"code"}]}],[{"type":"text","text":"Define a macro (like "},{"type":"text","text":"#define","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]},"revision":1},{"id":"520d25e9-b7cc-7ba5-babc-4fb3d568edf2","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Headers vs source files"}]},"revision":1},{"id":"3af3466f-3553-7e16-9f08-6ddcf591e09f","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"declaration","marks":[{"type":"bold"}]},{"type":"text","text":" says a name exists; a "},{"type":"text","text":"definition","marks":[{"type":"bold"}]},{"type":"text","text":" creates it. Headers hold declarations so every "},{"type":"text","text":".cpp","marks":[{"type":"code"}]},{"type":"text","text":" can use them; exactly one "},{"type":"text","text":".cpp","marks":[{"type":"code"}]},{"type":"text","text":" holds each definition."}]}]}},"revision":1},{"id":"b6434368-f713-713d-87fc-052a071009af","type":"code","position":"a8","content":{"language":"cpp","code":"// math_utils.h — the interface\n#pragma once              // include guard: paste this header at most once per TU\n\nint square(int x);        // declaration only\ninline int cube(int x) {  // `inline` lets a definition live in a header\n    return x * x * x;\n}","filename":"C++ — header"},"revision":1},{"id":"8fe6265e-7bc1-7097-84ec-60c382ed07b0","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\n// In a real project: #include \"math_utils.h\" and square() lives in math_utils.cpp.\nint square(int x);                    // what the header provides\nint main() { std::cout << square(7) << ''\\n''; }\nint square(int x) { return x * x; }   // what math_utils.cpp provides","filename":"C++"},"revision":1},{"id":"a8b2a100-c9c4-73de-9859-bd4b8cd76082","type":"code","position":"aA","content":{"language":"text","code":"49","filename":"Output"},"revision":1},{"id":"cccadf84-3b1d-7b04-8fef-972c53ea7466","type":"callout","position":"aB","content":{"variant":"note","title":"Undefined reference","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linker","marks":[{"type":"italic"}]},{"type":"text","text":" error: something was declared and used but never defined (or the "},{"type":"text","text":".cpp","marks":[{"type":"code"}]},{"type":"text","text":" defining it wasn''t linked)."}]}]}},"revision":1},{"id":"c3b9890d-a0e0-7463-bead-283e56e48558","type":"callout","position":"aC","content":{"variant":"note","title":"Multiple definition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linker","marks":[{"type":"italic"}]},{"type":"text","text":" error: two translation units both define the same non-"},{"type":"text","text":"inline","marks":[{"type":"code"}]},{"type":"text","text":" function/variable — e.g. a function body in a header included twice."}]}]}},"revision":1},{"id":"db260ad6-7a8c-7578-85dd-e112eabc0a0f","type":"callout","position":"aD","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One Definition Rule (ODR)","marks":[{"type":"bold"}]},{"type":"text","text":" — every function or variable may be "},{"type":"text","text":"declared","marks":[{"type":"italic"}]},{"type":"text","text":" many times but "},{"type":"text","text":"defined","marks":[{"type":"italic"}]},{"type":"text","text":" exactly once in the program — except "},{"type":"text","text":"inline","marks":[{"type":"code"}]},{"type":"text","text":" functions/variables, templates and classes, which may be defined in every TU as long as all definitions are identical."}]}]}},"revision":1},{"id":"9f74031d-1a1a-7b6d-a98a-4f925779a6b9","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Include guards"}]},"revision":1},{"id":"59a19c3d-eb20-77bb-8b28-a280a9fcc4f5","type":"code","position":"aF","content":{"language":"cpp","code":"#ifndef POINT_H           // classic guard — works everywhere\n#define POINT_H\nstruct Point { int x, y; };\n#endif","filename":"C++ — classic guard"},"revision":1},{"id":"2cf7795c-3409-77c2-b74e-a9b5ae5dc07f","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Build systems"}]},"revision":1},{"id":"0b23e5e3-343a-7d62-b9a0-8bea25d4931b","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real projects don''t type compiler commands — "},{"type":"text","text":"CMake","marks":[{"type":"bold"}]},{"type":"text","text":" generates the build (Make/Ninja/Xcode) from a "},{"type":"text","text":"CMakeLists.txt","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]}},"revision":1},{"id":"528ef13f-c771-76d6-a7d1-0f73781267bd","type":"code","position":"aI","content":{"language":"","code":"# CMakeLists.txt\ncmake_minimum_required(VERSION 3.20)\nproject(app CXX)\nset(CMAKE_CXX_STANDARD 20)\nadd_executable(app main.cpp math_utils.cpp)\n\n$ cmake -S . -B build && cmake --build build","filename":"Terminal"},"revision":1},{"id":"cfba462d-69d3-7219-a270-a8c2a35b3bee","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between a compile error and a linker error?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A compile error is found while checking a single translation unit (syntax, types, undeclared names). A linker error happens after every file compiled fine, when symbols are stitched together: a missing definition ("},{"type":"text","text":"undefined reference","marks":[{"type":"italic"}]},{"type":"text","text":") or two definitions ("},{"type":"text","text":"multiple definition","marks":[{"type":"italic"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"e1e8a78b-4e69-7804-8e00-6ffc41a0754d","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do templates usually live entirely in headers?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The compiler generates code for a template only when it sees it used with concrete types, and it needs the full definition at that point. If the definition were in a "},{"type":"text","text":".cpp","marks":[{"type":"code"}]},{"type":"text","text":", other translation units couldn''t instantiate it and you''d get undefined-reference errors."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
