SELECT '11cf8477-2537-7e80-bc8f-c1c18fa3e98a', '419fbeaa-f9e8-708c-bd5f-b5384395c328', 1, 'PUBLISHED', 'Concepts & Constraints (C++20)', '[{"id":"db143449-9ad1-7cc9-b862-59a750a8e8e1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A concept is a named, compile-time predicate on types. Constraining a template with one gives clear error messages and lets you overload on what a type can do."}]}]}},"revision":1},{"id":"5a95f0e7-3bd9-7946-af1c-6feeb92de716","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Using standard concepts"}]},"revision":1},{"id":"32fec7ca-83b8-7c34-bc92-73a7a8d33de0","type":"code","position":"a2","content":{"language":"cpp","code":"#include <concepts>\n#include <iostream>\n\ntemplate <std::integral T>                 // T must be an integer type\nT gcd(T a, T b) { return b == 0 ? a : gcd(b, a % b); }\n\nauto half(std::floating_point auto x) { return x / 2; }      // abbreviated syntax\n\ntemplate <typename T>\n    requires std::totally_ordered<T>       // requires-clause\nconst T& clampTo(const T& v, const T& lo, const T& hi) { return v < lo ? lo : hi < v ? hi : v; }\n\nint main() {\n    std::cout << gcd(48, 18) << '' '' << half(5.0) << '' '' << clampTo(15, 0, 10) << ''\\n'';\n    // gcd(4.5, 1.5);   // error: constraints not satisfied — ''double'' is not integral\n}","filename":"C++"},"revision":1},{"id":"37b05127-f885-767f-a09c-99499ff0b981","type":"code","position":"a3","content":{"language":"text","code":"6 2.5 10","filename":"Output"},"revision":1},{"id":"8233f4e0-5fbf-7670-b63b-b771f65b5f41","type":"code","position":"a4","content":{"language":"cpp","code":"#include <concepts>\ntemplate <std::integral T>\nT gcd(T a, T b) { return b == 0 ? a : gcd(b, a % b); }\nint main() { return static_cast<int>(gcd(4.5, 1.5)); }","filename":"C++ — constraint violated"},"revision":1},{"id":"9c973e80-6bcd-7459-b112-0bd5426c729b","type":"code","position":"a5","content":{"language":"text","code":"error: no matching function for call to ''gcd''\nnote: candidate template ignored: constraints not satisfied [with T = double]\nnote: because ''double'' does not satisfy ''integral''","filename":"Compiler error — short and to the point"},"revision":1},{"id":"711b236b-109b-7dfd-b164-d97ba6ffe559","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Defining a concept"}]},"revision":1},{"id":"80fbf4bd-3b70-77c7-8647-6341797bad5f","type":"code","position":"a7","content":{"language":"cpp","code":"#include <concepts>\n#include <iostream>\n#include <string>\n#include <vector>\n\ntemplate <typename T>\nconcept Shape = requires(const T& s) {\n    { s.area() } -> std::convertible_to<double>;    // must have area() returning something double-like\n    { s.name() } -> std::convertible_to<std::string>;\n};\n\nstruct Square { double side; double area() const { return side * side; } std::string name() const { return \"square\"; } };\nstruct Blob   { int size; };\n\nvoid report(const Shape auto& s) { std::cout << s.name() << \": \" << s.area() << ''\\n''; }\n\ntemplate <typename T>\nconcept Container = requires(T c) { c.begin(); c.end(); c.size(); };\n\nvoid info(const Container auto& c) { std::cout << \"container of \" << c.size() << ''\\n''; }\nvoid info(const auto&)            { std::cout << \"not a container\\n\"; }   // less constrained fallback\n\nint main() {\n    report(Square{3});\n    // report(Blob{1});   // error: Blob does not satisfy Shape\n    info(std::vector<int>{1, 2});\n    info(42);\n    std::cout << Shape<Square> << Shape<Blob> << ''\\n'';     // concepts are bool constants\n}","filename":"C++"},"revision":1},{"id":"278226ba-7958-79c6-a9ab-647377f38081","type":"code","position":"a8","content":{"language":"text","code":"square: 9\ncontainer of 2\nnot a container\n10","filename":"Output"},"revision":1},{"id":"20925576-6ada-7c03-986f-b6a6c9bd7e82","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Concept ("},{"type":"text","text":"<concepts>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<iterator>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<ranges>","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Satisfied when"}]],[[{"type":"text","text":"std::integral","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::floating_point","marks":[{"type":"code"}]}],[{"type":"text","text":"Built-in integer / floating type"}]],[[{"type":"text","text":"std::same_as<T, U>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::convertible_to<From, To>","marks":[{"type":"code"}]}],[{"type":"text","text":"Type relationships"}]],[[{"type":"text","text":"std::equality_comparable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::totally_ordered","marks":[{"type":"code"}]}],[{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" etc. work"}]],[[{"type":"text","text":"std::copyable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::movable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::default_initializable","marks":[{"type":"code"}]}],[{"type":"text","text":"Object capabilities"}]],[[{"type":"text","text":"std::invocable<F, Args...>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::predicate<F, Args...>","marks":[{"type":"code"}]}],[{"type":"text","text":"Callable with those arguments"}]],[[{"type":"text","text":"std::ranges::range","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::random_access_iterator","marks":[{"type":"code"}]}],[{"type":"text","text":"Range / iterator categories"}]]]},"revision":1},{"id":"a2580640-b243-7c0a-9476-3046b92a8887","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Four ways to write a constraint"}]},"revision":1},{"id":"d00f47fe-7123-730c-99a4-d0eb68d95a78","type":"code","position":"aB","content":{"language":"cpp","code":"#include <concepts>\ntemplate <std::integral T> T a(T x) { return x; }                  // 1. constrained parameter\ntemplate <typename T> requires std::integral<T> T b(T x) { return x; }   // 2. requires-clause\ntemplate <typename T> T c(T x) requires std::integral<T> { return x; }   // 3. trailing requires\nstd::integral auto d(std::integral auto x) { return x; }           // 4. abbreviated","filename":"C++ — equivalent forms"},"revision":1},{"id":"d599636d-a1b9-7696-9525-cd4c297484b9","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What problem do concepts solve compared with plain templates?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plain templates accept any type and fail deep inside the implementation with pages of errors. Concepts state requirements in the interface: misuse is rejected at the call site with a short message, overloads can be selected by capability (more-constrained wins), and the code documents itself. They replace most "},{"type":"text","text":"enable_if","marks":[{"type":"code"}]},{"type":"text","text":"/SFINAE tricks."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
