SELECT '424a0d64-f56a-7912-af1d-12a88f22cbe2', '1c1d8ee0-1e0a-7616-b34c-eddd5a574c18', 1, 'PUBLISHED', 'Constructors', '[{"id":"1e338cfe-fb04-7f7a-a99f-47acd51e4f3f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A constructor initialises an object when it is created. C++ has default, parameterised, copy and move constructors, plus member initializer lists, delegation and "},{"type":"text","text":"explicit","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6cb34feb-62f6-779f-b033-514f84d518cb","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Kinds of constructors"}]},"revision":1},{"id":"57f1f5e0-be27-7e9e-9060-a7e6338e0ed2","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\nclass Person {\npublic:\n    Person() : name_(\"anonymous\"), age_(0) { std::cout << \"default\\n\"; }\n    Person(std::string name, int age) : name_(std::move(name)), age_(age) { std::cout << \"param\\n\"; }\n    Person(const Person& o) : name_(o.name_), age_(o.age_) { std::cout << \"copy\\n\"; }\n    Person(Person&& o) noexcept : name_(std::move(o.name_)), age_(o.age_) { std::cout << \"move\\n\"; }\n    void show() const { std::cout << name_ << \" (\" << age_ << \")\\n\"; }\nprivate:\n    std::string name_;\n    int age_;\n};\n\nint main() {\n    Person a;                   // default\n    Person b(\"Ada\", 36);        // parameterised\n    Person c = b;               // copy\n    Person d = std::move(b);    // move\n    a.show(); c.show(); d.show();\n}","filename":"C++"},"revision":1},{"id":"6a0c1b36-ca86-7fdd-8138-4a570b40d746","type":"code","position":"a3","content":{"language":"text","code":"default\nparam\ncopy\nmove\nanonymous (0)\nAda (36)\nAda (36)","filename":"Output"},"revision":1},{"id":"9f9955d2-bdd8-74aa-8ee6-bed17510eb31","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Member initializer lists"}]},"revision":1},{"id":"4358a013-eb09-7bf5-90f0-87d3858bd9f4","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Members are initialised "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the constructor body runs. Initialise them in the list — assigning in the body means default-construct first, then assign. "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" members, references and members without a default constructor "},{"type":"text","text":"must","marks":[{"type":"bold"}]},{"type":"text","text":" use the list."}]}]}},"revision":1},{"id":"35471f21-1ed6-7119-aec7-54597b8f6481","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\nclass Config {\n    const int maxUsers_;          // const: must be initialised, can''t be assigned\n    int& counter_;                // reference: same\n    int timeout_ = 30;            // default member initializer (C++11)\npublic:\n    Config(int maxUsers, int& counter) : maxUsers_(maxUsers), counter_(counter) { ++counter_; }\n    Config(int maxUsers, int& counter, int timeout) : Config(maxUsers, counter) {   // delegating\n        timeout_ = timeout;\n    }\n    void show() const { std::cout << maxUsers_ << '' '' << timeout_ << '' '' << counter_ << ''\\n''; }\n};\nint main() {\n    int created = 0;\n    Config a(10, created);\n    Config b(20, created, 5);\n    a.show();\n    b.show();\n}","filename":"C++"},"revision":1},{"id":"625cde6a-8be7-786d-8bdc-3c07cbfa9341","type":"code","position":"a7","content":{"language":"text","code":"10 30 2\n20 5 2","filename":"Output"},"revision":1},{"id":"06a2b0b3-a556-7109-8838-e26d27675388","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Members are initialised in the order they are "},{"type":"text","text":"declared in the class","marks":[{"type":"bold"}]},{"type":"text","text":", not the order in the initializer list. "},{"type":"text","text":"B(int v) : b_(v), a_(b_) {}","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"a_","marks":[{"type":"code"}]},{"type":"text","text":" declared first reads "},{"type":"text","text":"b_","marks":[{"type":"code"}]},{"type":"text","text":" before it''s initialised. ("},{"type":"text","text":"-Wall","marks":[{"type":"code"}]},{"type":"text","text":" warns about the mismatch.)"}]}]}},"revision":1},{"id":"4942ce83-dee3-717f-8626-041f9fc785c3","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"explicit","marks":[{"type":"code"}]}]},"revision":1},{"id":"23a12aa6-041d-7255-a80c-eba088740b75","type":"code","position":"aA","content":{"language":"cpp","code":"#include <iostream>\nstruct Meters {\n    double v;\n    explicit Meters(double x) : v(x) {}      // no implicit double → Meters\n};\nstruct Label {\n    int id;\n    Label(int i) : id(i) {}                  // implicit conversion allowed\n};\nvoid run(Meters m) { std::cout << m.v << \"m\\n\"; }\nvoid print(Label l) { std::cout << \"#\" << l.id << ''\\n''; }\nint main() {\n    run(Meters(5));       // must be explicit\n    print(42);            // 42 silently becomes a Label — often surprising\n    // run(5.0);          // error: no implicit conversion\n}","filename":"C++"},"revision":1},{"id":"f2d17ced-c527-72e4-91d9-fa954a8d0494","type":"code","position":"aB","content":{"language":"text","code":"5m\n#42","filename":"Output"},"revision":1},{"id":"7f512ba8-38cc-71e3-814c-0e58f4652a65","type":"callout","position":"aC","content":{"variant":"note","title":"Guideline","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark single-argument constructors "},{"type":"text","text":"explicit","marks":[{"type":"code"}]},{"type":"text","text":" unless the implicit conversion is genuinely natural (like "},{"type":"text","text":"std::string","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"const char*","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"4fbd4b16-1a2d-73a4-a98e-2bf08f2e7f14","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Compiler-generated constructors"}]},"revision":1},{"id":"895eda1a-2687-7419-ae32-845a42c44c1d","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Special member"}],[{"type":"text","text":"Generated when…"}]],[[{"type":"text","text":"Default constructor "},{"type":"text","text":"T()","marks":[{"type":"code"}]}],[{"type":"text","text":"You declare "},{"type":"text","text":"no","marks":[{"type":"bold"}]},{"type":"text","text":" constructors at all"}]],[[{"type":"text","text":"Copy constructor / copy assignment"}],[{"type":"text","text":"You don''t declare a move operation (deprecated if you declare a destructor)"}]],[[{"type":"text","text":"Move constructor / move assignment"}],[{"type":"text","text":"You declare "},{"type":"text","text":"none","marks":[{"type":"bold"}]},{"type":"text","text":" of: copy ops, move ops, destructor"}]],[[{"type":"text","text":"Destructor"}],[{"type":"text","text":"You don''t declare one"}]]]},"revision":1},{"id":"db7cea80-1202-7a55-b88b-528dd745320f","type":"code","position":"aF","content":{"language":"cpp","code":"#include <iostream>\nstruct Widget {\n    int size = 1;\n    Widget() = default;                  // bring back the default ctor alongside another one\n    explicit Widget(int s) : size(s) {}\n    Widget(const Widget&) = delete;      // forbid copying\n};\nint main() {\n    Widget a;\n    Widget b(5);\n    std::cout << a.size << '' '' << b.size << ''\\n'';\n    // Widget c = b;   // error: call to deleted constructor\n}","filename":"C++"},"revision":1},{"id":"dedc929d-b07a-7247-8b4b-15645d41a8a5","type":"code","position":"aG","content":{"language":"text","code":"1 5","filename":"Output"},"revision":1},{"id":"15b7ad43-c5a2-756f-87fe-cdfc5b31dbbf","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"The most vexing parse"}]},"revision":1},{"id":"7091d705-65f8-7130-8c5a-9cd7fc846005","type":"code","position":"aI","content":{"language":"cpp","code":"#include <iostream>\nstruct Timer { int ticks = 0; };\nint main() {\n    Timer t{};        // an object\n    // Timer u();     // declares a *function* u returning Timer — not an object!\n    std::cout << t.ticks << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"aa8447df-1b8c-7566-9cee-1cb812e25afa","type":"code","position":"aJ","content":{"language":"text","code":"0","filename":"Output"},"revision":1},{"id":"2f807428-6b0c-7c6d-b719-058eb6ef9798","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why initialise members in the initializer list rather than the constructor body?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because members are always initialised before the body runs. Assigning in the body means default-constructing then assigning (wasteful for strings/containers), and it''s impossible for "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" members, references and types without a default constructor."}]}]}},"revision":1},{"id":"bf7b6617-4e53-7f80-a151-22ce244fdb98","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a constructor be virtual?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. When a constructor runs, the object''s dynamic type is being built, so there''s nothing to dispatch on yet. For “virtual construction” use a factory function or a virtual "},{"type":"text","text":"clone()","marks":[{"type":"code"}]},{"type":"text","text":" method."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
