SELECT '71bae61f-841b-78e9-aae8-6eb6f917807c', '8185caa6-4d68-78a5-a932-23c516cc354b', 'stack, queue & priority_queue', 'stack, queue & priority_queue', 'Container adaptors wrap a sequence container and expose only a restricted interface: LIFO (stack), FIFO (queue) or “largest first” (priority_queue).
std::stack & std::queue
#include <iostream>
#include <queue>
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == ''('' || c == ''['' || c == ''{'') st.push(c);
        else {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == '')'' && open != ''('') || (c == '']'' && open != ''['') || (c == ''}'' && open != ''{'')) return false;
        }
    }
    return st.empty();
}

int main() {
    std::cout << balanced("{[()]}") << balanced("([)]") << ''\n'';

    std::queue<std::string> q;                  // FIFO
    q.push("first"); q.push("second"); q.push("third");
    q.pop();
    std::cout << q.front() << '' '' << q.back() << '' '' << q.size() << ''\n'';
}
