    || setweight(to_tsvector('english', 'Container adaptors wrap a sequence container and expose only a restricted interface: LIFO (stack), FIFO (queue) or “largest first” (priority_queue).
std::stack & std::queue
#include <iostream>
#include <queue>
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == ''('' || c == ''['' || c == ''{'') st.push(c);
        else {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == '')'' && open != ''('') || (c == '']'' && open != ''['') || (c == ''}'' && open != ''{'')) return false;
        }
    }
    return st.empty();
}

int main() {
    std::cout << balanced("{[()]}") << balanced("([)]") << ''\n'';

    std::queue<std::string> q;                  // FIFO
    q.push("first"); q.push("second"); q.push("third");
    q.pop();
    std::cout << q.front() << '' '' << q.back() << '' '' << q.size() << ''\n'';
}
