SELECT '5ecf9c8b-bff3-780e-9089-c50d5542f376', 'f6f05f5e-c140-7ddf-b3b2-91d00cb9b5a9', 1, 'PUBLISHED', 'Copy Semantics: Shallow vs Deep', '[{"id":"3af251e5-fe47-71b1-b994-cd957885f963","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copying an object calls its copy constructor (new object) or copy assignment operator (existing object). If the class owns a raw resource, the default member-wise copy is "},{"type":"text","text":"shallow","marks":[{"type":"italic"}]},{"type":"text","text":" — and wrong."}]}]}},"revision":1},{"id":"464b7523-8fdf-7f94-8ad1-f7123b817ad3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Copy constructor vs copy assignment"}]},"revision":1},{"id":"58259a66-1496-7c50-a7ed-800610e27336","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\nstruct Tag {\n    int v = 0;\n    Tag() = default;\n    Tag(const Tag& o) : v(o.v) { std::cout << \"copy ctor\\n\"; }\n    Tag& operator=(const Tag& o) { v = o.v; std::cout << \"copy assign\\n\"; return *this; }\n};\nvoid byValue(Tag) {}\nint main() {\n    Tag a;\n    Tag b = a;       // copy ctor: b is being created (the ''='' here is not assignment)\n    Tag c(a);        // copy ctor\n    c = b;           // copy assignment: c already exists\n    byValue(a);      // copy ctor for the parameter\n}","filename":"C++"},"revision":1},{"id":"79e32802-a8f8-760a-a333-d9ecfa93600e","type":"code","position":"a3","content":{"language":"text","code":"copy ctor\ncopy ctor\ncopy assign\ncopy ctor","filename":"Output"},"revision":1},{"id":"760f67ed-62e9-7a16-8ba0-872abe7d4587","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"The shallow-copy bug"}]},"revision":1},{"id":"9a931347-993d-7264-9a96-99a1c9d428a4","type":"code","position":"a5","content":{"language":"cpp","code":"#include <cstring>\nclass Buffer {\n    char* data_;\npublic:\n    explicit Buffer(const char* s) : data_(new char[std::strlen(s) + 1]) { std::strcpy(data_, s); }\n    ~Buffer() { delete[] data_; }\n    // no copy constructor → the compiler copies the *pointer*\n};\nint main() {\n    Buffer a(\"hello\");\n    Buffer b = a;        // b.data_ == a.data_\n}                        // both destructors delete[] the same block → double free","filename":"C++ — double free (ASan)"},"revision":1},{"id":"fd97fcab-4250-7de4-8ea5-d684a1e72211","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Deep copy done right"}]},"revision":1},{"id":"9ca7cd5d-6712-778d-b8cb-79ef36084198","type":"code","position":"a7","content":{"language":"cpp","code":"#include <algorithm>\n#include <cstring>\n#include <iostream>\n#include <utility>\n\nclass Buffer {\n    std::size_t size_;\n    char* data_;\npublic:\n    explicit Buffer(const char* s) : size_(std::strlen(s)), data_(new char[size_ + 1]) {\n        std::copy(s, s + size_ + 1, data_);\n    }\n    ~Buffer() { delete[] data_; }\n\n    Buffer(const Buffer& o) : size_(o.size_), data_(new char[o.size_ + 1]) {   // deep copy\n        std::copy(o.data_, o.data_ + size_ + 1, data_);\n    }\n    Buffer& operator=(Buffer o) {          // copy-and-swap: `o` is already a copy\n        swap(*this, o);                    // take its contents; old ones die with `o`\n        return *this;\n    }\n    friend void swap(Buffer& a, Buffer& b) noexcept {\n        std::swap(a.size_, b.size_);\n        std::swap(a.data_, b.data_);\n    }\n    void set(std::size_t i, char c) { data_[i] = c; }\n    const char* str() const { return data_; }\n};\n\nint main() {\n    Buffer a(\"hello\");\n    Buffer b = a;          // independent copy\n    b.set(0, ''j'');\n    Buffer c(\"x\");\n    c = a;                 // assignment\n    Buffer& alias = c;\n    c = alias;             // self-assignment is safe\n    std::cout << a.str() << '' '' << b.str() << '' '' << c.str() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"51a5b5b9-1d60-7ac8-8930-a3a4beea1350","type":"code","position":"a8","content":{"language":"text","code":"hello jello hello","filename":"Output"},"revision":1},{"id":"8508782c-5095-7daf-999b-a2d184253e6f","type":"callout","position":"a9","content":{"variant":"note","title":"Copy-and-swap","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy-and-swap gives the "},{"type":"text","text":"strong exception guarantee","marks":[{"type":"bold"}]},{"type":"text","text":" (if the copy throws, "},{"type":"text","text":"*this","marks":[{"type":"code"}]},{"type":"text","text":" is untouched) and handles self-assignment for free."}]}]}},"revision":1},{"id":"4ca8c17d-0eba-7194-8a42-5b7a2402ef24","type":"callout","position":"aA","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hold resources in members that already know how to copy themselves ("},{"type":"text","text":"std::string","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::vector","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::unique_ptr","marks":[{"type":"code"}]},{"type":"text","text":") — then you write "},{"type":"text","text":"no","marks":[{"type":"italic"}]},{"type":"text","text":" copy code at all (Rule of Zero)."}]}]}},"revision":1},{"id":"73bb4d70-a8a1-7d26-b7cd-e4594917d293","type":"callout","position":"aB","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Owning raw pointers ("},{"type":"text","text":"char*","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"T*","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":") in a class without writing — or deleting — the copy operations."}]}]}},"revision":1},{"id":"4d56450f-5b1f-7dc7-940a-b809ab8e6f01","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between a shallow and a deep copy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A shallow copy duplicates the member values, so two objects'' pointers end up pointing at the same resource (leading to double frees and aliasing bugs). A deep copy allocates a fresh resource and copies the pointed-to contents, giving each object its own."}]}]}},"revision":1},{"id":"c1113a63-1701-72da-bf42-7b8c268368b3","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When is the copy constructor called?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a new object is initialised from an existing one: "},{"type":"text","text":"T b = a;","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"T b(a);","marks":[{"type":"code"}]},{"type":"text","text":", passing by value, returning by value (unless elided), throwing/catching by value, and when containers copy elements."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
