SELECT '7cb3ebaa-e4d7-7c84-a533-b75c54af3af1', 'f0f49008-2bf3-7d02-906f-894af66a9909', 1, 'PUBLISHED', 'deque, list & forward_list', '[{"id":"9fa6ceb8-fb11-776b-9d5c-b3a2b2de18ef","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::deque","marks":[{"type":"code"}]},{"type":"text","text":" is a double-ended queue with O(1) push/pop at both ends and random access; "},{"type":"text","text":"std::list","marks":[{"type":"code"}]},{"type":"text","text":" is a doubly linked list with O(1) splicing anywhere."}]}]}},"revision":1},{"id":"37fc63bd-55f2-7abf-b2d3-5a681ad97e41","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"std::deque","marks":[{"type":"code"}]}]},"revision":1},{"id":"bfac3863-1f45-7845-b996-c6fee9d95c26","type":"code","position":"a2","content":{"language":"cpp","code":"#include <deque>\n#include <iostream>\nint main() {\n    std::deque<int> d{3, 4};\n    d.push_front(2);\n    d.push_front(1);\n    d.push_back(5);\n    std::cout << d.front() << '' '' << d.back() << '' '' << d[2] << '' '' << d.size() << ''\\n'';\n    d.pop_front();\n    d.pop_back();\n    for (int x : d) std::cout << x;\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"f2cebf82-c5db-7c61-a1ef-cc52e4663637","type":"code","position":"a3","content":{"language":"text","code":"1 5 3 5\n234","filename":"Output"},"revision":1},{"id":"205d4b84-a99c-7977-bb00-01b88a09dd8e","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Internally a deque is an array of fixed-size blocks, so growing at either end never moves existing elements (references stay valid on push at the ends) — but elements aren''t contiguous overall."}]}]}},"revision":1},{"id":"42b2a91d-068c-728d-ab56-0cdcb591ee99","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"std::list","marks":[{"type":"code"}]}]},"revision":1},{"id":"c3085b76-787d-7a47-b418-266535da35a9","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n#include <iterator>\n#include <list>\n\nint main() {\n    std::list<int> l{5, 1, 4, 1, 3};\n    auto it = std::next(l.begin(), 2);     // no random access: walk there\n    l.insert(it, 99);                      // O(1) once you have the iterator\n    l.remove(1);                           // remove all 1s\n    l.sort();                              // member sort (std::sort needs random access)\n    for (int x : l) std::cout << x << '' '';\n    std::cout << ''\\n'';\n\n    std::list<int> other{7, 8};\n    l.splice(l.begin(), other);            // move nodes from other in O(1) — no copies\n    l.unique();                            // drop consecutive duplicates\n    l.reverse();\n    for (int x : l) std::cout << x << '' '';\n    std::cout << \"| other size \" << other.size() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"e686db62-f473-7a7a-9fda-c1f31b6bdaf4","type":"code","position":"a7","content":{"language":"text","code":"3 4 5 99\n99 5 4 3 8 7 | other size 0","filename":"Output"},"revision":1},{"id":"c9d6f8ca-c5fb-7d48-9862-27bb7d4878b3","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"std::forward_list","marks":[{"type":"code"}]}]},"revision":1},{"id":"38093318-2cd8-710e-a80f-02d1bc42adc2","type":"code","position":"a9","content":{"language":"cpp","code":"#include <forward_list>\n#include <iostream>\nint main() {\n    std::forward_list<int> fl{2, 3};       // singly linked: one pointer per node, no size()\n    fl.push_front(1);\n    fl.insert_after(fl.begin(), 10);       // only insert *after* a position\n    for (int x : fl) std::cout << x << '' '';\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"505e05d9-58c3-7c45-8a0e-ae6a3673feed","type":"code","position":"aA","content":{"language":"text","code":"1 10 2 3","filename":"Output"},"revision":1},{"id":"71c66f5b-7904-7079-8ee3-346b091b5fdb","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"vector","marks":[{"type":"code"}]}],[{"type":"text","text":"deque","marks":[{"type":"code"}]}],[{"type":"text","text":"list","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Random access "},{"type":"text","text":"[i]","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"push/pop front"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Insert in middle"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)","marks":[{"type":"bold"}]},{"type":"text","text":" with iterator"}]],[[{"type":"text","text":"Contiguous memory"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No (chunks)"}],[{"type":"text","text":"No (nodes)"}]],[[{"type":"text","text":"Iterators stay valid on insert"}],[{"type":"text","text":"No (reallocation)"}],[{"type":"text","text":"No (but refs do at ends)"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Memory overhead"}],[{"type":"text","text":"Low"}],[{"type":"text","text":"Medium"}],[{"type":"text","text":"2 pointers per element"}]]]},"revision":1},{"id":"4b6e48b5-ea0a-70bd-8336-1115b7e2a9c6","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you actually use std::list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When you need iterators/references to stay valid while inserting and erasing elsewhere, or you splice elements between lists in O(1) — e.g. an LRU cache (list + hash map of iterators). For plain sequences, "},{"type":"text","text":"vector","marks":[{"type":"code"}]},{"type":"text","text":" wins on speed and memory."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
