SELECT '0538c1cb-5d1b-7e47-b9f1-03a9b664b429', '09e616f4-75f9-7f52-a9ab-af1e7677af05', 1, 'PUBLISHED', 'Destructors & RAII', '[{"id":"76ff3b3e-ac25-70f2-a797-0778b971a8b9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A destructor "},{"type":"text","text":"~T()","marks":[{"type":"code"}]},{"type":"text","text":" runs automatically when an object''s lifetime ends. "},{"type":"text","text":"RAII","marks":[{"type":"bold"}]},{"type":"text","text":" ties a resource (memory, file, lock, socket) to an object so the destructor always releases it — even when an exception is thrown."}]}]}},"revision":1},{"id":"87a88595-dccd-724b-aaff-6bdf10551a9e","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"RAII","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"Resource Acquisition Is Initialization","marks":[{"type":"italic"}]},{"type":"text","text":": acquire the resource in the constructor, release it in the destructor. The object''s scope becomes the resource''s lifetime."}]}]}},"revision":1},{"id":"a14b1203-01db-7595-b047-2096eeff79b5","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Destructor basics"}]},"revision":1},{"id":"afbcf678-36c8-704a-9910-b68105565aa2","type":"code","position":"a3","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\nstruct Noisy {\n    std::string name;\n    explicit Noisy(std::string n) : name(std::move(n)) { std::cout << \"ctor \" << name << ''\\n''; }\n    ~Noisy() { std::cout << \"dtor \" << name << ''\\n''; }\n};\n\nint main() {\n    Noisy a(\"a\");\n    {\n        Noisy b(\"b\");\n        Noisy c(\"c\");\n    }                             // c then b destroyed here — reverse order\n    Noisy d(\"d\");\n    std::cout << \"end of main\\n\";\n}                                 // d then a","filename":"C++"},"revision":1},{"id":"6aa5a586-cd2f-766c-a2ae-eb7c1adf3366","type":"code","position":"a4","content":{"language":"text","code":"ctor a\nctor b\nctor c\ndtor c\ndtor b\nctor d\nend of main\ndtor d\ndtor a","filename":"Output"},"revision":1},{"id":"0a32c4de-84e2-7edb-9cd8-485253edab6b","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Writing an RAII wrapper"}]},"revision":1},{"id":"56f92230-36bc-7f40-b827-9fa308ce83b0","type":"code","position":"a6","content":{"language":"cpp","code":"#include <cstdio>\n#include <iostream>\n#include <stdexcept>\n\nclass File {\n    std::FILE* f_;\npublic:\n    File(const char* path, const char* mode) : f_(std::fopen(path, mode)) {\n        if (!f_) throw std::runtime_error(\"cannot open file\");\n    }\n    ~File() { std::fclose(f_); std::cout << \"file closed\\n\"; }\n    File(const File&) = delete;              // one owner only\n    File& operator=(const File&) = delete;\n    std::FILE* get() const { return f_; }\n};\n\nvoid process() {\n    File out(\"raii_demo.txt\", \"w\");\n    std::fputs(\"hello\\n\", out.get());\n    throw std::runtime_error(\"something failed\");   // destructor still closes the file\n}\n\nint main() {\n    try { process(); } catch (const std::exception& e) { std::cout << \"caught: \" << e.what() << ''\\n''; }\n    std::remove(\"raii_demo.txt\");\n}","filename":"C++"},"revision":1},{"id":"c3e13a2d-6dc9-7c72-8230-1a5676eaa01b","type":"code","position":"a7","content":{"language":"text","code":"file closed\ncaught: something failed","filename":"Output"},"revision":1},{"id":"c3cdef82-ddd9-77f1-b7bc-1aba9922655b","type":"callout","position":"a8","content":{"variant":"note","title":"Memory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::unique_ptr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::shared_ptr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","tex