SELECT '7887eb9a-4276-743c-936f-f4b13b2da40f', 'c7f2dbfc-a9c0-741e-a272-1f1b1c4721fd', 1, 'PUBLISHED', 'Exceptions', '[{"id":"5192f085-623b-76a9-9a1c-d0197f4cff02","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"throw","marks":[{"type":"code"}]},{"type":"text","text":" signals an error that the current function can''t handle; the stack unwinds (destroying locals) until a matching "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":" is found."}]}]}},"revision":1},{"id":"4c2d66d0-6996-70cb-80c0-05fd6b0bd444","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"throw / try / catch"}]},"revision":1},{"id":"043bec4b-8c85-7e4c-b3f5-237beadb67a6","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\n#include <string>\n\ndouble divide(double a, double b) {\n    if (b == 0) throw std::invalid_argument(\"division by zero\");\n    return a / b;\n}\n\nint parseAge(const std::string& s) {\n    int age = std::stoi(s);                          // may throw invalid_argument / out_of_range\n    if (age < 0 || age > 150) throw std::out_of_range(\"age \" + s + \" out of range\");\n    return age;\n}\n\nint main() {\n    try {\n        std::cout << divide(10, 4) << ''\\n'';\n        std::cout << divide(1, 0) << ''\\n'';           // throws — the rest of the try is skipped\n        std::cout << \"never printed\\n\";\n    } catch (const std::invalid_argument& e) {\n        std::cout << \"invalid: \" << e.what() << ''\\n'';\n    }\n\n    for (std::string input : {\"42\", \"abc\", \"200\"}) {\n        try {\n            std::cout << parseAge(input) << ''\\n'';\n        } catch (const std::out_of_range& e) {       // most specific first\n            std::cout << \"range: \" << e.what() << ''\\n'';\n        } catch (const std::exception& e) {          // any standard exception\n            std::cout << \"error: \" << e.what() << ''\\n'';\n        } catch (...) {                              // anything at all\n            std::cout << \"unknown\\n\";\n        }\n    }\n}","filename":"C++"},"revision":1},{"id":"42eecc92-8bbe-77f5-bf3c-23674b03953d","type":"code","position":"a3","content":{"language":"text","code":"2.5\ninvalid: division by zero\n42\nerror: stoi: no conversion\nrange: age 200 out of range","filename":"Output"},"revision":1},{"id":"8ccc63dd-f651-7266-9f42-aa0dabc1647b","type":"callout","position":"a4","content":{"variant":"note","title":"Rule","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Throw by value, catch by "},{"type":"text","text":"const reference","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"catch (const std::exception& e)","marks":[{"type":"code"}]},{"type":"text","text":"). Catching by value copies and "},{"type":"text","text":"slices","marks":[{"type":"italic"}]},{"type":"text","text":" derived exceptions; catching by reference keeps their dynamic type and "},{"type":"text","text":"what()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"97264d86-7dae-78fe-8049-4099e58abf18","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The standard hierarchy"}]},"revision":1},{"id":"00e5434a-046e-7bd1-8734-70a5cc30e661","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Exception"}],[{"type":"text","text":"Thrown by / used for"}]],[[{"type":"text","text":"std::exception","marks":[{"type":"code"}]}],[{"type":"text","text":"Base of all — has "},{"type":"text","text":"virtual const char* what()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"std::logic_error","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"invalid_argument","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"out_of_range","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"length_error","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"domain_error","marks":[{"type":"code"}]}],[{"type":"text","text":"Bugs detectable before running: bad arguments, "},{"type":"text","text":"vector::at","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"stoi","marks":[{"type":"code"}]}]],[[{"type":"text","text":"std::runtime_error","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"range_error","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"overflow_error","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"system_error","marks":[{"type":"code"}]}],[{"type":"text","text":"Errors only detectable at run time: I/O, OS"}]],[[{"type":"text","text":"std::bad_alloc","marks":[{"type":"code"}]}],[{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" failed"}]],[[{"type":"text","text":"std::bad_cast","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::bad_optional_access","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::bad_variant_access","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::bad_function_call","marks":[{"type":"code"}]}],[{"type":"text","text":"Misused library types"}]]]},"revision":1},{"id":"e8f5f55f-471d-7696-ac11-339f99dd3568","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Custom exceptions & rethrowing"}]},"revision":1},{"id":"849e90b1-5f3c-7a98-912a-efed00a8e448","type":"code","position":"a8","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\n#include <string>\n\nclass HttpError : public std::runtime_error {\npublic:\n    HttpError(int code, const std::string& msg)\n        : std::runtime_error(msg), code_(code) {}\n    int code() const noexcept { return code_; }\nprivate:\n    int code_;\n};\n\nvoid fetch() { throw HttpError(404, \"page not found\"); }\n\nvoid handler() {\n    try {\n        fetch();\n    } catch (const HttpError& e) {\n        std::cout << \"log: \" << e.code() << ''\\n'';\n        throw;                                       // rethrow the SAME exception object\n    }\n}\n\nint main() {\n    try { handler(); }\n    catch (const std::exception& e) { std::cout << \"top level: \" << e.what() << ''\\n''; }\n}","filename":"C++"},"revision":1},{"id":"18e04ea2-3b0c-7bbd-8273-7d34ea2adba2","type":"code","position":"a9","content":{"language":"text","code":"log: 404\ntop level: page not found","filename":"Output"},"revision":1},{"id":"6b466b46-e27b-77af-ac50-5884b807b43f","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Stack unwinding"}]},"revision":1},{"id":"b9d5c9d2-167e-7af4-9df6-7f991d2260d9","type":"code","position":"aB","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\nstruct Guard {\n    const char* name;\n    ~Guard() { std::cout << \"cleanup \" << name << ''\\n''; }\n};\nvoid inner() { Guard g{\"inner\"}; throw std::runtime_error(\"fail\"); }\nvoid outer() { Guard g{\"outer\"}; inner(); }\nint main() {\n    try { outer(); } catch (const std::exception& e) { std::cout << \"caught \" << e.what() << ''\\n''; }\n}","filename":"C++"},"revision":1},{"id":"a3aead4e-4550-7939-a087-78c7a54aeb22","type":"code","position":"aC","content":{"language":"text","code":"cleanup inner\ncleanup outer\ncaught fail","filename":"Output"},"revision":1},{"id":"bece21b4-0564-7715-aff1-f023d7111e0e","type":"callout","position":"aD","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use exceptions for "},{"type":"text","text":"exceptional","marks":[{"type":"italic"}]},{"type":"text","text":" failures that the immediate caller can''t sensibly handle (I/O failure, invalid config, out of memory). Rely on RAII so unwinding cleans up."}]}]}},"revision":1},{"id":"fe73919d-c914-7fe4-90dc-dd05431b1131","type":"callout","position":"aE","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using exceptions for normal control flow (e.g. “not found” in a lookup), throwing from destructors, or "},{"type":"text","text":"catch (...) {}","marks":[{"type":"code"}]},{"type":"text","text":" that silently swallows errors."}]}]}},"revision":1},{"id":"5b00bbb4-c254-7665-9cae-1ac52b84076c","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If an exception escapes "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" (or any "},{"type":"text","text":"noexcept","marks":[{"type":"code"}]},{"type":"text","text":" function), "},{"type":"text","text":"std::terminate","marks":[{"type":"code"}]},{"type":"text","text":" is called and the program aborts — destructors of the remaining stack may not run."}]}]}},"revision":1},{"id":"bf2e8cfc-ee9b-7c98-9e50-dedb7ae5bdcc","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens when an exception is thrown?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The exception object is copied/moved into special storage, then the runtime searches up the call stack for a matching "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":". Each frame it leaves is "},{"type":"text","text":"unwound","marks":[{"type":"italic"}]},{"type":"text","text":": local objects are destroyed in reverse order. When a handler matches (by type, allowing derived-to-base), it runs; if none matches, "},{"type":"text","text":"std::terminate","marks":[{"type":"code"}]},{"type":"text","text":" is called."}]}]}},"revision":1},{"id":"e840bd4c-e088-7779-9bca-c602b50e3b40","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exceptions vs error codes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exceptions can''t be ignored silently, separate the error path from the happy path, and carry rich information through many layers. Error codes (or "},{"type":"text","text":"std::optional","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"std::expected","marks":[{"type":"code"}]},{"type":"text","text":") are explicit in the signature, cheaper when failure is common, and required where exceptions are disabled (some embedded/game code). Many code bases use exceptions for rare failures and return values for expected ones."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
