SELECT '3bc48cd6-4362-730a-b089-636771633fcd', '2d633ada-9278-7976-b72f-6e231cfb0b05', 1, 'PUBLISHED', 'Function Pointers, Functors & std::function', '[{"id":"31001f46-f571-7a6c-8c33-bfa1a4b6e58e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three ways to treat “a function” as a value: raw function pointers (C-style), function objects (classes with "},{"type":"text","text":"operator()","marks":[{"type":"code"}]},{"type":"text","text":"), and the type-erased "},{"type":"text","text":"std::function","marks":[{"type":"code"}]},{"type":"text","text":" wrapper."}]}]}},"revision":1},{"id":"b8bbf54f-98a2-7ac1-bfd6-6f9ea5cdcd32","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Function pointers"}]},"revision":1},{"id":"ddbf20b1-28dd-79b7-accd-431b5145accf","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n\nint add(int a, int b) { return a + b; }\nint mul(int a, int b) { return a * b; }\n\nint apply(int (*op)(int, int), int x, int y) { return op(x, y); }\n\nusing BinaryOp = int (*)(int, int);          // alias makes the syntax readable\n\nint main() {\n    BinaryOp ops[] = {add, mul};             // table of functions\n    for (BinaryOp op : ops) std::cout << apply(op, 3, 4) << '' '';\n    std::cout << ''\\n'';\n    int (*p)(int, int) = &add;               // & and * are optional for functions\n    std::cout << (*p)(1, 1) << '' '' << p(2, 2) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"3952298a-06a6-77e2-916b-fde1f9293b14","type":"code","position":"a3","content":{"language":"text","code":"7 12\n2 4","filename":"Output"},"revision":1},{"id":"05fb947b-33dd-7a96-8239-d2feaeb8f471","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Functors (function objects)"}]},"revision":1},{"id":"05a92a1c-0c44-7eb3-b885-4714a6a0b5b7","type":"code","position":"a5","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <vector>\n\nclass InRange {                               // a functor can carry state\n    int lo_, hi_;\npublic:\n    InRange(int lo, int hi) : lo_(lo), hi_(hi) {}\n    bool operator()(int x) const { return lo_ <= x && x <= hi_; }\n};\n\nint main() {\n    std::vector<int> v{1, 5, 9, 12, 7};\n    std::cout << std::count_if(v.begin(), v.end(), InRange(5, 10)) << ''\\n'';\n    std::sort(v.begin(), v.end(), std::greater<int>());   // standard functor from <functional>\n    std::cout << v.front() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"1ed82ac8-f0f1-7643-8348-c38025bc9877","type":"code","position":"a6","content":{"language":"text","code":"3\n12","filename":"Output"},"revision":1},{"id":"e8b5c30a-9577-7acf-bc19-ef62b319ddc2","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"std::function","marks":[{"type":"code"}]}]},"revision":1},{"id":"e159f1e5-f0dc-78b8-a92a-e69e3a2a446b","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::function<R(Args...)>","marks":[{"type":"code"}]},{"type":"text","text":" can hold "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" callable with that signature — function pointer, functor or lambda (even with captures). It''s the tool for storing callbacks of unknown type, at the cost of a possible heap allocation and an indirect call."}]}]}},"revision":1},{"id":"c40b075f-440e-7215-b826-babdee753c77","type":"code","position":"a9","content":{"language":"cpp","code":"#include <functional>\n#include <iostream>\n#include <map>\n#include <string>\n\nint sub(int a, int b) { return a - b; }\n\nint main() {\n    int bonus = 100;\n    std::map<std::string, std::function<int(int, int)>> calc{\n        {\"+\", [](int a, int b) { return a + b; }},\n        {\"-\", sub},\n        {\"max\", [](int a, int b) { return std::max(a, b); }},\n 