SELECT 'f6b508df-1395-728b-8830-d08a13fca2bb', '7a043413-3925-7557-9f1a-65dc74a73dd4', 1, 'PUBLISHED', 'Function Templates', '[{"id":"8ddb482d-8bd5-782f-89b6-86620c1edd80","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A template is a blueprint the compiler stamps out for each set of types you use it with. Write the algorithm once; get type-checked, fully optimised code for every type."}]}]}},"revision":1},{"id":"f43a7242-88cc-715b-a87d-fabfcba0ae72","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Defining and calling"}]},"revision":1},{"id":"383f2375-6531-7cd3-a5a9-92bbfe68ced6","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\ntemplate <typename T>                     // `class T` means the same\nT maxOf(T a, T b) { return a > b ? a : b; }\n\ntemplate <typename T, typename U>\nauto add(T a, U b) { return a + b; }      // return type deduced from the expression\n\ntemplate <typename T, int N>              // non-type template parameter\nconstexpr int length(const T (&)[N]) { return N; }\n\nint main() {\n    std::cout << maxOf(3, 7) << '' '' << maxOf(2.5, 1.5) << '' '' << maxOf<std::string>(\"pear\", \"apple\") << ''\\n'';\n    std::cout << add(1, 2.5) << ''\\n'';\n    int arr[] = {1, 2, 3, 4};\n    std::cout << length(arr) << ''\\n'';\n    // maxOf(3, 7.0);   // error: T deduced as both int and double\n    std::cout << maxOf<double>(3, 7.5) << ''\\n'';   // explicit template argument\n}","filename":"C++"},"revision":1},{"id":"f273ef4e-6ced-7e20-8876-46c532b23394","type":"code","position":"a3","content":{"language":"text","code":"7 2.5 pear\n3.5\n4\n7.5","filename":"Output"},"revision":1},{"id":"9802f1fd-2a43-7812-82a1-725b9333fcf1","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"How instantiation works"}]},"revision":1},{"id":"49b1a05b-846c-7b6c-aa1a-9987641ab189","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deduction","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"From the call "},{"type":"text","text":"maxOf(3, 7)","marks":[{"type":"code"}]},{"type":"text","text":" the compiler deduces "},{"type":"text","text":"T = int","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instantiation","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"It generates "},{"type":"text","text":"int maxOf<int>(int, int)","marks":[{"type":"code"}]},{"type":"text","text":" — a real function — and type-checks it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reuse","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Every call with "},{"type":"text","text":"T = int","marks":[{"type":"code"}]},{"type":"text","text":" in this translation unit uses the same instantiation; identical instantiations in other TUs are merged by the linker."}]}]}]}]}},"revision":1},{"id":"d2bc96ea-3e2f-7492-9b45-0b38b9091ede","type":"callout","position":"a6","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Templates are checked twice: syntax when defined, and fully when instantiated. Errors like “no match for "},{"type":"text","text":"operator>","marks":[{"type":"code"}]},{"type":"text","text":"” appear only when you use the template with a type that lacks it — which is what "},{"type":"text","text":"concepts","marks":[{"type":"bold"}]},{"type":"text","text":" fix."}]}]}},"revision":1},{"id":"ceb730ba-d650-7431-abb1-1d98a0b76663","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Overloading and explicit specialisation"}]},"revision":1},{"id":"52765a4e-f651-7158-8045-0159c55829bb","type":"code","position":"a8","content":{"language":"cpp","code":"#include <cstring>\n#include <iostream>\n\ntemplate <typename T>\nbool equal(const T& a, const T& b) { return a == b; }\n\ntemplate <>                                               // full specialisation for const char*\nbool equal<const char*>(const char* const& a, const char* const& b) { return std::strcmp(a, b) == 0; }\n\ntemplate <typename T>\nvoid describe(T)  { std::cout << \"value\\n\"; }\ntemplate <typename T>\nvoid describe(T*) { std::cout << \"pointer\\n\"; }           // overload: more specialised, preferred\n\nint main() {\n    const char* x = \"hi\";\n    char buf[] = \"hi\";\n    const char* y = buf;\n    std::cout << equal(1, 1) << equal(x, y) << ''\\n'';     // compares contents, not addresses\n    int n = 0;\n    describe(n);\n    describe(&n);\n}","filename":"C++"},"revision":1},{"id":"fd31fd22-590d-7fd6-8802-edf56259d5ac","type":"code","position":"a9","content":{"language":"text","code":"11\nvalue\npointer","filename":"Output"},"revision":1},{"id":"8a3a6320-c69d-7d61-8d2b-3058e1e94625","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"overloading","marks":[{"type":"italic"}]},{"type":"text","text":" function templates to specialising them — specialisations don''t take part in overload resolution, which surprises people."}]}]}},"revision":1},{"id":"a8f66364-8974-7a97-bac1-dbbbaf9e2be5","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Abbreviated templates (C++20)"}]},"revision":1},{"id":"5d5c82cc-df9e-7d1e-b4e3-4526544bb7b2","type":"code","position":"aC","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nauto sum(const auto& container) {          // `auto` parameter = implicit template\n    typename std::decay_t<decltype(container)>::value_type total{};\n    for (const auto& x : container) total += x;\n    return total;\n}\nint main() {\n    std::cout << sum(std::vector<int>{1, 2, 3}) << '' '' << sum(std::vector<double>{0.5, 0.25}) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"66537374-0c84-78e4-a6f0-2cedab1d5098","type":"code","position":"aD","content":{"language":"text","code":"6 0.75","filename":"Output"},"revision":1},{"id":"909b27ef-e588-7d1b-bd8f-72bf9787d0a9","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is template argument deduction?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The process where the compiler figures out template parameters from the types of the call''s arguments, so you can write "},{"type":"text","text":"maxOf(3, 7)","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"maxOf<int>(3, 7)","marks":[{"type":"code"}]},{"type":"text","text":". Deduction doesn''t consider implicit conversions: "},{"type":"text","text":"maxOf(3, 7.0)","marks":[{"type":"code"}]},{"type":"text","text":" fails because "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" would have to be both "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"102d0455-e4b1-74c4-abba-5d102ad96e34","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Do templates cause code bloat?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each distinct instantiation is separate code, so using a template with many types can grow the binary. In exchange each version is specialised and inlinable. Mitigations: factor type-independent code into non-template helpers, and use type erasure where performance isn''t critical."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
