SELECT '629e313d-9fab-7a8a-9371-9b17d20cafe2', 'f6435e73-a619-761b-81b2-60fe7aa6e314', 1, 'PUBLISHED', 'Inheritance & Access Specifiers', '[{"id":"ee43597d-cf46-7dab-9cc7-6019cc6ce935","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A derived class inherits the members of its base class and can add or customise behaviour. Public inheritance models an "},{"type":"text","text":"is-a","marks":[{"type":"bold"}]},{"type":"text","text":" relationship."}]}]}},"revision":1},{"id":"6bf40065-9a54-7251-ac79-688fcc16193b","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Basics"}]},"revision":1},{"id":"7e0733f0-2e40-722c-bd2d-9e84dd91cdea","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\nclass Animal {\npublic:\n    explicit Animal(std::string name) : name_(std::move(name)) { std::cout << \"Animal()\\n\"; }\n    ~Animal() { std::cout << \"~Animal()\\n\"; }\n    void eat() const { std::cout << name_ << \" eats\\n\"; }\nprotected:\n    std::string name_;                 // visible to derived classes, not to outsiders\n};\n\nclass Dog : public Animal {\npublic:\n    Dog(std::string name, std::string breed)\n        : Animal(std::move(name)), breed_(std::move(breed)) { std::cout << \"Dog()\\n\"; }   // base first\n    ~Dog() { std::cout << \"~Dog()\\n\"; }\n    void bark() const { std::cout << name_ << \" the \" << breed_ << \" barks\\n\"; }\nprivate:\n    std::string breed_;\n};\n\nint main() {\n    Dog d(\"Rex\", \"beagle\");\n    d.eat();          // inherited\n    d.bark();         // added\n}","filename":"C++"},"revision":1},{"id":"2918f998-f9b1-70d9-b371-177d0693a887","type":"code","position":"a3","content":{"language":"text","code":"Animal()\nDog()\nRex eats\nRex the beagle barks\n~Dog()\n~Animal()","filename":"Output"},"revision":1},{"id":"a2c3141a-3fb8-7fe4-8436-0e17fb73f707","type":"callout","position":"a4","content":{"variant":"note","title":"Order","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Construction goes "},{"type":"text","text":"base → members → derived body","marks":[{"type":"bold"}]},{"type":"text","text":"; destruction runs in exactly the reverse order."}]}]}},"revision":1},{"id":"285fae01-0e8f-7ad5-b142-d2e2c7442bf1","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Inheritance access"}]},"revision":1},{"id":"534b9e51-f873-7ce0-9683-e204f6646a86","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Base member is…"}],[{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":" inheritance"}],[{"type":"text","text":"protected","marks":[{"type":"code"}]},{"type":"text","text":" inheritance"}],[{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" inheritance"}]],[[{"type":"text","text":"public","marks":[{"type":"code"}]}],[{"type":"text","text":"public"}],[{"type":"text","text":"protected"}],[{"type":"text","text":"private"}]],[[{"type":"text","text":"protected","marks":[{"type":"code"}]}],[{"type":"text","text":"protected"}],[{"type":"text","text":"protected"}],[{"type":"text","text":"private"}]],[[{"type":"text","text":"private","marks":[{"type":"code"}]}],[{"type":"text","text":"inaccessible"}],[{"type":"text","text":"inaccessible"}],[{"type":"text","text":"inaccessible"}]]]},"revision":1},{"id":"36f4da4f-9e4e-7310-8c58-c8042118dc0d","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":" inheritance = "},{"type":"text","text":"is-a","marks":[{"type":"italic"}]},{"type":"text","text":" (a "},{"type":"text","text":"Dog","marks":[{"type":"code"}]},{"type":"text","text":" can be used wherever an "},{"type":"text","text":"Animal&","marks":[{"type":"code"}]},{"type":"text","text":" is expected). 99% of the time this is what you want."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" inheritance = "},{"type":"text","text":"implemented-in-terms-of","marks":[{"type":"italic"}]},{"type":"text","text":" — usually better expressed with composition (a member)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"class D : B","marks":[{"type":"code"}]},{"type":"text","text":" defaults to "},{"type":"text","text":"private","marks":[{"type":"bold"}]},{"type":"text","text":" inheritance; "},{"type":"text","text":"struct D : B","marks":[{"type":"code"}]},{"type":"text","text":" to public."}]}]}]}]}},"revision":1},{"id":"b6e9ab3a-e507-776d-b0f7-50baef66d9ee","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Hiding, "},{"type":"text","text":"using","marks":[{"type":"code"}]},{"type":"text","text":" and calling the base version"}]},"revision":1},{"id":"6e2243a8-50c6-7890-a31a-428c28780552","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\n\nstruct Base {\n    void greet() const { std::cout << \"Base::greet\\n\"; }\n    void greet(int n) const { std::cout << \"Base::greet(\" << n << \")\\n\"; }\n};\n\nstruct Derived : Base {\n    using Base::greet;                 // without this, greet(int) would be hidden\n    void greet() const {\n        std::cout << \"Derived::greet, then \";\n        Base::greet();                 // call the base version explicitly\n    }\n};\n\nstruct WithCtors : Base {\n    using Base::Base;                  // inherit constructors (C++11)\n};\n\nint main() {\n    Derived d;\n    d.greet();\n    d.greet(3);\n}","filename":"C++"},"revision":1},{"id":"f425f945-74a1-7725-ad90-915630d78a09","type":"code","position":"aA","content":{"language":"text","code":"Derived::greet, then Base::greet\nBase::greet(3)","filename":"Output"},"revision":1},{"id":"b4d798c2-bc83-70bc-a140-fbd95baa3c4b","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Declaring a function in the derived class with the same "},{"type":"text","text":"name","marks":[{"type":"italic"}]},{"type":"text","text":" hides "},{"type":"text","text":"all","marks":[{"type":"bold"}]},{"type":"text","text":" base overloads of that name, whatever their parameters. Bring them back with "},{"type":"text","text":"using Base::name;","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ce97de59-6dbb-79d6-a2ca-00e2c2f64a70","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Composition vs inheritance"}]},"revision":1},{"id":"b71dbaed-c4ee-7316-9f11-fb3379739b91","type":"callout","position":"aD","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use inheritance for genuine is-a relationships with polymorphic behaviour; prefer "},{"type":"text","text":"composition","marks":[{"type":"bold"}]},{"type":"text","text":" (has-a) for reuse: a "},{"type":"text","text":"Car","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"has an","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"Engine","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"613c3aed-53de-7b6c-93a5-51cf1835c4ab","type":"callout","position":"aE","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inheriting just to reuse code ("},{"type":"text","text":"class Stack : public std::vector<int>","marks":[{"type":"code"}]},{"type":"text","text":") — it exposes every base operation and couples you to its implementation."}]}]}},"revision":1},{"id":"e086da09-7242-78d5-a51c-2923644005ff","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is not inherited from a base class?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Constructors (unless brought in with "},{"type":"text","text":"using Base::Base;","marks":[{"type":"code"}]},{"type":"text","text":"), the destructor, copy/move assignment operators (the derived class gets its own implicitly-declared ones), and friendships. Private members "},{"type":"text","text":"are","marks":[{"type":"italic"}]},{"type":"text","text":" inherited — they''re part of the object — but not accessible."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
